// 文法速查表資料（草稿，待老師審核）。t=標題 d=說明 ex=例句；k=搜尋用關鍵字（自動產生，不顯示）；簡體由繁體自動轉換（OpenCC tw2s，保留台灣用語）
window.GRAMMAR={"books":{"1":"A1–A2","2":"A2–B1","3":"B1","4":"B1–B2","5":"B2–C1","6":"C1"},"lessons":{"1-1":{"tc":"歡迎你來台灣！","sc":"欢迎你来台湾！"},"1-2":{"tc":"我的家人","sc":"我的家人"},"1-3":{"tc":"週末做什麼？","sc":"周末做什么？"},"1-4":{"tc":"請問一共多少錢？","sc":"请问一共多少钱？"},"1-5":{"tc":"牛肉麵真好吃","sc":"牛肉面真好吃"},"1-6":{"tc":"他們學校在山上","sc":"他们学校在山上"},"1-7":{"tc":"早上九點去 KTV","sc":"早上九点去 KTV"},"1-8":{"tc":"坐火車去台南","sc":"坐火车去台南"},"1-9":{"tc":"放假去哪裡玩？","sc":"放假去哪里玩？"},"1-10":{"tc":"台灣的水果很好吃","sc":"台湾的水果很好吃"},"1-11":{"tc":"我要租房子","sc":"我要租房子"},"1-12":{"tc":"你在台灣學多久的中文？","sc":"你在台湾学多久的中文？"},"1-13":{"tc":"生日快樂","sc":"生日快乐"},"1-14":{"tc":"天氣這麼冷！","sc":"天气这么冷！"},"1-15":{"tc":"我很不舒服","sc":"我很不舒服"},"2-1":{"tc":"請問，到師到怎麼走？","sc":"请问，到师到怎么走？"},"2-2":{"tc":"還是坐捷運吧！","sc":"还是坐捷运吧！"},"2-3":{"tc":"你的中文進步了！","sc":"你的中文进步了！"},"2-4":{"tc":"我打工，我教法文","sc":"我打工，我教法文"},"2-5":{"tc":"吃喜酒","sc":"吃喜酒"},"2-6":{"tc":"我打算搬到學校附近","sc":"我打算搬到学校附近"},"2-7":{"tc":"垃圾車來了！","sc":"垃圾车来了！"},"2-8":{"tc":"學功夫","sc":"学功夫"},"2-9":{"tc":"那個城市好漂亮","sc":"那个城市好漂亮"},"2-10":{"tc":"歡迎到我家來包餃子","sc":"欢迎到我家来包饺子"},"2-11":{"tc":"台灣好玩的地方真多","sc":"台湾好玩的地方真多"},"2-12":{"tc":"怎麼吃才健康？","sc":"怎么吃才健康？"},"2-13":{"tc":"我的手機掉了","sc":"我的手机掉了"},"2-14":{"tc":"我要開始工作了","sc":"我要开始工作了"},"2-15":{"tc":"過春節","sc":"过春节"},"3-1":{"tc":"開學了","sc":"开学了"},"3-2":{"tc":"八折起","sc":"八折起"},"3-3":{"tc":"外套帶了沒有？","sc":"外套带了没有？"},"3-4":{"tc":"我愛台灣的人情味","sc":"我爱台湾的人情味"},"3-5":{"tc":"現在流行什麼？","sc":"现在流行什么？"},"3-6":{"tc":"到鄉下住一晚！","sc":"到乡下住一晚！"},"3-7":{"tc":"我最親的家「人」","sc":"我最亲的家「人」"},"3-8":{"tc":"我想做自己","sc":"我想做自己"},"3-9":{"tc":"網購時代","sc":"网购时代"},"3-10":{"tc":"我住院了","sc":"我住院了"},"3-11":{"tc":"台灣故事","sc":"台湾故事"},"3-12":{"tc":"我要去投票","sc":"我要去投票"},"4-1":{"tc":"十七歲還是二十五歲？","sc":"十七岁还是二十五岁？"},"4-2":{"tc":"眼睛、耳朵的饗宴","sc":"眼睛、耳朵的飨宴"},"4-3":{"tc":"雲端科技","sc":"云端科技"},"4-4":{"tc":"床該擺哪裡？","sc":"床该摆哪里？"},"4-5":{"tc":"有夢最美","sc":"有梦最美"},"4-6":{"tc":"天搖地動","sc":"天摇地动"},"4-7":{"tc":"大學生的事","sc":"大学生的事"},"4-8":{"tc":"他們的選擇","sc":"他们的选择"},"4-9":{"tc":"再談台灣故事","sc":"再谈台湾故事"},"4-10":{"tc":"應徵","sc":"应征"},"4-11":{"tc":"文化、種族的大熔爐","sc":"文化、种族的大熔炉"},"4-12":{"tc":"期待美好的未來","sc":"期待美好的未来"},"5-1":{"tc":"言論自由的界線","sc":"言论自由的界线"},"5-2":{"tc":"關於基改食品，我有話要說","sc":"关于基改食品，我有话要说"},"5-3":{"tc":"整型好不好","sc":"整型好不好"},"5-4":{"tc":"傳統與現代","sc":"传统与现代"},"5-5":{"tc":"代理孕母，帶來幸福？","sc":"代理孕母，带来幸福？"},"5-6":{"tc":"死刑的存廢","sc":"死刑的存废"},"5-7":{"tc":"增富人稅=減窮人苦？","sc":"增富人税=减穷人苦？"},"5-8":{"tc":"左右為難的難民問題","sc":"左右为难的难民问题"},"5-9":{"tc":"有核到底可不可？","sc":"有核到底可不可？"},"5-10":{"tc":"同性婚姻合法化","sc":"同性婚姻合法化"},"6-1":{"tc":"職校教育","sc":"职校教育"},"6-2":{"tc":"科技與生活","sc":"科技与生活"},"6-3":{"tc":"舞蹈藝術","sc":"舞蹈艺术"},"6-4":{"tc":"做人心法","sc":"做人心法"},"6-5":{"tc":"國際語言","sc":"国际语言"},"6-6":{"tc":"貓熊角色","sc":"猫熊角色"},"6-7":{"tc":"感情世界","sc":"感情世界"},"6-8":{"tc":"奧運黑洞","sc":"奥运黑洞"},"6-9":{"tc":"鄉關何處","sc":"乡关何处"},"6-10":{"tc":"智慧與能力","sc":"智慧与能力"}},"points":[{"id":"1-1-0","b":1,"l":1,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Preguntas con 嗎","en":"Ways to Ask Questions in Chinese / Asking Questions with 嗎 ma","ens":"Ways to Ask Questions in Chinese / Asking Questions with 吗 ma","tc":"用「嗎」問問題","sc":"用「吗」问问题"},"d":{"es":"Para preguntas de sí/no: añade 嗎 al final de una oración afirmativa. También puedes usar la forma A-no-A (verbo + 不 + verbo).","en":"For yes/no questions, add 嗎 at the end of a statement. You can also use the A-not-A pattern (verb + 不 + verb).","tc":"問是不是、有沒有的問題時，在句子最後加「嗎」。也可以用「A 不 A」的方式問，例如「是不是」。","sc":"问是不是、有没有的问题时，在句子最后加「吗」。也可以用「A 不 A」的方式问，例如「是不是」。"},"ex":[{"c":"你是學生嗎？","s":"你是学生吗？","es":"¿Eres estudiante?","en":"Are you a student?","p":"nǐ shì xué shēng ma?"},{"c":"你是不是學生？","s":"你是不是学生？","es":"¿Eres o no eres estudiante?","en":"Are you a student or not?","p":"nǐ shì bú shì xué shēng?"}]},{"id":"1-1-1","b":1,"l":1,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 negación negar negativa negation negative 否定 pregunta preguntar interrogativa question ask 疑问 问句 提问 negación negar negativa negation negative 否定","t":{"es":"Cómo responder: 是 / 不是","en":"Answering Questions in Chinese / Affirmative Answers / Negative Replies with 不 bù","ens":"Answering Questions in Chinese / Affirmative Answers / Negative Replies with 不 bù","tc":"回答問題：是／不是","sc":"回答问题：是／不是"},"d":{"es":"Se responde repitiendo el verbo: 是 / 不是. La negación 不 va justo antes del verbo o adjetivo. No se contesta con un simple «sí/no».","en":"Answer by repeating the verb: 是 / 不是. 不 goes right before the verb or adjective. Don't answer with a bare 'yes' or 'no'.","tc":"回答時重複問句裡的動詞，例如「是」或「不是」。「不」放在動詞或形容詞前面，不要只回答 yes 或 no。","sc":"回答时重复问句里的动词，例如「是」或「不是」。「不」放在动词或形容词前面，不要只回答 yes 或 no。"},"ex":[{"c":"你是老師嗎？——不是，我不是老師。","s":"你是老师吗？——不是，我不是老师。","es":"¿Eres profesor? — No, no soy profesor.","en":"Are you a teacher? — No, I'm not a teacher.","p":"nǐ shì lǎo shī ma? — bú shì, wǒ bú shì lǎo shī."}]},{"id":"1-1-2","b":1,"l":1,"k":"","t":{"es":"Adjetivos con 很","en":"Modification Marker 很 hěn","ens":"Modification Marker 很 hěn","tc":"形容詞前面的「很」","sc":"形容词前面的「很」"},"d":{"es":"Con adjetivos (verbos estativos) se pone 很 antes del adjetivo. Aquí 很 casi no significa «muy»; sin él, la oración suena a comparación.","en":"When an adjective is the predicate, put 很 before it. Here 很 usually doesn't mean 'very'; without it the sentence sounds like a comparison.","tc":"形容詞當謂語時，前面通常要加「很」。這裡的「很」不一定是「非常」的意思，沒有它句子會像在做比較。","sc":"形容词当谓语时，前面通常要加「很」。这里的「很」不一定是「非常」的意思，没有它句子会像在做比较。"},"ex":[{"c":"我很忙。","s":"我很忙。","es":"Estoy ocupado.","en":"I'm busy.","p":"wǒ hěn máng."}]},{"id":"1-1-3","b":1,"l":1,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"¿Y tú? con 呢","en":"Contrastive Questions with 呢 ne","ens":"Contrastive Questions with 呢 ne","tc":"用「呢」反問","sc":"用「呢」反问"},"d":{"es":"呢 devuelve la misma pregunta al otro: «¿y tú?», «¿y …?».","en":"呢 turns the same question back to the other person: 'And you?', 'What about …?'.","tc":"「呢」可以把同樣的問題丟給對方，意思是「那你呢？」「那……呢？」。","sc":"「呢」可以把同样的问题丢给对方，意思是「那你呢？」「那……呢？」。"},"ex":[{"c":"我很好，你呢？","s":"我很好，你呢？","es":"Yo estoy bien, ¿y tú?","en":"I'm fine, and you?","p":"wǒ hěn hǎo, nǐ ne?"}]},{"id":"1-2-0","b":1,"l":2,"k":"","t":{"es":"Posesión con 的","en":"的 de possessive","ens":"的 de possessive","tc":"表示擁有的「的」","sc":"表示拥有的「的」"},"d":{"es":"Sustantivo/pronombre + 的 + sustantivo expresa posesión. Con familiares o personas muy cercanas se suele omitir 的.","en":"Noun/pronoun + 的 + noun shows possession. With family or very close people, 的 is often left out.","tc":"「名詞或代名詞＋的＋名詞」表示誰的東西。家人或很親近的人，常常可以省略「的」。","sc":"「名词或代名词＋的＋名词」表示谁的东西。家人或很亲近的人，常常可以省略「的」。"},"ex":[{"c":"這是我的書。","s":"这是我的书。","es":"Este es mi libro.","en":"This is my book.","p":"zhè shì wǒ de shū."},{"c":"我媽媽很忙。","s":"我妈妈很忙。","es":"Mi mamá está ocupada.","en":"My mom is very busy.","p":"wǒ mā ma hěn máng."}]},{"id":"1-2-1","b":1,"l":2,"k":"","t":{"es":"Modificador + 的","en":"Modifier Marker 的 de","ens":"Modifier Marker 的 de","tc":"修飾名詞的「的」","sc":"修饰名词的「的」"},"d":{"es":"的 une un modificador (adjetivo o frase) con el sustantivo que describe. El modificador siempre va delante del sustantivo.","en":"的 links a modifier (an adjective or a phrase) to the noun it describes. The modifier always comes before the noun.","tc":"「的」連接修飾語（形容詞或一段話）和它說明的名詞。修飾語一定放在名詞前面。","sc":"「的」连接修饰语（形容词或一段话）和它说明的名词。修饰语一定放在名词前面。"},"ex":[{"c":"她是一個很好的老師。","s":"她是一个很好的老师。","es":"Ella es una muy buena profesora.","en":"She is a very good teacher.","p":"tā shì yí ge hěn hǎo de lǎo shī."}]},{"id":"1-2-2","b":1,"l":2,"k":"","t":{"es":"Tener con 有","en":"有 yǒu possessive","ens":"有 yǒu possessive","tc":"「有」：擁有","sc":"「有」：拥有"},"d":{"es":"有 = tener. Su negación es 沒有 (nunca 不有).","en":"有 means 'to have'. Its negation is 沒有 (never 不有).","tc":"「有」是「擁有」的意思。否定要說「沒有」，不能說「不有」。","sc":"「有」是「拥有」的意思。否定要说「没有」，不能说「不有」。"},"ex":[{"c":"我有兩個姐姐，沒有哥哥。","s":"我有两个姐姐，没有哥哥。","es":"Tengo dos hermanas mayores y ningún hermano mayor.","en":"I have two older sisters and no older brother.","p":"wǒ yǒu liǎng ge jiě jie, méi yǒu gē ge."}]},{"id":"1-2-3","b":1,"l":2,"k":"","t":{"es":"Todos con 都","en":"都 dōu totality","ens":"都 dōu totality","tc":"「都」：全部","sc":"「都」：全部"},"d":{"es":"都 = todos / ambos. Va antes del verbo y se refiere a lo que aparece antes de él.","en":"都 means 'all' or 'both'. It goes before the verb and refers to what comes before it.","tc":"「都」是「全部」「都是」的意思。放在動詞前面，指的是它前面提到的人或事。","sc":"「都」是「全部」「都是」的意思。放在动词前面，指的是它前面提到的人或事。"},"ex":[{"c":"我們都是學生。","s":"我们都是学生。","es":"Todos somos estudiantes.","en":"We are all students.","p":"wǒ men dōu shì xué shēng."}]},{"id":"1-2-4","b":1,"l":2,"k":"clasificador clasificadores medida contar cantidad measure word classifier counter 量詞 clasificador clasificadores medida contar cantidad measure word classifier counter 量词","t":{"es":"Clasificadores 個 y 張","en":"Measures 個 ge and 張 zhāng","ens":"Measures 个 ge and 张 zhāng","tc":"量詞：個、張","sc":"量词：个、张"},"d":{"es":"Estructura: número + clasificador + sustantivo. 個 es el clasificador más general; 張 se usa para cosas planas (papel, mesa, boleto, foto).","en":"Pattern: number + measure word + noun. 個 is the most general measure word; 張 is for flat things (paper, tables, tickets, photos).","tc":"句型是「數字＋量詞＋名詞」。「個」最常用；「張」用在平平的東西，例如紙、桌子、票、照片。","sc":"句型是「数字＋量词＋名词」。「个」最常用；「张」用在平平的东西，例如纸、桌子、票、照片。"},"ex":[{"c":"三個人、一張桌子","s":"三个人、一张桌子","es":"tres personas, una mesa","en":"three people, one table","p":"sān ge rén, yì zhāng zhuō zi"}]},{"id":"1-3-0","b":1,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 tiempo momento orden secuencia time order sequence 时间 顺序 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Palabras de tiempo","en":"Placement of Time Words","ens":"Placement of Time Words","tc":"時間詞的位置","sc":"时间词的位置"},"d":{"es":"Las palabras de tiempo van antes del verbo (después del sujeto o al inicio de la oración), nunca al final.","en":"Time words go before the verb (after the subject or at the start of the sentence), never at the end.","tc":"時間詞放在動詞前面（主詞後面或句首），不放在句尾。","sc":"时间词放在动词前面（主词后面或句首），不放在句尾。"},"ex":[{"c":"我明天去台北。","s":"我明天去台北。","es":"Mañana voy a Taipéi.","en":"I'm going to Taipei tomorrow.","p":"wǒ míng tiān qù tái běi."}]},{"id":"1-3-1","b":1,"l":3,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Ir a hacer algo con 去","en":"To Go Do Something with 去 qù","ens":"To Go Do Something with 去 qù","tc":"「去」＋地方＋動作","sc":"「去」＋地方＋动作"},"d":{"es":"去 + lugar + verbo: ir a un lugar para hacer algo.","en":"去 + place + verb means going somewhere to do something.","tc":"「去＋地方＋動詞」表示到某個地方做某件事。","sc":"「去＋地方＋动词」表示到某个地方做某件事。"},"ex":[{"c":"我去圖書館看書。","s":"我去图书馆看书。","es":"Voy a la biblioteca a leer.","en":"I'm going to the library to read.","p":"wǒ qù tú shū guǎn kàn shū."}]},{"id":"1-3-2","b":1,"l":3,"k":"","t":{"es":"Oraciones con tema","en":"Topic Sentences","ens":"Topic Sentences","tc":"主題句","sc":"主题句"},"d":{"es":"Se puede poner primero el tema (algo ya conocido) y luego comentarlo. El objeto pasa al inicio de la oración.","en":"You can start with the topic (something already known) and then comment on it. The object moves to the front of the sentence.","tc":"可以先說出大家已經知道的話題，再說明它。這時受詞會移到句子前面。","sc":"可以先说出大家已经知道的话题，再说明它。这时受词会移到句子前面。"},"ex":[{"c":"中文我會說，日文我不會說。","s":"中文我会说，日文我不会说。","es":"El chino sí sé hablarlo; el japonés no.","en":"Chinese I can speak; Japanese I can't.","p":"zhōng wén wǒ huì shuō, rì wén wǒ bú huì shuō."}]},{"id":"1-3-3","b":1,"l":3,"k":"","t":{"es":"Orden de 也, 都, 常","en":"The Word Order of Adverbs 也 yě,都 dōu and 常 cháng","ens":"The Word Order of Adverbs 也 yě,都 dōu and 常 cháng","tc":"副詞順序：也、都、常","sc":"副词顺序：也、都、常"},"d":{"es":"Los adverbios 也, 都 y 常 van después del sujeto y antes del verbo. Si aparecen 也 y 都 juntos, 也 va primero.","en":"The adverbs 也, 都 and 常 go after the subject and before the verb. When 也 and 都 appear together, 也 comes first.","tc":"「也」「都」「常」放在主詞後面、動詞前面。「也」和「都」一起用時，「也」在前面。","sc":"「也」「都」「常」放在主词后面、动词前面。「也」和「都」一起用时，「也」在前面。"},"ex":[{"c":"我們也都喜歡吃麵。","s":"我们也都喜欢吃面。","es":"A nosotros también nos gusta a todos comer fideos.","en":"We all like eating noodles too.","p":"wǒ men yě dōu xǐ huān chī miàn."}]},{"id":"1-3-4","b":1,"l":3,"k":"sugerencia proposición suggestion 建議 sugerencia proposición suggestion 建议","t":{"es":"Sugerencias con 吧","en":"Making Suggestions 吧 ba","ens":"Making Suggestions 吧 ba","tc":"用「吧」提出建議","sc":"用「吧」提出建议"},"d":{"es":"吧 al final de la oración hace una sugerencia o invitación suave: «vamos a…», «¿qué tal si…?».","en":"Adding 吧 at the end makes a gentle suggestion or invitation: 'let's …', 'how about …?'.","tc":"句尾加「吧」，語氣比較輕，是在提議或邀請：「我們……吧」。","sc":"句尾加「吧」，语气比较轻，是在提议或邀请：「我们……吧」。"},"ex":[{"c":"我們去吃飯吧。","s":"我们去吃饭吧。","es":"Vamos a comer.","en":"Let's go eat.","p":"wǒ men qù chī fàn ba."}]},{"id":"1-4-0","b":1,"l":4,"k":"clasificador clasificadores medida contar cantidad measure word classifier counter 量詞 clasificador clasificadores medida contar cantidad measure word classifier counter 量词","t":{"es":"Clasificadores 塊, 杯, 支, 種","en":"Measures 塊 kuài, 杯 bēi,支 zhī and 種 zhǒng","ens":"Measures 块 kuài, 杯 bēi,支 zhī and 种 zhǒng","tc":"量詞：塊、杯、支、種","sc":"量词：块、杯、支、种"},"d":{"es":"塊 para dinero; 杯 para bebidas en vaso o taza; 支 para objetos largos y delgados (lápiz, bolígrafo); 種 = tipo, clase.","en":"塊 is for money; 杯 for drinks in a cup or glass; 支 for long, thin objects (pens, pencils); 種 means 'kind, type'.","tc":"「塊」用在錢；「杯」用在杯子裝的飲料；「支」用在細長的東西（筆）；「種」是「種類」。","sc":"「块」用在钱；「杯」用在杯子装的饮料；「支」用在细长的东西（笔）；「种」是「种类」。"},"ex":[{"c":"一杯咖啡、兩支筆、三種水果、五十塊","s":"一杯咖啡、两支笔、三种水果、五十块","es":"una taza de café, dos bolígrafos, tres tipos de fruta, cincuenta dólares","en":"a cup of coffee, two pens, three kinds of fruit, fifty dollars","p":"yì bēi kā fēi, liǎng zhī bǐ, sān zhǒng shuǐ guǒ, wǔ shí kuài"}]},{"id":"1-4-1","b":1,"l":4,"k":"","t":{"es":"Hacer algo por alguien: 幫","en":"Preposition 幫 bāng on behalf of","ens":"Preposition 帮 bāng on behalf of","tc":"「幫」：替別人做","sc":"「帮」：替别人做"},"d":{"es":"幫 + persona + verbo = hacer algo por alguien / en su lugar.","en":"幫 + person + verb means doing something for someone.","tc":"「幫＋人＋動詞」表示替某人做某件事。","sc":"「帮＋人＋动词」表示替某人做某件事。"},"ex":[{"c":"我幫你買咖啡。","s":"我帮你买咖啡。","es":"Te compro el café.","en":"I'll buy you a coffee.","p":"wǒ bāng nǐ mǎi kā fēi."}]},{"id":"1-4-2","b":1,"l":4,"k":"","t":{"es":"Omitir el sustantivo: …的","en":"的 De-phrase with the Head Noun Omitted","ens":"的 De-phrase with the Head Noun Omitted","tc":"省略名詞的「的」","sc":"省略名词的「的」"},"d":{"es":"Cuando ya se sabe de qué sustantivo se habla, se omite y queda «modificador + 的»: «el/la/los de…».","en":"When it's clear what noun is meant, you can drop it and keep 'modifier + 的': 'the one that is …'.","tc":"已經知道在說什麼東西時，可以把名詞省略，只留下「修飾語＋的」，意思是「……的那個」。","sc":"已经知道在说什么东西时，可以把名词省略，只留下「修饰语＋的」，意思是「……的那个」。"},"ex":[{"c":"這杯是我的。","s":"这杯是我的。","es":"Esta taza es la mía.","en":"This cup is mine.","p":"zhè bēi shì wǒ de."},{"c":"紅色的比較貴。","s":"红色的比较贵。","es":"El rojo es más caro.","en":"The red one is more expensive.","p":"hóng sè de bǐ jiào guì."}]},{"id":"1-4-3","b":1,"l":4,"k":"","t":{"es":"Demasiado: 太…了","en":"太…了 tài…le overly","ens":"太…了 tài…le overly","tc":"太……了","sc":"太……了"},"d":{"es":"太 + adjetivo + 了 = demasiado… (a veces solo exclamación: «¡qué… !»).","en":"太 + adjective + 了 means 'too …' (sometimes just an exclamation: 'so …!').","tc":"「太＋形容詞＋了」是「太……了」，有時只是感嘆，意思是「真是……啊」。","sc":"「太＋形容词＋了」是「太……了」，有时只是感叹，意思是「真是……啊」。"},"ex":[{"c":"這個太貴了！","s":"这个太贵了！","es":"¡Esto es demasiado caro!","en":"This is too expensive!","p":"zhè ge tài guì le!"}]},{"id":"1-4-4","b":1,"l":4,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Poder con 能","en":"能 néng capability","ens":"能 néng capability","tc":"「能」：可以、有能力","sc":"「能」：可以、有能力"},"d":{"es":"能 expresa capacidad o posibilidad: «puedo», «es posible». Negación: 不能.","en":"能 expresses ability or possibility ('can'). The negative is 不能.","tc":"「能」表示有能力或有可能做某件事。否定是「不能」。","sc":"「能」表示有能力或有可能做某件事。否定是「不能」。"},"ex":[{"c":"你明天能來嗎？","s":"你明天能来吗？","es":"¿Puedes venir mañana?","en":"Can you come tomorrow?","p":"nǐ míng tiān néng lái ma?"}]},{"id":"1-4-5","b":1,"l":4,"k":"","t":{"es":"Y pico: 多","en":"多 duō …and more","ens":"多 duō …and more","tc":"數字後面的「多」","sc":"数字后面的「多」"},"d":{"es":"Después de un número, 多 significa «y pico, más de». También se usa en preguntas de grado: 多大, 多高, 多久.","en":"After a number, 多 means 'more than'. It is also used in degree questions: 多大, 多高, 多久.","tc":"數字後面加「多」，意思是「超過」。也用在問程度的問句：多大、多高、多久。","sc":"数字后面加「多」，意思是「超过」。也用在问程度的问句：多大、多高、多久。"},"ex":[{"c":"我有三十多本書。","s":"我有三十多本书。","es":"Tengo más de treinta libros.","en":"I have more than thirty books.","p":"wǒ yǒu sān shí duō běn shū."}]},{"id":"1-5-0","b":1,"l":5,"k":"","t":{"es":"Un poco: 有一點","en":"有一點 yǒu yìdiǎn slightly","ens":"有一点 yǒu yìdiǎn slightly","tc":"有一點","sc":"有一点"},"d":{"es":"有一點 + adjetivo = un poco, algo. Suele expresar algo que no es del todo agradable.","en":"有一點 + adjective means 'a little, somewhat', usually about something not quite pleasant.","tc":"「有一點＋形容詞」是「有點……」，通常表示不太滿意的感覺。","sc":"「有一点＋形容词」是「有点……」，通常表示不太满意的感觉。"},"ex":[{"c":"今天有一點冷。","s":"今天有一点冷。","es":"Hoy hace un poco de frío.","en":"It's a little cold today.","p":"jīn tiān yǒu yì diǎn lěng."}]},{"id":"1-5-1","b":1,"l":5,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Verbo + 得 + adjetivo","en":"Complement Marker 得 de","ens":"Complement Marker 得 de","tc":"程度補語「得」","sc":"程度补语「得」"},"d":{"es":"Verbo + 得 + adjetivo describe cómo se hace la acción. Si hay objeto, se repite el verbo.","en":"Verb + 得 + adjective describes how an action is done. If there is an object, the verb is repeated.","tc":"「動詞＋得＋形容詞」說明動作做得怎麼樣。如果有受詞，要先重複一次動詞。","sc":"「动词＋得＋形容词」说明动作做得怎么样。如果有受词，要先重复一次动词。"},"ex":[{"c":"他跑得很快。","s":"他跑得很快。","es":"Corre muy rápido.","en":"He runs very fast.","p":"tā pǎo de hěn kuài."},{"c":"他說中文說得很好。","s":"他说中文说得很好。","es":"Habla muy bien el chino.","en":"He speaks Chinese very well.","p":"tā shuō zhōng wén shuō de hěn hǎo."}]},{"id":"1-5-2","b":1,"l":5,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Saber hacer: 會","en":"Acquired Skills 會 huì","ens":"Acquired Skills 会 huì","tc":"「會」：學會的能力","sc":"「会」：学会的能力"},"d":{"es":"會 = saber hacer algo (habilidad aprendida). Negación: 不會.","en":"會 means knowing how to do something (a learned skill). The negative is 不會.","tc":"「會」表示學過、懂得怎麼做。否定是「不會」。","sc":"「会」表示学过、懂得怎么做。否定是「不会」。"},"ex":[{"c":"我會說中文。","s":"我会说中文。","es":"Sé hablar chino.","en":"I can speak Chinese.","p":"wǒ huì shuō zhōng wén."}]},{"id":"1-5-3","b":1,"l":5,"k":"","t":{"es":"Destino con 到","en":"Destination Marker 到 dào","ens":"Destination Marker 到 dào","tc":"「到」：到達的地方","sc":"「到」：到达的地方"},"d":{"es":"Verbo de movimiento + 到 + lugar: llegar hasta / ir hasta. 到 marca el destino.","en":"Movement verb + 到 + place means reaching or going as far as a place; 到 marks the destination.","tc":"「移動動詞＋到＋地方」表示去到、走到某個地方，「到」標示目的地。","sc":"「移动动词＋到＋地方」表示去到、走到某个地方，「到」标示目的地。"},"ex":[{"c":"他們開車到高雄。","s":"他们开车到高雄。","es":"Ellos van en coche hasta Kaohsiung.","en":"They drive to Kaohsiung.","p":"tā men kāi chē dào gāo xióng."}]},{"id":"1-6-0","b":1,"l":6,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Ubicación con 在","en":"Locative Marker 在 zài","ens":"Locative Marker 在 zài","tc":"「在」：在哪裡","sc":"「在」：在哪里"},"d":{"es":"Sujeto + 在 + lugar indica dónde está algo o alguien (algo que ya se conoce).","en":"Subject + 在 + place tells where someone or something is (something already known).","tc":"「主詞＋在＋地方」說明某人或某物在哪裡（說的是已經知道的人或東西）。","sc":"「主词＋在＋地方」说明某人或某物在哪里（说的是已经知道的人或东西）。"},"ex":[{"c":"我的手機在桌子上。","s":"我的手机在桌子上。","es":"Mi celular está sobre la mesa.","en":"My phone is on the table.","p":"wǒ de shǒu jī zài zhuō zi shàng."}]},{"id":"1-6-1","b":1,"l":6,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Hay: lugar + 有","en":"Existential Sentence with 有 yǒu","ens":"Existential Sentence with 有 yǒu","tc":"「有」：存在句","sc":"「有」：存在句"},"d":{"es":"Lugar + 有 + cosa/persona = en ese lugar hay algo. Contraste: 在 (algo conocido está en…) vs. 有 (en un lugar hay algo).","en":"Place + 有 + thing/person means 'there is …' in that place. Contrast: 在 (a known thing is at …) vs. 有 (a place has …).","tc":"「地方＋有＋東西／人」表示那裡有什麼。比較：「在」是已知的東西在哪裡；「有」是某個地方有什麼。","sc":"「地方＋有＋东西／人」表示那里有什么。比较：「在」是已知的东西在哪里；「有」是某个地方有什么。"},"ex":[{"c":"桌子上有一本書。","s":"桌子上有一本书。","es":"Sobre la mesa hay un libro.","en":"There is a book on the table.","p":"zhuō zi shàng yǒu yì běn shū."}]},{"id":"1-6-2","b":1,"l":6,"k":"","t":{"es":"Suavizar: V(一)V","en":"Softened Action V（一）V","ens":"Softened Action V（一）V","tc":"動詞重複：V(一)V","sc":"动词重复：V(一)V"},"d":{"es":"Repetir el verbo (V一V / VV) suaviza la acción: «un poquito», «probar». Se usa con acciones cortas.","en":"Repeating the verb (V一V / VV) softens the action: 'a little', 'give it a try'. It is used with short actions.","tc":"動詞重複（V一V、VV）讓語氣變輕，意思是「稍微做一下」「試試看」，多用在短短的動作。","sc":"动词重复（V一V、VV）让语气变轻，意思是「稍微做一下」「试试看」，多用在短短的动作。"},"ex":[{"c":"你看(一)看。","s":"你看(一)看。","es":"Echa un vistazo.","en":"Take a look.","p":"nǐ kàn (yī) kàn."},{"c":"讓我想一想。","s":"让我想一想。","es":"Déjame pensarlo un momento.","en":"Let me think about it for a moment.","p":"ràng wǒ xiǎng yì xiǎng."}]},{"id":"1-6-3","b":1,"l":6,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Negar con 不是","en":"不是 búshì Negation","ens":"不是 búshì Negation","tc":"「不是」：否定名詞","sc":"「不是」：否定名词"},"d":{"es":"不是 niega 是 y sirve para corregir: «no es X (sino Y)». Se usa para negar sustantivos.","en":"不是 negates 是 and is used to correct: 'it's not X, it's Y'. It negates nouns.","tc":"「不是」否定「是」，也用來更正：「不是 X，是 Y」。用來否定名詞。","sc":"「不是」否定「是」，也用来更正：「不是 X，是 Y」。用来否定名词。"},"ex":[{"c":"我不是老師，我是學生。","s":"我不是老师，我是学生。","es":"No soy profesor, soy estudiante.","en":"I'm not a teacher, I'm a student.","p":"wǒ bú shì lǎo shī, wǒ shì xué shēng."}]},{"id":"1-6-4","b":1,"l":6,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Lugar de la actividad","en":"Location of an Activity","ens":"Location of an Activity","tc":"動作發生的地點","sc":"动作发生的地点"},"d":{"es":"El lugar donde ocurre la actividad va con 在 antes del verbo: 在 + lugar + verbo.","en":"The place where an activity happens is marked with 在 + place, before the verb.","tc":"動作發生的地點用「在＋地方」，放在動詞前面。","sc":"动作发生的地点用「在＋地方」，放在动词前面。"},"ex":[{"c":"我在家看書。","s":"我在家看书。","es":"Leo en casa.","en":"I read at home.","p":"wǒ zài jiā kàn shū."}]},{"id":"1-7-0","b":1,"l":7,"k":"tiempo momento orden secuencia time order sequence 時間 順序 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 tiempo momento orden secuencia time order sequence 时间 顺序 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Tiempo y lugar","en":"Time and Place of Events","ens":"Time and Place of Events","tc":"時間和地點的順序","sc":"时间和地点的顺序"},"d":{"es":"Orden básico: sujeto + tiempo + lugar + verbo.","en":"Basic order: subject + time + place + verb.","tc":"基本順序是：主詞＋時間＋地點＋動詞。","sc":"基本顺序是：主词＋时间＋地点＋动词。"},"ex":[{"c":"我昨天在家看電影。","s":"我昨天在家看电影。","es":"Ayer vi una película en casa.","en":"I watched a movie at home yesterday.","p":"wǒ zuó tiān zài jiā kàn diàn yǐng."}]},{"id":"1-7-1","b":1,"l":7,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"De A a B: 從…到…","en":"從 cóng…到 dào… from A to B","ens":"从 cóng…到 dào… from A to B","tc":"從……到……","sc":"从……到……"},"d":{"es":"從 A 到 B = de A a B (para lugares o tiempos).","en":"從 A 到 B means 'from A to B', for places or times.","tc":"「從 A 到 B」表示從 A 到 B，可以用在地點或時間。","sc":"「从 A 到 B」表示从 A 到 B，可以用在地点或时间。"},"ex":[{"c":"從台北到高雄","s":"从台北到高雄","es":"de Taipéi a Kaohsiung","en":"from Taipei to Kaohsiung","p":"cóng tái běi dào gāo xióng"},{"c":"我從九點到十二點上課。","s":"我从九点到十二点上课。","es":"Tengo clase de nueve a doce.","en":"I have class from nine to twelve.","p":"wǒ cóng jiǔ diǎn dào shí èr diǎn shàng kè."}]},{"id":"1-7-2","b":1,"l":7,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Acción en curso: 在","en":"Progressive, On-going Actions 在 zài","ens":"Progressive, On-going Actions 在 zài","tc":"正在做：在","sc":"正在做：在"},"d":{"es":"(正)在 + verbo = estar haciendo algo (acción en curso). Puede terminar con 呢.","en":"(正)在 + verb shows an action in progress ('be doing'). 呢 can be added at the end.","tc":"「(正)在＋動詞」表示動作正在進行。句尾可以加「呢」。","sc":"「(正)在＋动词」表示动作正在进行。句尾可以加「呢」。"},"ex":[{"c":"我在吃飯。","s":"我在吃饭。","es":"Estoy comiendo.","en":"I'm eating.","p":"wǒ zài chī fàn."}]},{"id":"1-7-3","b":1,"l":7,"k":"siempre nunca frecuencia always never frequency 經常 從來 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Cada: 每","en":"每 měi each and every","ens":"每 měi each and every","tc":"「每」：每一個","sc":"「每」：每一个"},"d":{"es":"每 + clasificador / palabra de tiempo = cada, todos los. Suele ir con 都 antes del verbo.","en":"每 + measure word/time word means 'every, each'. It often goes with 都 before the verb.","tc":"「每＋量詞／時間詞」是「每一……」。常常和「都」一起放在動詞前面。","sc":"「每＋量词／时间词」是「每一……」。常常和「都」一起放在动词前面。"},"ex":[{"c":"我每天都喝咖啡。","s":"我每天都喝咖啡。","es":"Tomo café todos los días.","en":"I drink coffee every day.","p":"wǒ měi tiān dōu hē kā fēi."}]},{"id":"1-7-4","b":1,"l":7,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Permiso con 可以","en":"可以 kěyǐ permission","ens":"可以 kěyǐ permission","tc":"「可以」：許可","sc":"「可以」：许可"},"d":{"es":"可以 = permiso: «se puede / puedo». Para pedir permiso: 可以…嗎？ Prohibición: 不可以.","en":"可以 expresses permission ('may, can'). To ask for permission: 可以…嗎？ Prohibition: 不可以.","tc":"「可以」表示可以做某事（許可）。問許可：「可以……嗎？」。不可以：「不可以」。","sc":"「可以」表示可以做某事（许可）。问许可：「可以……吗？」。不可以：「不可以」。"},"ex":[{"c":"這裡可以拍照嗎？","s":"这里可以拍照吗？","es":"¿Se pueden tomar fotos aquí?","en":"Can we take photos here?","p":"zhè lǐ kě yǐ pāi zhào ma?"}]},{"id":"1-8-0","b":1,"l":8,"k":"","t":{"es":"Compañía con 跟","en":"Companionship with 跟 gēn","ens":"Companionship with 跟 gēn","tc":"「跟」：一起做","sc":"「跟」：一起做"},"d":{"es":"A 跟 B 一起 + verbo = hacer algo con B.","en":"A 跟 B 一起 + verb means doing something together with B.","tc":"「A 跟 B 一起＋動詞」表示和 B 一起做某件事。","sc":"「A 跟 B 一起＋动词」表示和 B 一起做某件事。"},"ex":[{"c":"我跟朋友一起去看電影。","s":"我跟朋友一起去看电影。","es":"Voy al cine con mis amigos.","en":"I go to the movies with my friends.","p":"wǒ gēn péng yǒu yì qǐ qù kàn diàn yǐng."}]},{"id":"1-8-1","b":1,"l":8,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Cómo con 怎麼","en":"Asking How with 怎麼 zěnme","ens":"Asking How with 怎么 zěnme","tc":"「怎麼」：怎樣做","sc":"「怎么」：怎样做"},"d":{"es":"怎麼 + verbo pregunta por la manera o el método de hacer algo.","en":"怎麼 + verb asks how to do something (the method).","tc":"「怎麼＋動詞」問做某件事的方法或方式。","sc":"「怎么＋动词」问做某件事的方法或方式。"},"ex":[{"c":"這個字怎麼念？","s":"这个字怎么念？","es":"¿Cómo se pronuncia este carácter?","en":"How do you pronounce this character?","p":"zhè ge zì zěn me niàn?"},{"c":"去台北車站怎麼走？","s":"去台北车站怎么走？","es":"¿Cómo se va a la estación de Taipéi?","en":"How do I get to Taipei Main Station?","p":"qù tái běi chē zhàn zěn me zǒu?"}]},{"id":"1-8-2","b":1,"l":8,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Comparación con 比較","en":"Implicit Comparison with 比較 bǐjiào","ens":"Implicit Comparison with 比较 bǐjiào","tc":"「比較」：比較級","sc":"「比较」：比较级"},"d":{"es":"比較 + adjetivo/verbo = «más» o «relativamente»; es una comparación implícita, sin decir con qué se compara.","en":"比較 + adjective/verb means 'more …' or 'relatively …'. It is an implicit comparison; you don't say what it's compared to.","tc":"「比較＋形容詞／動詞」是「比較……」，不用說出跟誰比，是隱含的比較。","sc":"「比较＋形容词／动词」是「比较……」，不用说出跟谁比，是隐含的比较。"},"ex":[{"c":"我比較喜歡喝茶。","s":"我比较喜欢喝茶。","es":"Prefiero tomar té.","en":"I prefer drinking tea.","p":"wǒ bǐ jiào xǐ huān hē chá."}]},{"id":"1-8-3","b":1,"l":8,"k":"","t":{"es":"Ambas cualidades: 又…又…","en":"又 yòu…又 yòu…… both A and B","ens":"又 yòu…又 yòu…… both A and B","tc":"又……又……","sc":"又……又……"},"d":{"es":"又 A 又 B = a la vez A y B (dos cualidades juntas).","en":"又 A 又 B means both A and B at the same time (two qualities together).","tc":"「又 A 又 B」表示同時有 A 和 B 兩個特點。","sc":"「又 A 又 B」表示同时有 A 和 B 两个特点。"},"ex":[{"c":"這家的菜又好吃又便宜。","s":"这家的菜又好吃又便宜。","es":"La comida de este lugar es rica y barata.","en":"The food at this place is both tasty and cheap.","p":"zhè jiā de cài yòu hǎo chī yòu pián yí."}]},{"id":"1-8-4","b":1,"l":8,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Comparar con 比","en":"Comparison with 比 bǐ","ens":"Comparison with 比 bǐ","tc":"比較句：A 比 B","sc":"比较句：A 比 B"},"d":{"es":"A 比 B + adjetivo = A es más… que B. Con 比 no se usa 很. Para indicar la diferencia: 一點 / 多了 / 三歲, etc.","en":"A 比 B + adjective means A is more … than B. Don't use 很 with 比. To say how much the difference is, add 一點 / 多了 / an amount.","tc":"「A 比 B＋形容詞」表示 A 比 B 更……。用「比」的時候不加「很」。要說差多少，可以加「一點」「多了」或數量。","sc":"「A 比 B＋形容词」表示 A 比 B 更……。用「比」的时候不加「很」。要说差多少，可以加「一点」「多了」或数量。"},"ex":[{"c":"哥哥比我高。","s":"哥哥比我高。","es":"Mi hermano mayor es más alto que yo.","en":"My older brother is taller than I am.","p":"gē ge bǐ wǒ gāo."},{"c":"他比我大三歲。","s":"他比我大三岁。","es":"Es tres años mayor que yo.","en":"He is three years older than I am.","p":"tā bǐ wǒ dà sān suì."}]},{"id":"1-9-0","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Momento vs. duración","en":"Time-When vs. Time-Duration","ens":"Time-When vs. Time-Duration","tc":"時間點和時間長度","sc":"时间点和时间长度"},"d":{"es":"El momento (cuándo) va antes del verbo; la duración (cuánto tiempo) va después del verbo.","en":"When something happens (a point in time) goes before the verb; how long it lasts (duration) goes after the verb.","tc":"「什麼時候」（時間點）放在動詞前面；「多久」（時間長度）放在動詞後面。","sc":"「什么时候」（时间点）放在动词前面；「多久」（时间长度）放在动词后面。"},"ex":[{"c":"我八點上課。","s":"我八点上课。","es":"Tengo clase a las ocho.","en":"I have class at eight.","p":"wǒ bā diǎn shàng kè."},{"c":"我每天睡八個小時。","s":"我每天睡八个小时。","es":"Duermo ocho horas al día.","en":"I sleep eight hours a day.","p":"wǒ měi tiān shuì bā ge xiǎo shí."}]},{"id":"1-9-1","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Duración de la acción","en":"Time-Duration ‘for a period of time’","ens":"Time-Duration ‘for a period of time’","tc":"動作持續的時間","sc":"动作持续的时间"},"d":{"es":"Verbo + duración (+ 的 + objeto) indica cuánto tiempo dura la acción.","en":"Verb + duration (+ 的 + object) tells how long the action lasts.","tc":"「動詞＋時間長度（＋的＋受詞）」表示動作持續多久。","sc":"「动词＋时间长度（＋的＋受词）」表示动作持续多久。"},"ex":[{"c":"我想在台灣住三個月。","s":"我想在台湾住三个月。","es":"Quiero vivir tres meses en Taiwán.","en":"I'd like to live in Taiwan for three months.","p":"wǒ xiǎng zài tái wān zhù sān ge yuè."}]},{"id":"1-9-2","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Cuando: …的時候","en":"…的時候 de shíhòu when","ens":"…的时候 de shíhòu when","tc":"「……的時候」","sc":"「……的时候」"},"d":{"es":"Frase + 的時候 = cuando… (en el momento en que ocurre algo).","en":"Clause + 的時候 means 'when …' (at the time the action happens).","tc":"「一段話＋的時候」表示「當……的時候」，說明動作發生的那段時間。","sc":"「一段话＋的时候」表示「当……的时候」，说明动作发生的那段时间。"},"ex":[{"c":"我吃飯的時候不看手機。","s":"我吃饭的时候不看手机。","es":"Cuando como no miro el celular.","en":"I don't look at my phone when I eat.","p":"wǒ chī fàn de shí hòu bú kàn shǒu jī."}]},{"id":"1-9-3","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"A veces… a veces…","en":"有時候 yǒu shíhòu…有時候 yǒu shíhòu… sometimes … sometimes …","ens":"有时候 yǒu shíhòu…有时候 yǒu shíhòu… sometimes … sometimes …","tc":"有時候……有時候……","sc":"有时候……有时候……"},"d":{"es":"有時候 A，有時候 B = a veces A, a veces B.","en":"有時候 A，有時候 B means 'sometimes A, sometimes B'.","tc":"「有時候 A，有時候 B」表示有時候做 A，有時候做 B。","sc":"「有时候 A，有时候 B」表示有时候做 A，有时候做 B。"},"ex":[{"c":"我有時候喝茶，有時候喝咖啡。","s":"我有时候喝茶，有时候喝咖啡。","es":"A veces tomo té y a veces café.","en":"Sometimes I drink tea and sometimes coffee.","p":"wǒ yǒu shí hòu hē chá, yǒu shí hòu hē kā fēi."}]},{"id":"1-9-4","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Si…, entonces: 要是…就","en":"Condition and Consequence with 要是 yaoshi…就 jiu…","ens":"Condition and Consequence with 要是 yaoshi…就 jiu…","tc":"要是……就……","sc":"要是……就……"},"d":{"es":"要是 + condición，就 + resultado = si…, entonces…. 就 va antes del verbo.","en":"要是 + condition, 就 + result means 'if …, then …'. 就 goes before the verb.","tc":"「要是＋條件，就＋結果」表示「如果……就……」。「就」放在動詞前面。","sc":"「要是＋条件，就＋结果」表示「如果……就……」。「就」放在动词前面。"},"ex":[{"c":"要是下雨，我就不去。","s":"要是下雨，我就不去。","es":"Si llueve, no voy.","en":"If it rains, I won't go.","p":"yào shì xià yǔ, wǒ jiù bú qù."}]},{"id":"1-10-0","b":1,"l":10,"k":"","t":{"es":"Probar: V V 看","en":"V V 看 kàn to try and see","ens":"V V 看 kàn to try and see","tc":"動詞重複＋「看」","sc":"动词重复＋「看」"},"d":{"es":"Verbo repetido + 看 = probar a hacer algo para ver qué tal.","en":"Repeated verb + 看 means 'try doing it and see how it goes'.","tc":"「動詞重複＋看」表示試試看，看看會怎麼樣。","sc":"「动词重复＋看」表示试试看，看看会怎么样。"},"ex":[{"c":"這個很好吃，你吃吃看。","s":"这个很好吃，你吃吃看。","es":"Esto está muy rico, pruébalo.","en":"This is very tasty, try it.","p":"zhè ge hěn hǎo chī, nǐ chī chī kàn."}]},{"id":"1-10-1","b":1,"l":10,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"Adjetivos duplicados","en":"Intensification with Reduplicated State Verbs","ens":"Intensification with Reduplicated State Verbs","tc":"形容詞重疊","sc":"形容词重叠"},"d":{"es":"Duplicar un adjetivo (AA) lo hace más vívido; ya no se le pone 很. Para adjetivos de dos sílabas se usa AABB.","en":"Doubling an adjective (AA) makes it more vivid and no 很 is added. Two-syllable adjectives are doubled as AABB.","tc":"形容詞重疊（AA）會更生動，不再加「很」。兩個字的形容詞要重疊成 AABB。","sc":"形容词重叠（AA）会更生动，不再加「很」。两个字的形容词要重叠成 AABB。"},"ex":[{"c":"她的眼睛大大的。","s":"她的眼睛大大的。","es":"Tiene los ojos bien grandes.","en":"Her eyes are big and round.","p":"tā de yǎn jīng dà dà de."}]},{"id":"1-10-2","b":1,"l":10,"k":"","t":{"es":"Oración como modificador","en":"Clause as Modifiers of Nouns","ens":"Clause as Modifiers of Nouns","tc":"用一句話修飾名詞","sc":"用一句话修饰名词"},"d":{"es":"Una frase u oración + 的 + sustantivo: la descripción siempre va antes del sustantivo (como una cláusula de relativo).","en":"Clause + 的 + noun: the description always comes before the noun (like a relative clause).","tc":"「一句話＋的＋名詞」，說明的話一定放在名詞前面（像關係子句）。","sc":"「一句话＋的＋名词」，说明的话一定放在名词前面（像关系子句）。"},"ex":[{"c":"我喜歡的老師很年輕。","s":"我喜欢的老师很年轻。","es":"El profesor que me gusta es muy joven.","en":"The teacher I like is very young.","p":"wǒ xǐ huān de lǎo shī hěn nián qīng."}]},{"id":"1-10-3","b":1,"l":10,"k":"","t":{"es":"Cambio con 了","en":"Change in Situation with Sentential 了 le","ens":"Change in Situation with Sentential 了 le","tc":"句尾「了」：新的狀況","sc":"句尾「了」：新的状况"},"d":{"es":"了 al final de la oración indica un cambio de situación o un estado nuevo: «ya», «ahora ya».","en":"了 at the end of a sentence shows a change of situation or a new state: 'now …', 'already …'.","tc":"句尾的「了」表示情況改變、出現新的狀態：「已經……了」「現在……了」。","sc":"句尾的「了」表示情况改变、出现新的状态：「已经……了」「现在……了」。"},"ex":[{"c":"我現在不累了。","s":"我现在不累了。","es":"Ya no estoy cansado.","en":"I'm not tired anymore.","p":"wǒ xiàn zài bú lèi le."},{"c":"天黑了。","s":"天黑了。","es":"Ya oscureció.","en":"It's gotten dark.","p":"tiān hēi le."}]},{"id":"1-10-4","b":1,"l":10,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Causa y efecto","en":"Cause and Effect with 因為 yīnwèi，所以 suǒyǐ","ens":"Cause and Effect with 因为 yīnwèi，所以 suǒyǐ","tc":"因為……所以……","sc":"因为……所以……"},"d":{"es":"因為 introduce la causa y 所以 el resultado. En chino se suelen usar juntos.","en":"因為 gives the reason and 所以 the result. In Chinese the two are often used together.","tc":"「因為」說原因，「所以」說結果。中文常常兩個一起用。","sc":"「因为」说原因，「所以」说结果。中文常常两个一起用。"},"ex":[{"c":"因為下雨，所以我不去。","s":"因为下雨，所以我不去。","es":"Como llueve, no voy.","en":"Because it's raining, I'm not going.","p":"yīn wèi xià yǔ, suǒ yǐ wǒ bú qù."}]},{"id":"1-11-0","b":1,"l":11,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Venir a hacer: 來","en":"To Come to Do Something with 來 lái","ens":"To Come to Do Something with 来 lái","tc":"「來」＋動作","sc":"「来」＋动作"},"d":{"es":"來 + verbo = venir a hacer algo (desde el punto de vista del lugar donde se habla).","en":"來 + verb means coming (to where the speaker is) to do something.","tc":"「來＋動詞」表示來到說話的人所在的地方做某件事。","sc":"「来＋动词」表示来到说话的人所在的地方做某件事。"},"ex":[{"c":"他來台灣學中文。","s":"他来台湾学中文。","es":"Él viene a Taiwán a estudiar chino.","en":"He comes to Taiwan to study Chinese.","p":"tā lái tái wān xué zhōng wén."}]},{"id":"1-11-1","b":1,"l":11,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Más pronto: 就","en":"Sooner Than Expected with 就 jiù","ens":"Sooner Than Expected with 就 jiù","tc":"「就」：比預期早","sc":"「就」：比预期早"},"d":{"es":"Tiempo + 就 + verbo = la acción ocurre más temprano o más rápido de lo esperado.","en":"Time + 就 + verb shows the action happens earlier or sooner than expected.","tc":"「時間＋就＋動詞」表示動作比預期更早或更快發生。","sc":"「时间＋就＋动词」表示动作比预期更早或更快发生。"},"ex":[{"c":"我六點就起床了。","s":"我六点就起床了。","es":"Me levanté ya a las seis.","en":"I was already up at six.","p":"wǒ liù diǎn jiù qǐ chuáng le."}]},{"id":"1-11-2","b":1,"l":11,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Hay alguien que…","en":"Existential Subject with 有 yǒu","ens":"Existential Subject with 有 yǒu","tc":"「有」＋不確定的主詞","sc":"「有」＋不确定的主词"},"d":{"es":"有 + sujeto indefinido al inicio: «hay alguien/algo que…».","en":"Starting a sentence with 有 + an indefinite subject means 'there is someone/something that …'.","tc":"句首用「有＋不確定的人或東西」，意思是「有人／有東西……」。","sc":"句首用「有＋不确定的人或东西」，意思是「有人／有东西……」。"},"ex":[{"c":"有人找你。","s":"有人找你。","es":"Alguien te busca.","en":"Someone is looking for you.","p":"yǒu rén zhǎo nǐ."}]},{"id":"1-11-3","b":1,"l":11,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Usos de 會","en":"Different Types of 會 huì","ens":"Different Types of 会 huì","tc":"「會」的不同用法","sc":"「会」的不同用法"},"d":{"es":"會 también expresa probabilidad o futuro: «seguramente», «va a». No solo significa «saber hacer».","en":"Besides 'knowing how to', 會 also expresses probability or the future: 'will, is likely to'.","tc":"「會」除了「學會做某事」，也表示可能或將來：「應該會」「一定會」。","sc":"「会」除了「学会做某事」，也表示可能或将来：「应该会」「一定会」。"},"ex":[{"c":"明天會下雨。","s":"明天会下雨。","es":"Mañana va a llover.","en":"It will rain tomorrow.","p":"míng tiān huì xià yǔ."},{"c":"他會來嗎？","s":"他会来吗？","es":"¿Vendrá él?","en":"Will he come?","p":"tā huì lái ma?"}]},{"id":"1-11-4","b":1,"l":11,"k":"","t":{"es":"Omitir sustantivos","en":"Omitting Nouns at 2nd mention","ens":"Omitting Nouns at 2nd mention","tc":"第二次提到時省略名詞","sc":"第二次提到时省略名词"},"d":{"es":"Cuando el sustantivo ya se mencionó, la segunda vez se puede omitir.","en":"A noun that has already been mentioned can be omitted the second time.","tc":"已經提過的名詞，第二次說的時候可以省略。","sc":"已经提过的名词，第二次说的时候可以省略。"},"ex":[{"c":"這件太大了，有小的嗎？","s":"这件太大了，有小的吗？","es":"Esta es demasiado grande, ¿tiene una más pequeña?","en":"This one is too big. Do you have a smaller one?","p":"zhè jiàn tài dà le, yǒu xiǎo de ma?"}]},{"id":"1-12-0","b":1,"l":12,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Primero… luego: 先…再…","en":"先 xiān…再 zài… first…, and then …","ens":"先 xiān…再 zài… first…, and then …","tc":"先……再……","sc":"先……再……"},"d":{"es":"先 A，再 B = primero A, luego B.","en":"先 A，再 B means 'first A, then B'.","tc":"「先 A，再 B」表示先做 A，然後做 B。","sc":"「先 A，再 B」表示先做 A，然后做 B。"},"ex":[{"c":"我們先吃飯，再看電影。","s":"我们先吃饭，再看电影。","es":"Primero comemos y luego vemos una película.","en":"Let's eat first and then watch a movie.","p":"wǒ men xiān chī fàn, zài kàn diàn yǐng."}]},{"id":"1-12-1","b":1,"l":12,"k":"","t":{"es":"Enfatizar con 是…的","en":"To Focus with 是 shì…的 de…","ens":"To Focus with 是 shì…的 de…","tc":"是……的","sc":"是……的"},"d":{"es":"是…的 destaca el cuándo, dónde, cómo o con quién de una acción que ya ocurrió.","en":"是…的 emphasizes the time, place, manner or companion of an action that has already happened.","tc":"「是……的」用來強調已經發生的動作的時間、地點、方式或一起去的人。","sc":"「是……的」用来强调已经发生的动作的时间、地点、方式或一起去的人。"},"ex":[{"c":"我是昨天來的。","s":"我是昨天来的。","es":"Vine ayer.","en":"I came yesterday.","p":"wǒ shì zuó tiān lái de."},{"c":"我是坐高鐵來的。","s":"我是坐高铁来的。","es":"Vine en el tren de alta velocidad.","en":"I came by high-speed rail.","p":"wǒ shì zuò gāo tiě lái de."}]},{"id":"1-12-2","b":1,"l":12,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Después de: 以後","en":"以後 yǐhòu after…","ens":"以后 yǐhòu after…","tc":"「以後」","sc":"「以后」"},"d":{"es":"Tiempo / frase + 以後 = después de…. Solo, 以後 significa «en el futuro».","en":"Time/clause + 以後 means 'after …'. Used alone, 以後 means 'in the future'.","tc":"「時間／一段話＋以後」表示「在……之後」。單獨說「以後」是「未來」。","sc":"「时间／一段话＋以后」表示「在……之后」。单独说「以后」是「未来」。"},"ex":[{"c":"下課以後，我去吃飯。","s":"下课以后，我去吃饭。","es":"Después de clase voy a comer.","en":"After class, I'm going to eat.","p":"xià kè yǐ hòu, wǒ qù chī fàn."}]},{"id":"1-12-3","b":1,"l":12,"k":"","t":{"es":"好 / 難 + verbo","en":"Special Meanings of 好 hǎo/難 nán +Verbs","ens":"Special Meanings of 好 hǎo/难 nán +Verbs","tc":"「好／難＋動詞」","sc":"「好／难＋动词」"},"d":{"es":"好 + verbo = fácil / agradable de…: 好吃, 好看, 好用. 難 + verbo = difícil / desagradable de…: 難吃, 難看, 難用.","en":"好 + verb means easy or pleasant to … (好吃, 好看, 好用); 難 + verb means hard or unpleasant to … (難吃, 難看, 難用).","tc":"「好＋動詞」表示容易、好用或令人愉快（好吃、好看、好用）；「難＋動詞」表示不容易或不好（難吃、難看、難用）。","sc":"「好＋动词」表示容易、好用或令人愉快（好吃、好看、好用）；「难＋动词」表示不容易或不好（难吃、难看、难用）。"},"ex":[{"c":"這個手機很好用。","s":"这个手机很好用。","es":"Este celular es muy fácil de usar.","en":"This phone is very easy to use.","p":"zhè ge shǒu jī hěn hǎo yòng."},{"c":"這道菜很難吃。","s":"这道菜很难吃。","es":"Este platillo sabe mal.","en":"This dish tastes bad.","p":"zhè dào cài hěn nán chī."}]},{"id":"1-13-0","b":1,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"En cuanto: 一…就…","en":"一 yī…就 jiù… …as soon as…","ens":"一 yī…就 jiù… …as soon as…","tc":"一……就……","sc":"一……就……"},"d":{"es":"一 A 就 B = en cuanto A, B.","en":"一 A 就 B means 'as soon as A, B'.","tc":"「一 A 就 B」表示一做完 A，馬上就 B。","sc":"「一 A 就 B」表示一做完 A，马上就 B。"},"ex":[{"c":"他一下課就回家。","s":"他一下课就回家。","es":"En cuanto termina la clase, se va a casa.","en":"He goes home as soon as class ends.","p":"tā yí xià kè jiù huí jiā."}]},{"id":"1-13-1","b":1,"l":13,"k":"pasado completado terminado past completed finished perfective 完成 過去 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Acción completada: 了","en":"Completed Action with Verbal 了 le","ens":"Completed Action with Verbal 了 le","tc":"動作完成：「了」","sc":"动作完成：「了」"},"d":{"es":"Verbo + 了 indica que la acción se completó (no equivale a «pasado»). Suele haber una cantidad o complemento después.","en":"Verb + 了 shows the action is completed (it is not simply 'past tense'). It is usually followed by a quantity or other information.","tc":"「動詞＋了」表示動作已經完成，不等於過去式。後面通常有數量或其他補充說明。","sc":"「动词＋了」表示动作已经完成，不等于过去式。后面通常有数量或其他补充说明。"},"ex":[{"c":"我買了一本書。","s":"我买了一本书。","es":"Compré un libro.","en":"I bought a book.","p":"wǒ mǎi le yì běn shū."}]},{"id":"1-13-2","b":1,"l":13,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"不 vs. 沒","en":"不 Negation vs.沒 Negation","ens":"不 Negation vs.没 Negation","tc":"「不」和「沒」的差別","sc":"「不」和「没」的差别"},"d":{"es":"不 niega hábitos, presente, futuro y voluntad. 沒(有) niega que una acción haya ocurrido, y niega 有. Con 沒 no se usa 了.","en":"不 negates habits, the present, the future and will. 沒(有) negates that an action took place, and negates 有. Don't use 了 with 沒.","tc":"「不」用在習慣、現在、未來和意願；「沒(有)」用在否定過去沒發生的事，也否定「有」。用「沒」的時候不加「了」。","sc":"「不」用在习惯、现在、未来和意愿；「没(有)」用在否定过去没发生的事，也否定「有」。用「没」的时候不加「了」。"},"ex":[{"c":"我不喝咖啡。","s":"我不喝咖啡。","es":"No tomo café.","en":"I don't drink coffee.","p":"wǒ bù hē kā fēi."},{"c":"我昨天沒去學校。","s":"我昨天没去学校。","es":"Ayer no fui a la escuela.","en":"I didn't go to school yesterday.","p":"wǒ zuó tiān méi qù xué xiào."}]},{"id":"1-13-3","b":1,"l":13,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Pregunta + 都: cualquiera","en":"All-inclusive with Question Words","ens":"All-inclusive with Question Words","tc":"疑問詞＋都：全部","sc":"疑问词＋都：全部"},"d":{"es":"Pregunta + 都 / 也: «cualquiera, todo, nadie…». Con negación: 誰都不 / 什麼都沒.","en":"Question word + 都/也 means 'any, every, no one…'. Negative: 誰都不 / 什麼都沒.","tc":"「疑問詞＋都／也」表示「任何……都」。否定用「誰都不」「什麼都沒」。","sc":"「疑问词＋都／也」表示「任何……都」。否定用「谁都不」「什么都没」。"},"ex":[{"c":"誰都知道。","s":"谁都知道。","es":"Todo el mundo lo sabe.","en":"Everyone knows.","p":"shéi dōu zhī dào."},{"c":"我什麼都吃。","s":"我什么都吃。","es":"Como de todo.","en":"I eat anything.","p":"wǒ shén me dōu chī."}]},{"id":"1-13-4","b":1,"l":13,"k":"","t":{"es":"Más / menos de lo planeado","en":"More/less…Than Planned with 多 duō /少 shǎo＋ Verb…","ens":"More/less…Than Planned with 多 duō /少 shǎo＋ Verb…","tc":"多／少＋動詞","sc":"多／少＋动词"},"d":{"es":"多 / 少 + verbo + cantidad = más / menos de lo planeado (acción ya realizada).","en":"多/少 + verb + quantity means more/less than planned (the action has already happened).","tc":"「多／少＋動詞＋數量」表示比原本計畫的更多／更少（動作已經發生）。","sc":"「多／少＋动词＋数量」表示比原本计划的更多／更少（动作已经发生）。"},"ex":[{"c":"我多買了兩個。","s":"我多买了两个。","es":"Compré dos de más.","en":"I bought two extra.","p":"wǒ duō mǎi le liǎng ge."}]},{"id":"1-13-5","b":1,"l":13,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 negación negar negativa negation negative 否定 pregunta preguntar interrogativa question ask 疑问 问句 提问 negación negar negativa negation negative 否定","t":{"es":"¿Verdad? con 是不是","en":"是不是 shìbú shì is it true?","ens":"是不是 shìbú shì is it true?","tc":"是不是","sc":"是不是"},"d":{"es":"是不是 sirve para confirmar algo que se supone: «¿verdad que…?». Va antes del verbo o al final de la oración.","en":"是不是 is used to confirm something you assume: 'is it true that …?'. It goes before the verb or at the end.","tc":"「是不是」用來確認自己猜的事：「是不是……？」放在動詞前面或句尾。","sc":"「是不是」用来确认自己猜的事：「是不是……？」放在动词前面或句尾。"},"ex":[{"c":"你是不是累了？","s":"你是不是累了？","es":"¿Estás cansado, verdad?","en":"You're tired, aren't you?","p":"nǐ shì bú shì lèi le?"}]},{"id":"1-13-6","b":1,"l":13,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Igual que: 跟…一樣","en":"Comparison with 跟 gēn…一樣 yíyàng","ens":"Comparison with 跟 gēn…一样 yíyàng","tc":"跟……一樣","sc":"跟……一样"},"d":{"es":"A 跟 B 一樣 (+ adjetivo) = A es igual que B.","en":"A 跟 B 一樣 (+ adjective) means A is the same as B.","tc":"「A 跟 B 一樣（＋形容詞）」表示 A 和 B 一樣。","sc":"「A 跟 B 一样（＋形容词）」表示 A 和 B 一样。"},"ex":[{"c":"我的手機跟你的一樣。","s":"我的手机跟你的一样。","es":"Mi celular es igual al tuyo.","en":"My phone is the same as yours.","p":"wǒ de shǒu jī gēn nǐ de yí yàng."},{"c":"我跟他一樣高。","s":"我跟他一样高。","es":"Soy tan alto como él.","en":"I'm as tall as he is.","p":"wǒ gēn tā yí yàng gāo."}]},{"id":"1-14-0","b":1,"l":14,"k":"tiempo momento orden secuencia time order sequence 時間 順序 pasado completado terminado past completed finished perfective 完成 過去 tiempo momento orden secuencia time order sequence 时间 顺序 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Duración tras 了","en":"Time-Duration after Verbal 了 le","ens":"Time-Duration after Verbal 了 le","tc":"「了」後面的時間長度","sc":"「了」后面的时间长度"},"d":{"es":"Verbo + 了 + duración (+ 的 + objeto) = cuánto tiempo duró una acción ya terminada.","en":"Verb + 了 + duration (+ 的 + object) tells how long a finished action lasted.","tc":"「動詞＋了＋時間長度（＋的＋受詞）」表示已經做完的動作持續了多久。","sc":"「动词＋了＋时间长度（＋的＋受词）」表示已经做完的动作持续了多久。"},"ex":[{"c":"我昨天睡了八個小時。","s":"我昨天睡了八个小时。","es":"Ayer dormí ocho horas.","en":"I slept eight hours yesterday.","p":"wǒ zuó tiān shuì le bā ge xiǎo shí."}]},{"id":"1-14-1","b":1,"l":14,"k":"pasado completado terminado past completed finished perfective 完成 過去 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Doble 了: hasta ahora","en":"Completion-to-date with Double 了 le","ens":"Completion-to-date with Double 了 le","tc":"雙「了」：到現在","sc":"双「了」：到现在"},"d":{"es":"Verbo + 了 + cantidad + 了 = la acción lleva esa cantidad hasta ahora y todavía continúa.","en":"Verb + 了 + quantity + 了 means 'up to now' the action has lasted/amounted to that much, and it is still going on.","tc":"「動詞＋了＋數量＋了」表示到現在為止做了這麼久、這麼多，而且還在繼續。","sc":"「动词＋了＋数量＋了」表示到现在为止做了这么久、这么多，而且还在继续。"},"ex":[{"c":"我學中文學了兩年了。","s":"我学中文学了两年了。","es":"Llevo dos años estudiando chino.","en":"I've been studying Chinese for two years.","p":"wǒ xué zhōng wén xué le liǎng nián le."}]},{"id":"1-14-2","b":1,"l":14,"k":"","t":{"es":"Casi: 快…了","en":"快 kuài…了 le about to","ens":"快 kuài…了 le about to","tc":"快……了","sc":"快……了"},"d":{"es":"快 + verbo / adjetivo / hora + 了 = a punto de, ya casi.","en":"快 + verb/adjective/time + 了 means 'about to', 'almost'.","tc":"「快＋動詞／形容詞／時間＋了」表示快要、差不多了。","sc":"「快＋动词／形容词／时间＋了」表示快要、差不多了。"},"ex":[{"c":"快下雨了。","s":"快下雨了。","es":"Ya casi llueve.","en":"It's about to rain.","p":"kuài xià yǔ le."},{"c":"快十二點了。","s":"快十二点了。","es":"Ya casi son las doce.","en":"It's almost twelve o'clock.","p":"kuài shí èr diǎn le."}]},{"id":"1-14-3","b":1,"l":14,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Aún más: 更","en":"Comparison 更 gèng even more so","ens":"Comparison 更 gèng even more so","tc":"「更」：更加","sc":"「更」：更加"},"d":{"es":"更 + adjetivo = todavía más. Se compara con algo ya mencionado.","en":"更 + adjective means 'even more …'. It compares with something already mentioned.","tc":"「更＋形容詞」是「更加……」，是跟前面提過的事物比較。","sc":"「更＋形容词」是「更加……」，是跟前面提过的事物比较。"},"ex":[{"c":"這家比那家更好吃。","s":"这家比那家更好吃。","es":"Este lugar es todavía más rico que aquel.","en":"This place is even tastier than that one.","p":"zhè jiā bǐ nà jiā gèng hǎo chī."}]},{"id":"1-14-4","b":1,"l":14,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定","t":{"es":"No tan…: 沒有","en":"Inferior Comparison 沒有 méiyǒu…","ens":"Inferior Comparison 没有 méiyǒu…","tc":"A 沒有 B（那麼）……","sc":"A 没有 B（那么）……"},"d":{"es":"A 沒有 B (那麼) + adjetivo = A no es tan… como B.","en":"A 沒有 B (那麼) + adjective means A is not as … as B.","tc":"「A 沒有 B（那麼）＋形容詞」表示 A 不如 B。","sc":"「A 没有 B（那么）＋形容词」表示 A 不如 B。"},"ex":[{"c":"我沒有哥哥那麼高。","s":"我没有哥哥那么高。","es":"No soy tan alto como mi hermano.","en":"I'm not as tall as my brother.","p":"wǒ méi yǒu gē ge nà me gāo."}]},{"id":"1-15-0","b":1,"l":15,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Postura libre: lo que sea","en":"Non-committal Stance with Question Words","ens":"Non-committal Stance with Question Words","tc":"疑問詞：隨你喜歡","sc":"疑问词：随你喜欢"},"d":{"es":"Con pronombres interrogativos se expresa «lo que quieras»: 什麼…就 + verbo. Es una postura sin compromiso.","en":"Question words can express 'whatever you like': 什麼…就…. It signals no particular restriction.","tc":"用疑問詞可以表示「你想……就……」，是沒有特別限制的說法：什麼……就……。","sc":"用疑问词可以表示「你想……就……」，是没有特别限制的说法：什么……就……。"},"ex":[{"c":"你想喝什麼就點什麼。","s":"你想喝什么就点什么。","es":"Pide lo que quieras beber.","en":"Order whatever you'd like to drink.","p":"nǐ xiǎng hē shén me jiù diǎn shén me."}]},{"id":"1-15-1","b":1,"l":15,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Disponer con 把","en":"To Dispose of Something with 把 bǎ","ens":"To Dispose of Something with 把 bǎ","tc":"「把」字句","sc":"「把」字句"},"d":{"es":"把 + objeto (ya conocido) + verbo + complemento: se «dispone» del objeto y se dice qué se hace con él. El verbo no puede ir solo.","en":"把 + object (already known) + verb + complement means 'dealing with' the object, saying what is done to it. The verb can't stand alone.","tc":"「把＋受詞（已知的）＋動詞＋補充說明」表示處理某個東西、對它做什麼。動詞後面不能單獨出現。","sc":"「把＋受词（已知的）＋动词＋补充说明」表示处理某个东西、对它做什么。动词后面不能单独出现。"},"ex":[{"c":"請你把窗戶打開。","s":"请你把窗户打开。","es":"Por favor abre la ventana.","en":"Please open the window.","p":"qǐng nǐ bǎ chuāng hù dǎ kāi."}]},{"id":"1-15-2","b":1,"l":15,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Apenas hice… : V了…就…","en":"V 了 le…就 jiù… do…right after doing…","ens":"V 了 le…就 jiù… do…right after doing…","tc":"V 了……就……","sc":"V 了……就……"},"d":{"es":"V 了 A 就 B = en cuanto terminé A, hago B.","en":"V 了 A 就 B means 'right after finishing A, do B'.","tc":"「V 了 A 就 B」表示做完 A 以後，馬上做 B。","sc":"「V 了 A 就 B」表示做完 A 以后，马上做 B。"},"ex":[{"c":"我下了課就回家。","s":"我下了课就回家。","es":"En cuanto termine la clase me voy a casa.","en":"I'll go home right after class.","p":"wǒ xià le kè jiù huí jiā."}]},{"id":"1-15-3","b":1,"l":15,"k":"","t":{"es":"Un poco: 一點","en":"一點 yìdiǎn a bit","ens":"一点 yìdiǎn a bit","tc":"「一點」：一些","sc":"「一点」：一些"},"d":{"es":"Adjetivo + 一點 = un poco más (suaviza una petición). Verbo + 一點 = un poco de.","en":"Adjective + 一點 means 'a bit more …' and softens a request. Verb + 一點 means 'a little more'.","tc":"「形容詞＋一點」是「更……一些」，讓請求更客氣。「動詞＋一點」是「做多一些」。","sc":"「形容词＋一点」是「更……一些」，让请求更客气。「动词＋一点」是「做多一些」。"},"ex":[{"c":"這個便宜一點好嗎？","s":"这个便宜一点好吗？","es":"¿Podría ser un poco más barato?","en":"Could it be a little cheaper?","p":"zhè ge pián yí yì diǎn hǎo ma?"},{"c":"你多吃一點。","s":"你多吃一点。","es":"Come un poco más.","en":"Eat a little more.","p":"nǐ duō chī yì diǎn."}]},{"id":"1-15-4","b":1,"l":15,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 complemento resultado potencial complement result potential 補語 結果補語 可能補語 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Comparar acciones con 得","en":"Comparing Actions with a 得 de Complement","ens":"Comparing Actions with a 得 de Complement","tc":"用「得」比較動作","sc":"用「得」比较动作"},"d":{"es":"Para comparar acciones con 得: A + verbo + 得 + 比 B + adjetivo, o A 比 B + verbo + 得 + adjetivo.","en":"To compare actions with 得: A + verb + 得 + 比 B + adjective, or A 比 B + verb + 得 + adjective.","tc":"比較動作時：「A＋動詞＋得＋比 B＋形容詞」，或「A 比 B＋動詞＋得＋形容詞」。","sc":"比较动作时：「A＋动词＋得＋比 B＋形容词」，或「A 比 B＋动词＋得＋形容词」。"},"ex":[{"c":"他比我跑得快。","s":"他比我跑得快。","es":"Corre más rápido que yo.","en":"He runs faster than I do.","p":"tā bǐ wǒ pǎo de kuài."}]},{"id":"1-15-5","b":1,"l":15,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 complemento resultado potencial complement result potential 補語 結果補語 可能補語 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Grado en comparaciones","en":"Complements of Degree in Comparison Structures","ens":"Complements of Degree in Comparison Structures","tc":"比較句的程度補語","sc":"比较句的程度补语"},"d":{"es":"En la comparación con complemento de grado se puede añadir la diferencia: 一點 (un poco) o 多了 / 得多 (mucho más).","en":"In comparisons with 得 you can add the size of the difference: 一點 (a little) or 多了 / 得多 (much more).","tc":"用「得」比較時，可以再加差別：「一點」（差一些）或「多了／得多」（差很多）。","sc":"用「得」比较时，可以再加差别：「一点」（差一些）或「多了／得多」（差很多）。"},"ex":[{"c":"他說得比我好多了。","s":"他说得比我好多了。","es":"Habla mucho mejor que yo.","en":"He speaks much better than I do.","p":"tā shuō de bǐ wǒ hǎo duō le."}]},{"id":"1-15-6","b":1,"l":15,"k":"","t":{"es":"Verbos separables","en":"Separable Verbs","ens":"Separable Verbs","tc":"離合詞","sc":"离合词"},"d":{"es":"Los verbos separables (吃飯, 睡覺, 游泳, 見面) son verbo + objeto: se pueden separar y la duración o cantidad va en medio. No llevan otro objeto directo.","en":"Separable verbs (吃飯, 睡覺, 游泳, 見面) are verb + object; other words can go in between, such as a duration or quantity. They cannot take another object.","tc":"離合詞（吃飯、睡覺、游泳、見面）是「動詞＋受詞」，中間可以放別的詞，時間長度或數量放在中間。後面不能再接受詞。","sc":"离合词（吃饭、睡觉、游泳、见面）是「动词＋受词」，中间可以放别的词，时间长度或数量放在中间。后面不能再接受词。"},"ex":[{"c":"我們見了三次面。","s":"我们见了三次面。","es":"Nos vimos tres veces.","en":"We met three times.","p":"wǒ men jiàn le sān cì miàn."},{"c":"他游了一個小時的泳。","s":"他游了一个小时的泳。","es":"Nadó una hora.","en":"He swam for an hour.","p":"tā yóu le yí ge xiǎo shí de yǒng."}]},{"id":"2-1-0","b":2,"l":1,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Desde… hacia con 從…往","en":"從 cóng…往 wǎng… go…from…","ens":"从 cóng…往 wǎng… go…from…","tc":"從…往…","sc":"从…往…"},"d":{"es":"從 + lugar + 往 + dirección + verbo: desde… hacia… (se usa mucho para dar indicaciones).","en":"從 + place + 往 + direction + verb means 'from… toward…'. It is often used to give directions.","tc":"「從＋地點＋往＋方向＋動詞」表示從哪裡往哪個方向去，常用來指路。","sc":"「从＋地点＋往＋方向＋动词」表示从哪里往哪个方向去，常用来指路。"},"ex":[{"c":"從這裡往前走，再往右轉。","s":"从这里往前走，再往右转。","es":"Desde aquí sigue derecho y luego gira a la derecha.","en":"From here go straight, then turn right.","p":"cóng zhè lǐ wǎng qián zǒu, zài wǎng yòu zhuǎn."}]},{"id":"2-1-1","b":2,"l":1,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Juicio con V起來","en":"Judgmental V-起來 qǐlái It’s my assessment that…","ens":"Judgmental V-起来 qǐlái It’s my assessment that…","tc":"V＋起來（看起來、聽起來）","sc":"V＋起来（看起来、听起来）"},"d":{"es":"V + 起來 expresa una evaluación subjetiva: «a juzgar por cómo se ve / se oye / sabe / se siente».","en":"V + 起來 expresses a subjective judgment: 'judging by how it looks / sounds / tastes / feels'.","tc":"「V＋起來」表示說話的人根據看到、聽到、吃到的感覺所做的判斷：從……來看。","sc":"「V＋起来」表示说话的人根据看到、听到、吃到的感觉所做的判断：从……来看。"},"ex":[{"c":"這個菜看起來很好吃。","s":"这个菜看起来很好吃。","es":"Este platillo se ve muy rico.","en":"This dish looks delicious.","p":"zhè ge cài kàn qǐ lái hěn hǎo chī."}]},{"id":"2-1-2","b":2,"l":1,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Estado continuo con 著","en":"Ongoing Action with -著 zhe","ens":"Ongoing Action with -着 zhe","tc":"V＋著（狀態持續）","sc":"V＋着（状态持续）"},"d":{"es":"V + 著 indica un estado que continúa (resultado de una acción que permanece). Negación: 沒 + V + 著.","en":"V + 著 shows a state that continues (the result of an action that stays). Negation: 沒 + V + 著.","tc":"「V＋著」表示動作的結果或狀態一直持續著。否定時用「沒＋V＋著」。","sc":"「V＋着」表示动作的结果或状态一直持续着。否定时用「没＋V＋着」。"},"ex":[{"c":"門開著。","s":"门开着。","es":"La puerta está abierta.","en":"The door is open.","p":"mén kāi zhe."},{"c":"他穿著一件藍色的外套。","s":"他穿着一件蓝色的外套。","es":"Lleva puesta una chaqueta azul.","en":"He is wearing a blue jacket.","p":"tā chuān zhe yí jiàn lán sè de wài tào."}]},{"id":"2-1-3","b":2,"l":1,"k":"","t":{"es":"Dos acciones con 一邊…一邊","en":"Two Simultaneously Actions with 一邊 yìbiān…一邊 yìbiān…","ens":"Two Simultaneously Actions with 一边 yìbiān…一边 yìbiān…","tc":"一邊…一邊…","sc":"一边…一边…"},"d":{"es":"一邊 A 一邊 B = hacer A y B al mismo tiempo (el mismo sujeto).","en":"一邊 A 一邊 B means doing A and B at the same time (same subject).","tc":"「一邊 A 一邊 B」表示同一個人同時做 A 和 B 兩件事。","sc":"「一边 A 一边 B」表示同一个人同时做 A 和 B 两件事。"},"ex":[{"c":"他一邊走路一邊聽音樂。","s":"他一边走路一边听音乐。","es":"Camina mientras escucha música.","en":"He listens to music while walking.","p":"tā yì biān zǒu lù yì biān tīng yīn yuè."}]},{"id":"2-1-4","b":2,"l":1,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Distancia con 離","en":"Distance from with 離 lí…","ens":"Distance from with 离 lí…","tc":"離（距離）","sc":"离（距离）"},"d":{"es":"A 離 B + (很) 遠 / 近 = A está lejos / cerca de B. 離 indica distancia; 從 indica punto de partida.","en":"A 離 B + (很) 遠 / 近 means A is far from / near B. 離 shows distance; 從 shows a starting point.","tc":"「A 離 B ＋（很）遠／近」表示 A 和 B 之間的距離。「離」說的是距離，「從」說的是起點。","sc":"「A 离 B ＋（很）远／近」表示 A 和 B 之间的距离。「离」说的是距离，「从」说的是起点。"},"ex":[{"c":"我家離學校很近。","s":"我家离学校很近。","es":"Mi casa está muy cerca de la escuela.","en":"My home is very close to the school.","p":"wǒ jiā lí xué xiào hěn jìn."}]},{"id":"2-2-0","b":2,"l":2,"k":"negación negar negativa negation negative 否定 énfasis enfático incluso emphasis emphatic even 強調 甚至 negación negar negativa negation negative 否定 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Negación enfática 一點也不","en":"Emphatic Negation with 一點也不 yìdiǎn yě bù V …","ens":"Emphatic Negation with 一点也不 yìdiǎn yě bù V …","tc":"一點也不／一點也沒","sc":"一点也不／一点也没"},"d":{"es":"一點也不 / 一點也沒 + verbo o adjetivo = en absoluto, nada. Es una negación enfática.","en":"一點也不 / 一點也沒 + verb or adjective is an emphatic negation: 'not at all'.","tc":"「一點也不／一點也沒＋動詞或形容詞」是加強語氣的否定，意思是完全不、一點都不。","sc":"「一点也不／一点也没＋动词或形容词」是加强语气的否定，意思是完全不、一点都不。"},"ex":[{"c":"我一點也不累。","s":"我一点也不累。","es":"No estoy nada cansado.","en":"I am not tired at all.","p":"wǒ yì diǎn yě bú lèi."}]},{"id":"2-2-1","b":2,"l":2,"k":"además adición también addition also besides 另外 而且 sugerencia proposición suggestion 建議 además adición también addition also besides 另外 而且 sugerencia proposición suggestion 建议","t":{"es":"Sugerencia con 還是…吧","en":"還是 háishì…吧 ba！ It would be better if …","ens":"还是 háishì…吧 ba！ It would be better if …","tc":"還是…吧","sc":"还是…吧"},"d":{"es":"還是 + sugerencia + 吧 = mejor + (hagamos algo). Se compara y se recomienda una opción.","en":"還是 + suggestion + 吧 means 'it would be better to…' after comparing options.","tc":"「還是＋建議＋吧」表示比較過後，覺得這樣做比較好。","sc":"「还是＋建议＋吧」表示比较过后，觉得这样做比较好。"},"ex":[{"c":"太晚了，我們還是搭計程車吧。","s":"太晚了，我们还是搭计程车吧。","es":"Es muy tarde, mejor tomemos un taxi.","en":"It's too late; we'd better take a taxi.","p":"tài wǎn le, wǒ men hái shì dā jì chéng chē ba."}]},{"id":"2-2-2","b":2,"l":2,"k":"","t":{"es":"Petición con 一點","en":"Form Adverbials with 一點 yìdiǎn","ens":"Form Adverbials with 一点 yìdiǎn","tc":"形容詞＋一點（說慢一點）","sc":"形容词＋一点（说慢一点）"},"d":{"es":"Adjetivo + 一點 + verbo (o verbo + adjetivo + 一點) forma una petición suave: «hazlo un poco más…».","en":"Adjective + 一點 + verb (or verb + adjective + 一點) makes a soft request: 'a little more…'.","tc":"「形容詞＋一點＋動詞」或「動詞＋形容詞＋一點」用來客氣地請對方再怎麼樣一點，語氣比較柔和。","sc":"「形容词＋一点＋动词」或「动词＋形容词＋一点」用来客气地请对方再怎么样一点，语气比较柔和。"},"ex":[{"c":"請你說慢一點。","s":"请你说慢一点。","es":"Por favor habla un poco más despacio.","en":"Please speak a little slower.","p":"qǐng nǐ shuō màn yì diǎn."},{"c":"你早一點來。","s":"你早一点来。","es":"Llega un poco más temprano.","en":"Come a little earlier.","p":"nǐ zǎo yì diǎn lái."}]},{"id":"2-2-3","b":2,"l":2,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"Reduplicación AABB","en":"Reduplication of Disyllabic Adjectives","ens":"Reduplication of Disyllabic Adjectives","tc":"雙音節形容詞重疊（AABB）","sc":"双音节形容词重叠（AABB）"},"d":{"es":"Los adjetivos de dos sílabas AB se duplican como AABB; resultan más vívidos y ya no llevan 很.","en":"A two-syllable adjective AB can be doubled as AABB to be more vivid. 很 is no longer needed.","tc":"雙音節形容詞 AB 可以重疊成 AABB，讓描述更生動，前面不用再加「很」。","sc":"双音节形容词 AB 可以重叠成 AABB，让描述更生动，前面不用再加「很」。"},"ex":[{"c":"房間乾乾淨淨的。","s":"房间干干净净的。","es":"El cuarto está muy limpio.","en":"The room is nice and clean.","p":"fáng jiān gān gān jìng jìng de."}]},{"id":"2-2-4","b":2,"l":2,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Negación suave con 不太","en":"不太 bútài not very","ens":"不太 bútài not very","tc":"不太","sc":"不太"},"d":{"es":"不太 + adjetivo / verbo = no muy, no demasiado. Es una negación suave.","en":"不太 + adjective / verb means 'not very, not so much'. It is a softer negation.","tc":"「不太＋形容詞／動詞」表示不是很、不怎麼，語氣比「不」柔和。","sc":"「不太＋形容词／动词」表示不是很、不怎么，语气比「不」柔和。"},"ex":[{"c":"我不太喜歡吃辣。","s":"我不太喜欢吃辣。","es":"No me gusta mucho el picante.","en":"I don't really like spicy food.","p":"wǒ bú tài xǐ huān chī là."}]},{"id":"2-2-5","b":2,"l":2,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Ubicación con 部 y 邊","en":"Locations with 部 bù /邊 biān","ens":"Locations with 部 bù /边 biān","tc":"方位詞：部、邊","sc":"方位词：部、边"},"d":{"es":"部 se usa para regiones (北部, 南部, 東部, 西部); 邊 para posiciones (上邊, 裡邊, 旁邊, 左邊, 右邊).","en":"部 is used for regions (北部, 南部, 東部, 西部); 邊 for positions (上邊, 裡邊, 旁邊, 左邊, 右邊).","tc":"「部」用在地區，例如北部、南部、東部；「邊」用在位置，例如上邊、旁邊、左邊、右邊。","sc":"「部」用在地区，例如北部、南部、东部；「边」用在位置，例如上边、旁边、左边、右边。"},"ex":[{"c":"台北在台灣的北部。","s":"台北在台湾的北部。","es":"Taipéi está en el norte de Taiwán.","en":"Taipei is in northern Taiwan.","p":"tái běi zài tái wān de běi bù."},{"c":"銀行在郵局的旁邊。","s":"银行在邮局的旁边。","es":"El banco está al lado del correo.","en":"The bank is next to the post office.","p":"yín háng zài yóu jú de páng biān."}]},{"id":"2-3-0","b":2,"l":3,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Usos de 差不多","en":"Various Functions of 差不 chàbùduō","ens":"Various Functions of 差不 chàbùduō","tc":"差不多","sc":"差不多"},"d":{"es":"差不多 puede ser adjetivo («casi igual»), adverbio («casi») o «más o menos».","en":"差不多 can be an adjective ('almost the same'), an adverb ('almost') or mean 'more or less'.","tc":"「差不多」可以當形容詞（幾乎一樣）、副詞（快要）或表示大概。","sc":"「差不多」可以当形容词（几乎一样）、副词（快要）或表示大概。"},"ex":[{"c":"我們差不多高。","s":"我们差不多高。","es":"Somos casi igual de altos.","en":"We are about the same height.","p":"wǒ men chā bù duō gāo."},{"c":"差不多十二點了。","s":"差不多十二点了。","es":"Son casi las doce.","en":"It is almost twelve o'clock.","p":"chā bù duō shí èr diǎn le."}]},{"id":"2-3-1","b":2,"l":3,"k":"experiencia alguna vez haber experience ever 經驗 經歷 experiencia alguna vez haber experience ever 经验 经历","t":{"es":"Experiencia con 過","en":"Experience Particle 過 guò","ens":"Experience Particle 过 guò","tc":"經驗：V＋過","sc":"经验：V＋过"},"d":{"es":"V + 過 indica experiencia: «alguna vez». Negación: 沒 + V + 過.","en":"V + 過 shows past experience: 'have ever done'. Negation: 沒 + V + 過.","tc":"「V＋過」表示有過這樣的經驗。否定時用「沒＋V＋過」。","sc":"「V＋过」表示有过这样的经验。否定时用「没＋V＋过」。"},"ex":[{"c":"我去過日本。","s":"我去过日本。","es":"He ido a Japón.","en":"I have been to Japan.","p":"wǒ qù guò rì běn."},{"c":"我沒吃過臭豆腐。","s":"我没吃过臭豆腐。","es":"Nunca he comido tofu apestoso.","en":"I have never eaten stinky tofu.","p":"wǒ méi chī guò chòu dòu fǔ."}]},{"id":"2-3-2","b":2,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Apenas con 才","en":"才 cái merely, only","ens":"才 cái merely, only","tc":"才（只有、剛剛）","sc":"才（只有、刚刚）"},"d":{"es":"才 + cantidad pequeña = apenas, solo.","en":"才 + a small amount means 'only, just'.","tc":"「才＋數量少」表示只有、才剛剛。","sc":"「才＋数量少」表示只有、才刚刚。"},"ex":[{"c":"現在才八點。","s":"现在才八点。","es":"Apenas son las ocho.","en":"It's only eight o'clock now.","p":"xiàn zài cái bā diǎn."},{"c":"我才學了三個月。","s":"我才学了三个月。","es":"Solo llevo tres meses estudiando.","en":"I have only studied for three months.","p":"wǒ cái xué le sān ge yuè."}]},{"id":"2-3-3","b":2,"l":3,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Recordar con 想起來","en":"想起來 xiǎngqǐlái to have remembered","ens":"想起来 xiǎngqǐlái to have remembered","tc":"想起來","sc":"想起来"},"d":{"es":"想起來 = recordar de repente algo que se había olvidado.","en":"想起來 means to suddenly remember something that had been forgotten.","tc":"「想起來」表示突然想到、記起原本忘記的事。","sc":"「想起来」表示突然想到、记起原本忘记的事。"},"ex":[{"c":"我想起來了，他叫王明。","s":"我想起来了，他叫王明。","es":"Ya recordé, se llama Wang Ming.","en":"I remember now, his name is Wang Ming.","p":"wǒ xiǎng qǐ lái le, tā jiào wáng míng."}]},{"id":"2-3-4","b":2,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Más tarde de lo esperado con 才","en":"Longer/Later Than Expected with 才 cái","ens":"Longer/Later Than Expected with 才 cái","tc":"時間＋才（比預期晚）","sc":"时间＋才（比预期晚）"},"d":{"es":"Tiempo + 才 + verbo = más tarde de lo esperado. Contrasta con 就 (más temprano de lo esperado).","en":"Time + 才 + verb shows something happens later than expected. It is the opposite of 就 (earlier than expected).","tc":"「時間＋才＋動詞」表示比預期的晚。跟「就」相反，「就」表示比預期的早。","sc":"「时间＋才＋动词」表示比预期的晚。跟「就」相反，「就」表示比预期的早。"},"ex":[{"c":"他十點才起床。","s":"他十点才起床。","es":"Se levanta hasta las diez.","en":"He doesn't get up until ten.","p":"tā shí diǎn cái qǐ chuáng."}]},{"id":"2-3-5","b":2,"l":3,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"Acción suave con ABAB","en":"Tentative Action with Reduplicated Disyllabic Verbs ABAB","ens":"Tentative Action with Reduplicated Disyllabic Verbs ABAB","tc":"雙音節動詞重疊（ABAB）","sc":"双音节动词重叠（ABAB）"},"d":{"es":"Los verbos de dos sílabas AB duplicados como ABAB suavizan la acción: «un poco, para ver».","en":"A two-syllable verb AB can be doubled as ABAB to soften the action: 'do it a little'.","tc":"雙音節動詞 AB 可以重疊成 ABAB，讓動作比較輕鬆，意思是稍微做一下、試試看。","sc":"双音节动词 AB 可以重叠成 ABAB，让动作比较轻松，意思是稍微做一下、试试看。"},"ex":[{"c":"我們討論討論吧。","s":"我们讨论讨论吧。","es":"Hablemos un poco de esto.","en":"Let's discuss it a bit.","p":"wǒ men tǎo lùn tǎo lùn ba."}]},{"id":"2-4-0","b":2,"l":4,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Además de con 除了…還","en":"除了 chúle…，還 hái… in addition to…","ens":"除了 chúle…，还 hái… in addition to…","tc":"除了…，還…","sc":"除了…，还…"},"d":{"es":"除了 A，還 B = además de A, también B.","en":"除了 A，還 B means 'in addition to A, also B'.","tc":"「除了 A，還 B」表示 A 之外，也有 B。","sc":"「除了 A，还 B」表示 A 之外，也有 B。"},"ex":[{"c":"除了英文，他還會說中文。","s":"除了英文，他还会说中文。","es":"Además de inglés, también habla chino.","en":"Besides English, he also speaks Chinese.","p":"chú le yīng wén, tā hái huì shuō zhōng wén."}]},{"id":"2-4-1","b":2,"l":4,"k":"","t":{"es":"Según con 按照","en":"按照…ànzhào… in accordance with","ens":"按照…ànzhào… in accordance with","tc":"按照","sc":"按照"},"d":{"es":"按照 + norma / plan / indicación = según, conforme a.","en":"按照 + rule / plan / instruction means 'according to, in accordance with'.","tc":"「按照＋規定／計畫／說法」表示依照某個標準去做。","sc":"「按照＋规定／计划／说法」表示依照某个标准去做。"},"ex":[{"c":"請按照老師說的做。","s":"请按照老师说的做。","es":"Por favor haz lo que dijo el profesor.","en":"Please do as the teacher said.","p":"qǐng àn zhào lǎo shī shuō de zuò."}]},{"id":"2-4-2","b":2,"l":4,"k":"","t":{"es":"Usos de 跟","en":"Various Meaning of the Preposition 跟 gēn","ens":"Various Meaning of the Preposition 跟 gēn","tc":"跟（多種意思）","sc":"跟（多种意思）"},"d":{"es":"跟 tiene varios usos: «con» (compañía), «de» en 跟…學 / 跟…借, «igual que» en 跟…一樣, y «y» entre sustantivos.","en":"跟 has several uses: 'with' (company), 'from' in 跟…學 / 跟…借, 'the same as' in 跟…一樣, and 'and' between nouns.","tc":"「跟」有很多用法：跟誰一起（陪伴）、跟誰學／借（對象）、跟……一樣（比較），也可以像「和」連接兩個名詞。","sc":"「跟」有很多用法：跟谁一起（陪伴）、跟谁学／借（对象）、跟……一样（比较），也可以像「和」连接两个名词。"},"ex":[{"c":"我跟老師學中文。","s":"我跟老师学中文。","es":"Aprendo chino con el profesor.","en":"I learn Chinese from my teacher.","p":"wǒ gēn lǎo shī xué zhōng wén."}]},{"id":"2-4-3","b":2,"l":4,"k":"","t":{"es":"Usos de 給","en":"Various Meanings of 給 gěi","ens":"Various Meanings of 给 gěi","tc":"給（多種意思）","sc":"给（多种意思）"},"d":{"es":"給 puede ser verbo («dar»), preposición («para») o marcar al destinatario después del verbo (寄給你).","en":"給 can be a verb ('give'), a preposition ('for') or follow a verb to mark the receiver (寄給你).","tc":"「給」可以是動詞（給我一本書）、介詞（給你的禮物），也可以放在動詞後面表示給誰，例如「寄給他」。","sc":"「给」可以是动词（给我一本书）、介词（给你的礼物），也可以放在动词后面表示给谁，例如「寄给他」。"},"ex":[{"c":"我給你一個禮物。","s":"我给你一个礼物。","es":"Te doy un regalo.","en":"I give you a gift.","p":"wǒ gěi nǐ yí ge lǐ wù."},{"c":"我寄給他一封信。","s":"我寄给他一封信。","es":"Le envié una carta.","en":"I sent him a letter.","p":"wǒ jì gěi tā yì fēng xìn."}]},{"id":"2-4-4","b":2,"l":4,"k":"","t":{"es":"Hacia con 對","en":"對 duì… towards…","ens":"对 duì… towards…","tc":"對（對於）","sc":"对（对于）"},"d":{"es":"對 + persona / cosa + adjetivo o verbo = hacia, con respecto a. Es común en 對…有興趣 y 對…很好.","en":"對 + person / thing + adjective or verb means 'toward, regarding'. Common in 對…有興趣 and 對…很好.","tc":"「對＋人／事＋形容詞或動詞」表示針對某個對象，常見的有「對……有興趣」「對……很好」。","sc":"「对＋人／事＋形容词或动词」表示针对某个对象，常见的有「对……有兴趣」「对……很好」。"},"ex":[{"c":"我對台灣文化很有興趣。","s":"我对台湾文化很有兴趣。","es":"Me interesa mucho la cultura de Taiwán.","en":"I am very interested in Taiwanese culture.","p":"wǒ duì tái wān wén huà hěn yǒu xìng qù."}]},{"id":"2-5-0","b":2,"l":5,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Todavía con 還","en":"還 hái still","ens":"还 hái still","tc":"還（仍然）","sc":"还（仍然）"},"d":{"es":"還 = todavía, aún (continúa una situación). 還沒 + verbo = todavía no.","en":"還 means 'still' (the situation continues). 還沒 + verb means 'not yet'.","tc":"「還」表示情況持續，意思是仍然、還在。「還沒＋動詞」表示到現在還沒有。","sc":"「还」表示情况持续，意思是仍然、还在。「还没＋动词」表示到现在还没有。"},"ex":[{"c":"他還在睡覺。","s":"他还在睡觉。","es":"Todavía está durmiendo.","en":"He is still sleeping.","p":"tā hái zài shuì jiào."},{"c":"我還沒吃飯。","s":"我还没吃饭。","es":"Todavía no he comido.","en":"I haven't eaten yet.","p":"wǒ hái méi chī fàn."}]},{"id":"2-5-1","b":2,"l":5,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Manera con V著","en":"Manner of an Action with V 著 zhe","ens":"Manner of an Action with V 着 zhe","tc":"V1＋著＋V2（方式）","sc":"V1＋着＋V2（方式）"},"d":{"es":"V1 + 著 + V2: V1 describe la manera en que se realiza V2.","en":"In V1 + 著 + V2, V1 describes the manner in which V2 is done.","tc":"「V1＋著＋V2」中，V1 說明做 V2 時的方式或狀態。","sc":"「V1＋着＋V2」中，V1 说明做 V2 时的方式或状态。"},"ex":[{"c":"他笑著說話。","s":"他笑着说话。","es":"Habla sonriendo.","en":"He speaks with a smile.","p":"tā xiào zhe shuō huà."}]},{"id":"2-5-2","b":2,"l":5,"k":"","t":{"es":"Varios verbos en una oración","en":"Multiple Verb Phrases in a Sentence","ens":"Multiple Verb Phrases in a Sentence","tc":"連動句（多個動詞）","sc":"连动句（多个动词）"},"d":{"es":"En una oración se pueden encadenar varios verbos en el orden en que ocurren.","en":"A sentence can chain several verbs in the order the actions happen.","tc":"一個句子裡可以依照動作發生的順序，連續放好幾個動詞。","sc":"一个句子里可以依照动作发生的顺序，连续放好几个动词。"},"ex":[{"c":"她下班回家做飯。","s":"她下班回家做饭。","es":"Ella sale del trabajo, vuelve a casa y cocina.","en":"She gets off work, goes home and cooks.","p":"tā xià bān huí jiā zuò fàn."}]},{"id":"2-5-3","b":2,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Cuando… entonces con 等…就","en":"When A Comes, Then B…with 等 děng 就…jiù…","ens":"When A Comes, Then B…with 等 děng 就…jiù…","tc":"等…就…","sc":"等…就…"},"d":{"es":"等 A 就 B = cuando ocurra A, entonces B.","en":"等 A 就 B means 'when A happens, then B'.","tc":"「等 A 就 B」表示等 A 發生之後，就做 B。","sc":"「等 A 就 B」表示等 A 发生之后，就做 B。"},"ex":[{"c":"等你來了，我們就出發。","s":"等你来了，我们就出发。","es":"Cuando llegues, salimos.","en":"When you arrive, we'll set off.","p":"děng nǐ lái le, wǒ men jiù chū fā."}]},{"id":"2-5-4","b":2,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 tiempo momento orden secuencia time order sequence 时间 顺序 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"De pronto con V著V著就…了","en":"While Doing A, B Happens with V 著 zhe V 著 zhe， 就 jiù…了 le","ens":"While Doing A, B Happens with V 着 zhe V 着 zhe， 就 jiù…了 le","tc":"V著V著就…了","sc":"V着V着就…了"},"d":{"es":"V著V著就…了 = mientras hacía algo, de pronto ocurrió otra cosa.","en":"V著V著就…了 means 'while doing something, suddenly something else happened'.","tc":"「V著V著就…了」表示做著做著，突然出現了另一個情況。","sc":"「V着V着就…了」表示做着做着，突然出现了另一个情况。"},"ex":[{"c":"他看著看著就睡著了。","s":"他看着看着就睡着了。","es":"Mientras miraba, se quedó dormido.","en":"He was watching and fell asleep.","p":"tā kàn zhe kàn zhe jiù shuì zháo le."}]},{"id":"2-6-0","b":2,"l":6,"k":"","t":{"es":"Destino con 到","en":"Destination Marker 到 dào","ens":"Destination Marker 到 dào","tc":"V＋到＋地點","sc":"V＋到＋地点"},"d":{"es":"V + 到 + lugar: la acción llega hasta ese lugar. 到 marca el destino.","en":"V + 到 + place means the action reaches that place. 到 marks the destination.","tc":"「V＋到＋地點」表示動作到達某個地方，「到」標示終點。","sc":"「V＋到＋地点」表示动作到达某个地方，「到」标示终点。"},"ex":[{"c":"我們走到公園吧。","s":"我们走到公园吧。","es":"Caminemos hasta el parque.","en":"Let's walk to the park.","p":"wǒ men zǒu dào gōng yuán ba."}]},{"id":"2-6-1","b":2,"l":6,"k":"","t":{"es":"Dar a alguien con 給","en":"Indirect Object Marker 給 gěi","ens":"Indirect Object Marker 给 gěi","tc":"V＋給＋人","sc":"V＋给＋人"},"d":{"es":"V + 給 + persona: dar o transferir algo a alguien (送給, 寄給, 交給, 借給).","en":"V + 給 + person means giving or passing something to someone (送給, 寄給, 交給, 借給).","tc":"「V＋給＋人」表示把東西送、寄、交給某個人，例如送給、寄給、交給、借給。","sc":"「V＋给＋人」表示把东西送、寄、交给某个人，例如送给、寄给、交给、借给。"},"ex":[{"c":"他送給我一本書。","s":"他送给我一本书。","es":"Me regaló un libro.","en":"He gave me a book as a present.","p":"tā sòng gěi wǒ yì běn shū."}]},{"id":"2-6-2","b":2,"l":6,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Lugar resultante con V在","en":"Resultant Location with V+在 zài…","ens":"Resultant Location with V+在 zài…","tc":"V＋在＋地點","sc":"V＋在＋地点"},"d":{"es":"V + 在 + lugar: como resultado de la acción, algo o alguien queda en ese lugar.","en":"V + 在 + place means that, as a result of the action, something or someone ends up in that place.","tc":"「V＋在＋地點」表示動作之後，東西或人留在那個地方。","sc":"「V＋在＋地点」表示动作之后，东西或人留在那个地方。"},"ex":[{"c":"我把車停在學校。","s":"我把车停在学校。","es":"Estaciono el coche en la escuela.","en":"I park my car at the school.","p":"wǒ bǎ chē tíng zài xué xiào."}]},{"id":"2-6-3","b":2,"l":6,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 disposición objeto complemento disposal object ba 處置 把字句 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Mover con 把","en":"Moving an Object to a Location with 把 bǎ","ens":"Moving an Object to a Location with 把 bǎ","tc":"把＋物＋V＋到／在／給","sc":"把＋物＋V＋到／在／给"},"d":{"es":"把 + objeto + V + 到 / 在 / 給 + lugar o persona: mover un objeto a otro lugar.","en":"把 + object + V + 到 / 在 / 給 + place or person means moving an object somewhere.","tc":"「把＋東西＋動詞＋到／在／給＋地點或人」表示把東西移到某個地方。","sc":"「把＋东西＋动词＋到／在／给＋地点或人」表示把东西移到某个地方。"},"ex":[{"c":"請把書放在桌子上。","s":"请把书放在桌子上。","es":"Por favor pon el libro sobre la mesa.","en":"Please put the book on the table.","p":"qǐng bǎ shū fàng zài zhuō zi shàng."}]},{"id":"2-6-4","b":2,"l":6,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Además con 而且","en":"而且 érqiě furthermore","ens":"而且 érqiě furthermore","tc":"而且","sc":"而且"},"d":{"es":"而且 = además. Añade información que refuerza lo anterior.","en":"而且 means 'furthermore'. It adds information that reinforces the previous point.","tc":"「而且」表示再加上另一個更進一步的情況。","sc":"「而且」表示再加上另一个更进一步的情况。"},"ex":[{"c":"這家餐廳很好吃，而且很便宜。","s":"这家餐厅很好吃，而且很便宜。","es":"Este restaurante es rico y además barato.","en":"This restaurant is delicious, and cheap too.","p":"zhè jiā cān tīng hěn hǎo chī, ér qiě hěn pián yí."}]},{"id":"2-7-0","b":2,"l":7,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Dirección con 來／去","en":"Directional ConstructionsV1V2 and V1V2V3","ens":"Directional ConstructionsV1V2 and V1V2V3","tc":"複合趨向補語（V＋進來、V＋出去）","sc":"复合趋向补语（V＋进来、V＋出去）"},"d":{"es":"Verbo + dirección (上, 下, 進, 出, 回, 過, 起) + 來 / 去: movimiento hacia (來) o lejos (去) del hablante. También V1V2V3.","en":"A verb plus a direction (上, 下, 進, 出, 回, 過, 起) plus 來 or 去 shows movement toward (來) or away from (去) the speaker. V1V2V3 also exists.","tc":"動詞後面加上、下、進、出、回、過、起，再加「來」或「去」，表示動作的方向：朝說話的人是「來」，離開說話的人是「去」。","sc":"动词后面加上、下、进、出、回、过、起，再加「来」或「去」，表示动作的方向：朝说话的人是「来」，离开说话的人是「去」。"},"ex":[{"c":"他走進來了。","s":"他走进来了。","es":"Entró caminando.","en":"He walked in.","p":"tā zǒu jìn lái le."},{"c":"她跑出去了。","s":"她跑出去了。","es":"Salió corriendo.","en":"She ran out.","p":"tā pǎo chū qù le."}]},{"id":"2-7-1","b":2,"l":7,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"把 con dirección","en":"把 bǎ with V1V2V3","ens":"把 bǎ with V1V2V3","tc":"把＋物＋V＋趨向補語","sc":"把＋物＋V＋趋向补语"},"d":{"es":"把 + objeto + verbo + dirección + 來 / 去: mover el objeto en esa dirección.","en":"把 + object + verb + direction + 來 / 去 means moving the object in that direction.","tc":"「把＋東西＋動詞＋方向＋來／去」表示把東西往某個方向移動。","sc":"「把＋东西＋动词＋方向＋来／去」表示把东西往某个方向移动。"},"ex":[{"c":"請把椅子搬到樓上去。","s":"请把椅子搬到楼上去。","es":"Por favor lleva la silla al piso de arriba.","en":"Please carry the chair upstairs.","p":"qǐng bǎ yǐ zi bān dào lóu shàng qù."}]},{"id":"2-7-2","b":2,"l":7,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Reproche con 嗎","en":"Confrontation with 嗎?","ens":"Confrontation with 吗?","tc":"用「嗎」表示責備","sc":"用「吗」表示责备"},"d":{"es":"Una pregunta con 嗎 puede expresar reproche o confrontación: «¿no ves que…?».","en":"A question with 嗎 can express reproach or confrontation rather than a real question: 'Can't you see…?'","tc":"用「嗎」的問句有時不是真的在問，而是在責備或表示不滿：你沒看到……嗎？","sc":"用「吗」的问句有时不是真的在问，而是在责备或表示不满：你没看到……吗？"},"ex":[{"c":"你沒看到我在忙嗎？","s":"你没看到我在忙吗？","es":"¿No ves que estoy ocupado?","en":"Can't you see that I'm busy?","p":"nǐ méi kàn dào wǒ zài máng ma?"}]},{"id":"2-7-3","b":2,"l":7,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Posición con V著","en":"Existential Sentence with Posture Verbs","ens":"Existential Sentence with Posture Verbs","tc":"存在句：地點＋V著＋物","sc":"存在句：地点＋V着＋物"},"d":{"es":"Lugar + verbo de posición (坐, 站, 躺, 放, 掛, 貼) + 著 + persona o cosa: así está colocado.","en":"Place + posture verb (坐, 站, 躺, 放, 掛, 貼) + 著 + person or thing describes how something is placed there.","tc":"「地點＋姿勢動詞（坐、站、躺、放、掛、貼）＋著＋人或東西」表示那裡擺放或存在的狀態。","sc":"「地点＋姿势动词（坐、站、躺、放、挂、贴）＋着＋人或东西」表示那里摆放或存在的状态。"},"ex":[{"c":"桌子上放著一本書。","s":"桌子上放着一本书。","es":"Sobre la mesa hay un libro (puesto).","en":"There is a book lying on the table.","p":"zhuō zi shàng fàng zhe yì běn shū."}]},{"id":"2-7-4","b":2,"l":7,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Para con 為了","en":"為了 wèile in order to","ens":"为了 wèile in order to","tc":"為了","sc":"为了"},"d":{"es":"為了 + objetivo, + acción = para, con el fin de.","en":"為了 + goal, + action means 'in order to'.","tc":"「為了＋目的，＋動作」表示做某件事的目的。","sc":"「为了＋目的，＋动作」表示做某件事的目的。"},"ex":[{"c":"為了學好中文，我每天聽廣播。","s":"为了学好中文，我每天听广播。","es":"Para aprender bien chino escucho la radio todos los días.","en":"To learn Chinese well, I listen to the radio every day.","p":"wèi le xué hǎo zhōng wén, wǒ měi tiān tīng guǎng bò."}]},{"id":"2-8-0","b":2,"l":8,"k":"","t":{"es":"Percepción con 見","en":"見 jiàn as a Perceptual Result","ens":"见 jiàn as a Perceptual Result","tc":"V＋見（看見、聽見）","sc":"V＋见（看见、听见）"},"d":{"es":"V + 見 expresa que la percepción se logró: 看見 (ver), 聽見 (oír).","en":"V + 見 shows a successful perception: 看見 (see), 聽見 (hear).","tc":"「V＋見」表示感官的結果，例如看見、聽見，真的看到或聽到了。","sc":"「V＋见」表示感官的结果，例如看见、听见，真的看到或听到了。"},"ex":[{"c":"我聽見有人在叫我。","s":"我听见有人在叫我。","es":"Oí que alguien me llamaba.","en":"I heard someone calling me.","p":"wǒ tīng jiàn yǒu rén zài jiào wǒ."}]},{"id":"2-8-1","b":2,"l":8,"k":"","t":{"es":"Comprender con 懂","en":"懂 dǒng as a Cognitive Result","ens":"懂 dǒng as a Cognitive Result","tc":"V＋懂（聽懂、看懂）","sc":"V＋懂（听懂、看懂）"},"d":{"es":"V + 懂 = comprender lo que se escucha o lee: 聽懂, 看懂.","en":"V + 懂 means understanding what you hear or read: 聽懂, 看懂.","tc":"「V＋懂」表示聽或看之後理解了，例如聽懂、看懂。","sc":"「V＋懂」表示听或看之后理解了，例如听懂、看懂。"},"ex":[{"c":"老師說的話我聽得懂。","s":"老师说的话我听得懂。","es":"Entiendo lo que dice el profesor.","en":"I can understand what the teacher says.","p":"lǎo shī shuō de huà wǒ tīng dé dǒng."}]},{"id":"2-8-2","b":2,"l":8,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Aprender con 會","en":"會 huìas an Achievement Result","ens":"会 huìas an Achievement Result","tc":"V＋會（學會、教會）","sc":"V＋会（学会、教会）"},"d":{"es":"V + 會 = aprender a hacer algo (logro): 學會, 教會.","en":"V + 會 means to have learned how to do something: 學會, 教會.","tc":"「V＋會」表示學習之後學會了，例如學會、教會。","sc":"「V＋会」表示学习之后学会了，例如学会、教会。"},"ex":[{"c":"我學會了做蛋糕。","s":"我学会了做蛋糕。","es":"Aprendí a hacer pasteles.","en":"I learned how to make a cake.","p":"wǒ xué huì le zuò dàn gāo."}]},{"id":"2-8-3","b":2,"l":8,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Potencial con 得／不","en":"Potential Capability with -得 de- or -不 bù-","ens":"Potential Capability with -得 de- or -不 bù-","tc":"可能補語（V得＋補語／V不＋補語）","sc":"可能补语（V得＋补语／V不＋补语）"},"d":{"es":"V + 得 + complemento = se puede; V + 不 + complemento = no se puede (por las circunstancias).","en":"V + 得 + complement means can; V + 不 + complement means cannot, depending on the circumstances.","tc":"「V＋得＋補語」表示可以，「V＋不＋補語」表示不能，指在條件上做不做得到。","sc":"「V＋得＋补语」表示可以，「V＋不＋补语」表示不能，指在条件上做不做得到。"},"ex":[{"c":"我看得懂，他看不懂。","s":"我看得懂，他看不懂。","es":"Yo sí lo entiendo al leerlo; él no.","en":"I can understand it, but he can't.","p":"wǒ kàn de dǒng, tā kàn bù dǒng."},{"c":"這麼多菜，我吃不完。","s":"这么多菜，我吃不完。","es":"Con tanta comida, no puedo terminarla.","en":"With so many dishes, I can't finish them.","p":"zhè me duō cài, wǒ chī bù wán."}]},{"id":"2-8-4","b":2,"l":8,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 complemento resultado potencial complement result potential 补语 结果补语 可能补语 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Capacidad con 了 (liǎo)","en":"Capability Complement 了 liǎo","ens":"Capability Complement 了 liǎo","tc":"V＋得了／不了","sc":"V＋得了／不了"},"d":{"es":"V + 得了 / 不了 = poder / no poder completar o soportar algo. Aquí 了 se lee liǎo.","en":"V + 得了 / 不了 means being able / unable to finish or endure something. Here 了 is read liǎo.","tc":"「V＋得了／不了」表示能不能完成或承受。這裡的「了」唸 liǎo。","sc":"「V＋得了／不了」表示能不能完成或承受。这里的「了」念 liǎo。"},"ex":[{"c":"太多了，我吃不了。","s":"太多了，我吃不了。","es":"Es demasiado, no puedo con todo.","en":"It's too much, I can't finish it.","p":"tài duō le, wǒ chī bù liǎo."}]},{"id":"2-8-5","b":2,"l":8,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Resultado con 得","en":"Vs +得 de + complement so …that…","ens":"Vs +得 de + complement so …that…","tc":"形容詞／動詞＋得＋結果","sc":"形容词／动词＋得＋结果"},"d":{"es":"Adjetivo / verbo + 得 + resultado = tan… que…","en":"Adjective / verb + 得 + result means 'so… that…'.","tc":"「形容詞或動詞＋得＋結果」表示程度很高，高到出現某個結果：……得……。","sc":"「形容词或动词＋得＋结果」表示程度很高，高到出现某个结果：……得……。"},"ex":[{"c":"他高興得跳起來。","s":"他高兴得跳起来。","es":"Estaba tan contento que saltó.","en":"He was so happy that he jumped up.","p":"tā gāo xìng de tiào qǐ lái."}]},{"id":"2-8-6","b":2,"l":8,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Continuar con 下去","en":"To Keep on Doing Something with 下去 xiàqù","ens":"To Keep on Doing Something with 下去 xiàqù","tc":"V＋下去","sc":"V＋下去"},"d":{"es":"V + 下去 = seguir haciendo algo (de ahora en adelante).","en":"V + 下去 means to keep on doing something from now on.","tc":"「V＋下去」表示從現在開始繼續做下去。","sc":"「V＋下去」表示从现在开始继续做下去。"},"ex":[{"c":"你說下去，我在聽。","s":"你说下去，我在听。","es":"Sigue, te estoy escuchando.","en":"Go on, I'm listening.","p":"nǐ shuō xià qù, wǒ zài tīng."}]},{"id":"2-8-7","b":2,"l":8,"k":"pasado completado terminado past completed finished perfective 完成 過去 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Terminar con 完","en":"Completion of an Action with V+完 wán","ens":"Completion of an Action with V+完 wán","tc":"V＋完","sc":"V＋完"},"d":{"es":"V + 完 = terminar de hacer algo. Negación: 沒 + V + 完.","en":"V + 完 means to finish doing something. Negation: 沒 + V + 完.","tc":"「V＋完」表示把某件事做完。否定時用「沒＋V＋完」。","sc":"「V＋完」表示把某件事做完。否定时用「没＋V＋完」。"},"ex":[{"c":"我寫完功課了。","s":"我写完功课了。","es":"Terminé la tarea.","en":"I finished my homework.","p":"wǒ xiě wán gōng kè le."}]},{"id":"2-9-0","b":2,"l":9,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Listo con 好","en":"All Set and Ready with Verb Complement 好 hǎo","ens":"All Set and Ready with Verb Complement 好 hǎo","tc":"V＋好","sc":"V＋好"},"d":{"es":"V + 好 = quedar listo o hecho bien: 準備好, 做好, 洗好.","en":"V + 好 means something is done or ready: 準備好, 做好, 洗好.","tc":"「V＋好」表示事情做好了、準備好了，例如準備好、做好、洗好。","sc":"「V＋好」表示事情做好了、准备好了，例如准备好、做好、洗好。"},"ex":[{"c":"飯做好了。","s":"饭做好了。","es":"La comida ya está lista.","en":"The meal is ready.","p":"fàn zuò hǎo le."}]},{"id":"2-9-1","b":2,"l":9,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Lograr con 到","en":"To Be Successful in …with Verb Complement 到 dào","ens":"To Be Successful in …with Verb Complement 到 dào","tc":"V＋到（達成結果）","sc":"V＋到（达成结果）"},"d":{"es":"V + 到 = lograr el resultado esperado: 買到, 找到, 看到.","en":"V + 到 means achieving the intended result: 買到, 找到, 看到.","tc":"「V＋到」表示達到想要的結果，例如買到、找到、看到。","sc":"「V＋到」表示达到想要的结果，例如买到、找到、看到。"},"ex":[{"c":"我買到票了。","s":"我买到票了。","es":"Conseguí el boleto.","en":"I got the ticket.","p":"wǒ mǎi dào piào le."}]},{"id":"2-9-2","b":2,"l":9,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 dirección movimiento direction movement 方向 趨向 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 dirección movimiento direction movement 方向 趋向","t":{"es":"Comparar con 比起來","en":"Comparison with 比起來 bǐ qǐlái","ens":"Comparison with 比起来 bǐ qǐlái","tc":"跟…比起來","sc":"跟…比起来"},"d":{"es":"跟 B 比起來，A… / 比起 B，A… = en comparación con B, A…","en":"跟 B 比起來，A… / 比起 B，A… means 'compared with B, A…'.","tc":"「跟 B 比起來，A……」或「比起 B，A……」表示拿 A 跟 B 做比較。","sc":"「跟 B 比起来，A……」或「比起 B，A……」表示拿 A 跟 B 做比较。"},"ex":[{"c":"跟台北比起來，高雄比較熱。","s":"跟台北比起来，高雄比较热。","es":"Comparado con Taipéi, Kaohsiung es más caluroso.","en":"Compared with Taipei, Kaohsiung is hotter.","p":"gēn tái běi bǐ qǐ lái, gāo xióng bǐ jiào rè."}]},{"id":"2-9-3","b":2,"l":9,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Semejanza con 像…一樣","en":"像 xiàng…一樣 yí yàng … is just like…","ens":"像 xiàng…一样 yí yàng … is just like…","tc":"像…一樣","sc":"像…一样"},"d":{"es":"A 像 B 一樣 (+ adjetivo / verbo) = A es como B.","en":"A 像 B 一樣 (+ adjective / verb) means A is like B.","tc":"「A 像 B 一樣（＋形容詞／動詞）」表示 A 跟 B 很相似。","sc":"「A 像 B 一样（＋形容词／动词）」表示 A 跟 B 很相似。"},"ex":[{"c":"他像小孩子一樣愛玩。","s":"他像小孩子一样爱玩。","es":"Le gusta jugar como a un niño.","en":"He loves to play just like a child.","p":"tā xiàng xiǎo hái zi yí yàng ài wán."}]},{"id":"2-9-4","b":2,"l":9,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Extremo con 極了","en":"Adverbial Complements 極了 jíle、得不得了 de bùdéliǎo、得很 de hěn terribly, extremely","ens":"Adverbial Complements 极了 jíle、得不得了 de bùdéliǎo、得很 de hěn terribly, extremely","tc":"形容詞＋極了／得不得了／得很","sc":"形容词＋极了／得不得了／得很"},"d":{"es":"Adjetivo + 極了 / 得不得了 / 得很 = extremadamente. Van después del adjetivo.","en":"Adjective + 極了 / 得不得了 / 得很 goes after the adjective and means 'extremely'.","tc":"「形容詞＋極了／得不得了／得很」放在形容詞後面，表示非常、程度很高。","sc":"「形容词＋极了／得不得了／得很」放在形容词后面，表示非常、程度很高。"},"ex":[{"c":"今天熱極了。","s":"今天热极了。","es":"Hoy hace muchísimo calor.","en":"It is extremely hot today.","p":"jīn tiān rè jí le."},{"c":"她高興得不得了。","s":"她高兴得不得了。","es":"Está contentísima.","en":"She is overjoyed.","p":"tā gāo xìng de bù dé liǎo."}]},{"id":"2-9-5","b":2,"l":9,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Poder permitirse con 起","en":"Verb Complement 起 qǐ to be able to afford","ens":"Verb Complement 起 qǐ to be able to afford","tc":"V＋得起／不起","sc":"V＋得起／不起"},"d":{"es":"V + 得起 / 不起 = poder / no poder permitirse algo (por dinero o categoría).","en":"V + 得起 / 不起 means being able / unable to afford something (usually money).","tc":"「V＋得起／不起」表示有沒有能力負擔，通常指錢夠不夠。","sc":"「V＋得起／不起」表示有没有能力负担，通常指钱够不够。"},"ex":[{"c":"這個包包太貴了，我買不起。","s":"这个包包太贵了，我买不起。","es":"Esta bolsa es muy cara, no me la puedo permitir.","en":"This bag is too expensive; I can't afford it.","p":"zhè ge bāo bāo tài guì le, wǒ mǎi bù qǐ."}]},{"id":"2-10-0","b":2,"l":10,"k":"dirección movimiento direction movement 方向 趨向 complemento resultado potencial complement result potential 補語 結果補語 可能補語 dirección movimiento direction movement 方向 趋向 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Descubrir con 出來","en":"To Figure out with the Complement 出來 chūlái","ens":"To Figure out with the Complement 出来 chūlái","tc":"V＋出來","sc":"V＋出来"},"d":{"es":"V + 出來 = descubrir, distinguir o llegar a darse cuenta (sacar a la luz).","en":"V + 出來 means to figure out, make out or discover something.","tc":"「V＋出來」表示把原本不清楚的事情找出來、分辨出來或想出來。","sc":"「V＋出来」表示把原本不清楚的事情找出来、分辨出来或想出来。"},"ex":[{"c":"你聽得出來他是誰嗎？","s":"你听得出来他是谁吗？","es":"¿Puedes reconocer quién es por la voz?","en":"Can you tell who he is from his voice?","p":"nǐ tīng dé chū lái tā shì shéi ma?"}]},{"id":"2-10-1","b":2,"l":10,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Caber con 下","en":"Enough Space to Accommodate with Verb Complement 下 xià","ens":"Enough Space to Accommodate with Verb Complement 下 xià","tc":"V＋得下／不下","sc":"V＋得下／不下"},"d":{"es":"V + 得下 / 不下 = hay / no hay espacio suficiente para acomodar algo.","en":"V + 得下 / 不下 means whether there is enough space to hold something.","tc":"「V＋得下／不下」表示空間夠不夠容納。","sc":"「V＋得下／不下」表示空间够不够容纳。"},"ex":[{"c":"這個房間坐得下十個人。","s":"这个房间坐得下十个人。","es":"En este cuarto caben diez personas sentadas.","en":"This room can seat ten people.","p":"zhè ge fáng jiān zuò de xià shí ge rén."}]},{"id":"2-10-2","b":2,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 reduplicación repetición reduplication repetition 重疊 disposición objeto complemento disposal object ba 处置 把字句 reduplicación repetición reduplication repetition 重叠","t":{"es":"把…V(一)V","en":"Disposal Construction 把 bǎ with Verb Reduplication 把 bǎ…V(一)V","ens":"Disposal Construction 把 bǎ with Verb Reduplication 把 bǎ…V(一)V","tc":"把＋物＋V(一)V","sc":"把＋物＋V(一)V"},"d":{"es":"把 + objeto + V(一)V = hacer algo con el objeto de forma breve o ligera.","en":"把 + object + V(一)V means to do something to the object briefly or lightly.","tc":"「把＋東西＋V(一)V」表示稍微處理一下那個東西，語氣輕鬆。","sc":"「把＋东西＋V(一)V」表示稍微处理一下那个东西，语气轻松。"},"ex":[{"c":"請你把房間整理整理。","s":"请你把房间整理整理。","es":"Por favor ordena un poco el cuarto.","en":"Please tidy up the room a bit.","p":"qǐng nǐ bǎ fáng jiān zhěng lǐ zhěng lǐ."}]},{"id":"2-10-3","b":2,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 complemento resultado potencial complement result potential 補語 結果補語 可能補語 disposición objeto complemento disposal object ba 处置 把字句 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"把 con resultado","en":"Disposal Construction 把 bǎ with Resultative Complements","ens":"Disposal Construction 把 bǎ with Resultative Complements","tc":"把＋物＋V＋結果補語","sc":"把＋物＋V＋结果补语"},"d":{"es":"把 + objeto + V + complemento de resultado (完, 好, 乾淨, 壞…): el objeto queda en ese estado.","en":"把 + object + verb + result complement (完, 好, 乾淨, 壞…) shows the state the object ends up in.","tc":"「把＋東西＋動詞＋結果補語（完、好、乾淨、壞……）」表示東西因為這個動作變成某種結果。","sc":"「把＋东西＋动词＋结果补语（完、好、干净、坏……）」表示东西因为这个动作变成某种结果。"},"ex":[{"c":"我把衣服洗乾淨了。","s":"我把衣服洗干净了。","es":"Lavé la ropa y quedó limpia.","en":"I washed the clothes clean.","p":"wǒ bǎ yī fú xǐ gān jìng le."}]},{"id":"2-10-4","b":2,"l":10,"k":"","t":{"es":"Aprovechar con 趁","en":"趁 chèn seize the moment","ens":"趁 chèn seize the moment","tc":"趁","sc":"趁"},"d":{"es":"趁 + oportunidad + verbo = aprovechar el momento para…","en":"趁 + opportunity + verb means 'take advantage of the moment to…'.","tc":"「趁＋機會＋動詞」表示利用某個機會或時間去做事。","sc":"「趁＋机会＋动词」表示利用某个机会或时间去做事。"},"ex":[{"c":"趁天氣好，我們去爬山吧。","s":"趁天气好，我们去爬山吧。","es":"Aprovechemos que hace buen tiempo para ir a la montaña.","en":"Let's go hiking while the weather is nice.","p":"chèn tiān qì hǎo, wǒ men qù pá shān ba."}]},{"id":"2-11-0","b":2,"l":11,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"其他的 vs 別的","en":"The Others 其他 qítā de vs. Other 別的 biéde vs.","ens":"The Others 其他 qítā de vs. Other 别的 biéde vs.","tc":"其他的、別的","sc":"其他的、别的"},"d":{"es":"其他的 = los demás (el resto de un grupo). 別的 = otro, diferente (otra cosa u opción).","en":"其他的 means 'the rest' of a group; 別的 means 'another / something different'.","tc":"「其他的」是一群裡面剩下的人或東西；「別的」是另外不同的東西或選擇。","sc":"「其他的」是一群里面剩下的人或东西；「别的」是另外不同的东西或选择。"},"ex":[{"c":"其他的同學都走了。","s":"其他的同学都走了。","es":"Los demás compañeros ya se fueron.","en":"The other classmates have all left.","p":"qí tā de tóng xué dōu zǒu le."},{"c":"這個我不要，我要別的。","s":"这个我不要，我要别的。","es":"Esto no lo quiero, quiero otra cosa.","en":"I don't want this one; I want something else.","p":"zhè ge wǒ bú yào, wǒ yào bié de."}]},{"id":"2-11-1","b":2,"l":11,"k":"clasificador clasificadores medida contar cantidad measure word classifier counter 量詞 clasificador clasificadores medida contar cantidad measure word classifier counter 量词","t":{"es":"Clasificadores verbales","en":"Verbal Classifiers 下 xià , 趟 tàng ,遍 biàn , and 次 cì","ens":"Verbal Classifiers 下 xià , 趟 tàng ,遍 biàn , and 次 cì","tc":"動量詞：下、趟、遍、次","sc":"动量词：下、趟、遍、次"},"d":{"es":"Clasificadores verbales: 次 = veces; 遍 = de principio a fin; 趟 = viaje de ida y vuelta; 下 = acción breve.","en":"Verbal measure words count actions: 次 = times; 遍 = once from start to finish; 趟 = a round trip; 下 = a short action.","tc":"動量詞用來算動作的次數：「次」是回數；「遍」是從頭到尾一次；「趟」是去一次再回來；「下」是很短的動作。","sc":"动量词用来算动作的次数：「次」是回数；「遍」是从头到尾一次；「趟」是去一次再回来；「下」是很短的动作。"},"ex":[{"c":"我去過兩次。","s":"我去过两次。","es":"He ido dos veces.","en":"I have been there twice.","p":"wǒ qù guò liǎng cì."},{"c":"請你再說一遍。","s":"请你再说一遍。","es":"Por favor dilo una vez más.","en":"Please say it once more.","p":"qǐng nǐ zài shuō yí biàn."}]},{"id":"2-11-2","b":2,"l":11,"k":"tiempo momento orden secuencia time order sequence 時間 順序 dirección movimiento direction movement 方向 趨向 tiempo momento orden secuencia time order sequence 时间 顺序 dirección movimiento direction movement 方向 趋向","t":{"es":"然後、後來、以後","en":"Expressing Next in Sequence with 然後 ránhòu, 後來 hòulái, and 以後 yǐhòu","ens":"Expressing Next in Sequence with 然后 ránhòu, 后来 hòulái, and 以后 yǐhòu","tc":"然後、後來、以後","sc":"然后、后来、以后"},"d":{"es":"然後 = luego (secuencia); 後來 = más tarde (solo para el pasado); 以後 = después (pasado o futuro).","en":"然後 means 'and then' (sequence); 後來 means 'later' (only for the past); 以後 means 'after' (past or future).","tc":"「然後」表示接著；「後來」只能說過去的事；「以後」可以說過去或未來。","sc":"「然后」表示接着；「后来」只能说过去的事；「以后」可以说过去或未来。"},"ex":[{"c":"我先吃飯，然後看電視。","s":"我先吃饭，然后看电视。","es":"Primero como y luego veo televisión.","en":"First I eat, then I watch TV.","p":"wǒ xiān chī fàn, rán hòu kàn diàn shì."},{"c":"後來他搬家了。","s":"后来他搬家了。","es":"Más tarde se mudó.","en":"Later he moved house.","p":"hòu lái tā bān jiā le."}]},{"id":"2-11-3","b":2,"l":11,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Solo entonces con 才","en":"才 cái then and only then","ens":"才 cái then and only then","tc":"A才B（先後條件）","sc":"A才B（先后条件）"},"d":{"es":"A 才 B = solo después de A ocurre B (A es condición previa).","en":"A 才 B means B happens only after A. A is a prerequisite.","tc":"「A 才 B」表示要先有 A，才會有 B，A 是前提。","sc":"「A 才 B」表示要先有 A，才会有 B，A 是前提。"},"ex":[{"c":"吃了飯才可以玩。","s":"吃了饭才可以玩。","es":"Solo después de comer puedes jugar.","en":"You can play only after you eat.","p":"chī le fàn cái kě yǐ wán."}]},{"id":"2-11-4","b":2,"l":11,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Pasiva con 被","en":"Passive Sentences with 被 bèi","ens":"Passive Sentences with 被 bèi","tc":"被字句","sc":"被字句"},"d":{"es":"A 被 B + verbo + complemento = A es afectado por B (pasiva, suele tener sentido negativo).","en":"A 被 B + verb + complement means A is affected by B (passive). It often describes something unfortunate.","tc":"「A 被 B ＋動詞＋補語」表示 A 受到 B 的影響，常常是不好的事。","sc":"「A 被 B ＋动词＋补语」表示 A 受到 B 的影响，常常是不好的事。"},"ex":[{"c":"我的手機被偷了。","s":"我的手机被偷了。","es":"Me robaron el celular.","en":"My phone was stolen.","p":"wǒ de shǒu jī bèi tōu le."}]},{"id":"2-11-5","b":2,"l":11,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"V了V","en":"Verb Reduplication in V 了 le V","ens":"Verb Reduplication in V 了 le V","tc":"V了V","sc":"V了V"},"d":{"es":"V 了 V = hacer algo un ratito o un poco (acción ya realizada).","en":"V了V means doing something for a little while (an action already carried out).","tc":"「V了V」表示做了一下子，是已經做過的動作。","sc":"「V了V」表示做了一下子，是已经做过的动作。"},"ex":[{"c":"我想了想，決定不去。","s":"我想了想，决定不去。","es":"Lo pensé un poco y decidí no ir.","en":"I thought about it for a moment and decided not to go.","p":"wǒ xiǎng le xiǎng, jué dìng bú qù."}]},{"id":"2-11-6","b":2,"l":11,"k":"","t":{"es":"Contacto con 上","en":"Verb Particle 上 shàng coming into contact","ens":"Verb Particle 上 shàng coming into contact","tc":"V＋上","sc":"V＋上"},"d":{"es":"V + 上 expresa contacto o cierre: 關上 (cerrar), 穿上 (ponerse), 考上 (ser admitido), 愛上 (enamorarse).","en":"V + 上 shows contact or closing: 關上 (close), 穿上 (put on), 考上 (get admitted), 愛上 (fall in love with).","tc":"「V＋上」表示接觸或閉合，例如關上、穿上、考上、愛上。","sc":"「V＋上」表示接触或闭合，例如关上、穿上、考上、爱上。"},"ex":[{"c":"請關上門。","s":"请关上门。","es":"Por favor cierra la puerta.","en":"Please close the door.","p":"qǐng guān shàng mén."},{"c":"他考上大學了。","s":"他考上大学了。","es":"Entró a la universidad.","en":"He got into university.","p":"tā kǎo shàng dà xué le."}]},{"id":"2-12-0","b":2,"l":12,"k":"","t":{"es":"Dejar con 讓","en":"讓 ràng to let someone do something","ens":"让 ràng to let someone do something","tc":"讓","sc":"让"},"d":{"es":"A 讓 B + verbo = A deja / hace que B haga algo (permiso o causa).","en":"A 讓 B + verb means A lets / makes B do something (permission or cause).","tc":"「A 讓 B ＋動詞」表示 A 允許或使 B 去做某件事。","sc":"「A 让 B ＋动词」表示 A 允许或使 B 去做某件事。"},"ex":[{"c":"媽媽讓我去玩。","s":"妈妈让我去玩。","es":"Mi mamá me deja ir a jugar.","en":"Mom lets me go play.","p":"mā ma ràng wǒ qù wán."}]},{"id":"2-12-1","b":2,"l":12,"k":"","t":{"es":"Apúrate con 快一點","en":"快一點 kuài yìdiǎn hurry up","ens":"快一点 kuài yìdiǎn hurry up","tc":"快一點","sc":"快一点"},"d":{"es":"快一點 = ¡date prisa! (petición o mandato suave).","en":"快一點 is a gentle urging: 'hurry up'.","tc":"「快一點」是催促的說法，語氣比較柔和，意思是動作快一點。","sc":"「快一点」是催促的说法，语气比较柔和，意思是动作快一点。"},"ex":[{"c":"快一點，我們要遲到了。","s":"快一点，我们要迟到了。","es":"Apúrate, vamos a llegar tarde.","en":"Hurry up, we're going to be late.","p":"kuài yì diǎn, wǒ men yào chí dào le."}]},{"id":"2-12-2","b":2,"l":12,"k":"","t":{"es":"Mencionar con 起","en":"Verb Particle 起 qǐ to touch upon","ens":"Verb Particle 起 qǐ to touch upon","tc":"V＋起（談起、提起）","sc":"V＋起（谈起、提起）"},"d":{"es":"V + 起 (談起, 提起, 說起, 想起) = empezar a mencionar un tema.","en":"V + 起 (談起, 提起, 說起) means to begin mentioning a topic.","tc":"「V＋起」，例如談起、提起、說起，表示開始提到某個話題。","sc":"「V＋起」，例如谈起、提起、说起，表示开始提到某个话题。"},"ex":[{"c":"他常常談起他的家人。","s":"他常常谈起他的家人。","es":"Habla a menudo de su familia.","en":"He often talks about his family.","p":"tā cháng cháng tán qǐ tā de jiā rén."}]},{"id":"2-12-3","b":2,"l":12,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Con tal de que 只要…就","en":"只要 zhǐyào……就 jiù… …as long as…","ens":"只要 zhǐyào……就 jiù… …as long as…","tc":"只要…就…","sc":"只要…就…"},"d":{"es":"只要 A 就 B = con tal de que A, B (A es condición suficiente).","en":"只要 A 就 B means 'as long as A, then B' (A is a sufficient condition).","tc":"「只要 A 就 B」表示只需要 A 這個條件，就會有 B。","sc":"「只要 A 就 B」表示只需要 A 这个条件，就会有 B。"},"ex":[{"c":"只要你努力，就會成功。","s":"只要你努力，就会成功。","es":"Con tal de que te esfuerces, tendrás éxito.","en":"As long as you work hard, you will succeed.","p":"zhǐ yào nǐ nǔ lì, jiù huì chéng gōng."}]},{"id":"2-12-4","b":2,"l":12,"k":"","t":{"es":"Cuanto más… con 越…越","en":"越 yuè…越 yuè…the more…, the more…","ens":"越 yuè…越 yuè…the more…, the more…","tc":"越…越…","sc":"越…越…"},"d":{"es":"越 A 越 B = cuanto más A, más B.","en":"越 A 越 B means 'the more A, the more B'.","tc":"「越 A 越 B」表示 A 的程度增加，B 也跟著增加。","sc":"「越 A 越 B」表示 A 的程度增加，B 也跟着增加。"},"ex":[{"c":"他越說越快。","s":"他越说越快。","es":"Cuanto más habla, más rápido habla.","en":"The more he talks, the faster he gets.","p":"tā yuè shuō yuè kuài."}]},{"id":"2-12-5","b":2,"l":12,"k":"","t":{"es":"Tema de contraste","en":"Topic as Contrastive","ens":"Topic as Contrastive","tc":"對比的主題","sc":"对比的主题"},"d":{"es":"Un tema al inicio sirve para contrastar con otro: «en cuanto a A…, pero B…».","en":"Putting a topic at the start of the sentence sets up a contrast: 'as for A…, but B…'.","tc":"把一個主題放在句子開頭，用來和另一件事對比：就 A 來說……，可是 B……。","sc":"把一个主题放在句子开头，用来和另一件事对比：就 A 来说……，可是 B……。"},"ex":[{"c":"中文我會說，可是不會寫。","s":"中文我会说，可是不会写。","es":"El chino sí sé hablarlo, pero no sé escribirlo.","en":"I can speak Chinese, but I can't write it.","p":"zhōng wén wǒ huì shuō, kě shì bú huì xiě."}]},{"id":"2-13-0","b":2,"l":13,"k":"pasado completado terminado past completed finished perfective 完成 過去 experiencia alguna vez haber experience ever 經驗 經歷 pasado completado terminado past completed finished perfective 完成 过去 experiencia alguna vez haber experience ever 经验 经历","t":{"es":"Haber terminado con 過","en":"Completion of Action with V+過 guò","ens":"Completion of Action with V+过 guò","tc":"V＋過（完成）","sc":"V＋过（完成）"},"d":{"es":"V + 過 también indica que ya terminó de hacer algo (acción completada). Se usa sobre todo en preguntas: 吃過飯了嗎？","en":"V + 過 can also mean that an action has already been completed, mostly in questions: 吃過飯了嗎？","tc":"「V＋過」也可以表示已經做完某件事，多用在問句，例如「吃過飯了嗎？」","sc":"「V＋过」也可以表示已经做完某件事，多用在问句，例如「吃过饭了吗？」"},"ex":[{"c":"你吃過飯了嗎？","s":"你吃过饭了吗？","es":"¿Ya comiste?","en":"Have you eaten yet?","p":"nǐ chī guò fàn le ma?"}]},{"id":"2-13-1","b":2,"l":13,"k":"","t":{"es":"Alejarse con 走","en":"Verb Particle 走 zǒu away","ens":"Verb Particle 走 zǒu away","tc":"V＋走","sc":"V＋走"},"d":{"es":"V + 走 = llevarse, irse (alejarse): 拿走, 帶走, 開走.","en":"V + 走 means taking away or leaving: 拿走, 帶走, 開走.","tc":"「V＋走」表示離開或被帶走，例如拿走、帶走、開走。","sc":"「V＋走」表示离开或被带走，例如拿走、带走、开走。"},"ex":[{"c":"他把我的書拿走了。","s":"他把我的书拿走了。","es":"Se llevó mi libro.","en":"He took my book away.","p":"tā bǎ wǒ de shū ná zǒu le."}]},{"id":"2-13-2","b":2,"l":13,"k":"","t":{"es":"Mandar con 叫","en":"Imperative Sentences with 叫 jiào","ens":"Imperative Sentences with 叫 jiào","tc":"叫（命令、要求）","sc":"叫（命令、要求）"},"d":{"es":"A 叫 B + verbo = A manda o pide a B que haga algo.","en":"A 叫 B + verb means A tells / asks B to do something.","tc":"「A 叫 B ＋動詞」表示 A 要求或命令 B 去做某件事。","sc":"「A 叫 B ＋动词」表示 A 要求或命令 B 去做某件事。"},"ex":[{"c":"老師叫我們寫作業。","s":"老师叫我们写作业。","es":"El profesor nos pide hacer la tarea.","en":"The teacher asks us to do the homework.","p":"lǎo shī jiào wǒ men xiě zuò yè."}]},{"id":"2-13-3","b":2,"l":13,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Dejar de con 別再…了","en":"別再 bié zài…了 le stop doing it","ens":"别再 bié zài…了 le stop doing it","tc":"別再…了","sc":"别再…了"},"d":{"es":"別再 + verbo + 了 = no lo vuelvas a hacer / deja de hacerlo.","en":"別再 + verb + 了 means 'don't do it again / stop doing it'.","tc":"「別再＋動詞＋了」表示不要再重複做，或叫對方停止。","sc":"「别再＋动词＋了」表示不要再重复做，或叫对方停止。"},"ex":[{"c":"你別再玩手機了。","s":"你别再玩手机了。","es":"Deja de jugar con el celular.","en":"Stop playing with your phone.","p":"nǐ bié zài wán shǒu jī le."}]},{"id":"2-13-4","b":2,"l":13,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Seguridad con 會…的","en":"To offer assurance with 會 huì…的 de…","ens":"To offer assurance with 会 huì…的 de…","tc":"會…的（保證）","sc":"会…的（保证）"},"d":{"es":"會…的 expresa seguridad o promesa sobre el futuro: «seguro que…».","en":"會…的 expresses confidence about the future, with a reassuring tone: 'surely…'.","tc":"「會……的」表示說話的人很確定未來會發生，有保證、安慰的語氣。","sc":"「会……的」表示说话的人很确定未来会发生，有保证、安慰的语气。"},"ex":[{"c":"你放心，他會來的。","s":"你放心，他会来的。","es":"Tranquilo, seguro que viene.","en":"Don't worry, he will come.","p":"nǐ fàng xīn, tā huì lái de."}]},{"id":"2-13-5","b":2,"l":13,"k":"","t":{"es":"Por medio de 透過","en":"透過 tòuguò… by means of…","ens":"透过 tòuguò… by means of…","tc":"透過","sc":"透过"},"d":{"es":"透過 + medio o persona = por medio de, a través de.","en":"透過 + means or person means 'through, by means of'.","tc":"「透過＋方法或人」表示經由某個管道或人。","sc":"「透过＋方法或人」表示经由某个管道或人。"},"ex":[{"c":"我是透過朋友認識他的。","s":"我是透过朋友认识他的。","es":"Lo conocí por medio de un amigo.","en":"I met him through a friend.","p":"wǒ shì tòu guò péng yǒu rèn shì tā de."}]},{"id":"2-13-6","b":2,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"才…就…","en":"才 cái…就 jiù… only just…, and…already","ens":"才 cái…就 jiù… only just…, and…already","tc":"才…就…","sc":"才…就…"},"d":{"es":"A 才 B 就 C = apenas A y ya B: algo ocurrió muy pronto.","en":"A 才 B 就 C means 'barely A and already B': something happened very soon.","tc":"「A 才 B 就 C」表示剛剛 A，很快就 B，表示事情發生得很快。","sc":"「A 才 B 就 C」表示刚刚 A，很快就 B，表示事情发生得很快。"},"ex":[{"c":"他才來一個月就學會了。","s":"他才来一个月就学会了。","es":"Apenas llevaba un mes y ya aprendió.","en":"He had been here only a month and had already learned it.","p":"tā cái lái yí ge yuè jiù xué huì le."}]},{"id":"2-13-7","b":2,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 siempre nunca frecuencia always never frequency 經常 從來 tiempo momento orden secuencia time order sequence 时间 顺序 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Frecuencia con 每","en":"Frequency with 每 měi + Time Expression","ens":"Frequency with 每 měi + Time Expression","tc":"每＋時間＋次數","sc":"每＋时间＋次数"},"d":{"es":"每 + tiempo + frecuencia = tantas veces cada…","en":"每 + time + frequency means how many times something happens in each period.","tc":"「每＋時間＋次數」表示在固定的時間裡做幾次。","sc":"「每＋时间＋次数」表示在固定的时间里做几次。"},"ex":[{"c":"我每個星期游泳兩次。","s":"我每个星期游泳两次。","es":"Nado dos veces por semana.","en":"I swim twice a week.","p":"wǒ měi ge xīng qí yóu yǒng liǎng cì."}]},{"id":"2-13-8","b":2,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Solo si con 只有…才","en":"只有 zhǐyǒu…，才 cái… cannot …, unless…","ens":"只有 zhǐyǒu…，才 cái… cannot …, unless…","tc":"只有…才…","sc":"只有…才…"},"d":{"es":"只有 A 才 B = solo si A, B (A es condición necesaria).","en":"只有 A 才 B means 'only if A, then B' (A is a necessary condition).","tc":"「只有 A 才 B」表示 A 是唯一的條件，沒有 A 就不會有 B。","sc":"「只有 A 才 B」表示 A 是唯一的条件，没有 A 就不会有 B。"},"ex":[{"c":"只有多練習，才能說得好。","s":"只有多练习，才能说得好。","es":"Solo practicando mucho se puede hablar bien.","en":"Only with lots of practice can you speak well.","p":"zhǐ yǒu duō liàn xí, cái néng shuō de hǎo."}]},{"id":"2-14-0","b":2,"l":14,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"A punto de con 就要…了","en":"就要 jiù yào…了 le will soon…","ens":"就要 jiù yào…了 le will soon…","tc":"就要…了","sc":"就要…了"},"d":{"es":"就要 + verbo + 了 = estar a punto de. Es más cercano que 快…了.","en":"就要 + verb + 了 means 'about to happen', closer in time than 快…了.","tc":"「就要＋動詞＋了」表示馬上就要發生，比「快……了」更近。","sc":"「就要＋动词＋了」表示马上就要发生，比「快……了」更近。"},"ex":[{"c":"火車就要開了。","s":"火车就要开了。","es":"El tren está por salir.","en":"The train is about to leave.","p":"huǒ chē jiù yào kāi le."}]},{"id":"2-14-1","b":2,"l":14,"k":"","t":{"es":"Hablando de con 說到","en":"說到 shuōdào/談到 tándào… talking of…","ens":"说到 shuōdào/谈到 tándào… talking of…","tc":"說到／談到","sc":"说到／谈到"},"d":{"es":"說到 / 談到 + tema = hablando de…, cuando se trata de…","en":"說到 / 談到 + topic means 'speaking of…, when it comes to…'.","tc":"「說到／談到＋話題」表示說起某個話題的時候。","sc":"「说到／谈到＋话题」表示说起某个话题的时候。"},"ex":[{"c":"說到台灣小吃，我最喜歡滷肉飯。","s":"说到台湾小吃，我最喜欢卤肉饭。","es":"Hablando de comida callejera de Taiwán, lo que más me gusta es el lu rou fan.","en":"Speaking of Taiwanese street food, my favorite is braised pork rice.","p":"shuō dào tái wān xiǎo chī, wǒ zuì xǐ huān lǔ ròu fàn."}]},{"id":"2-14-2","b":2,"l":14,"k":"","t":{"es":"對A有B","en":"對 duìA 有 yǒu B to be B in A","ens":"对 duìA 有 yǒu B to be B in A","tc":"對…有…","sc":"对…有…"},"d":{"es":"對 A 有 B = hacia A hay B (efecto o sentimiento): 對…有幫助 / 有興趣 / 有信心.","en":"對 A 有 B means B (an effect or feeling) toward A: 對…有幫助 / 有興趣 / 有信心.","tc":"「對 A 有 B」表示對 A 有某種影響或感覺，例如對……有幫助、有興趣、有信心。","sc":"「对 A 有 B」表示对 A 有某种影响或感觉，例如对……有帮助、有兴趣、有信心。"},"ex":[{"c":"運動對身體有幫助。","s":"运动对身体有帮助。","es":"Hacer ejercicio ayuda al cuerpo.","en":"Exercise is good for your body.","p":"yùn dòng duì shēn tǐ yǒu bāng zhù."}]},{"id":"2-14-3","b":2,"l":14,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Incluso con 連…都","en":"連 lián…都 dōu… even","ens":"连 lián…都 dōu… even","tc":"連…都…","sc":"连…都…"},"d":{"es":"連 A 都 B = incluso A también B. A es el caso extremo.","en":"連 A 都 B means 'even A is B'. A is the extreme case.","tc":"「連 A 都 B」表示連 A 這麼極端的情況也是 B。","sc":"「连 A 都 B」表示连 A 这么极端的情况也是 B。"},"ex":[{"c":"他連飯都沒吃就走了。","s":"他连饭都没吃就走了。","es":"Se fue sin siquiera comer.","en":"He left without even eating.","p":"tā lián fàn dōu méi chī jiù zǒu le."}]},{"id":"2-14-4","b":2,"l":14,"k":"negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No solo con 不但…而且","en":"不但 búdàn…，而且 érqiě… not only…but also…","ens":"不但 búdàn…，而且 érqiě… not only…but also…","tc":"不但…，而且…","sc":"不但…，而且…"},"d":{"es":"不但 A，而且 B = no solo A sino también B.","en":"不但 A，而且 B means 'not only A but also B'.","tc":"「不但 A，而且 B」表示不只 A，還有 B。","sc":"「不但 A，而且 B」表示不只 A，还有 B。"},"ex":[{"c":"他不但會說中文，而且說得很好。","s":"他不但会说中文，而且说得很好。","es":"No solo habla chino, sino que lo habla muy bien.","en":"Not only can he speak Chinese, he speaks it very well.","p":"tā bú dàn huì shuō zhōng wén, ér qiě shuō de hěn hǎo."}]},{"id":"2-14-5","b":2,"l":14,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"把 sin querer","en":"Unintentional 把 bǎ Construction","ens":"Unintentional 把 bǎ Construction","tc":"把（非故意）","sc":"把（非故意）"},"d":{"es":"把 + objeto + verbo + complemento puede expresar algo hecho sin querer (un accidente): 弄丟, 弄壞, 忘.","en":"把 + object + verb + complement can also describe something done unintentionally, such as 弄丟, 弄壞, 忘.","tc":"「把＋東西＋動詞＋補語」也可以表示不是故意做的事，例如弄丟、弄壞、忘了。","sc":"「把＋东西＋动词＋补语」也可以表示不是故意做的事，例如弄丢、弄坏、忘了。"},"ex":[{"c":"我把鑰匙弄丟了。","s":"我把钥匙弄丢了。","es":"Perdí las llaves.","en":"I lost my keys.","p":"wǒ bǎ yuè shi nòng diū le."}]},{"id":"2-15-0","b":2,"l":15,"k":"","t":{"es":"Hasta con 到","en":"Post-verbal Preposition 到 dào upto, till","ens":"Post-verbal Preposition 到 dào upto, till","tc":"V＋到（時間、地點）","sc":"V＋到（时间、地点）"},"d":{"es":"V + 到 + tiempo / lugar = hasta (el límite de una acción).","en":"V + 到 + time / place means 'until / up to' (the limit of the action).","tc":"「V＋到＋時間或地點」表示動作持續到某個時間或地點為止。","sc":"「V＋到＋时间或地点」表示动作持续到某个时间或地点为止。"},"ex":[{"c":"我昨天工作到十二點。","s":"我昨天工作到十二点。","es":"Ayer trabajé hasta las doce.","en":"I worked until twelve o'clock yesterday.","p":"wǒ zuó tiān gōng zuò dào shí èr diǎn."}]},{"id":"2-15-1","b":2,"l":15,"k":"","t":{"es":"De uno en uno con 一M一M","en":"Manner 一 M 一 M one at a time","ens":"Manner 一 M 一 M one at a time","tc":"一M一M","sc":"一M一M"},"d":{"es":"一 + clasificador + 一 + clasificador = de uno en uno, poco a poco (manera).","en":"一 + measure word + 一 + measure word means 'one by one' or 'bit by bit'.","tc":"「一＋量詞＋一＋量詞」表示一個接著一個，例如一個一個、一口一口。","sc":"「一＋量词＋一＋量词」表示一个接着一个，例如一个一个、一口一口。"},"ex":[{"c":"請大家一個一個說。","s":"请大家一个一个说。","es":"Por favor hablen uno por uno.","en":"Please speak one by one.","p":"qǐng dà jiā yí ge yí ge shuō."}]},{"id":"2-15-2","b":2,"l":15,"k":"","t":{"es":"Cada vez más con 一M比一M","en":"Intensifying a State with 一 M 一 M more and more X; more X than the last…","ens":"Intensifying a State with 一 M 一 M more and more X; more X than the last…","tc":"一M比一M＋形容詞","sc":"一M比一M＋形容词"},"d":{"es":"一 + clasificador + 比 + 一 + clasificador + adjetivo = cada vez más…","en":"一 + measure word + 比 + 一 + measure word + adjective means 'more and more…'.","tc":"「一＋量詞＋比＋一＋量詞＋形容詞」表示越來越……。","sc":"「一＋量词＋比＋一＋量词＋形容词」表示越来越……。"},"ex":[{"c":"天氣一天比一天冷。","s":"天气一天比一天冷。","es":"Cada día hace más frío.","en":"It gets colder day by day.","p":"tiān qì yì tiān bǐ yì tiān lěng."}]},{"id":"2-15-3","b":2,"l":15,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Empezar con 起來","en":"Inchoative Meaning with 起來 qǐlái","ens":"Inchoative Meaning with 起来 qǐlái","tc":"V／形容詞＋起來（開始）","sc":"V／形容词＋起来（开始）"},"d":{"es":"V / adjetivo + 起來 = empezar a (inicio de una acción o estado).","en":"Verb / adjective + 起來 means starting an action or a state.","tc":"「動詞或形容詞＋起來」表示開始出現某個動作或狀態。","sc":"「动词或形容词＋起来」表示开始出现某个动作或状态。"},"ex":[{"c":"她突然哭起來。","s":"她突然哭起来。","es":"De pronto se puso a llorar.","en":"She suddenly started to cry.","p":"tā tú rán kū qǐ lái."},{"c":"天氣冷起來了。","s":"天气冷起来了。","es":"Empezó a hacer frío.","en":"It is getting cold.","p":"tiān qì lěng qǐ lái le."}]},{"id":"2-15-4","b":2,"l":15,"k":"","t":{"es":"Frases de cuatro caracteres","en":"Four-character Phrases 四字格 sìzìgé","ens":"Four-character Phrases 四字格 sìzìgé","tc":"四字格","sc":"四字格"},"d":{"es":"Las expresiones de cuatro caracteres (四字格) condensan una idea y se usan como una unidad fija.","en":"Four-character phrases (四字格) are fixed expressions that express an idea concisely. Learn them as a unit.","tc":"四字格是由四個字組成的固定說法，用來簡短表達一個意思，要當成一個整體來記。","sc":"四字格是由四个字组成的固定说法，用来简短表达一个意思，要当成一个整体来记。"},"ex":[{"c":"這次考試我考得馬馬虎虎。","s":"这次考试我考得马马虎虎。","es":"En este examen me fue así así.","en":"I did so-so on this exam.","p":"zhè cì kǎo shì wǒ kǎo dé mǎ mǎ hǔ hǔ."}]},{"id":"3-1-0","b":3,"l":1,"k":"condicional condición si conditional condition if 條件 假設 如果 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Si…: …的話","en":"…的話 if, supposing","ens":"…的话 if, supposing","tc":"…的話","sc":"…的话"},"d":{"es":"A 的話，B = si A, entonces B (condicional coloquial). Se combina con 如果 / 要是.","en":"A 的話，B = if A, then B (colloquial conditional). Often used with 如果 or 要是.","tc":"A 的話，B：如果 A 發生，就 B。口語常和「如果」「要是」一起用。","sc":"A 的话，B：如果 A 发生，就 B。口语常和「如果」「要是」一起用。"},"ex":[{"c":"如果你有空的話，我們一起去吧。","s":"如果你有空的话，我们一起去吧。","es":"Si tienes tiempo, vamos juntos.","en":"If you have time, let's go together.","p":"rú guǒ nǐ yǒu kòng de huà, wǒ men yì qǐ qù ba."}]},{"id":"3-1-1","b":3,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Menos de: 不到","en":"不到 less than","ens":"不到 less than","tc":"不到","sc":"不到"},"d":{"es":"不到 + cantidad = menos de.","en":"不到 + quantity = less than that amount.","tc":"不到＋數量：比那個數量還少。","sc":"不到＋数量：比那个数量还少。"},"ex":[{"c":"我等了不到十分鐘。","s":"我等了不到十分钟。","es":"Esperé menos de diez minutos.","en":"I waited less than ten minutes.","p":"wǒ děng le bú dào shí fēn zhōng."}]},{"id":"3-1-2","b":3,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Por poco: 差一點","en":"差一點（就）… almost","ens":"差一点（就）… almost","tc":"差一點","sc":"差一点"},"d":{"es":"差一點(就) + verbo = por poco ocurre (pero no ocurrió).","en":"差一點(就) + verb = almost happened, but in the end did not.","tc":"差一點(就)＋動詞：幾乎發生，但最後沒發生。","sc":"差一点(就)＋动词：几乎发生，但最后没发生。"},"ex":[{"c":"我差一點就遲到了。","s":"我差一点就迟到了。","es":"Por poco llego tarde.","en":"I almost was late.","p":"wǒ chā yì diǎn jiù chí dào le."}]},{"id":"3-1-3","b":3,"l":1,"k":"","t":{"es":"Me temo que: 恐怕","en":"恐怕… probably","ens":"恐怕… probably","tc":"恐怕","sc":"恐怕"},"d":{"es":"恐怕 = me temo que, probablemente (sobre algo desfavorable).","en":"恐怕 = I'm afraid that…, probably (about something undesirable).","tc":"恐怕：擔心或推測不太好的事情可能會發生，意思是「我怕…」。","sc":"恐怕：担心或推测不太好的事情可能会发生，意思是「我怕…」。"},"ex":[{"c":"恐怕要下雨了。","s":"恐怕要下雨了。","es":"Me temo que va a llover.","en":"I'm afraid it's going to rain.","p":"kǒng pà yào xià yǔ le."}]},{"id":"3-1-4","b":3,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Por fin: 好不容易","en":"好不容易 finally managed to","ens":"好不容易 finally managed to","tc":"好不容易","sc":"好不容易"},"d":{"es":"好不容易 = con mucha dificultad, por fin logró.","en":"好不容易(才) = after great difficulty, finally managed to.","tc":"好不容易（才）：經過很多困難，終於做到。","sc":"好不容易（才）：经过很多困难，终于做到。"},"ex":[{"c":"我好不容易才買到票。","s":"我好不容易才买到票。","es":"Con mucho trabajo por fin conseguí el boleto.","en":"After a lot of trouble I finally managed to get the ticket.","p":"wǒ hǎo bù róng yì cái mǎi dào piào."}]},{"id":"3-1-5","b":3,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Decir y hacer: 說…就…","en":"Instantly without Prior Warning with 說…就…","ens":"Instantly without Prior Warning with 说…就…","tc":"說…就…","sc":"说…就…"},"d":{"es":"說 A 就 A = hacer algo en cuanto se dice, sin previo aviso.","en":"說 A 就 A = does it right away as soon as it's said, with no warning.","tc":"說 A 就 A：一說就馬上做，沒有任何預告。","sc":"说 A 就 A：一说就马上做，没有任何预告。"},"ex":[{"c":"他說走就走。","s":"他说走就走。","es":"Dijo que se iba y se fue de inmediato.","en":"He said he was leaving and left right away.","p":"tā shuō zǒu jiù zǒu."}]},{"id":"3-1-6","b":3,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No importa: 不管…都","en":"不管…都 … regardless of whether or not","ens":"不管…都 … regardless of whether or not","tc":"不管…都…","sc":"不管…都…"},"d":{"es":"不管 + pregunta u opciones，都… = no importa…, siempre…","en":"不管 + question or alternatives, 都 + result = no matter what, the result is the same.","tc":"不管＋疑問或選項，都＋結果：不論情況怎麼樣，結果都一樣。","sc":"不管＋疑问或选项，都＋结果：不论情况怎么样，结果都一样。"},"ex":[{"c":"不管天氣好不好，他都去爬山。","s":"不管天气好不好，他都去爬山。","es":"Haga o no haga buen tiempo, él va a la montaña.","en":"Whether the weather is good or not, he goes hiking.","p":"bù guǎn tiān qì hǎo bù hǎo, tā dōu qù pá shān."}]},{"id":"3-2-0","b":3,"l":2,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"En general: 一般來說","en":"一般來說 generally speaking","ens":"一般来说 generally speaking","tc":"一般來說","sc":"一般来说"},"d":{"es":"一般來說 = en general, por lo común.","en":"一般來說 = generally, usually (not necessarily every time).","tc":"一般來說：通常的情況是…，不一定每次都這樣。","sc":"一般来说：通常的情况是…，不一定每次都这样。"},"ex":[{"c":"一般來說，學生都很忙。","s":"一般来说，学生都很忙。","es":"En general, los estudiantes están ocupados.","en":"Generally speaking, students are all busy.","p":"yì bān lái shuō, xué shēng dōu hěn máng."}]},{"id":"3-2-1","b":3,"l":2,"k":"","t":{"es":"Verbo comodín: 弄","en":"General Verb 弄","ens":"General Verb 弄","tc":"弄","sc":"弄"},"d":{"es":"弄 es un verbo comodín: «hacer, arreglar, estropear» según el complemento: 弄壞, 弄髒, 弄好.","en":"弄 is an all-purpose verb; its meaning depends on the complement: 弄壞 (break), 弄髒 (dirty), 弄好 (fix).","tc":"「弄」是萬用動詞，意思會跟著後面的補語變，例如弄壞、弄髒、弄好。","sc":"「弄」是万用动词，意思会跟着后面的补语变，例如弄坏、弄脏、弄好。"},"ex":[{"c":"我把手機弄壞了。","s":"我把手机弄坏了。","es":"Descompuse mi celular.","en":"I broke my phone.","p":"wǒ bǎ shǒu jī nòng huài le."}]},{"id":"3-2-2","b":3,"l":2,"k":"tiempo momento orden secuencia time order sequence 時間 順序 además adición también addition also besides 另外 而且 tiempo momento orden secuencia time order sequence 时间 顺序 además adición también addition also besides 另外 而且","t":{"es":"Además: 再說","en":"再說 besides, moreover","ens":"再说 besides, moreover","tc":"再說","sc":"再说"},"d":{"es":"再說 = además, y por si fuera poco (añade otra razón).","en":"再說 = besides, what's more (adds another reason).","tc":"再說：再補充一個理由，意思是「而且」「何況」。","sc":"再说：再补充一个理由，意思是「而且」「何况」。"},"ex":[{"c":"太晚了，再說我也累了，明天再去吧。","s":"太晚了，再说我也累了，明天再去吧。","es":"Es muy tarde, además estoy cansado; vamos mañana.","en":"It's too late, and besides I'm tired too; let's go tomorrow.","p":"tài wǎn le, zài shuō wǒ yě lèi le, míng tiān zài qù ba."}]},{"id":"3-2-3","b":3,"l":2,"k":"","t":{"es":"Convertir en: V成","en":"V+成 to become, to turn into","ens":"V+成 to become, to turn into","tc":"V成","sc":"V成"},"d":{"es":"V + 成 = convertir, resultar en: 變成, 寫成, 翻成.","en":"Verb + 成 = turn into, convert to: 變成, 寫成, 翻成.","tc":"動詞＋成：表示變成、轉換成另一種東西，例如變成、寫成、翻成。","sc":"动词＋成：表示变成、转换成另一种东西，例如变成、写成、翻成。"},"ex":[{"c":"請把這句話翻成中文。","s":"请把这句话翻成中文。","es":"Por favor traduce esta frase al chino.","en":"Please translate this sentence into Chinese.","p":"qǐng bǎ zhè jù huà fān chéng zhōng wén."}]},{"id":"3-2-4","b":3,"l":2,"k":"","t":{"es":"En realidad no: 並","en":"Contrary to Expectation with 並","ens":"Contrary to Expectation with 并","tc":"並不／並沒有","sc":"并不／并没有"},"d":{"es":"並 + 不 / 沒 = en realidad no. Refuerza una negación contraria a lo que se esperaba.","en":"並 + 不/沒 = actually not; strengthens a negation that goes against expectations.","tc":"並＋不／沒：加強否定，表示事實跟想像或預期不一樣。","sc":"并＋不／没：加强否定，表示事实跟想像或预期不一样。"},"ex":[{"c":"這件事並不難。","s":"这件事并不难。","es":"Este asunto en realidad no es difícil.","en":"This matter is actually not difficult.","p":"zhè jiàn shì bìng bù nán."}]},{"id":"3-2-5","b":3,"l":2,"k":"","t":{"es":"Sobre todo: 尤其是","en":"尤其是 especially","ens":"尤其是 especially","tc":"尤其是","sc":"尤其是"},"d":{"es":"尤其是 = especialmente. Destaca un caso dentro de un grupo.","en":"尤其是 = especially; singles out one case within a group.","tc":"尤其是：在一群裡特別強調其中一個。","sc":"尤其是：在一群里特别强调其中一个。"},"ex":[{"c":"我喜歡水果，尤其是芒果。","s":"我喜欢水果，尤其是芒果。","es":"Me gustan las frutas, sobre todo el mango.","en":"I like fruit, especially mango.","p":"wǒ xǐ huān shuǐ guǒ, yóu qí shì máng guǒ."}]},{"id":"3-2-6","b":3,"l":2,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No hay remedio: 只好","en":"Concession with 只好 could only, have no choice but to","ens":"Concession with 只好 could only, have no choice but to","tc":"只好","sc":"只好"},"d":{"es":"只好 + verbo = no queda más remedio que…","en":"只好 + verb = have no choice but to.","tc":"只好＋動詞：沒有別的辦法，只能這樣做。","sc":"只好＋动词：没有别的办法，只能这样做。"},"ex":[{"c":"沒有車，我們只好走路去。","s":"没有车，我们只好走路去。","es":"No hay coche, así que no nos queda más que ir caminando.","en":"There's no car, so we have no choice but to walk.","p":"méi yǒu chē, wǒ men zhǐ hǎo zǒu lù qù."}]},{"id":"3-3-0","b":3,"l":3,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Influido por: 受到…影響","en":"受到…的影響 to be influenced by, affected by","ens":"受到…的影响 to be influenced by, affected by","tc":"受到…的影響","sc":"受到…的影响"},"d":{"es":"受到 + X + 的影響 = ser influenciado por X.","en":"受到 + X + 的影響 = to be influenced by X.","tc":"受到＋人事物＋的影響：被某人或某事影響。","sc":"受到＋人事物＋的影响：被某人或某事影响。"},"ex":[{"c":"他受到爸爸的影響，也喜歡音樂。","s":"他受到爸爸的影响，也喜欢音乐。","es":"Influido por su papá, a él también le gusta la música.","en":"Influenced by his dad, he likes music too.","p":"tā shòu dào bà ba de yǐng xiǎng, yě xǐ huān yīn yuè."}]},{"id":"3-3-1","b":3,"l":3,"k":"","t":{"es":"Menos mal: 幸虧","en":"幸虧… fortunately…","ens":"幸亏… fortunately…","tc":"幸虧","sc":"幸亏"},"d":{"es":"幸虧 A，B = por suerte A, (de lo contrario habría pasado algo malo).","en":"幸虧 A, B = fortunately A (otherwise something bad would have happened).","tc":"幸虧 A，B：因為有 A 這個好運，才沒有發生不好的事。","sc":"幸亏 A，B：因为有 A 这个好运，才没有发生不好的事。"},"ex":[{"c":"幸虧你提醒我，不然我忘了。","s":"幸亏你提醒我，不然我忘了。","es":"Menos mal que me lo recordaste, si no, lo habría olvidado.","en":"Luckily you reminded me, otherwise I would have forgotten.","p":"xìng kuī nǐ tí xǐng wǒ, bù rán wǒ wàng le."}]},{"id":"3-3-2","b":3,"l":3,"k":"","t":{"es":"Se puede considerar: 算是","en":"算是… can be considered…","ens":"算是… can be considered…","tc":"算是","sc":"算是"},"d":{"es":"算是 = se puede considerar (aunque no del todo).","en":"算是 = can be considered (though not entirely).","tc":"算是：雖然不是百分之百，但可以這樣看。","sc":"算是：虽然不是百分之百，但可以这样看。"},"ex":[{"c":"這家店算是很有名的。","s":"这家店算是很有名的。","es":"Esta tienda se puede considerar muy famosa.","en":"This shop can be considered quite famous.","p":"zhè jiā diàn suàn shì hěn yǒu míng de."}]},{"id":"3-3-3","b":3,"l":3,"k":"","t":{"es":"Sí que: 是…","en":"是… It is indeed true that…","ens":"是… It is indeed true that…","tc":"是（強調）","sc":"是（强调）"},"d":{"es":"是 acentuado antes de un adjetivo o verbo confirma algo: «sí que», «en efecto».","en":"A stressed 是 before an adjective or verb confirms something: 'indeed', 'it's true that'.","tc":"「是」放在形容詞或動詞前面，要重讀，表示確認、承認「的確如此」。","sc":"「是」放在形容词或动词前面，要重读，表示确认、承认「的确如此」。"},"ex":[{"c":"他是很聰明。","s":"他是很聪明。","es":"Es cierto que es muy inteligente.","en":"He is indeed very smart.","p":"tā shì hěn cōng míng."}]},{"id":"3-3-4","b":3,"l":3,"k":"","t":{"es":"Con razón: 難怪","en":"難怪 no wonder","ens":"难怪 no wonder","tc":"難怪","sc":"难怪"},"d":{"es":"難怪 = con razón, no es de extrañar (ahora se entiende la causa).","en":"難怪 = no wonder; now the cause is understood, the result makes sense.","tc":"難怪：知道原因後，覺得結果不奇怪了。","sc":"难怪：知道原因后，觉得结果不奇怪了。"},"ex":[{"c":"他是台灣人，難怪中文說得這麼好。","s":"他是台湾人，难怪中文说得这么好。","es":"Es taiwanés, con razón habla tan bien chino.","en":"He's Taiwanese, no wonder he speaks Chinese so well.","p":"tā shì tái wān rén, nán guài zhōng wén shuō de zhè me hǎo."}]},{"id":"3-3-5","b":3,"l":3,"k":"","t":{"es":"Muchísimo: …死了","en":"A Post-verbal Intensifier 死了 terribly","ens":"A Post-verbal Intensifier 死了 terribly","tc":"…死了","sc":"…死了"},"d":{"es":"Adjetivo / verbo + 死了 = muchísimo (coloquial, para sensaciones intensas).","en":"Adj/verb + 死了 = extremely (colloquial, for strong feelings).","tc":"形容詞或動詞＋死了：非常、極了，口語，多用在強烈的感覺。","sc":"形容词或动词＋死了：非常、极了，口语，多用在强烈的感觉。"},"ex":[{"c":"我累死了。","s":"我累死了。","es":"Estoy muertísimo de cansancio.","en":"I'm dead tired.","p":"wǒ lèi sǐ le."}]},{"id":"3-3-6","b":3,"l":3,"k":"","t":{"es":"Casi: 幾乎","en":"幾乎 almost","ens":"几乎 almost","tc":"幾乎","sc":"几乎"},"d":{"es":"幾乎 = casi (casi todo, casi siempre, casi ocurre).","en":"幾乎 = almost (almost all, almost every day).","tc":"幾乎：差不多、將近，例如幾乎全部、幾乎每天。","sc":"几乎：差不多、将近，例如几乎全部、几乎每天。"},"ex":[{"c":"他幾乎每天都來。","s":"他几乎每天都来。","es":"Viene casi todos los días.","en":"He comes almost every day.","p":"tā jī hū měi tiān dōu lái."}]},{"id":"3-3-7","b":3,"l":3,"k":"","t":{"es":"Algo, un poco: 多少","en":"多少 somewhat","ens":"多少 somewhat","tc":"多少","sc":"多少"},"d":{"es":"多少 + verbo / adjetivo = en alguna medida, algo, aunque sea un poco.","en":"多少 + verb/adjective = to some extent, at least a little.","tc":"多少＋動詞或形容詞：多多少少、至少有一點。","sc":"多少＋动词或形容词：多多少少、至少有一点。"},"ex":[{"c":"他多少知道一點。","s":"他多少知道一点。","es":"Algo sabe, aunque sea un poco.","en":"He knows a little, at least.","p":"tā duō shǎo zhī dào yì diǎn."}]},{"id":"3-3-8","b":3,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Por más que: 再…也","en":"再…也… no matter how…, still…","ens":"再…也… no matter how…, still…","tc":"再…也…","sc":"再…也…"},"d":{"es":"再 + adjetivo / verbo + 也 = por más… que sea, aun así…","en":"再 + adjective/verb + 也 = no matter how…, still…","tc":"再＋形容詞或動詞＋也：就算程度很高，結果還是一樣。","sc":"再＋形容词或动词＋也：就算程度很高，结果还是一样。"},"ex":[{"c":"再忙我也要吃早餐。","s":"再忙我也要吃早餐。","es":"Por muy ocupado que esté, desayuno.","en":"No matter how busy I am, I eat breakfast.","p":"zài máng wǒ yě yào chī zǎo cān."}]},{"id":"3-4-0","b":3,"l":4,"k":"negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No solo…también: 不但…還","en":"不但…，還… not only…, but also","ens":"不但…，还… not only…, but also","tc":"不但…，還…","sc":"不但…，还…"},"d":{"es":"不但 A，還 B = no solo A, también B.","en":"不但 A，還 B = not only A, but also B.","tc":"不但 A，還 B：除了 A 以外，還有 B。","sc":"不但 A，还 B：除了 A 以外，还有 B。"},"ex":[{"c":"他不但會唱歌，還會跳舞。","s":"他不但会唱歌，还会跳舞。","es":"No solo canta, también baila.","en":"He can not only sing but also dance.","p":"tā bú dàn huì chàng gē, hái huì tiào wǔ."}]},{"id":"3-4-1","b":3,"l":4,"k":"","t":{"es":"Hablar: 說 vs 談","en":"Speak 說 vs Talk 談","ens":"Speak 说 vs Talk 谈","tc":"說 vs 談","sc":"说 vs 谈"},"d":{"es":"說 = decir o hablar (producir palabras). 談 = conversar o discutir un tema con intercambio.","en":"說 = to say or speak (produce words); 談 = to talk over or discuss a topic back and forth.","tc":"「說」是把話說出口；「談」是就某個主題互相交談、討論。","sc":"「说」是把话说出口；「谈」是就某个主题互相交谈、讨论。"},"ex":[{"c":"他說中文。","s":"他说中文。","es":"Habla chino.","en":"He speaks Chinese.","p":"tā shuō zhōng wén."},{"c":"我們談一談這個問題。","s":"我们谈一谈这个问题。","es":"Hablemos de este problema.","en":"Let's talk about this problem.","p":"wǒ men tán yì tán zhè ge wèn tí."}]},{"id":"3-4-2","b":3,"l":4,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No es…sino: 不是…而是","en":"…不是…，而是… not…; rather…","ens":"…不是…，而是… not…; rather…","tc":"不是…，而是…","sc":"不是…，而是…"},"d":{"es":"不是 A，而是 B = no es A, sino B.","en":"不是 A，而是 B = it's not A, but B.","tc":"不是 A，而是 B：不是 A，真正的是 B。","sc":"不是 A，而是 B：不是 A，真正的是 B。"},"ex":[{"c":"他不是不想去，而是沒時間。","s":"他不是不想去，而是没时间。","es":"No es que no quiera ir, es que no tiene tiempo.","en":"It's not that he doesn't want to go; he has no time.","p":"tā bú shì bù xiǎng qù, ér shì méi shí jiān."}]},{"id":"3-4-3","b":3,"l":4,"k":"negación negar negativa negation negative 否定 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 dirección movimiento direction movement 方向 趨向 siempre nunca frecuencia always never frequency 經常 從來 negación negar negativa negation negative 否定 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在 dirección movimiento direction movement 方向 趋向 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Nunca: 從來","en":"從來+Negation never","ens":"从来+Negation never","tc":"從來","sc":"从来"},"d":{"es":"從來 + 不 / 沒 (有) = nunca, jamás (hasta ahora).","en":"從來 + 不/沒 = never, not once up to now.","tc":"從來＋不／沒：到現在都沒有過。","sc":"从来＋不／没：到现在都没有过。"},"ex":[{"c":"我從來沒吃過榴槤。","s":"我从来没吃过榴梿。","es":"Nunca he comido durián.","en":"I've never eaten durian.","p":"wǒ cóng lái méi chī guò liú lián."}]},{"id":"3-4-4","b":3,"l":4,"k":"","t":{"es":"Verbo 上: 上課, 上班","en":"Various Meanings of the Verb 上","ens":"Various Meanings of the Verb 上","tc":"動詞「上」","sc":"动词「上」"},"d":{"es":"上 tiene varios sentidos como verbo: 上課, 上班, 上網, 上車 (empezar o ir a una actividad, subir).","en":"上 has several senses as a verb: 上課, 上班, 上網, 上車 (start or go to an activity, get on a vehicle).","tc":"「上」有很多用法，像上課、上班、上網、上車，常表示開始或進入某個活動，或是搭上交通工具。","sc":"「上」有很多用法，像上课、上班、上网、上车，常表示开始或进入某个活动，或是搭上交通工具。"},"ex":[{"c":"他每天坐捷運上班。","s":"他每天坐捷运上班。","es":"Va al trabajo en metro todos los días.","en":"He takes the MRT to work every day.","p":"tā měi tiān zuò jié yùn shàng bān."}]},{"id":"3-4-5","b":3,"l":4,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Sí o sí: 非…不可","en":"非…不可 it is imperative that…","ens":"非…不可 it is imperative that…","tc":"非…不可","sc":"非…不可"},"d":{"es":"非 A 不可 = es imprescindible A, tiene que ser A.","en":"非 A 不可 = must do A; there's no alternative.","tc":"非 A 不可：一定要 A，不能不。","sc":"非 A 不可：一定要 A，不能不。"},"ex":[{"c":"明天的會，你非來不可。","s":"明天的会，你非来不可。","es":"A la reunión de mañana tienes que venir sí o sí.","en":"You must come to tomorrow's meeting.","p":"míng tiān de huì, nǐ fēi lái bù kě."}]},{"id":"3-4-6","b":3,"l":4,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Para…: 對…來說","en":"對…來說 as far as...is concerned, for","ens":"对…来说 as far as...is concerned, for","tc":"對…來說","sc":"对…来说"},"d":{"es":"對 X 來說 = para X, desde la perspectiva de X.","en":"對 X 來說 = for X, from X's point of view.","tc":"對＋人＋來說：從某人的角度來看。","sc":"对＋人＋来说：从某人的角度来看。"},"ex":[{"c":"對學生來說，睡眠很重要。","s":"对学生来说，睡眠很重要。","es":"Para los estudiantes, dormir es muy importante.","en":"For students, sleep is very important.","p":"duì xué shēng lái shuō, shuì mián hěn zhòng yào."}]},{"id":"3-4-7","b":3,"l":4,"k":"","t":{"es":"Ser exigente: 講究","en":"對…講究 to be discerning, discriminating, particular about","ens":"对…讲究 to be discerning, discriminating, particular about","tc":"對…講究","sc":"对…讲究"},"d":{"es":"對 X 很講究 = ser exigente o cuidadoso con X.","en":"對 X 很講究 = to be particular or demanding about X.","tc":"對＋事情＋很講究：對這件事要求很高、很在意。","sc":"对＋事情＋很讲究：对这件事要求很高、很在意。"},"ex":[{"c":"他對吃很講究。","s":"他对吃很讲究。","es":"Es muy exigente con la comida.","en":"He's very particular about food.","p":"tā duì chī hěn jiǎng jiù."}]},{"id":"3-5-0","b":3,"l":5,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Lleno de: V滿","en":"Verb Plus Complement V+滿 crowded with","ens":"Verb Plus Complement V+满 crowded with","tc":"V滿","sc":"V满"},"d":{"es":"V + 滿 = llenar: el espacio queda lleno.","en":"Verb + 滿 = the space gets filled up.","tc":"動詞＋滿：空間被填滿了。","sc":"动词＋满：空间被填满了。"},"ex":[{"c":"教室裡坐滿了人。","s":"教室里坐满了人。","es":"El salón está lleno de gente sentada.","en":"The classroom is full of people sitting.","p":"jiào shì lǐ zuò mǎn le rén."}]},{"id":"3-5-1","b":3,"l":5,"k":"","t":{"es":"Salir/descubrir: V出","en":"Verb Particle 出 to have emerged","ens":"Verb Particle 出 to have emerged","tc":"V出（來）","sc":"V出（来）"},"d":{"es":"V + 出 (來) = salir o aparecer; también descubrir o distinguir: 想出, 做出, 看出.","en":"Verb + 出(來) = come out or make out, discover: 想出, 做出, 看出.","tc":"動詞＋出（來）：出現、發現或分辨出來，例如想出、做出、看出。","sc":"动词＋出（来）：出现、发现或分辨出来，例如想出、做出、看出。"},"ex":[{"c":"我看不出他是外國人。","s":"我看不出他是外国人。","es":"No me doy cuenta de que sea extranjero.","en":"I can't tell that he is a foreigner.","p":"wǒ kàn bù chū tā shì wài guó rén."}]},{"id":"3-5-2","b":3,"l":5,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定","t":{"es":"No tan bueno: 不如","en":"不如 not as good as","ens":"不如 not as good as","tc":"不如","sc":"不如"},"d":{"es":"A 不如 B = A no es tan bueno como B (B es mejor).","en":"A 不如 B = A is not as good as B.","tc":"A 不如 B：A 沒有 B 好。","sc":"A 不如 B：A 没有 B 好。"},"ex":[{"c":"坐車不如坐捷運方便。","s":"坐车不如坐捷运方便。","es":"Ir en coche no es tan cómodo como ir en metro.","en":"Going by car is not as convenient as taking the MRT.","p":"zuò chē bù rú zuò jié yùn fāng biàn."}]},{"id":"3-5-3","b":3,"l":5,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Si no…ya: 再不…就…了","en":"Urgent Conditional with 再不…就…了","ens":"Urgent Conditional with 再不…就…了","tc":"再不…就…了","sc":"再不…就…了"},"d":{"es":"再不 A 就 B 了 = si no hacemos A ya, ocurrirá B (urgencia).","en":"再不 A 就 B 了 = if we don't do A now, B will happen (urgency).","tc":"再不 A 就 B 了：如果現在還不做 A，馬上就會出問題，有急迫的感覺。","sc":"再不 A 就 B 了：如果现在还不做 A，马上就会出问题，有急迫的感觉。"},"ex":[{"c":"再不走，就來不及了。","s":"再不走，就来不及了。","es":"Si no nos vamos ya, no llegamos.","en":"If we don't leave now, we'll be too late.","p":"zài bù zǒu, jiù lái bù jí le."}]},{"id":"3-5-4","b":3,"l":5,"k":"","t":{"es":"Quitar: V掉","en":"Verb Particle 掉 separated from","ens":"Verb Particle 掉 separated from","tc":"V掉","sc":"V掉"},"d":{"es":"V + 掉 = quitar, eliminar o perder: 丟掉, 吃掉, 忘掉.","en":"Verb + 掉 = get rid of, away, lose: 丟掉, 吃掉, 忘掉.","tc":"動詞＋掉：去掉、消失、失去，例如丟掉、吃掉、忘掉。","sc":"动词＋掉：去掉、消失、失去，例如丢掉、吃掉、忘掉。"},"ex":[{"c":"請把垃圾丟掉。","s":"请把垃圾丢掉。","es":"Por favor tira la basura.","en":"Please throw away the trash.","p":"qǐng bǎ lè sè diū diào."}]},{"id":"3-5-5","b":3,"l":5,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"¡Increíble!: 居然","en":"居然 to one’s surprise","ens":"居然 to one’s surprise","tc":"居然","sc":"居然"},"d":{"es":"居然 = increíblemente, ¡quién lo diría! (sorpresa).","en":"居然 = unexpectedly, surprisingly (expresses surprise).","tc":"居然：沒想到，帶有驚訝的語氣。","sc":"居然：没想到，带有惊讶的语气。"},"ex":[{"c":"他居然忘了今天考試。","s":"他居然忘了今天考试。","es":"¡Increíble, se olvidó del examen de hoy!","en":"He actually forgot there's an exam today!","p":"tā jū rán wàng le jīn tiān kǎo shì."}]},{"id":"3-5-6","b":3,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Ya que: 既然…就","en":"Concession with 既然…（就）… since…(then)…","ens":"Concession with 既然…（就）… since…(then)…","tc":"既然…（就）…","sc":"既然…（就）…"},"d":{"es":"既然 A (就) B = ya que A, entonces B (A es un hecho aceptado).","en":"既然 A，(就) B = since A is already the case, then B.","tc":"既然 A，（就）B：A 已經是事實，所以接著 B。","sc":"既然 A，（就）B：A 已经是事实，所以接着 B。"},"ex":[{"c":"既然你累了，就早點休息吧。","s":"既然你累了，就早点休息吧。","es":"Ya que estás cansado, descansa temprano.","en":"Since you're tired, get some rest early.","p":"jì rán nǐ lèi le, jiù zǎo diǎn xiū xí ba."}]},{"id":"3-5-7","b":3,"l":5,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No parar: V個不停","en":"V+個不停 keep on…","ens":"V+个不停 keep on…","tc":"V個不停","sc":"V个不停"},"d":{"es":"V + 個不停 = no parar de hacer algo.","en":"Verb + 個不停 = keep doing, can't stop.","tc":"動詞＋個不停：一直做，停不下來。","sc":"动词＋个不停：一直做，停不下来。"},"ex":[{"c":"孩子哭個不停。","s":"孩子哭个不停。","es":"El niño no deja de llorar.","en":"The child keeps crying.","p":"hái zi kū gè bù tíng."}]},{"id":"3-6-0","b":3,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 tiempo momento orden secuencia time order sequence 时间 顺序 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Justo por: 因為…才","en":"因為…才… only because…","ens":"因为…才… only because…","tc":"因為…才…","sc":"因为…才…"},"d":{"es":"因為 A 才 B = justamente por A es que B.","en":"因為 A 才 B = it's precisely because of A that B happens.","tc":"因為 A 才 B：正是因為 A，所以 B 才會發生。","sc":"因为 A 才 B：正是因为 A，所以 B 才会发生。"},"ex":[{"c":"就是因為你幫我，我才成功。","s":"就是因为你帮我，我才成功。","es":"Fue justo porque tú me ayudaste que tuve éxito.","en":"It was precisely because you helped me that I succeeded.","p":"jiù shì yīn wèi nǐ bāng wǒ, wǒ cái chéng gōng."}]},{"id":"3-6-1","b":3,"l":6,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Y encima: …不說，…也…","en":"Complaining with …S1…不說，S2 也… not merely, but also","ens":"Complaining with …S1…不说，S2 也… not merely, but also","tc":"…不說，…也…","sc":"…不说，…也…"},"d":{"es":"S1 … 不說，S2 也… = no solo S1, además S2 (para quejarse de algo que se suma).","en":"S1 …不說，S2 也… = not to mention S1, S2 too (used to complain).","tc":"S1 不說，S2 也…：除了前面那件事，後面還有另一件，常用來抱怨。","sc":"S1 不说，S2 也…：除了前面那件事，后面还有另一件，常用来抱怨。"},"ex":[{"c":"他遲到不說，也不道歉。","s":"他迟到不说，也不道歉。","es":"Llegó tarde y encima no pidió disculpas.","en":"He was late, and on top of that he didn't apologize.","p":"tā chí dào bù shuō, yě bú dào qiàn."}]},{"id":"3-6-2","b":3,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 además adición también addition also besides 另外 而且 tiempo momento orden secuencia time order sequence 时间 顺序 además adición también addition also besides 另外 而且","t":{"es":"Sumado a: 再加上","en":"再加上 furthermore","ens":"再加上 furthermore","tc":"再加上","sc":"再加上"},"d":{"es":"再加上 = sumado a, además. Añade otra razón.","en":"再加上 = on top of that, adds another reason.","tc":"再加上：再多加一個原因。","sc":"再加上：再多加一个原因。"},"ex":[{"c":"天氣冷，再加上下雨，我不想出門。","s":"天气冷，再加上下雨，我不想出门。","es":"Hace frío y además llueve, no quiero salir.","en":"It's cold, and it's raining too; I don't want to go out.","p":"tiān qì lěng, zài jiā shàng xià yǔ, wǒ bù xiǎng chū mén."}]},{"id":"3-6-3","b":3,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 contraste pero sin embargo contrast but however 對比 轉折 tiempo momento orden secuencia time order sequence 时间 顺序 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"De todo, pero: 什麼都…就是","en":"什麼都…，就是… everything but …","ens":"什么都…，就是… everything but …","tc":"什麼都…，就是…","sc":"什么都…，就是…"},"d":{"es":"什麼都 A，就是 B = de todo A, pero no B.","en":"什麼都 A，就是 B = anything is fine, except B.","tc":"什麼都 A，就是 B：什麼都可以，只有 B 例外。","sc":"什么都 A，就是 B：什么都可以，只有 B 例外。"},"ex":[{"c":"我什麼都吃，就是不吃香菜。","s":"我什么都吃，就是不吃香菜。","es":"Como de todo, menos cilantro.","en":"I eat everything, except cilantro.","p":"wǒ shén me dōu chī, jiù shì bù chī xiāng cài."}]},{"id":"3-6-4","b":3,"l":6,"k":"","t":{"es":"Preferir…: 寧可…也要","en":"寧可…也要… would rather…, in order to…","ens":"宁可…也要… would rather…, in order to…","tc":"寧可…也要…","sc":"宁可…也要…"},"d":{"es":"寧可 A 也要 B = preferir A antes que renunciar a B (sacrificio).","en":"寧可 A 也要 B = would rather give up A than not get B.","tc":"寧可 A 也要 B：願意犧牲 A，也一定要做到 B。","sc":"宁可 A 也要 B：愿意牺牲 A，也一定要做到 B。"},"ex":[{"c":"他寧可不睡覺也要把書看完。","s":"他宁可不睡觉也要把书看完。","es":"Prefiere no dormir con tal de terminar el libro.","en":"He'd rather not sleep than not finish the book.","p":"tā nìng kě bú shuì jiào yě yào bǎ shū kàn wán."}]},{"id":"3-6-5","b":3,"l":6,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Como…: 像…的+N","en":"像…的+noun such (nouns) as","ens":"像…的+noun such (nouns) as","tc":"像…的＋名詞","sc":"像…的＋名词"},"d":{"es":"像 X 的 N = N como X (da ejemplos de una categoría).","en":"像 X 的 N = N such as X (X gives examples of the category).","tc":"像 X 的 N：用 X 當例子說明這一類東西。","sc":"像 X 的 N：用 X 当例子说明这一类东西。"},"ex":[{"c":"像芒果、西瓜的水果，我都喜歡。","s":"像芒果、西瓜的水果，我都喜欢。","es":"Frutas como el mango y la sandía, me gustan todas.","en":"I like fruits such as mango and watermelon.","p":"xiàng máng guǒ, xī guā de shuǐ guǒ, wǒ dōu xǐ huān."}]},{"id":"3-6-6","b":3,"l":6,"k":"","t":{"es":"Por un lado: 一方面…","en":"一方面…，一方面… on the one hand, …, on the other","ens":"一方面…，一方面… on the one hand, …, on the other","tc":"一方面…，一方面…","sc":"一方面…，一方面…"},"d":{"es":"一方面 A，一方面 B = por un lado A, por otro lado B.","en":"一方面 A，一方面 B = on the one hand A, on the other hand B.","tc":"一方面 A，一方面 B：同時有兩件事或兩個角度。","sc":"一方面 A，一方面 B：同时有两件事或两个角度。"},"ex":[{"c":"一方面要工作，一方面要念書，很累。","s":"一方面要工作，一方面要念书，很累。","es":"Por un lado trabajar y por otro estudiar, es agotador.","en":"On the one hand I have to work, on the other I have to study; it's tiring.","p":"yì fāng miàn yào gōng zuò, yì fāng miàn yào niàn shū, hěn lèi."}]},{"id":"3-6-7","b":3,"l":6,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"A medida que: 隨著","en":"隨著 S1…，S2 也… as a consequence of…","ens":"随着 S1…，S2 也… as a consequence of…","tc":"隨著…，…也…","sc":"随着…，…也…"},"d":{"es":"隨著 X，Y 也… = a medida que X, Y también…","en":"隨著 X，Y 也… = as X changes, Y changes too.","tc":"隨著 X，Y 也…：X 改變時，Y 跟著改變。","sc":"随着 X，Y 也…：X 改变时，Y 跟着改变。"},"ex":[{"c":"隨著年紀增加，他的想法也不一樣了。","s":"随着年纪增加，他的想法也不一样了。","es":"A medida que crece, sus ideas también cambian.","en":"As he gets older, his way of thinking also changes.","p":"suí zhe nián jì zēng jiā, tā de xiǎng fǎ yě bù yí yàng le."}]},{"id":"3-7-0","b":3,"l":7,"k":"","t":{"es":"Sin cuidado: 亂+V","en":"亂＋V to do something in an irresponsible manner,","ens":"乱＋V to do something in an irresponsible manner,","tc":"亂＋動詞","sc":"乱＋动词"},"d":{"es":"亂 + verbo = hacer algo sin orden ni cuidado.","en":"亂 + verb = do something carelessly or without order.","tc":"亂＋動詞：沒有規矩、沒有秩序地做某件事。","sc":"乱＋动词：没有规矩、没有秩序地做某件事。"},"ex":[{"c":"不要亂丟垃圾。","s":"不要乱丢垃圾。","es":"No tires basura por cualquier lado.","en":"Don't litter.","p":"bú yào luàn diū lè sè."}]},{"id":"3-7-1","b":3,"l":7,"k":"","t":{"es":"Cada uno: 各V各的","en":"各 V 各的 each doing her/his own…","ens":"各 V 各的 each doing her/his own…","tc":"各V各的","sc":"各V各的"},"d":{"es":"各 V 各的 = cada uno hace lo suyo.","en":"各 V 各的 = everyone does their own thing.","tc":"各 V 各的：大家各做各的事，互不相干。","sc":"各 V 各的：大家各做各的事，互不相干。"},"ex":[{"c":"吃飯的時候，大家各玩各的手機。","s":"吃饭的时候，大家各玩各的手机。","es":"Mientras comen, cada uno juega con su celular.","en":"During meals, everyone plays with their own phone.","p":"chī fàn de shí hòu, dà jiā gè wán gè de shǒu jī."}]},{"id":"3-7-2","b":3,"l":7,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Aunque: 就算…也","en":"就算…，也… even if…(S1) …, would…(S2)…","ens":"就算…，也… even if…(S1) …, would…(S2)…","tc":"就算…，也…","sc":"就算…，也…"},"d":{"es":"就算 A，也 B = aunque A (hipótesis), igual B.","en":"就算 A，也 B = even if A happens, B still holds.","tc":"就算 A，也 B：假設 A 發生，結果還是 B。","sc":"就算 A，也 B：假设 A 发生，结果还是 B。"},"ex":[{"c":"就算下雨，我也要去。","s":"就算下雨，我也要去。","es":"Aunque llueva, voy a ir.","en":"Even if it rains, I'm going.","p":"jiù suàn xià yǔ, wǒ yě yào qù."}]},{"id":"3-7-3","b":3,"l":7,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Debido a: 因為+N","en":"因為 NP，S… because of NP, S…","ens":"因为 NP，S… because of NP, S…","tc":"因為＋名詞","sc":"因为＋名词"},"d":{"es":"因為 + sustantivo，S… = debido a + sustantivo.","en":"因為 + noun, clause = because of a noun (not a full clause).","tc":"因為＋名詞，句子：說明原因是某個事物，不是一個句子。","sc":"因为＋名词，句子：说明原因是某个事物，不是一个句子。"},"ex":[{"c":"因為天氣，比賽取消了。","s":"因为天气，比赛取消了。","es":"Por el clima, se canceló el partido.","en":"Because of the weather, the game was canceled.","p":"yīn wèi tiān qì, bǐ sài qǔ xiāo le."}]},{"id":"3-7-4","b":3,"l":7,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Primero…segundo: 一來…二來","en":"一來…，二來… on the one hand…, and on the other…; first…, second…","ens":"一来…，二来… on the one hand…, and on the other…; first…, second…","tc":"一來…，二來…","sc":"一来…，二来…"},"d":{"es":"一來 A，二來 B = primero A, segundo B (enumera razones).","en":"一來 A，二來 B = first A, second B (lists two reasons).","tc":"一來 A，二來 B：列出兩個理由。","sc":"一来 A，二来 B：列出两个理由。"},"ex":[{"c":"我不去，一來太遠，二來沒時間。","s":"我不去，一来太远，二来没时间。","es":"No voy: primero, está muy lejos; segundo, no tengo tiempo.","en":"I'm not going: first, it's too far; second, I have no time.","p":"wǒ bú qù, yì lái tài yuǎn, èr lái méi shí jiān."}]},{"id":"3-7-5","b":3,"l":7,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"De un lado a otro: V來V去","en":"Repetitively, Back and Forth with V 來 V 去","ens":"Repetitively, Back and Forth with V 来 V 去","tc":"V來V去","sc":"V来V去"},"d":{"es":"V 來 V 去 = hacer algo de aquí para allá o una y otra vez.","en":"V 來 V 去 = do the same action back and forth, or over and over.","tc":"V 來 V 去：同一個動作來回做，或一直重複。","sc":"V 来 V 去：同一个动作来回做，或一直重复。"},"ex":[{"c":"他走來走去。","s":"他走来走去。","es":"Camina de un lado a otro.","en":"He walks back and forth.","p":"tā zǒu lái zǒu qù."},{"c":"我想來想去，還是不去。","s":"我想来想去，还是不去。","es":"Lo pensé y lo pensé, y al final decidí no ir.","en":"I thought it over and over, and still decided not to go.","p":"wǒ xiǎng lái xiǎng qù, hái shì bú qù."}]},{"id":"3-7-6","b":3,"l":7,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Ya no: 不再…了","en":"不再…了 not…any more","ens":"不再…了 not…any more","tc":"不再…了","sc":"不再…了"},"d":{"es":"不再 + verbo + 了 = ya no (algo que antes sí se hacía).","en":"不再 + verb + 了 = no longer (used to, but not anymore).","tc":"不再＋動詞＋了：以前會做，現在不做了。","sc":"不再＋动词＋了：以前会做，现在不做了。"},"ex":[{"c":"他不再喝咖啡了。","s":"他不再喝咖啡了。","es":"Ya no toma café.","en":"He doesn't drink coffee anymore.","p":"tā bú zài hē kā fēi le."}]},{"id":"3-8-0","b":3,"l":8,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"O…o: 不是…就是","en":"不是…就是… if it's not…, then it’s…","ens":"不是…就是… if it's not…, then it’s…","tc":"不是…就是…","sc":"不是…就是…"},"d":{"es":"不是 A 就是 B = o bien A o bien B.","en":"不是 A 就是 B = it's either A or B.","tc":"不是 A 就是 B：只有這兩種可能。","sc":"不是 A 就是 B：只有这两种可能。"},"ex":[{"c":"他週末不是看書就是睡覺。","s":"他周末不是看书就是睡觉。","es":"Los fines de semana o lee o duerme.","en":"On weekends he's either reading or sleeping.","p":"tā zhōu mò bú shì kàn shū jiù shì shuì jiào."}]},{"id":"3-8-1","b":3,"l":8,"k":"","t":{"es":"Olvídalo: 算了","en":"算了 forget it, drop it","ens":"算了 forget it, drop it","tc":"算了","sc":"算了"},"d":{"es":"算了 = déjalo, olvídalo (dejar pasar o renunciar).","en":"算了 = forget it, drop it, let it go.","tc":"算了：不再想了、放棄、不計較。","sc":"算了：不再想了、放弃、不计较。"},"ex":[{"c":"太貴了，算了。","s":"太贵了，算了。","es":"Es muy caro, mejor olvídalo.","en":"It's too expensive, forget it.","p":"tài guì le, suàn le."}]},{"id":"3-8-2","b":3,"l":8,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Así que: 這樣一來","en":"這樣一來 that being the case, that way","ens":"这样一来 that being the case, that way","tc":"這樣一來","sc":"这样一来"},"d":{"es":"這樣一來 = de esta manera, en ese caso (introduce la consecuencia).","en":"這樣一來 = in that case, this way (introduces a consequence).","tc":"這樣一來：這樣的話，接著會出現某個結果。","sc":"这样一来：这样的话，接着会出现某个结果。"},"ex":[{"c":"這樣一來，我們就不用等了。","s":"这样一来，我们就不用等了。","es":"Así ya no tenemos que esperar.","en":"This way, we don't have to wait.","p":"zhè yàng yì lái, wǒ men jiù bú yòng děng le."}]},{"id":"3-8-3","b":3,"l":8,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Ya hace tiempo: 早就…了","en":"早就…了 long since…","ens":"早就…了 long since…","tc":"早就…了","sc":"早就…了"},"d":{"es":"早就 + verbo + 了 = hace mucho que ya…","en":"早就 + verb + 了 = already a long time ago.","tc":"早就＋動詞＋了：很久以前就已經…。","sc":"早就＋动词＋了：很久以前就已经…。"},"ex":[{"c":"我早就知道了。","s":"我早就知道了。","es":"Hace tiempo que lo sé.","en":"I knew a long time ago.","p":"wǒ zǎo jiù zhī dào le."}]},{"id":"3-8-4","b":3,"l":8,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"A partir de: 從…起","en":"從…起 starting from…","ens":"从…起 starting from…","tc":"從…起","sc":"从…起"},"d":{"es":"從 + tiempo / lugar + 起 = a partir de.","en":"從 + time/place + 起 = starting from.","tc":"從＋時間或地點＋起：從那裡開始算。","sc":"从＋时间或地点＋起：从那里开始算。"},"ex":[{"c":"從明天起，我要早起。","s":"从明天起，我要早起。","es":"A partir de mañana voy a madrugar.","en":"Starting tomorrow, I'm going to get up early.","p":"cóng míng tiān qǐ, wǒ yào zǎo qǐ."}]},{"id":"3-8-5","b":3,"l":8,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Sin embargo: 卻","en":"卻 however","ens":"却 however","tc":"卻","sc":"却"},"d":{"es":"卻 = sin embargo, en cambio (contraste inesperado). Va antes del verbo.","en":"卻 = but, however (contrary to expectation), placed before the verb.","tc":"卻：前後意思相反，有「沒想到」的感覺，放在動詞前面。","sc":"却：前后意思相反，有「没想到」的感觉，放在动词前面。"},"ex":[{"c":"他很聰明，卻不愛念書。","s":"他很聪明，却不爱念书。","es":"Es muy inteligente, pero no le gusta estudiar.","en":"He's very smart but doesn't like studying.","p":"tā hěn cōng míng, què bú ài niàn shū."}]},{"id":"3-8-6","b":3,"l":8,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Por…: 因為…而…","en":"因為…而… therefore, consequently","ens":"因为…而… therefore, consequently","tc":"因為…而…","sc":"因为…而…"},"d":{"es":"因為 X 而 V = por X, (resulta) V. Es una forma más escrita.","en":"因為 X 而 V = because of X, V happens (more literary).","tc":"因為 X 而 V：因為 X，所以 V，比較書面。","sc":"因为 X 而 V：因为 X，所以 V，比较书面。"},"ex":[{"c":"他因為生病而沒來上課。","s":"他因为生病而没来上课。","es":"No vino a clase porque se enfermó.","en":"He didn't come to class because he got sick.","p":"tā yīn wèi shēng bìng ér méi lái shàng kè."}]},{"id":"3-8-7","b":3,"l":8,"k":"","t":{"es":"Tras: 經過","en":"經過 after","ens":"经过 after","tc":"經過","sc":"经过"},"d":{"es":"經過 = pasar por (un lugar) o tras (un proceso o tiempo).","en":"經過 = pass through a place, or after going through a process or period of time.","tc":"經過：走過某個地方，或是經歷一段過程、一段時間之後。","sc":"经过：走过某个地方，或是经历一段过程、一段时间之后。"},"ex":[{"c":"經過一年的努力，他通過了考試。","s":"经过一年的努力，他通过了考试。","es":"Tras un año de esfuerzo, aprobó el examen.","en":"After a year of hard work, he passed the exam.","p":"jīng guò yì nián de nǔ lì, tā tōng guò le kǎo shì."}]},{"id":"3-9-0","b":3,"l":9,"k":"","t":{"es":"Depender de: 靠","en":"靠 to rely on, by means of","ens":"靠 to rely on, by means of","tc":"靠","sc":"靠"},"d":{"es":"靠 = depender de, apoyarse en.","en":"靠 = rely on, depend on.","tc":"靠：依賴、憑著某個人或某件事。","sc":"靠：依赖、凭着某个人或某件事。"},"ex":[{"c":"他靠自己的努力考上大學。","s":"他靠自己的努力考上大学。","es":"Entró a la universidad gracias a su propio esfuerzo.","en":"He got into university through his own effort.","p":"tā kào zì jǐ de nǔ lì kǎo shàng dà xué."}]},{"id":"3-9-1","b":3,"l":9,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Tanto…como: 既…又","en":"既…又… not merely…, but…as well","ens":"既…又… not merely…, but…as well","tc":"既…又…","sc":"既…又…"},"d":{"es":"既 A 又 B = tanto A como B (dos cualidades; más formal que 又…又…).","en":"既 A 又 B = both A and B (two qualities; more formal than 又…又…).","tc":"既 A 又 B：同時有兩個特點，比「又…又…」更書面。","sc":"既 A 又 B：同时有两个特点，比「又…又…」更书面。"},"ex":[{"c":"這裡既安靜又乾淨。","s":"这里既安静又干净。","es":"Este lugar es tranquilo y limpio.","en":"This place is both quiet and clean.","p":"zhè lǐ jì ān jìng yòu gān jìng."}]},{"id":"3-9-2","b":3,"l":9,"k":"","t":{"es":"Dentro de: 以內","en":"…以內 within …","ens":"…以内 within …","tc":"以內","sc":"以内"},"d":{"es":"以內 = dentro de (un límite de cantidad, tiempo o espacio).","en":"以內 = within (a limit of quantity, time or space).","tc":"以內：不超過某個範圍（數量、時間、空間）。","sc":"以内：不超过某个范围（数量、时间、空间）。"},"ex":[{"c":"請在三天以內回覆。","s":"请在三天以内回复。","es":"Por favor responde en un plazo de tres días.","en":"Please reply within three days.","p":"qǐng zài sān tiān yǐ nèi huí fù."}]},{"id":"3-9-3","b":3,"l":9,"k":"","t":{"es":"Representar: 占","en":"占 to constitute","ens":"占 to constitute","tc":"占","sc":"占"},"d":{"es":"占 = ocupar o representar (una parte o porcentaje).","en":"占 = to take up or make up (a proportion or space).","tc":"占：佔有某個比例或空間。","sc":"占：占有某个比例或空间。"},"ex":[{"c":"女生占全班的一半。","s":"女生占全班的一半。","es":"Las mujeres son la mitad de la clase.","en":"Girls make up half of the class.","p":"nǚ shēng zhàn quán bān de yí bàn."}]},{"id":"3-9-4","b":3,"l":9,"k":"","t":{"es":"En cuanto a: (在)…上","en":"（在） NP 上 regarding NP","ens":"（在） NP 上 regarding NP","tc":"（在）…上","sc":"（在）…上"},"d":{"es":"(在) N 上 = en el aspecto de N, en cuanto a N.","en":"(在) N 上 = in the area of N, regarding N.","tc":"（在）＋名詞＋上：在某方面、就某件事來說。","sc":"（在）＋名词＋上：在某方面、就某件事来说。"},"ex":[{"c":"在學習上，他很認真。","s":"在学习上，他很认真。","es":"En los estudios, él es muy aplicado.","en":"In his studies, he is very diligent.","p":"zài xué xí shàng, tā hěn rèn zhēn."}]},{"id":"3-9-5","b":3,"l":9,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Traer a: 給…帶來","en":"給…帶來 to bring… to…","ens":"给…带来 to bring… to…","tc":"給…帶來…","sc":"给…带来…"},"d":{"es":"給 A 帶來 B = traerle B a A (efecto o consecuencia).","en":"給 A 帶來 B = bring B to A (an effect or consequence).","tc":"給 A 帶來 B：對 A 產生 B 這個影響。","sc":"给 A 带来 B：对 A 产生 B 这个影响。"},"ex":[{"c":"網路給我們帶來很多方便。","s":"网路给我们带来很多方便。","es":"Internet nos trae muchas comodidades.","en":"The internet has brought us a lot of convenience.","p":"wǎng lù gěi wǒ men dài lái hěn duō fāng biàn."}]},{"id":"3-9-6","b":3,"l":9,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Al final: 結果","en":"結果 consequently, in the end","ens":"结果 consequently, in the end","tc":"結果","sc":"结果"},"d":{"es":"結果 = el resultado fue…, al final (el desenlace de algo).","en":"結果 = in the end, the outcome (often unexpected).","tc":"結果：最後的結局，常和預期不同。","sc":"结果：最后的结局，常和预期不同。"},"ex":[{"c":"我等了很久，結果他沒來。","s":"我等了很久，结果他没来。","es":"Esperé mucho y al final no vino.","en":"I waited a long time, and in the end he didn't come.","p":"wǒ děng le hěn jiǔ, jié guǒ tā méi lái."}]},{"id":"3-10-0","b":3,"l":10,"k":"","t":{"es":"En cuanto a: 至於","en":"Introducing a New Topic with 至於…, as to, as far","ens":"Introducing a New Topic with 至于…, as to, as far","tc":"至於","sc":"至于"},"d":{"es":"至於 = en cuanto a… (cambia a otro tema).","en":"至於 = as for (switches to another topic).","tc":"至於：換一個話題，意思是「說到…的話」。","sc":"至于：换一个话题，意思是「说到…的话」。"},"ex":[{"c":"我去，至於他去不去，我不知道。","s":"我去，至于他去不去，我不知道。","es":"Yo voy; en cuanto a si él va o no, no lo sé.","en":"I'm going; as for whether he's going, I don't know.","p":"wǒ qù, zhì yú tā qù bú qù, wǒ bù zhī dào."}]},{"id":"3-10-1","b":3,"l":10,"k":"","t":{"es":"Depende de: A看B","en":"看 depends on","ens":"看 depends on","tc":"A 看 B","sc":"A 看 B"},"d":{"es":"A 看 B = A depende de B.","en":"A 看 B = A depends on B.","tc":"A 看 B：A 要看 B 的情況才能決定。","sc":"A 看 B：A 要看 B 的情况才能决定。"},"ex":[{"c":"去不去看天氣。","s":"去不去看天气。","es":"Ir o no depende del clima.","en":"Whether we go depends on the weather.","p":"qù bú qù kàn tiān qì."}]},{"id":"3-10-2","b":3,"l":10,"k":"siempre nunca frecuencia always never frequency 經常 從來 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Siempre: 一向","en":"一向 all along, has always…","ens":"一向 all along, has always…","tc":"一向","sc":"一向"},"d":{"es":"一向 = siempre (desde antes hasta ahora, como hábito).","en":"一向 = always, all along (from before until now, as a habit).","tc":"一向：從以前到現在都是這樣，已成習慣。","sc":"一向：从以前到现在都是这样，已成习惯。"},"ex":[{"c":"他一向早起。","s":"他一向早起。","es":"Siempre se ha levantado temprano.","en":"He has always gotten up early.","p":"tā yí xiàng zǎo qǐ."}]},{"id":"3-10-3","b":3,"l":10,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Por ejemplo: 拿…來說","en":"拿…來說 take…as an example","ens":"拿…来说 take…as an example","tc":"拿…來說","sc":"拿…来说"},"d":{"es":"拿 X 來說 = tomando X como ejemplo.","en":"拿 X 來說 = take X as an example.","tc":"拿 X 來說：用 X 當例子來說明。","sc":"拿 X 来说：用 X 当例子来说明。"},"ex":[{"c":"拿我自己來說，我就不喜歡吃辣。","s":"拿我自己来说，我就不喜欢吃辣。","es":"Por ejemplo, yo no como picante.","en":"Take myself, for example: I don't like spicy food.","p":"ná wǒ zì jǐ lái shuō, wǒ jiù bù xǐ huān chī là."}]},{"id":"3-10-4","b":3,"l":10,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Pasiva formal: 受","en":"Passive Sentences with 受","ens":"Passive Sentences with 受","tc":"被動句「受」","sc":"被动句「受」"},"d":{"es":"受 + sustantivo: 受到歡迎 (ser bien recibido), 受傷 (herirse), 受影響 (ser afectado). Pasiva de estilo más formal.","en":"受 + noun: 受到歡迎 (be welcomed), 受傷 (get hurt), 受影響 (be affected); a more formal passive.","tc":"受＋名詞：受到歡迎、受傷、受影響，比「被」更書面。","sc":"受＋名词：受到欢迎、受伤、受影响，比「被」更书面。"},"ex":[{"c":"這部電影很受歡迎。","s":"这部电影很受欢迎。","es":"Esta película es muy popular.","en":"This movie is very popular.","p":"zhè bù diàn yǐng hěn shòu huān yíng."}]},{"id":"3-10-5","b":3,"l":10,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Por cualquier cosa: 動不動就","en":"動不動就… to do something impetuously","ens":"动不动就… to do something impetuously","tc":"動不動就","sc":"动不动就"},"d":{"es":"動不動就 + verbo = a la menor ocasión, por cualquier cosa (negativo).","en":"動不動就 + verb = at the slightest thing; usually negative behavior.","tc":"動不動就＋動詞：一點小事就會…，多用在不好的行為。","sc":"动不动就＋动词：一点小事就会…，多用在不好的行为。"},"ex":[{"c":"他動不動就生氣。","s":"他动不动就生气。","es":"Se enoja por cualquier cosa.","en":"He gets angry at the slightest thing.","p":"tā dòng bu dòng jiù shēng qì."}]},{"id":"3-11-0","b":3,"l":11,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"En realidad: 到底","en":"到底 after all? how on earth…?","ens":"到底 after all? how on earth…?","tc":"到底","sc":"到底"},"d":{"es":"到底 = en realidad, ¿qué demonios…? Insiste en una pregunta.","en":"到底 = on earth, exactly (presses a question); also 'after all'.","tc":"到底：用在問句，想問出真正的答案；也有「畢竟」的意思。","sc":"到底：用在问句，想问出真正的答案；也有「毕竟」的意思。"},"ex":[{"c":"你到底想吃什麼？","s":"你到底想吃什么？","es":"¿Pero qué quieres comer en realidad?","en":"What on earth do you want to eat?","p":"nǐ dào dǐ xiǎng chī shén me?"}]},{"id":"3-11-1","b":3,"l":11,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Incluso: 甚至","en":"甚至 even","ens":"甚至 even","tc":"甚至","sc":"甚至"},"d":{"es":"甚至 = incluso, hasta (el caso extremo).","en":"甚至 = even (points to an extreme case).","tc":"甚至：連…也，說到更極端的情況。","sc":"甚至：连…也，说到更极端的情况。"},"ex":[{"c":"他很忙，甚至沒有時間吃飯。","s":"他很忙，甚至没有时间吃饭。","es":"Está muy ocupado, incluso no tiene tiempo para comer.","en":"He is so busy that he doesn't even have time to eat.","p":"tā hěn máng, shèn zhì méi yǒu shí jiān chī fàn."}]},{"id":"3-11-2","b":3,"l":11,"k":"","t":{"es":"Entonces: 這麼說","en":"這麼說 that being the case, in that case","ens":"这么说 that being the case, in that case","tc":"這麼說","sc":"这么说"},"d":{"es":"這麼說 = entonces, siendo así… (se concluye a partir de lo que dijo el otro).","en":"這麼說 = in that case, so (drawing a conclusion from what was just said).","tc":"這麼說：根據對方說的話，得出一個結論。","sc":"这么说：根据对方说的话，得出一个结论。"},"ex":[{"c":"這麼說，你已經知道了？","s":"这么说，你已经知道了？","es":"Entonces, ¿ya lo sabías?","en":"So, you already knew?","p":"zhè me shuō, nǐ yǐ jīng zhī dào le?"}]},{"id":"3-11-3","b":3,"l":11,"k":"","t":{"es":"Relacionado con: 跟B有關的A","en":"跟 B 有關的 A A is related to B","ens":"跟 B 有关的 A A is related to B","tc":"跟…有關的…","sc":"跟…有关的…"},"d":{"es":"跟 B 有關的 A = A relacionado con B.","en":"跟 B 有關的 A = A that is related to B.","tc":"跟 B 有關的 A：和 B 有關係的 A。","sc":"跟 B 有关的 A：和 B 有关系的 A。"},"ex":[{"c":"我想看跟台灣歷史有關的書。","s":"我想看跟台湾历史有关的书。","es":"Quiero leer libros sobre la historia de Taiwán.","en":"I want to read books about Taiwan's history.","p":"wǒ xiǎng kàn gēn tái wān lì shǐ yǒu guān de shū."}]},{"id":"3-11-4","b":3,"l":11,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No hay remedio: 不得不","en":"不得不 have no choice but to","ens":"不得不 have no choice but to","tc":"不得不","sc":"不得不"},"d":{"es":"不得不 + verbo = no tener más remedio que, verse obligado a.","en":"不得不 + verb = have no choice but to, forced by circumstances.","tc":"不得不＋動詞：因為情況，沒有別的選擇。","sc":"不得不＋动词：因为情况，没有别的选择。"},"ex":[{"c":"太晚了，我不得不回家。","s":"太晚了，我不得不回家。","es":"Es muy tarde, no tengo más remedio que irme a casa.","en":"It's too late; I have no choice but to go home.","p":"tài wǎn le, wǒ bù dé bù huí jiā."}]},{"id":"3-11-5","b":3,"l":11,"k":"","t":{"es":"Así como: 以及","en":"以及 as well as","ens":"以及 as well as","tc":"以及","sc":"以及"},"d":{"es":"以及 = así como. Une sustantivos (más formal).","en":"以及 = as well as (a more formal 'and', linking nouns).","tc":"以及：「和」的書面說法，連接名詞。","sc":"以及：「和」的书面说法，连接名词。"},"ex":[{"c":"我買了蘋果、香蕉以及芒果。","s":"我买了苹果、香蕉以及芒果。","es":"Compré manzanas, plátanos y mangos.","en":"I bought apples, bananas and mangoes.","p":"wǒ mǎi le píng guǒ, xiāng jiāo yǐ jí máng guǒ."}]},{"id":"3-12-0","b":3,"l":12,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Solo…: 只不過","en":"只不過… (而已) merely…; nothing more than…","ens":"只不过… (而已) merely…; nothing more than…","tc":"只不過…（而已）","sc":"只不过…（而已）"},"d":{"es":"只不過…(而已) = simplemente, no es más que…","en":"只不過…(而已) = merely, nothing more than.","tc":"只不過…（而已）：只是…，沒有那麼嚴重或特別。","sc":"只不过…（而已）：只是…，没有那么严重或特别。"},"ex":[{"c":"這只不過是一個小問題而已。","s":"这只不过是一个小问题而已。","es":"Esto no es más que un pequeño problema.","en":"This is just a small problem.","p":"zhè zhǐ bú guò shì yí ge xiǎo wèn tí ér yǐ."}]},{"id":"3-12-1","b":3,"l":12,"k":"","t":{"es":"A cargo de: 由","en":"Introducing an Agent with 由","ens":"Introducing an Agent with 由","tc":"由","sc":"由"},"d":{"es":"由 + agente + verbo = a cargo de, por parte de (quien hace algo).","en":"由 + person/unit + verb = to be done by, in charge of.","tc":"由＋人或單位＋動詞：說明由誰負責做。","sc":"由＋人或单位＋动词：说明由谁负责做。"},"ex":[{"c":"這件事由我來做。","s":"这件事由我来做。","es":"De esto me encargo yo.","en":"I'll take care of this.","p":"zhè jiàn shì yóu wǒ lái zuò."}]},{"id":"3-12-2","b":3,"l":12,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"¿Acaso…?: 難道","en":"難道… how could it possibly be true","ens":"难道… how could it possibly be true","tc":"難道…嗎？","sc":"难道…吗？"},"d":{"es":"難道…嗎？ = ¿acaso…? Pregunta retórica.","en":"難道…嗎？ = a rhetorical question: 'surely not?'.","tc":"難道…嗎？：反問句，意思是「不可能吧」。","sc":"难道…吗？：反问句，意思是「不可能吧」。"},"ex":[{"c":"難道你不知道嗎？","s":"难道你不知道吗？","es":"¿Acaso no lo sabías?","en":"Don't tell me you didn't know?","p":"nán dào nǐ bù zhī dào ma?"}]},{"id":"3-12-3","b":3,"l":12,"k":"","t":{"es":"Lleno: 滿","en":"To Reach a Ceiling with 滿","ens":"To Reach a Ceiling with 满","tc":"滿","sc":"满"},"d":{"es":"滿 = llegar al máximo, estar lleno: 客滿, 額滿, 坐滿.","en":"滿 = full to the maximum: 客滿, 額滿, 坐滿.","tc":"滿：到最多了，不能再多，例如客滿、額滿、坐滿。","sc":"满：到最多了，不能再多，例如客满、额满、坐满。"},"ex":[{"c":"今天餐廳客滿了。","s":"今天餐厅客满了。","es":"Hoy el restaurante está lleno.","en":"The restaurant is full today.","p":"jīn tiān cān tīng kè mǎn le."}]},{"id":"3-12-4","b":3,"l":12,"k":"","t":{"es":"Por/para: 為","en":"Beneficiary marker 為","ens":"Beneficiary marker 为","tc":"為＋對象","sc":"为＋对象"},"d":{"es":"為 + beneficiario + verbo = por / para (a favor de).","en":"為 + beneficiary + verb = do something for someone.","tc":"為＋對象＋動詞：替誰、為了誰做某件事。","sc":"为＋对象＋动词：替谁、为了谁做某件事。"},"ex":[{"c":"他為家人工作。","s":"他为家人工作。","es":"Trabaja por su familia.","en":"He works for his family.","p":"tā wéi jiā rén gōng zuò."}]},{"id":"3-12-5","b":3,"l":12,"k":"","t":{"es":"En el aspecto: (在)…方面","en":"（在）…方面 with respect to; regarding","ens":"（在）…方面 with respect to; regarding","tc":"（在）…方面","sc":"（在）…方面"},"d":{"es":"(在) X 方面 = en el aspecto de X, con respecto a X.","en":"(在) X 方面 = in terms of X, with respect to X.","tc":"（在）＋名詞＋方面：就某個方面來說。","sc":"（在）＋名词＋方面：就某个方面来说。"},"ex":[{"c":"在工作方面，他很努力。","s":"在工作方面，他很努力。","es":"En lo laboral, se esfuerza mucho.","en":"In terms of work, he works very hard.","p":"zài gōng zuò fāng miàn, tā hěn nǔ lì."}]},{"id":"4-1-0","b":4,"l":1,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定","t":{"es":"Mejor B que A: 與其…不如","en":"與其 A…不如 B… B rather than A","ens":"与其 A…不如 B… B rather than A","tc":"與其 A，不如 B","sc":"与其 A，不如 B"},"d":{"es":"與其 A，不如 B = en vez de A, es mejor B. Se compara dos opciones y se recomienda la segunda.","en":"Compares two options and says the second is better. 與其 A，不如 B means 'rather than A, it would be better to B'.","tc":"比較兩個選擇，說明第二個比較好。「與其 A，不如 B」是「與其做 A，還不如做 B」的意思。","sc":"比较两个选择，说明第二个比较好。「与其 A，不如 B」是「与其做 A，还不如做 B」的意思。"},"ex":[{"c":"與其在家看電視，不如出去走走。","s":"与其在家看电视，不如出去走走。","es":"En vez de ver televisión en casa, mejor salir a caminar.","en":"Rather than watching TV at home, it's better to go out for a walk.","p":"yǔ qí zài jiā kàn diàn shì, bù rú chū qù zǒu zǒu."}]},{"id":"4-1-1","b":4,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 contraste pero sin embargo contrast but however 對比 轉折 tiempo momento orden secuencia time order sequence 时间 顺序 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Contraste con 就","en":"就 on the contrary","ens":"就 on the contrary","tc":"表示對比的「就」","sc":"表示对比的「就」"},"d":{"es":"就 puede marcar un contraste inesperado: «en cambio, sin embargo». Los demás piensan una cosa y esta persona piensa lo contrario.","en":"When others think or do one thing but this person differs, 就 marks the contrast, much like 'whereas' or 'on the contrary'.","tc":"別人的想法或情況是一樣的，但說話的人（或這個人）卻不同，這時可以用「就」表示對比，意思像「卻」「反倒」。","sc":"别人的想法或情况是一样的，但说话的人（或这个人）却不同，这时可以用「就」表示对比，意思像「却」「反倒」。"},"ex":[{"c":"大家都說這部電影很無聊，他就覺得很有意思。","s":"大家都说这部电影很无聊，他就觉得很有意思。","es":"Todos dicen que esta película es aburrida; él, en cambio, la encuentra interesante.","en":"Everyone says this movie is boring, but he finds it interesting.","p":"dà jiā dōu shuō zhè bù diàn yǐng hěn wú liáo, tā jiù jué dé hěn yǒu yì sī."}]},{"id":"4-1-2","b":4,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Usos de 就 (resumen)","en":"A Summary of the Various Usages of 就","ens":"A Summary of the Various Usages of 就","tc":"「就」的用法總整理","sc":"「就」的用法总整理"},"d":{"es":"Resumen de 就: (1) enseguida, pronto; (2) enfático, «precisamente»; (3) «solo», limita una cantidad; (4) condición y resultado (要是…就…).","en":"Main uses of 就: (1) soon, right away; (2) emphatic 'precisely'; (3) 'only'; (4) linking condition and result (要是…就…).","tc":"「就」常見的用法有：一、很快、馬上（我馬上就到）；二、強調「正是」（這就是……）；三、只有（就我一個人）；四、前後連接（要是……就……）。","sc":"「就」常见的用法有：一、很快、马上（我马上就到）；二、强调「正是」（这就是……）；三、只有（就我一个人）；四、前后连接（要是……就……）。"},"ex":[{"c":"我馬上就到。","s":"我马上就到。","es":"Llego enseguida.","en":"I'll be there right away.","p":"wǒ mǎ shàng jiù dào."},{"c":"這就是我要找的書。","s":"这就是我要找的书。","es":"Este es justamente el libro que busco.","en":"This is exactly the book I'm looking for.","p":"zhè jiù shì wǒ yào zhǎo de shū."}]},{"id":"4-1-3","b":4,"l":1,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 siempre nunca frecuencia always never frequency 經常 從來 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Ni A, ni B: 別說…就是","en":"別說 A，就是 B 也… never mind A, even B is the case…","ens":"别说 A，就是 B 也… never mind A, even B is the case…","tc":"別說 A，就是 B 也…","sc":"别说 A，就是 B 也…"},"d":{"es":"別說 A，就是 B 也… = ni hablar de A; incluso B (el caso más fácil) también…. A es el caso más difícil y B el más fácil.","en":"First name the harder thing (A), then say even the easier thing (B) isn't possible either: 'forget A, even B…'.","tc":"先說一件比較難的事（A）都不行，連比較容易的事（B）也不行。意思是「連 B 都……，更不用說 A」。","sc":"先说一件比较难的事（A）都不行，连比较容易的事（B）也不行。意思是「连 B 都……，更不用说 A」。"},"ex":[{"c":"別說跑步，就是走路他也覺得累。","s":"别说跑步，就是走路他也觉得累。","es":"Ni hablar de correr; hasta caminar lo cansa.","en":"Forget running, even walking tires him out.","p":"bié shuō pǎo bù, jiù shì zǒu lù tā yě jué dé lèi."}]},{"id":"4-1-4","b":4,"l":1,"k":"","t":{"es":"Prácticamente: 簡直","en":"簡直 to put it simply and plainly, it seems as if","ens":"简直 to put it simply and plainly, it seems as if","tc":"簡直","sc":"简直"},"d":{"es":"簡直 = es simplemente…, casi como si… Exagera para dar énfasis (admiración o queja).","en":"簡直 exaggerates for emphasis: 'it's practically…', 'it's simply like…'. It can express admiration or complaint.","tc":"「簡直」用來誇張地描述，意思是「幾乎就是」「根本就像」，可以表示讚美，也可以表示抱怨。","sc":"「简直」用来夸张地描述，意思是「几乎就是」「根本就像」，可以表示赞美，也可以表示抱怨。"},"ex":[{"c":"他的中文說得簡直跟台灣人一樣好。","s":"他的中文说得简直跟台湾人一样好。","es":"Habla chino tan bien que parece taiwanés.","en":"He speaks Chinese so well that he sounds just like a Taiwanese person.","p":"tā de zhōng wén shuō de jiǎn zhí gēn tái wān rén yí yàng hǎo."}]},{"id":"4-1-5","b":4,"l":1,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No llega a tanto: 不至於","en":"不至於 but the situation would not be so bad as to …","ens":"不至于 but the situation would not be so bad as to …","tc":"不至於","sc":"不至于"},"d":{"es":"不至於 = no llega al punto de…, no sería tan grave. Sirve para descartar una posibilidad exagerada.","en":"不至於 says things won't go as far as that; it's used to rule out an exaggerated possibility.","tc":"「不至於」表示事情不會嚴重到那個地步，用來否定一個太誇張的想法。","sc":"「不至于」表示事情不会严重到那个地步，用来否定一个太夸张的想法。"},"ex":[{"c":"只是小感冒，不至於住院吧。","s":"只是小感冒，不至于住院吧。","es":"Es solo un resfriado leve, no creo que haya que hospitalizarlo.","en":"It's just a mild cold; he surely doesn't need to be hospitalized.","p":"zhǐ shì xiǎo gǎn mào, bú zhì yú zhù yuàn ba."}]},{"id":"4-1-6","b":4,"l":1,"k":"","t":{"es":"Por lo general: 往往","en":"往往 usually, tend to","ens":"往往 usually, tend to","tc":"往往","sc":"往往"},"d":{"es":"往往 = por lo general, suele (patrón habitual basado en la experiencia). No se usa para el futuro ni para hechos únicos.","en":"往往 describes what usually happens based on experience. It isn't used for the future or for one-time events.","tc":"「往往」表示照過去的經驗，常常是這樣，有規律性。不能用在未來，也不能用在只發生一次的事。","sc":"「往往」表示照过去的经验，常常是这样，有规律性。不能用在未来，也不能用在只发生一次的事。"},"ex":[{"c":"週末的捷運往往很擠。","s":"周末的捷运往往很挤。","es":"Los fines de semana el metro suele estar lleno.","en":"On weekends the metro is usually crowded.","p":"zhōu mò de jié yùn wǎng wǎng hěn jǐ."}]},{"id":"4-1-7","b":4,"l":1,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Por diversión: V 著玩","en":"Do Something Just for Fun V 著玩","ens":"Do Something Just for Fun V 着玩","tc":"V 著玩","sc":"V 着玩"},"d":{"es":"V 著玩 = hacer algo solo por diversión, sin tomarlo en serio.","en":"V 著玩 means doing something just for fun, not seriously.","tc":"「V 著玩」表示只是為了好玩去做，不是認真的。","sc":"「V 着玩」表示只是为了好玩去做，不是认真的。"},"ex":[{"c":"我只是畫著玩，畫得不好。","s":"我只是画着玩，画得不好。","es":"Solo dibujo por diversión, no dibujo bien.","en":"I'm only drawing for fun; I'm not good at it.","p":"wǒ zhǐ shì huà zhe wán, huà de bù hǎo."},{"c":"別當真，他是說著玩的。","s":"别当真，他是说着玩的。","es":"No lo tomes en serio, lo dijo en broma.","en":"Don't take it seriously, he was just joking.","p":"bié dāng zhēn, tā shì shuō zhe wán de."}]},{"id":"4-2-0","b":4,"l":2,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Lograr algo: V 成","en":"Verb Complement 成 successful(ly)","ens":"Verb Complement 成 successful(ly)","tc":"動詞＋成（成功）","sc":"动词＋成（成功）"},"d":{"es":"V + 成 = lograr hacer algo (resultado exitoso). Negación: V 不成 = no se logró.","en":"V + 成 shows that something was achieved successfully. Its negative, V 不成, means it couldn't be done.","tc":"「V＋成」表示事情做成了、成功了。否定用「V 不成」，表示沒辦法完成。","sc":"「V＋成」表示事情做成了、成功了。否定用「V 不成」，表示没办法完成。"},"ex":[{"c":"這筆生意終於談成了。","s":"这笔生意终于谈成了。","es":"Por fin se cerró este negocio.","en":"This deal was finally closed.","p":"zhè bǐ shēng yì zhōng yú tán chéng le."},{"c":"下雨了，我們去不成了。","s":"下雨了，我们去不成了。","es":"Está lloviendo, ya no podemos ir.","en":"It's raining, so we can't go anymore.","p":"xià yǔ le, wǒ men qù bù chéng le."}]},{"id":"4-2-1","b":4,"l":2,"k":"","t":{"es":"Por si acaso: 萬一","en":"萬一 supposing, in the event of something negative","ens":"万一 supposing, in the event of something negative","tc":"萬一","sc":"万一"},"d":{"es":"萬一 = en caso de que (algo malo y poco probable), por si acaso.","en":"萬一 introduces something unlikely but bad if it happened: 'in case…', 'what if…'.","tc":"「萬一」用在可能性很小、但如果發生會很糟的事情，意思是「如果真的……」。","sc":"「万一」用在可能性很小、但如果发生会很糟的事情，意思是「如果真的……」。"},"ex":[{"c":"帶把傘吧，萬一下雨怎麼辦？","s":"带把伞吧，万一下雨怎么办？","es":"Lleva un paraguas, ¿y si llueve?","en":"Bring an umbrella. What if it rains?","p":"dài bǎ sǎn ba, wàn yī xià yǔ zěn me bàn?"}]},{"id":"4-2-2","b":4,"l":2,"k":"","t":{"es":"Creer erróneamente: 以為","en":"以為 to have wrongly thought that…","ens":"以为 to have wrongly thought that…","tc":"以為","sc":"以为"},"d":{"es":"以為 = creer (equivocadamente) que…; la realidad resultó ser distinta.","en":"以為 means you thought something that turned out to be wrong.","tc":"「以為」是自己想的跟事實不一樣，後來才發現弄錯了。","sc":"「以为」是自己想的跟事实不一样，后来才发现弄错了。"},"ex":[{"c":"我以為今天放假，原來要上班。","s":"我以为今天放假，原来要上班。","es":"Creí que hoy era feriado, pero resulta que hay que trabajar.","en":"I thought today was a day off, but it turns out I have to work.","p":"wǒ yǐ wéi jīn tiān fàng jià, yuán lái yào shàng bān."}]},{"id":"4-2-3","b":4,"l":2,"k":"","t":{"es":"El adverbio 可","en":"Adverb 可","ens":"Adverb 可","tc":"副詞「可」","sc":"副词「可」"},"d":{"es":"可 como adverbio da énfasis: «sí que», «de verdad». Se usa en advertencias, exclamaciones y lenguaje coloquial.","en":"The adverb 可 adds emphasis before a verb or adjective, often in reminders, warnings or exclamations. It's colloquial.","tc":"「可」放在動詞或形容詞前面加強語氣，常用在提醒、警告或感嘆，是口語的說法。","sc":"「可」放在动词或形容词前面加强语气，常用在提醒、警告或感叹，是口语的说法。"},"ex":[{"c":"你可別忘了明天的會議！","s":"你可别忘了明天的会议！","es":"¡No te vayas a olvidar de la reunión de mañana!","en":"Don't you forget about tomorrow's meeting!","p":"nǐ kě bié wàng le míng tiān de huì yì!"},{"c":"這家的牛肉麵可好吃了！","s":"这家的牛肉面可好吃了！","es":"¡Los fideos con carne de este lugar sí que están ricos!","en":"The beef noodles here are really delicious!","p":"zhè jiā de niú ròu miàn kě hǎo chī le!"}]},{"id":"4-2-4","b":4,"l":2,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Para evitar que: 免得","en":"免得 lest, so as to avoid","ens":"免得 lest, so as to avoid","tc":"免得","sc":"免得"},"d":{"es":"免得 = para evitar que, no sea que. Introduce la consecuencia no deseada y va en la segunda cláusula.","en":"免得 goes in the second clause: you do something first so as to avoid an unwanted result.","tc":"「免得」放在後面的句子，表示為了避免不好的結果，所以前面先做某件事。","sc":"「免得」放在后面的句子，表示为了避免不好的结果，所以前面先做某件事。"},"ex":[{"c":"你先打電話問一下，免得白跑一趟。","s":"你先打电话问一下，免得白跑一趟。","es":"Llama antes a preguntar, para no ir en balde.","en":"Call and ask first, so you don't make a trip for nothing.","p":"nǐ xiān dǎ diàn huà wèn yí xià, miǎn dé bái pǎo yí tàng."}]},{"id":"4-2-5","b":4,"l":2,"k":"","t":{"es":"Alguna vez: 曾經","en":"曾經 experience in the past, V’ed before","ens":"曾经 experience in the past, V’ed before","tc":"曾經","sc":"曾经"},"d":{"es":"曾經 + V = alguna vez, en el pasado (una experiencia que ya no continúa). Suele ir con 過.","en":"曾經 shows that something happened in the past and no longer holds now. It often appears with 過.","tc":"「曾經」表示過去有過某種經驗，現在已經不是這樣了，常常跟「過」一起用。","sc":"「曾经」表示过去有过某种经验，现在已经不是这样了，常常跟「过」一起用。"},"ex":[{"c":"我曾經在台南住過一年。","s":"我曾经在台南住过一年。","es":"Una vez viví un año en Tainan.","en":"I once lived in Tainan for a year.","p":"wǒ céng jīng zài tái nán zhù guò yì nián."}]},{"id":"4-2-6","b":4,"l":2,"k":"","t":{"es":"Etcétera: 等","en":"Enumeration Particle 等 etc…","ens":"Enumeration Particle 等 etc…","tc":"列舉的「等」","sc":"列举的「等」"},"d":{"es":"等 al final de una lista = etcétera; indica que hay más ejemplos. También se dice 等等.","en":"Add 等 after a list of examples to show there are more; 等等 also works.","tc":"列舉幾個例子後加上「等」，表示還有其他沒說完的，也可以說「等等」。","sc":"列举几个例子后加上「等」，表示还有其他没说完的，也可以说「等等」。"},"ex":[{"c":"夜市有臭豆腐、蚵仔煎、珍珠奶茶等小吃。","s":"夜市有臭豆腐、蚵仔煎、珍珠奶茶等小吃。","es":"En el mercado nocturno hay tofu apestoso, tortilla de ostras, té con perlas, etc.","en":"The night market has stinky tofu, oyster omelet, bubble tea and other snacks.","p":"yè shì yǒu chòu dòu fǔ, kē zǐ jiān, zhēn zhū nǎi chá děng xiǎo chī."}]},{"id":"4-2-7","b":4,"l":2,"k":"","t":{"es":"Lo que…: 所 + verbo","en":"Making a Verb with the Particle 所","ens":"Making a Verb with the Particle 所","tc":"「所」＋動詞","sc":"「所」＋动词"},"d":{"es":"所 + verbo forma una expresión nominal de estilo formal: «lo que…». Ejemplos: 我所知道的, 他所說的.","en":"所 before a verb turns it into a noun-like phrase meaning 'what…' or 'that which…'. It's fairly formal.","tc":"「所」加在動詞前面，可以把一個動作變成名詞性的說法，意思是「……的（事／東西）」，比較書面。","sc":"「所」加在动词前面，可以把一个动作变成名词性的说法，意思是「……的（事／东西）」，比较书面。"},"ex":[{"c":"這就是我所知道的一切。","s":"这就是我所知道的一切。","es":"Esto es todo lo que sé.","en":"This is everything I know.","p":"zhè jiù shì wǒ suǒ zhī dào de yí qiè."},{"c":"他所說的我都同意。","s":"他所说的我都同意。","es":"Estoy de acuerdo con todo lo que dijo.","en":"I agree with everything he said.","p":"tā suǒ shuō de wǒ dōu tóng yì."}]},{"id":"4-3-0","b":4,"l":3,"k":"","t":{"es":"¿Para qué? 何必","en":"何必 why must","ens":"何必 why must","tc":"何必","sc":"何必"},"d":{"es":"何必 = ¿para qué…?, ¿por qué habrías de…? Es una pregunta retórica: no hace falta.","en":"何必 is a rhetorical question meaning 'there's no need to…', often used to persuade someone not to do something.","tc":"「何必」是反問，意思是「不需要」「沒有必要」，常用來勸人不要這樣做。","sc":"「何必」是反问，意思是「不需要」「没有必要」，常用来劝人不要这样做。"},"ex":[{"c":"只是小事，你何必這麼生氣？","s":"只是小事，你何必这么生气？","es":"Es solo una tontería, ¿para qué enojarte tanto?","en":"It's only a small matter. Why get so angry?","p":"zhǐ shì xiǎo shì, nǐ hé bì zhè me shēng qì?"}]},{"id":"4-3-1","b":4,"l":3,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"No necesariamente: 不見得","en":"不見得 not necessarily","ens":"不见得 not necessarily","tc":"不見得","sc":"不见得"},"d":{"es":"不見得 = no necesariamente. Niega de forma suave que algo sea siempre así.","en":"不見得 means 'not necessarily'. It's a mild way to say it isn't always as you think.","tc":"「不見得」表示不一定，不一定是你想的那樣，語氣比較委婉。","sc":"「不见得」表示不一定，不一定是你想的那样，语气比较委婉。"},"ex":[{"c":"貴的東西不見得比較好。","s":"贵的东西不见得比较好。","es":"Lo caro no necesariamente es mejor.","en":"Expensive things are not necessarily better.","p":"guì de dōng xi bú jiàn dé bǐ jiào hǎo."}]},{"id":"4-3-2","b":4,"l":3,"k":"","t":{"es":"La partícula 嘛","en":"嘛 isn’t it obvious that","ens":"嘛 isn’t it obvious that","tc":"語氣詞「嘛」","sc":"语气词「嘛」"},"d":{"es":"嘛 al final de la oración es una partícula coloquial: indica que algo es obvio o insiste con un tono de reproche suave.","en":"嘛 at the end of a sentence shows that something is obvious, or adds a gently persuasive or impatient tone. It's colloquial.","tc":"「嘛」放在句尾，表示這件事很明顯、很簡單，或帶一點勸說、不耐煩的語氣，是口語的說法。","sc":"「嘛」放在句尾，表示这件事很明显、很简单，或带一点劝说、不耐烦的语气，是口语的说法。"},"ex":[{"c":"這很簡單嘛，你一定會的。","s":"这很简单嘛，你一定会的。","es":"Esto es fácil, ¿no ves?; seguro que puedes.","en":"It's easy, you know. I'm sure you can do it.","p":"zhè hěn jiǎn dān má, nǐ yí dìng huì de."},{"c":"有問題就問嘛。","s":"有问题就问嘛。","es":"Si tienes dudas, pregunta, ¿no?","en":"If you have a question, just ask!","p":"yǒu wèn tí jiù wèn má."}]},{"id":"4-3-3","b":4,"l":3,"k":"","t":{"es":"Acostumbrarse: V 慣","en":"Verb Particle 慣","ens":"Verb Particle 惯","tc":"動詞＋慣","sc":"动词＋惯"},"d":{"es":"V + 慣 = estar acostumbrado a: 吃慣, 住慣, 用慣. En negativo, 看不慣 = no soportar ver algo.","en":"V + 慣 means being used to something (吃慣, 住慣, 用慣). 看不慣 means you can't stand seeing it.","tc":"「V＋慣」表示習慣了，例如「吃慣」「住慣」「用慣」。否定的「看不慣」是「看了不舒服、無法接受」。","sc":"「V＋惯」表示习惯了，例如「吃惯」「住惯」「用惯」。否定的「看不惯」是「看了不舒服、无法接受」。"},"ex":[{"c":"我已經吃慣台灣菜了。","s":"我已经吃惯台湾菜了。","es":"Ya me acostumbré a la comida taiwanesa.","en":"I'm already used to Taiwanese food.","p":"wǒ yǐ jīng chī guàn tái wān cài le."},{"c":"他看不慣別人亂丟垃圾。","s":"他看不惯别人乱丢垃圾。","es":"No soporta ver que otros tiren basura por cualquier lado.","en":"He can't stand seeing people litter.","p":"tā kàn bú guàn bié rén luàn diū lè sè."}]},{"id":"4-3-4","b":4,"l":3,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"No tener fuerzas: V 得動／不動","en":"Verb Complement 動 capable of causing movement","ens":"Verb Complement 动 capable of causing movement","tc":"動詞＋得動／不動","sc":"动词＋得动／不动"},"d":{"es":"V + 得動 / 不動 = tener / no tener fuerza para mover o hacer algo: 搬不動, 走不動, 吃不動.","en":"V + 得動 / 不動 shows whether you have the strength to do something, like 搬不動, 走不動, 吃不動.","tc":"「V＋得動／不動」表示有沒有力氣把一個動作做完，例如「搬不動」「走不動」「吃不動」。","sc":"「V＋得动／不动」表示有没有力气把一个动作做完，例如「搬不动」「走不动」「吃不动」。"},"ex":[{"c":"這個箱子太重了，我搬不動。","s":"这个箱子太重了，我搬不动。","es":"Esta caja pesa demasiado, no puedo moverla.","en":"This box is too heavy; I can't move it.","p":"zhè ge xiāng zi tài zhòng le, wǒ bān bú dòng."},{"c":"我今天累得走不動了。","s":"我今天累得走不动了。","es":"Hoy estoy tan cansado que ya no puedo caminar.","en":"I'm so tired today that I can't walk anymore.","p":"wǒ jīn tiān lèi de zǒu bú dòng le."}]},{"id":"4-3-5","b":4,"l":3,"k":"","t":{"es":"Sin darse cuenta: 無形中","en":"無形中 without knowing it, and before you know it","ens":"无形中 without knowing it, and before you know it","tc":"無形中","sc":"无形中"},"d":{"es":"無形中 = sin darse cuenta, de forma imperceptible y poco a poco.","en":"無形中 means something happens imperceptibly and gradually, without you noticing.","tc":"「無形中」表示不知不覺、慢慢地發生，自己沒有特別注意到。","sc":"「无形中」表示不知不觉、慢慢地发生，自己没有特别注意到。"},"ex":[{"c":"常常看台劇，無形中他的中文進步了。","s":"常常看台剧，无形中他的中文进步了。","es":"Como veía series taiwanesas a menudo, su chino mejoró sin que se diera cuenta.","en":"He watched Taiwanese dramas often, and his Chinese improved without him realizing it.","p":"cháng cháng kàn tái jù, wú xíng zhōng tā de zhōng wén jìn bù le."}]},{"id":"4-3-6","b":4,"l":3,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Además: 此外","en":"此外 in addition, furthermore","ens":"此外 in addition, furthermore","tc":"此外","sc":"此外"},"d":{"es":"此外 = además, aparte de esto. Es un conector de estilo formal que añade otro punto.","en":"此外 is a formal connector meaning 'besides this, there is also…'; it adds another point.","tc":"「此外」是書面的連接詞，意思是「除了這個以外，還有……」，用來再加一點。","sc":"「此外」是书面的连接词，意思是「除了这个以外，还有……」，用来再加一点。"},"ex":[{"c":"這家店的東西很新鮮，此外服務也很好。","s":"这家店的东西很新鲜，此外服务也很好。","es":"Los productos de esta tienda son muy frescos y, además, el servicio es muy bueno.","en":"The food at this shop is very fresh, and the service is great too.","p":"zhè jiā diàn de dōng xi hěn xīn xiān, cǐ wài fú wù yě hěn hǎo."}]},{"id":"4-3-7","b":4,"l":3,"k":"","t":{"es":"En resumen: 總而言之","en":"總而言之 in short","ens":"总而言之 in short","tc":"總而言之","sc":"总而言之"},"d":{"es":"總而言之 = en resumen, en una palabra. Introduce la conclusión.","en":"總而言之 introduces a brief conclusion after several points have been made.","tc":"「總而言之」用在說完幾個看法之後，引出簡短的結論。","sc":"「总而言之」用在说完几个看法之后，引出简短的结论。"},"ex":[{"c":"總而言之，這個方法比較省時間。","s":"总而言之，这个方法比较省时间。","es":"En resumen, este método ahorra más tiempo.","en":"In short, this method saves more time.","p":"zǒng ér yán zhī, zhè ge fāng fǎ bǐ jiào shěng shí jiān."}]},{"id":"4-4-0","b":4,"l":4,"k":"","t":{"es":"Por fin: 總算","en":"總算 finally, speaking roughly (in the ball park)","ens":"总算 finally, speaking roughly (in the ball park)","tc":"總算","sc":"总算"},"d":{"es":"總算 = por fin, finalmente. Expresa alivio después de esperar o esforzarse mucho.","en":"總算 shows that after a long wait or effort, a result finally came, with a sense of relief.","tc":"「總算」表示等了很久或努力很久之後，終於有了結果，帶著鬆了一口氣的感覺。","sc":"「总算」表示等了很久或努力很久之后，终于有了结果，带着松了一口气的感觉。"},"ex":[{"c":"等了三個月，簽證總算下來了。","s":"等了三个月，签证总算下来了。","es":"Después de esperar tres meses, por fin salió la visa.","en":"After waiting three months, the visa has finally come through.","p":"děng le sān ge yuè, qiān zhèng zǒng suàn xià lái le."}]},{"id":"4-4-1","b":4,"l":4,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 además adición también addition also besides 另外 而且 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序 además adición también addition also besides 另外 而且","t":{"es":"No es más que…: 還不就是","en":"還不就是 nothing more than","ens":"还不就是 nothing more than","tc":"還不就是","sc":"还不就是"},"d":{"es":"還不就是 = no es más que…, al fin y al cabo es solo… Resta importancia; tono coloquial.","en":"還不就是 is a colloquial rhetorical phrase meaning 'it's nothing more than…', playing down how important something is.","tc":"「還不就是」用來說「也不過是……」，把事情說得不重要，是口語的反問。","sc":"「还不就是」用来说「也不过是……」，把事情说得不重要，是口语的反问。"},"ex":[{"c":"他們說的新方法，還不就是以前那一套？","s":"他们说的新方法，还不就是以前那一套？","es":"Ese «método nuevo» que dicen, ¿no es lo mismo de antes?","en":"That 'new method' they talk about is just the same old routine, isn't it?","p":"tā men shuō de xīn fāng fǎ, hái bú jiù shì yǐ qián nà yí tào?"}]},{"id":"4-4-2","b":4,"l":4,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Negación fuerte con 才","en":"Outright Denial with 才","ens":"Outright Denial with 才","tc":"表示強烈否定的「才」","sc":"表示强烈否定的「才」"},"d":{"es":"才 enfático con negación: «eso sí que no», «claro que no». Contradice con fuerza lo que se dijo: 才不, 才沒有.","en":"才不 / 才沒有 strongly denies or pushes back: 'no way', 'certainly not'.","tc":"「才不」「才沒有」用來強烈反駁，意思是「才不是這樣」「我才不要」。","sc":"「才不」「才没有」用来强烈反驳，意思是「才不是这样」「我才不要」。"},"ex":[{"c":"我才不要去！","s":"我才不要去！","es":"¡Yo no pienso ir!","en":"I'm not going, no way!","p":"wǒ cái bú yào qù!"},{"c":"誰說我生氣了？我才沒有。","s":"谁说我生气了？我才没有。","es":"¿Quién dijo que estoy enojado? Para nada.","en":"Who said I was angry? I'm not.","p":"shéi shuō wǒ shēng qì le? wǒ cái méi yǒu."}]},{"id":"4-4-3","b":4,"l":4,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Usos de 才 (resumen)","en":"A Summary of the Various Usages of 才","ens":"A Summary of the Various Usages of 才","tc":"「才」的用法總整理","sc":"「才」的用法总整理"},"d":{"es":"Resumen de 才: (1) «solo entonces» (condición previa); (2) «apenas» (cantidad pequeña); (3) más tarde de lo esperado; (4) negación enfática (我才不去).","en":"Main uses of 才: (1) only after something is done; (2) 'only/just' for small amounts; (3) later than expected; (4) emphatic denial.","tc":"「才」常見的用法有：一、做完某件事之後才能……；二、數量很少（才八點）；三、比預期晚（十點才來）；四、強烈否定（我才不去）。","sc":"「才」常见的用法有：一、做完某件事之后才能……；二、数量很少（才八点）；三、比预期晚（十点才来）；四、强烈否定（我才不去）。"},"ex":[{"c":"你先寫完功課才可以玩。","s":"你先写完功课才可以玩。","es":"Solo después de terminar la tarea puedes jugar.","en":"You can only play after you finish your homework.","p":"nǐ xiān xiě wán gōng kè cái kě yǐ wán."},{"c":"他昨天十二點才睡。","s":"他昨天十二点才睡。","es":"Ayer no se durmió hasta las doce.","en":"He didn't go to sleep until twelve yesterday.","p":"tā zuó tiān shí èr diǎn cái shuì."}]},{"id":"4-4-4","b":4,"l":4,"k":"","t":{"es":"Definir: 所謂…是指","en":"所謂（的） A 是指 B so called A refers to B","ens":"所谓（的） A 是指 B so called A refers to B","tc":"所謂（的）A，是指 B","sc":"所谓（的）A，是指 B"},"d":{"es":"所謂（的）A，是指 B = lo que se llama A se refiere a B. Sirve para definir un término.","en":"Used to define a term: 所謂 A means 'what is called A', followed by 是指 B to say what it refers to.","tc":"用來解釋一個詞的意思：「所謂 A」就是「大家說的 A」，後面接「是指 B」說明它是什麼。","sc":"用来解释一个词的意思：「所谓 A」就是「大家说的 A」，后面接「是指 B」说明它是什么。"},"ex":[{"c":"所謂「宵夜」，是指晚餐以後吃的東西。","s":"所谓「宵夜」，是指晚餐以后吃的东西。","es":"Lo que se llama «xiaoye» se refiere a lo que se come después de la cena.","en":"'Xiaoye' refers to what you eat after dinner.","p":"suǒ wèi 「xiāo yè」, shì zhǐ wǎn cān yǐ hòu chī de dōng xi."}]},{"id":"4-4-5","b":4,"l":4,"k":"","t":{"es":"De un tirón: 一口氣","en":"一口氣 lit. in one breath","ens":"一口气 lit. in one breath","tc":"一口氣","sc":"一口气"},"d":{"es":"一口氣 = de un tirón, sin parar (en una sola respiración).","en":"一口氣 means doing something in one go, without stopping or resting.","tc":"「一口氣」表示一次就做完，中間不停，不休息。","sc":"「一口气」表示一次就做完，中间不停，不休息。"},"ex":[{"c":"他一口氣喝完了一大杯水。","s":"他一口气喝完了一大杯水。","es":"Se tomó de un trago un vaso grande de agua.","en":"He drank a large glass of water in one gulp.","p":"tā yì kǒu qì hē wán le yí dà bēi shuǐ."},{"c":"我一口氣把書看完了。","s":"我一口气把书看完了。","es":"Me leí el libro de un tirón.","en":"I read the whole book in one go.","p":"wǒ yì kǒu qì bǎ shū kàn wán le."}]},{"id":"4-4-6","b":4,"l":4,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Solo A ya…: 光 A 就","en":"光 A 就… just A alone…","ens":"光 A 就… just A alone…","tc":"光 A 就…","sc":"光 A 就…"},"d":{"es":"光 A 就… = solo A ya… Solo eso ya es mucho, sin contar lo demás.","en":"光 A 就… means that A alone is already a lot, without counting anything else.","tc":"「光 A 就……」表示只算 A 這一項，就已經很多了，更不用算別的。","sc":"「光 A 就……」表示只算 A 这一项，就已经很多了，更不用算别的。"},"ex":[{"c":"光機票就要三萬塊。","s":"光机票就要三万块。","es":"Solo el pasaje de avión ya cuesta treinta mil dólares.","en":"The plane ticket alone costs thirty thousand dollars.","p":"guāng jī piào jiù yào sān wàn kuài."}]},{"id":"4-4-7","b":4,"l":4,"k":"","t":{"es":"Queja con 都","en":"Expressing Displeasure or Annoyance with 都","ens":"Expressing Displeasure or Annoyance with 都","tc":"表示抱怨的「都」","sc":"表示抱怨的「都」"},"d":{"es":"都 + causa o tiempo expresa queja o fastidio: 都是你… = es todo culpa tuya; 都 + hora + 了 = ya es tan tarde y todavía….","en":"都是你… blames someone ('it's all your fault'); 都 + time + 了 means 'it's already this late, and yet…'.","tc":"「都是你……」表示責怪，說因為你才會這樣；「都＋時間＋了」表示已經這麼晚了，還沒做某件事。","sc":"「都是你……」表示责怪，说因为你才会这样；「都＋时间＋了」表示已经这么晚了，还没做某件事。"},"ex":[{"c":"都是你，我們才會遲到！","s":"都是你，我们才会迟到！","es":"¡Por tu culpa llegamos tarde!","en":"It's all your fault that we're late!","p":"dōu shì nǐ, wǒ men cái huì chí dào!"},{"c":"都十二點了，你還不睡？","s":"都十二点了，你还不睡？","es":"Ya son las doce, ¿todavía no te duermes?","en":"It's already twelve o'clock; aren't you going to sleep yet?","p":"dōu shí èr diǎn le, nǐ hái bú shuì?"}]},{"id":"4-5-0","b":4,"l":5,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Pregunta retórica: 哪裡","en":"Rhetorical Question with 哪裡","ens":"Rhetorical Question with 哪里","tc":"反問的「哪裡」","sc":"反问的「哪里」"},"d":{"es":"哪裡 + verbo / adjetivo = negación retórica: «qué va», «cómo voy a…». También se usa como respuesta modesta a un halago.","en":"哪裡 before a verb or adjective makes a rhetorical negation: 'how could…', 'not at all'. Replying 哪裡 to a compliment is a modest answer.","tc":"「哪裡」放在動詞或形容詞前面，用反問的方式表示否定，意思是「怎麼會」「才不是」。回答別人稱讚時說「哪裡哪裡」，是謙虛的說法。","sc":"「哪里」放在动词或形容词前面，用反问的方式表示否定，意思是「怎么会」「才不是」。回答别人称赞时说「哪里哪里」，是谦虚的说法。"},"ex":[{"c":"我哪裡知道他今天不來？","s":"我哪里知道他今天不来？","es":"¿Cómo iba a saber yo que hoy no venía?","en":"How would I know he isn't coming today?","p":"wǒ nǎ lǐ zhī dào tā jīn tiān bù lái?"},{"c":"哪裡，我的中文還不夠好。","s":"哪里，我的中文还不够好。","es":"Qué va, mi chino todavía no es suficientemente bueno.","en":"Not at all, my Chinese still isn't good enough.","p":"nǎ lǐ, wǒ de zhōng wén hái bú gòu hǎo."}]},{"id":"4-5-1","b":4,"l":5,"k":"","t":{"es":"Al fin y al cabo: 畢竟","en":"畢竟 after all","ens":"毕竟 after all","tc":"畢竟","sc":"毕竟"},"d":{"es":"畢竟 = al fin y al cabo, después de todo. Recuerda la razón de fondo.","en":"畢竟 points to the underlying reason: 'after all', 'when all is said and done'.","tc":"「畢竟」提醒對方最根本的原因，意思是「說到底」「終究」。","sc":"「毕竟」提醒对方最根本的原因，意思是「说到底」「终究」。"},"ex":[{"c":"他畢竟還是個孩子，別太嚴格。","s":"他毕竟还是个孩子，别太严格。","es":"Al fin y al cabo es un niño, no seas tan estricto.","en":"After all, he's still a child, so don't be too strict.","p":"tā bì jìng hái shì ge hái zi, bié tài yán gé."}]},{"id":"4-5-2","b":4,"l":5,"k":"","t":{"es":"Efectivamente: 的確","en":"的確 indeed","ens":"的确 indeed","tc":"的確","sc":"的确"},"d":{"es":"的確 = efectivamente, realmente. Confirma que algo es cierto.","en":"的確 confirms that something is true: 'indeed', 'certainly'.","tc":"「的確」用來確認一件事是真的，意思是「確實」。","sc":"「的确」用来确认一件事是真的，意思是「确实」。"},"ex":[{"c":"這家店的牛肉麵的確很好吃。","s":"这家店的牛肉面的确很好吃。","es":"Los fideos con carne de este lugar de verdad están muy ricos.","en":"The beef noodles at this shop really are delicious.","p":"zhè jiā diàn de niú ròu miàn dí què hěn hǎo chī."}]},{"id":"4-5-3","b":4,"l":5,"k":"dirección movimiento direction movement 方向 趨向 contraste pero sin embargo contrast but however 對比 轉折 dirección movimiento direction movement 方向 趋向 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Por otro lado: 話說回來","en":"話說回來 however, on the other hand","ens":"话说回来 however, on the other hand","tc":"話說回來","sc":"话说回来"},"d":{"es":"話說回來 = pero, por otro lado; dicho esto. Introduce otro punto de vista o vuelve al tema.","en":"話說回來 shifts to another angle or brings the topic back: 'that said', 'on the other hand'.","tc":"「話說回來」用來轉到另一個角度，或把話題拉回來，意思是「不過」「說回來」。","sc":"「话说回来」用来转到另一个角度，或把话题拉回来，意思是「不过」「说回来」。"},"ex":[{"c":"台北交通很方便，話說回來，房租也真的很貴。","s":"台北交通很方便，话说回来，房租也真的很贵。","es":"En Taipéi el transporte es muy cómodo, pero, por otro lado, la renta sí que es cara.","en":"Transportation in Taipei is very convenient, but then again, the rent is really expensive.","p":"tái běi jiāo tōng hěn fāng biàn, huà shuō huí lái, fáng zū yě zhēn de hěn guì."}]},{"id":"4-5-4","b":4,"l":5,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"La razón es…: 之所以…是因為","en":"NP 之所以 S2 是因為 S1 S2 is due to S1","ens":"NP 之所以 S2 是因为 S1 S2 is due to S1","tc":"NP 之所以 S2，是因為 S1","sc":"NP 之所以 S2，是因为 S1"},"d":{"es":"NP 之所以 S2，是因為 S1 = la razón por la que S2 es que S1. Primero se dice el resultado y luego la causa.","en":"State the result first, then the cause: 之所以…，是因為…. It puts more weight on the reason than 因為…所以….","tc":"先說結果，再說原因：「之所以……，是因為……」。比「因為……所以……」更強調原因。","sc":"先说结果，再说原因：「之所以……，是因为……」。比「因为……所以……」更强调原因。"},"ex":[{"c":"他之所以能考上，是因為他每天都很努力。","s":"他之所以能考上，是因为他每天都很努力。","es":"La razón por la que pudo entrar es que se esforzaba todos los días.","en":"The reason he got in is that he worked hard every day.","p":"tā zhī suǒ yǐ néng kǎo shàng, shì yīn wèi tā měi tiān dōu hěn nǔ lì."}]},{"id":"4-5-5","b":4,"l":5,"k":"","t":{"es":"En absoluto: 根本","en":"根本 not…at all","ens":"根本 not…at all","tc":"根本","sc":"根本"},"d":{"es":"根本 + negación = en absoluto, de ninguna manera. Enfatiza que no es así desde el fondo.","en":"根本 in a negative sentence means 'not at all', 'not even in the slightest'.","tc":"「根本」放在否定的句子裡，表示完全不是這樣，意思是「從來就不」「完全不」。","sc":"「根本」放在否定的句子里，表示完全不是这样，意思是「从来就不」「完全不」。"},"ex":[{"c":"我根本不知道這件事。","s":"我根本不知道这件事。","es":"No tenía ni idea de este asunto.","en":"I had no idea about this matter at all.","p":"wǒ gēn běn bù zhī dào zhè jiàn shì."}]},{"id":"4-5-6","b":4,"l":5,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 siempre nunca frecuencia always never frequency 經常 從來 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Y mucho menos: 更別說…了","en":"更別說…了 let alone, never mind","ens":"更别说…了 let alone, never mind","tc":"更別說…了","sc":"更别说…了"},"d":{"es":"更別說 A 了 = y mucho menos A, ni hablar de A. Se niega un caso más difícil después de uno más fácil.","en":"After saying someone can't even do the easier thing, 更別說 A 了 adds that the harder thing is out of the question.","tc":"先說一件比較容易的事都做不到，再說「更別說 A 了」，表示更難的事當然做不到。","sc":"先说一件比较容易的事都做不到，再说「更别说 A 了」，表示更难的事当然做不到。"},"ex":[{"c":"他連中文都不會說，更別說寫了。","s":"他连中文都不会说，更别说写了。","es":"Ni siquiera sabe hablar chino, y mucho menos escribirlo.","en":"He can't even speak Chinese, let alone write it.","p":"tā lián zhōng wén dōu bú huì shuō, gèng bié shuō xiě le."}]},{"id":"4-5-7","b":4,"l":5,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Desear con fuerza: 恨不得","en":"恨不得 one really wishes one could…","ens":"恨不得 one really wishes one could…","tc":"恨不得","sc":"恨不得"},"d":{"es":"恨不得 + verbo = desear con todas las fuerzas poder hacer algo (a menudo imposible).","en":"恨不得 means desperately wanting to do something, usually something you can't actually do.","tc":"「恨不得」表示非常想做某件事，但通常做不到。","sc":"「恨不得」表示非常想做某件事，但通常做不到。"},"ex":[{"c":"太累了，我恨不得馬上就能睡覺。","s":"太累了，我恨不得马上就能睡觉。","es":"Estoy tan cansado que quisiera poder dormirme ya mismo.","en":"I'm so tired I wish I could fall asleep right now.","p":"tài lèi le, wǒ hèn bù dé mǎ shàng jiù néng shuì jiào."},{"c":"聽到好消息，他恨不得馬上告訴大家。","s":"听到好消息，他恨不得马上告诉大家。","es":"Al oír la buena noticia, se moría por contárselo a todos.","en":"Hearing the good news, he couldn't wait to tell everyone.","p":"tīng dào hǎo xiāo xí, tā hèn bù dé mǎ shàng gào sù dà jiā."}]},{"id":"4-6-0","b":4,"l":6,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"¿Por qué tan…? 怎麼這麼","en":"怎麼這麼 Why so…?","ens":"怎么这么 Why so…?","tc":"怎麼這麼","sc":"怎么这么"},"d":{"es":"怎麼這麼 + adjetivo / verbo = ¿por qué tan…? Expresa sorpresa o queja.","en":"怎麼這麼 + adjective / verb expresses surprise or complaint: 'why so…?'.","tc":"「怎麼這麼＋形容詞／動詞」表示驚訝或抱怨，意思是「為什麼這麼……」。","sc":"「怎么这么＋形容词／动词」表示惊讶或抱怨，意思是「为什么这么……」。"},"ex":[{"c":"今天怎麼這麼冷？","s":"今天怎么这么冷？","es":"¿Por qué hace tanto frío hoy?","en":"Why is it so cold today?","p":"jīn tiān zěn me zhè me lěng?"}]},{"id":"4-6-1","b":4,"l":6,"k":"","t":{"es":"Exclamación con 多","en":"Intensifying Adverb 多 how","ens":"Intensifying Adverb 多 how","tc":"感嘆的「多」","sc":"感叹的「多」"},"d":{"es":"多 + adjetivo en una exclamación = ¡qué…! Suele cerrar con 啊 / 呀 y expresa admiración.","en":"多 + adjective in an exclamation means 'how…!', and often ends with 啊 or 呀.","tc":"「多＋形容詞」用在感嘆句，意思是「多麼……」，句尾常加「啊」「呀」。","sc":"「多＋形容词」用在感叹句，意思是「多么……」，句尾常加「啊」「呀」。"},"ex":[{"c":"這裡的風景多美啊！","s":"这里的风景多美啊！","es":"¡Qué hermoso es el paisaje de aquí!","en":"How beautiful the scenery is here!","p":"zhè lǐ de fēng jǐng duō měi a!"}]},{"id":"4-6-2","b":4,"l":6,"k":"","t":{"es":"Usos de 多 (resumen)","en":"The Various Functions of 多","ens":"The Various Functions of 多","tc":"「多」的各種用法","sc":"「多」的各种用法"},"d":{"es":"Funciones de 多: (1) «más de» después de un número; (2) pregunta de grado (多高, 多久); (3) exclamación «qué…»; (4) «por más… que» en 不管多….","en":"Common uses of 多: (1) 'more than' after a number; (2) asking degree (多高); (3) exclamation 'how…'; (4) 不管多… for 'no matter how…'.","tc":"「多」常見的用法有：一、數字後面表示「超過」（三十多歲）；二、問程度（多高）；三、感嘆（多好看）；四、「不管多……」表示「再……也」。","sc":"「多」常见的用法有：一、数字后面表示「超过」（三十多岁）；二、问程度（多高）；三、感叹（多好看）；四、「不管多……」表示「再……也」。"},"ex":[{"c":"他今年三十多歲。","s":"他今年三十多岁。","es":"Este año tiene treinta y tantos.","en":"He's in his thirties this year.","p":"tā jīn nián sān shí duō suì."},{"c":"不管多忙，我都會陪家人吃晚飯。","s":"不管多忙，我都会陪家人吃晚饭。","es":"Por muy ocupado que esté, ceno con mi familia.","en":"No matter how busy I am, I eat dinner with my family.","p":"bù guǎn duō máng, wǒ dōu huì péi jiā rén chī wǎn fàn."}]},{"id":"4-6-3","b":4,"l":6,"k":"","t":{"es":"En vano: 白","en":"白 in vain, for nothing","ens":"白 in vain, for nothing","tc":"白","sc":"白"},"d":{"es":"白 + verbo = en vano, para nada, sin resultado: 白跑一趟 = ir en balde. También puede significar «gratis» (白吃).","en":"白 + verb means doing something with no result, such as 白跑一趟 (a wasted trip). It can also mean 'for free' (白吃).","tc":"「白＋動詞」表示做了卻沒有結果、沒有用，例如「白跑一趟」。也可以表示「不用付錢」（白吃）。","sc":"「白＋动词」表示做了却没有结果、没有用，例如「白跑一趟」。也可以表示「不用付钱」（白吃）。"},"ex":[{"c":"我白等了一個小時。","s":"我白等了一个小时。","es":"Esperé una hora en vano.","en":"I waited an hour for nothing.","p":"wǒ bái děng le yí ge xiǎo shí."},{"c":"他白跑了一趟。","s":"他白跑了一趟。","es":"Fue en balde.","en":"He made a trip for nothing.","p":"tā bái pǎo le yí tàng."}]},{"id":"4-6-4","b":4,"l":6,"k":"siempre nunca frecuencia always never frequency 經常 從來 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Siempre: 總是","en":"總是 always","ens":"总是 always","tc":"總是","sc":"总是"},"d":{"es":"總是 = siempre, constantemente. Es un hábito constante, a veces con un tono de queja.","en":"總是 means 'always', a constant habit, sometimes with a slight tone of complaint.","tc":"「總是」表示一直都是這樣，是固定的習慣，有時帶一點抱怨。","sc":"「总是」表示一直都是这样，是固定的习惯，有时带一点抱怨。"},"ex":[{"c":"他總是遲到。","s":"他总是迟到。","es":"Siempre llega tarde.","en":"He's always late.","p":"tā zǒng shì chí dào."}]},{"id":"4-6-5","b":4,"l":6,"k":"dirección movimiento direction movement 方向 趨向 complemento resultado potencial complement result potential 補語 結果補語 可能補語 dirección movimiento direction movement 方向 趋向 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"V 下來 (resumen)","en":"The Various Meanings of the Verb Complement 下來","ens":"The Various Meanings of the Verb Complement 下来","tc":"動詞＋下來","sc":"动词＋下来"},"d":{"es":"V + 下來: (1) de arriba hacia abajo; (2) algo queda registrado o se queda (記下來, 留下來); (3) continuar hasta ahora; (4) calmarse (安靜下來).","en":"Common meanings of V + 下來: (1) downward; (2) recording or keeping something (記下來, 留下來); (3) lasting up to now; (4) calming down.","tc":"「V＋下來」常見的意思有：一、從上往下；二、把東西記錄或留住（記下來、留下來）；三、從過去持續到現在；四、變安靜、變穩定（安靜下來）。","sc":"「V＋下来」常见的意思有：一、从上往下；二、把东西记录或留住（记下来、留下来）；三、从过去持续到现在；四、变安静、变稳定（安静下来）。"},"ex":[{"c":"請把這個電話號碼記下來。","s":"请把这个电话号码记下来。","es":"Por favor anota este número de teléfono.","en":"Please write down this phone number.","p":"qǐng bǎ zhè ge diàn huà hào mǎ jì xià lái."},{"c":"聽到音樂，他慢慢安靜下來了。","s":"听到音乐，他慢慢安静下来了。","es":"Al oír la música, poco a poco se fue calmando.","en":"Hearing the music, he gradually calmed down.","p":"tīng dào yīn yuè, tā màn màn ān jìng xià lái le."}]},{"id":"4-6-6","b":4,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Cuando: 當…的時候","en":"當…的時候 when, while, at the time of","ens":"当…的时候 when, while, at the time of","tc":"當…的時候","sc":"当…的时候"},"d":{"es":"當 + frase + 的時候 = cuando, mientras, en el momento en que…. 當 hace la expresión un poco más formal.","en":"當 + clause + 的時候 means 'at the time when…'; it's slightly more formal than just …的時候.","tc":"「當＋一段話＋的時候」表示「在……的時間」，比只說「……的時候」稍微正式一點。","sc":"「当＋一段话＋的时候」表示「在……的时间」，比只说「……的时候」稍微正式一点。"},"ex":[{"c":"當我到家的時候，天已經黑了。","s":"当我到家的时候，天已经黑了。","es":"Cuando llegué a casa, ya había oscurecido.","en":"When I got home, it was already dark.","p":"dāng wǒ dào jiā de shí hòu, tiān yǐ jīng hēi le."}]},{"id":"4-6-7","b":4,"l":6,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Al contrario: 反而","en":"反而 on the contrary","ens":"反而 on the contrary","tc":"反而","sc":"反而"},"d":{"es":"反而 = al contrario, en cambio. El resultado va en contra de lo esperado.","en":"反而 shows that the result is the opposite of what you'd expect: 'on the contrary', 'instead'.","tc":"「反而」表示結果和預期相反，意思是「結果卻是」。","sc":"「反而」表示结果和预期相反，意思是「结果却是」。"},"ex":[{"c":"吃了藥，他不但沒好，反而更不舒服了。","s":"吃了药，他不但没好，反而更不舒服了。","es":"Tomó la medicina y no solo no mejoró, sino que se sintió peor.","en":"He took the medicine, and not only didn't he get better, he felt even worse.","p":"chī le yào, tā bú dàn méi hǎo, fǎn ér gèng bù shū fú le."},{"c":"我已經提醒他了，他反而生氣了。","s":"我已经提醒他了，他反而生气了。","es":"Ya se lo recordé y, al contrario, se enojó.","en":"I already reminded him, and he got angry instead.","p":"wǒ yǐ jīng tí xǐng tā le, tā fǎn ér shēng qì le."}]},{"id":"4-7-0","b":4,"l":7,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Sorpresa con 還","en":"還 to my surprise","ens":"还 to my surprise","tc":"表示意外的「還」","sc":"表示意外的「还」"},"d":{"es":"還 expresa sorpresa: algo resulta mejor o más de lo esperado. Suele aparecer en frases como 還會…, 還有….","en":"還 expresses surprise that something is better or more than expected. Common patterns are 還會… and 還有….","tc":"「還」可以表示事情比想像的更好、更多，帶有一點意外。常見的說法有「還會……」「還有……」。","sc":"「还」可以表示事情比想像的更好、更多，带有一点意外。常见的说法有「还会……」「还有……」。"},"ex":[{"c":"這麼難的歌，他還會唱！","s":"这么难的歌，他还会唱！","es":"¡Hasta sabe cantar una canción tan difícil!","en":"He can even sing such a hard song!","p":"zhè me nán de gē, tā hái huì chàng!"},{"c":"沒想到這家店還有賣中文書。","s":"没想到这家店还有卖中文书。","es":"No esperaba que esta tienda hasta vendiera libros en chino.","en":"I didn't expect this shop to sell Chinese books, too.","p":"méi xiǎng dào zhè jiā diàn hái yǒu mài zhōng wén shū."}]},{"id":"4-7-1","b":4,"l":7,"k":"","t":{"es":"Alternar: 一下…一下…","en":"Alternating Events with 一下…一下…","ens":"Alternating Events with 一下…一下…","tc":"一下……一下……","sc":"一下……一下……"},"d":{"es":"一下 A，一下 B = ahora A, ahora B. Describe dos situaciones que se alternan rápidamente.","en":"一下 A, 一下 B means 'one moment A, the next moment B'. Two situations alternate quickly.","tc":"「一下 A，一下 B」表示兩種情況很快輪流出現，一下子這樣、一下子那樣。","sc":"「一下 A，一下 B」表示两种情况很快轮流出现，一下子这样、一下子那样。"},"ex":[{"c":"他一下高興、一下難過，真讓人搞不懂。","s":"他一下高兴、一下难过，真让人搞不懂。","es":"Un rato está contento y otro triste; es difícil entenderlo.","en":"He's happy one moment and sad the next; it's hard to figure him out.","p":"tā yí xià gāo xìng, yí xià nán guò, zhēn ràng rén gǎo bù dǒng."},{"c":"天氣一下熱、一下冷，很容易感冒。","s":"天气一下热、一下冷，很容易感冒。","es":"El clima cambia de calor a frío todo el tiempo; es fácil resfriarse.","en":"The weather swings between hot and cold; it's easy to catch a cold.","p":"tiān qì yí xià rè, yí xià lěng, hěn róng yì gǎn mào."}]},{"id":"4-7-2","b":4,"l":7,"k":"","t":{"es":"Fracciones: A 分之 B","en":"Various Fractions with A 分之 B","ens":"Various Fractions with A 分之 B","tc":"分數：A 分之 B","sc":"分数：A 分之 B"},"d":{"es":"A 分之 B expresa fracciones: se dice primero el denominador (A) y luego el numerador (B). Los porcentajes usan 百分之.","en":"For fractions, say the denominator (A) first, then 分之, then the numerator (B). Percentages use 百分之.","tc":"說分數時，先說分母（A），再說分子（B），中間加「分之」。百分比用「百分之」。","sc":"说分数时，先说分母（A），再说分子（B），中间加「分之」。百分比用「百分之」。"},"ex":[{"c":"全班有三分之一的人去過日本。","s":"全班有三分之一的人去过日本。","es":"Un tercio de la clase ha ido a Japón.","en":"A third of the class has been to Japan.","p":"quán bān yǒu sān fēn zhī yī de rén qù guò rì běn."},{"c":"這家公司百分之八十的員工是女生。","s":"这家公司百分之八十的员工是女生。","es":"El ochenta por ciento de los empleados de esta empresa son mujeres.","en":"Eighty percent of the employees at this company are women.","p":"zhè jiā gōng sī bǎi fēn zhī bā shí de yuán gōng shì nǚ shēng."}]},{"id":"4-7-3","b":4,"l":7,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Seguidos: 一連","en":"一連 without interruption, in rapid succession","ens":"一连 without interruption, in rapid succession","tc":"一連","sc":"一连"},"d":{"es":"一連 + cantidad + verbo = varias veces o durante varios días seguidos, sin interrupción.","en":"一連 + quantity + verb means an action happens several times or for several days in a row, without a break.","tc":"「一連＋數量＋動詞」表示動作連續發生好幾次，或持續好幾天，中間沒有停。","sc":"「一连＋数量＋动词」表示动作连续发生好几次，或持续好几天，中间没有停。"},"ex":[{"c":"他一連請了三天假。","s":"他一连请了三天假。","es":"Pidió permiso tres días seguidos.","en":"He took leave for three days in a row.","p":"tā yì lián qǐng le sān tiān jiǎ."},{"c":"這個星期一連下了五天雨。","s":"这个星期一连下了五天雨。","es":"Esta semana llovió cinco días seguidos.","en":"It rained for five days straight this week.","p":"zhè ge xīng qí yī lián xià le wǔ tiān yǔ."}]},{"id":"4-7-4","b":4,"l":7,"k":"","t":{"es":"Hasta saciarse: V 個夠","en":"To Have a Full Dosage of an Activity V 個夠","ens":"To Have a Full Dosage of an Activity V 个够","tc":"動詞＋個夠","sc":"动词＋个够"},"d":{"es":"Verbo + 個夠 = hacer algo hasta quedar satisfecho, a más no poder (玩個夠, 吃個夠, 睡個夠).","en":"Verb + 個夠 means doing something to your heart's content, as in 玩個夠, 吃個夠, 睡個夠.","tc":"「動詞＋個夠」表示盡情做某件事，做到滿意為止，例如「玩個夠」「吃個夠」「睡個夠」。","sc":"「动词＋个够」表示尽情做某件事，做到满意为止，例如「玩个够」「吃个够」「睡个够」。"},"ex":[{"c":"放假的時候，我想睡個夠。","s":"放假的时候，我想睡个够。","es":"En las vacaciones quiero dormir todo lo que quiera.","en":"On vacation I want to sleep as much as I like.","p":"fàng jià de shí hòu, wǒ xiǎng shuì gè gòu."},{"c":"今天我們一定要吃個夠！","s":"今天我们一定要吃个够！","es":"¡Hoy vamos a comer hasta hartarnos!","en":"Today we're definitely going to eat our fill!","p":"jīn tiān wǒ men yí dìng yào chī gè gòu!"}]},{"id":"4-7-5","b":4,"l":7,"k":"","t":{"es":"Ayudar a: 有助於","en":"有助於 be conducive to","ens":"有助于 be conducive to","tc":"有助於","sc":"有助于"},"d":{"es":"有助於 + verbo / sustantivo = ayudar a, ser útil para. Es una forma más formal de 對…有幫助.","en":"有助於 + verb/noun means 'helps with / is conducive to'. It is a more formal way of saying 對…有幫助.","tc":"「有助於」是「對……有幫助」的比較正式說法，後面接動詞或名詞。","sc":"「有助于」是「对……有帮助」的比较正式说法，后面接动词或名词。"},"ex":[{"c":"多聽多說有助於提高中文程度。","s":"多听多说有助于提高中文程度。","es":"Escuchar y hablar mucho ayuda a mejorar el nivel de chino.","en":"Listening and speaking a lot helps improve your Chinese.","p":"duō tīng duō shuō yǒu zhù yú tí gāo zhōng wén chéng dù."},{"c":"運動有助於睡眠。","s":"运动有助于睡眠。","es":"El ejercicio ayuda a dormir.","en":"Exercise helps you sleep.","p":"yùn dòng yǒu zhù yú shuì mián."}]},{"id":"4-7-6","b":4,"l":7,"k":"","t":{"es":"Así que: 於是","en":"於是… thus, consequently","ens":"于是… thus, consequently","tc":"於是","sc":"于是"},"d":{"es":"於是 = así que, por eso (en consecuencia). Une dos hechos en orden: el segundo ocurre a causa del primero.","en":"於是 means 'so / as a result'. The second event follows from the first, in order.","tc":"「於是」表示因為前面的事，接著發生了後面的事，意思是「所以就」。前後兩件事有先後順序。","sc":"「于是」表示因为前面的事，接着发生了后面的事，意思是「所以就」。前后两件事有先后顺序。"},"ex":[{"c":"他覺得中文很有趣，於是決定去台灣學。","s":"他觉得中文很有趣，于是决定去台湾学。","es":"Le pareció que el chino era interesante, así que decidió ir a estudiarlo a Taiwán.","en":"He found Chinese interesting, so he decided to study it in Taiwan.","p":"tā jué dé zhōng wén hěn yǒu qù, yú shì jué dìng qù tái wān xué."},{"c":"外面下大雨，於是我們留在家裡看電影。","s":"外面下大雨，于是我们留在家里看电影。","es":"Llovía a cántaros afuera, así que nos quedamos en casa viendo una película.","en":"It was pouring outside, so we stayed home and watched a movie.","p":"wài miàn xià dà yǔ, yú shì wǒ men liú zài jiā lǐ kàn diàn yǐng."}]},{"id":"4-7-7","b":4,"l":7,"k":"","t":{"es":"Hacia, a: 向","en":"向 to, toward","ens":"向 to, toward","tc":"介詞「向」","sc":"介词「向」"},"d":{"es":"向 + persona o dirección = hacia, a, de. Marca el destinatario de una acción: 向…借, 向…道謝, 向前走.","en":"向 + person or direction marks the target or direction of an action, as in 向…借, 向…道謝, 向前走.","tc":"「向」後面接人或方向，表示動作的對象或方向，例如「向……借」「向……道謝」「向前走」。","sc":"「向」后面接人或方向，表示动作的对象或方向，例如「向……借」「向……道谢」「向前走」。"},"ex":[{"c":"我想向你借一本書。","s":"我想向你借一本书。","es":"Quiero pedirte prestado un libro.","en":"I'd like to borrow a book from you.","p":"wǒ xiǎng xiàng nǐ jiè yì běn shū."},{"c":"他向大家說明了新的規定。","s":"他向大家说明了新的规定。","es":"Les explicó a todos las nuevas reglas.","en":"He explained the new rules to everyone.","p":"tā xiàng dà jiā shuō míng le xīn de guī dìng."}]},{"id":"4-8-0","b":4,"l":8,"k":"","t":{"es":"De todos modos: 反正","en":"反正 at any rate, anyway","ens":"反正 at any rate, anyway","tc":"反正","sc":"反正"},"d":{"es":"反正 = de todos modos, total. Se usa cuando la situación no cambia, haga lo que se haga.","en":"反正 means 'anyway': whatever happens, the result is the same, so there's no need to worry or argue about it.","tc":"「反正」表示不管怎麼樣，結果都一樣，所以不用在意或不必再討論。","sc":"「反正」表示不管怎么样，结果都一样，所以不用在意或不必再讨论。"},"ex":[{"c":"你不用擔心，反正我們時間很多。","s":"你不用担心，反正我们时间很多。","es":"No te preocupes, total tenemos mucho tiempo.","en":"Don't worry, we have plenty of time anyway.","p":"nǐ bú yòng dān xīn, fǎn zhèng wǒ men shí jiān hěn duō."},{"c":"反正我已經決定了，你說什麼都沒用。","s":"反正我已经决定了，你说什么都没用。","es":"De todos modos ya decidí; nada de lo que digas servirá.","en":"I've already decided anyway; nothing you say will help.","p":"fǎn zhèng wǒ yǐ jīng jué dìng le, nǐ shuō shén me dōu méi yòng."}]},{"id":"4-8-1","b":4,"l":8,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No solo: 不只","en":"不只 not merely, exceeding","ens":"不只 not merely, exceeding","tc":"不只……還／也……","sc":"不只……还／也……"},"d":{"es":"不只 A，還／也 B = no solo A, sino también B. La parte B añade algo más.","en":"不只 A, 還/也 B means 'not only A, but also B'; B adds something beyond A.","tc":"「不只 A，還／也 B」表示除了 A 以外，B 也是，範圍比 A 更大。","sc":"「不只 A，还／也 B」表示除了 A 以外，B 也是，范围比 A 更大。"},"ex":[{"c":"他不只會說中文，還會說日文。","s":"他不只会说中文，还会说日文。","es":"No solo habla chino, también habla japonés.","en":"He doesn't just speak Chinese; he speaks Japanese, too.","p":"tā bù zhǐ huì shuō zhōng wén, hái huì shuō rì wén."},{"c":"不只小孩喜歡這部電影，大人也很喜歡。","s":"不只小孩喜欢这部电影，大人也很喜欢。","es":"No solo a los niños les gusta esta película; a los adultos también.","en":"It's not only kids who like this movie; adults like it, too.","p":"bù zhǐ xiǎo hái xǐ huān zhè bù diàn yǐng, dà rén yě hěn xǐ huān."}]},{"id":"4-8-2","b":4,"l":8,"k":"","t":{"es":"Inevitable: 難免","en":"難免 inevitably, it is only natural that","ens":"难免 inevitably, it is only natural that","tc":"難免","sc":"难免"},"d":{"es":"難免 = es inevitable, es natural que. Se usa para algo que casi siempre pasa en esa situación.","en":"難免 means 'it's hard to avoid / it's only natural': something is very likely to happen in this situation.","tc":"「難免」表示在這種情況下，很容易發生某件事，幾乎無法避免。","sc":"「难免」表示在这种情况下，很容易发生某件事，几乎无法避免。"},"ex":[{"c":"剛開始學中文，難免會說錯。","s":"刚开始学中文，难免会说错。","es":"Al empezar a aprender chino es inevitable equivocarse al hablar.","en":"When you first start learning Chinese, it's inevitable that you'll make mistakes.","p":"gāng kāi shǐ xué zhōng wén, nán miǎn huì shuō cuò."},{"c":"第一次出國，難免會有點緊張。","s":"第一次出国，难免会有点紧张。","es":"La primera vez que se viaja al extranjero es normal estar un poco nervioso.","en":"Going abroad for the first time, it's natural to feel a bit nervous.","p":"dì yī cì chū guó, nán miǎn huì yǒu diǎn jǐn zhāng."}]},{"id":"4-8-3","b":4,"l":8,"k":"","t":{"es":"Eso sí: 倒是","en":"倒是 on the other hand","ens":"倒是 on the other hand","tc":"倒是","sc":"倒是"},"d":{"es":"倒是 = en cambio, eso sí. Introduce un contraste suave con lo anterior.","en":"倒是 introduces a mild contrast with what came before: 'but, on the other hand'.","tc":"「倒是」表示和前面說的有一點相反或不同，語氣比較輕，意思是「不過……卻……」。","sc":"「倒是」表示和前面说的有一点相反或不同，语气比较轻，意思是「不过……却……」。"},"ex":[{"c":"這家餐廳不大，東西倒是挺好吃的。","s":"这家餐厅不大，东西倒是挺好吃的。","es":"Este restaurante no es grande, pero la comida sí que es bastante rica.","en":"This restaurant isn't big, but the food is actually quite good.","p":"zhè jiā cān tīng bú dà, dōng xi dào shì tǐng hǎo chī de."},{"c":"他中文說得不太好，字倒是寫得很漂亮。","s":"他中文说得不太好，字倒是写得很漂亮。","es":"No habla muy bien chino, pero eso sí, escribe los caracteres muy bonito.","en":"His Chinese isn't great, but his handwriting is really beautiful.","p":"tā zhōng wén shuō de bú tài hǎo, zì dào shì xiě de hěn piào liàng."}]},{"id":"4-8-4","b":4,"l":8,"k":"","t":{"es":"Ahora sí: 這下子","en":"這下子 that being the case, as a consequence","ens":"这下子 that being the case, as a consequence","tc":"這下子","sc":"这下子"},"d":{"es":"這下子 = ahora sí, con esto. Señala la consecuencia de lo que acaba de ocurrir (buena o mala).","en":"這下子 means 'now, with this': it points to the consequence of what just happened, good or bad.","tc":"「這下子」表示因為剛才發生的事，產生了新的結果，可以是好事，也可以是壞事。","sc":"「这下子」表示因为刚才发生的事，产生了新的结果，可以是好事，也可以是坏事。"},"ex":[{"c":"鑰匙不見了，這下子麻煩了！","s":"钥匙不见了，这下子麻烦了！","es":"Se perdieron las llaves, ¡ahora sí estamos en problemas!","en":"The keys are lost, so now we're in trouble!","p":"yuè shi bú jiàn le, zhè xià zi má fán le!"},{"c":"他考上了，這下子爸媽可以放心了。","s":"他考上了，这下子爸妈可以放心了。","es":"Aprobó el examen; ahora sí sus papás pueden estar tranquilos.","en":"He got in, so now his parents can relax.","p":"tā kǎo shàng le, zhè xià zi bà mā kě yǐ fàng xīn le."}]},{"id":"4-8-5","b":4,"l":8,"k":"dirección movimiento direction movement 方向 趨向 complemento resultado potencial complement result potential 補語 結果補語 可能補語 dirección movimiento direction movement 方向 趋向 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Congeniar: V 得來／不來","en":"Verb Complement 來 personable","ens":"Verb Complement 来 personable","tc":"動詞＋得來／不來","sc":"动词＋得来／不来"},"d":{"es":"Verbo + 得來 / 不來 expresa si algo se lleva bien con uno: 合得來 (llevarse bien), 談得來 (conectar al conversar), 合不來 (no congeniar).","en":"Verb + 得來/不來 says whether you get along with someone or something suits you, as in 合得來, 談得來, 合不來.","tc":"「動詞＋得來／不來」表示跟某人或某件事合不合得上，例如「合得來」「談得來」「合不來」。","sc":"「动词＋得来／不来」表示跟某人或某件事合不合得上，例如「合得来」「谈得来」「合不来」。"},"ex":[{"c":"我跟新室友很談得來。","s":"我跟新室友很谈得来。","es":"Con mi nuevo compañero de cuarto conecto muy bien al conversar.","en":"I really click with my new roommate when we talk.","p":"wǒ gēn xīn shì yǒu hěn tán dé lái."},{"c":"他們兩個個性不同，合不來。","s":"他们两个个性不同，合不来。","es":"Esos dos tienen personalidades distintas y no congenian.","en":"The two of them have different personalities and don't get along.","p":"tā men liǎng ge gè xìng bù tóng, hé bù lái."}]},{"id":"4-8-6","b":4,"l":8,"k":"","t":{"es":"Cuánto más: 何況","en":"何況 let alone, no need to mention","ens":"何况 let alone, no need to mention","tc":"何況","sc":"何况"},"d":{"es":"何況 = y más aún, cuánto más. Para reforzar un argumento con un caso aún más claro.","en":"何況 strengthens an argument with an even clearer case: 'let alone', 'not to mention'.","tc":"「何況」用更明顯的例子來加強前面的說法，意思是「更不用說」「而且」。","sc":"「何况」用更明显的例子来加强前面的说法，意思是「更不用说」「而且」。"},"ex":[{"c":"連大人都搬不動，何況是小孩？","s":"连大人都搬不动，何况是小孩？","es":"Ni los adultos pueden moverlo, ¿cuánto menos un niño?","en":"Even adults can't move it, let alone a child.","p":"lián dà rén dōu bān bú dòng, hé kuàng shì xiǎo hái?"},{"c":"這麼近，何況天氣又好，我們走路去吧。","s":"这么近，何况天气又好，我们走路去吧。","es":"Está tan cerca y además hace buen tiempo; vayamos caminando.","en":"It's so close, and the weather is nice, too, so let's walk.","p":"zhè me jìn, hé kuàng tiān qì yòu hǎo, wǒ men zǒu lù qù ba."}]},{"id":"4-8-7","b":4,"l":8,"k":"","t":{"es":"De lo contrario: 否則","en":"否則 otherwise","ens":"否则 otherwise","tc":"否則","sc":"否则"},"d":{"es":"否則 = de lo contrario, si no. Introduce lo que pasará si no se cumple lo anterior.","en":"否則 means 'otherwise': if the previous condition isn't met, something bad will happen.","tc":"「否則」表示如果前面說的事沒有做到，就會有不好的結果，意思是「不然」。","sc":"「否则」表示如果前面说的事没有做到，就会有不好的结果，意思是「不然」。"},"ex":[{"c":"快一點，否則會趕不上火車。","s":"快一点，否则会赶不上火车。","es":"Date prisa; si no, perderemos el tren.","en":"Hurry up, or we'll miss the train.","p":"kuài yì diǎn, fǒu zé huì gǎn bú shàng huǒ chē."},{"c":"你要多休息，否則身體會受不了。","s":"你要多休息，否则身体会受不了。","es":"Tienes que descansar más; de lo contrario, tu cuerpo no lo resistirá.","en":"You need to rest more; otherwise your body won't be able to take it.","p":"nǐ yào duō xiū xí, fǒu zé shēn tǐ huì shòu bù liǎo."}]},{"id":"4-9-0","b":4,"l":9,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Considerar: 把A當做B","en":"把 A 當做 B to treat, take A as B","ens":"把 A 当做 B to treat, take A as B","tc":"把 A 當做 B","sc":"把 A 当做 B"},"d":{"es":"把 A 當做 B = tratar o considerar a A como B.","en":"把 A 當做 B means to treat or regard A as B.","tc":"「把 A 當做 B」表示把 A 看成 B，或用對待 B 的方式對待 A。","sc":"「把 A 当做 B」表示把 A 看成 B，或用对待 B 的方式对待 A。"},"ex":[{"c":"我把他當做自己的弟弟。","s":"我把他当做自己的弟弟。","es":"Lo considero como a mi propio hermano menor.","en":"I think of him as my own younger brother.","p":"wǒ bǎ tā dāng zuò zì jǐ de dì di."},{"c":"很多人把網路當做主要的資訊來源。","s":"很多人把网路当做主要的资讯来源。","es":"Mucha gente considera internet su principal fuente de información.","en":"Many people regard the internet as their main source of information.","p":"hěn duō rén bǎ wǎng lù dāng zuò zhǔ yào de zī xùn lái yuán."}]},{"id":"4-9-1","b":4,"l":9,"k":"","t":{"es":"Bajo, con: 在…下","en":"在…下 under the…, due to the…","ens":"在…下 under the…, due to the…","tc":"在……下","sc":"在……下"},"d":{"es":"在…下 = bajo, con (condición, ayuda o circunstancia): 在…的幫助下, 在這種情況下.","en":"在…下 means 'under / with' a condition, help or circumstance, as in 在…的幫助下 and 在這種情況下.","tc":"「在……下」表示在某種條件、幫助或情況之下，例如「在……的幫助下」「在這種情況下」。","sc":"「在……下」表示在某种条件、帮助或情况之下，例如「在……的帮助下」「在这种情况下」。"},"ex":[{"c":"在朋友的幫助下，我找到了工作。","s":"在朋友的帮助下，我找到了工作。","es":"Con la ayuda de un amigo, encontré trabajo.","en":"With a friend's help, I found a job.","p":"zài péng yǒu de bāng zhù xià, wǒ zhǎo dào le gōng zuò."},{"c":"在這樣的天氣下，比賽還是照常舉行。","s":"在这样的天气下，比赛还是照常举行。","es":"Aun con este clima, el partido se celebra como de costumbre.","en":"Even in this weather, the game is going ahead as usual.","p":"zài zhè yàng de tiān qì xià, bǐ sài hái shì zhào cháng jǔ xíng."}]},{"id":"4-9-2","b":4,"l":9,"k":"","t":{"es":"Usos de 該","en":"The Various Functions of 該","ens":"The Various Functions of 该","tc":"「該」的各種用法","sc":"「该」的各种用法"},"d":{"es":"該 tiene varios usos: «deber» (我該走了), «ya es hora de…» (該…了), y en lenguaje escrito «dicho, el mencionado» (該公司).","en":"該 can mean 'should' (我該走了), 'it's time to…' (該…了), and in written language 'the said / that' (該公司).","tc":"「該」可以表示「應該」（我該走了）、「到了該做某事的時候」（該……了），書面語裡也可以指前面提過的人或事，意思是「這個、那個」（該公司）。","sc":"「该」可以表示「应该」（我该走了）、「到了该做某事的时候」（该……了），书面语里也可以指前面提过的人或事，意思是「这个、那个」（该公司）。"},"ex":[{"c":"太晚了，我該回家了。","s":"太晚了，我该回家了。","es":"Es muy tarde, ya debo irme a casa.","en":"It's too late; I should head home now.","p":"tài wǎn le, wǒ gāi huí jiā le."},{"c":"該公司成立於一九八〇年。","s":"该公司成立于一九八〇年。","es":"Dicha empresa fue fundada en 1980.","en":"The said company was founded in 1980.","p":"gāi gōng sī chéng lì yú yī jiǔ bā líng nián."}]},{"id":"4-9-3","b":4,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 tiempo momento orden secuencia time order sequence 时间 顺序 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Desde que: 自從…以後","en":"自從…以後 ever since...","ens":"自从…以后 ever since...","tc":"自從……以後","sc":"自从……以后"},"d":{"es":"自從 + tiempo + 以後 = desde que…; la situación empieza en ese momento y continúa hasta ahora.","en":"自從…以後 means 'ever since': a situation starts at some point and has continued until now.","tc":"「自從……以後」表示從某個時間開始，到現在一直是同樣的情況。","sc":"「自从……以后」表示从某个时间开始，到现在一直是同样的情况。"},"ex":[{"c":"自從搬到台北以後，我就很少回老家了。","s":"自从搬到台北以后，我就很少回老家了。","es":"Desde que me mudé a Taipéi, rara vez vuelvo a mi pueblo.","en":"Since I moved to Taipei, I rarely go back to my hometown.","p":"zì cóng bān dào tái běi yǐ hòu, wǒ jiù hěn shǎo huí lǎo jiā le."},{"c":"自從學了中文以後，他交了很多新朋友。","s":"自从学了中文以后，他交了很多新朋友。","es":"Desde que estudió chino, ha hecho muchos amigos nuevos.","en":"Since he started studying Chinese, he has made a lot of new friends.","p":"zì cóng xué le zhōng wén yǐ hòu, tā jiāo le hěn duō xīn péng yǒu."}]},{"id":"4-9-4","b":4,"l":9,"k":"","t":{"es":"Usos de 幾","en":"Summary of the Various Usages of 幾","ens":"Summary of the Various Usages of 几","tc":"「幾」的各種用法","sc":"「几」的各种用法"},"d":{"es":"幾 pregunta «cuántos» (números pequeños), significa «unos cuantos» (幾天) y, tras un número, «y tantos» (十幾個). 好幾 = bastantes.","en":"幾 asks 'how many' (small numbers), means 'a few' (幾天), means 'and some' after a number (十幾個), and 好幾 means 'quite a lot'.","tc":"「幾」可以問「多少」（你要幾個？）、表示不多的數量（幾天），放在數字後面表示零頭（十幾個），「好幾」表示相當多。","sc":"「几」可以问「多少」（你要几个？）、表示不多的数量（几天），放在数字后面表示零头（十几个），「好几」表示相当多。"},"ex":[{"c":"你要買幾個？","s":"你要买几个？","es":"¿Cuántos quieres comprar?","en":"How many do you want to buy?","p":"nǐ yào mǎi jǐ ge?"},{"c":"我已經等了好幾個小時了。","s":"我已经等了好几个小时了。","es":"Ya llevo esperando bastantes horas.","en":"I've been waiting for quite a few hours already.","p":"wǒ yǐ jīng děng le hǎo jǐ ge xiǎo shí le."}]},{"id":"4-9-5","b":4,"l":9,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No poder evitar: 不禁","en":"不禁 uncontrollably, cannot help but…","ens":"不禁 uncontrollably, cannot help but…","tc":"不禁","sc":"不禁"},"d":{"es":"不禁 + verbo = no poder evitar hacer algo (una reacción involuntaria).","en":"不禁 means 'can't help (doing something)': an involuntary, natural reaction.","tc":"「不禁」表示忍不住做某個動作，是自然、不自覺的反應。","sc":"「不禁」表示忍不住做某个动作，是自然、不自觉的反应。"},"ex":[{"c":"聽到這個好消息，我不禁笑了出來。","s":"听到这个好消息，我不禁笑了出来。","es":"Al oír la buena noticia no pude evitar reírme.","en":"Hearing the good news, I couldn't help laughing.","p":"tīng dào zhè ge hǎo xiāo xí, wǒ bú jìn xiào le chū lái."},{"c":"看到老朋友的照片，他不禁想起了以前的日子。","s":"看到老朋友的照片，他不禁想起了以前的日子。","es":"Al ver la foto de un viejo amigo, no pudo evitar recordar los viejos tiempos.","en":"Seeing a photo of an old friend, he couldn't help remembering the old days.","p":"kàn dào lǎo péng yǒu de zhào piàn, tā bú jìn xiǎng qǐ le yǐ qián de rì zi."}]},{"id":"4-9-6","b":4,"l":9,"k":"","t":{"es":"Todavía: 仍然","en":"仍然 still the same, same as before","ens":"仍然 still the same, same as before","tc":"仍然","sc":"仍然"},"d":{"es":"仍然 = todavía, aun así. La situación no cambia a pesar del tiempo o de las circunstancias.","en":"仍然 means 'still / even so': the situation stays the same despite time or circumstances.","tc":"「仍然」表示經過一段時間或有了變化，情況還是和以前一樣。","sc":"「仍然」表示经过一段时间或有了变化，情况还是和以前一样。"},"ex":[{"c":"過了十年，他仍然住在同一個地方。","s":"过了十年，他仍然住在同一个地方。","es":"Pasaron diez años y él sigue viviendo en el mismo lugar.","en":"Ten years have passed and he still lives in the same place.","p":"guò le shí nián, tā réng rán zhù zài tóng yí ge dì fāng."},{"c":"雖然很累，他仍然堅持把工作做完。","s":"虽然很累，他仍然坚持把工作做完。","es":"Aunque estaba muy cansado, insistió en terminar el trabajo.","en":"Although he was tired, he still insisted on finishing the work.","p":"suī rán hěn lèi, tā réng rán jiān chí bǎ gōng zuò zuò wán."}]},{"id":"4-9-7","b":4,"l":9,"k":"","t":{"es":"En realidad: 究竟","en":"究竟 I wonder","ens":"究竟 I wonder","tc":"究竟","sc":"究竟"},"d":{"es":"究竟 = en realidad, a fin de cuentas. Se usa en preguntas para insistir en la respuesta; es más formal que 到底.","en":"究竟 is used in questions to press for the real answer: 'on earth, exactly'. It's more formal than 到底.","tc":"「究竟」用在疑問句裡，追問真正的答案，意思是「到底」，語氣比「到底」正式。","sc":"「究竟」用在疑问句里，追问真正的答案，意思是「到底」，语气比「到底」正式。"},"ex":[{"c":"你究竟想不想去？","s":"你究竟想不想去？","es":"¿En realidad quieres ir o no?","en":"Do you actually want to go or not?","p":"nǐ jiù jìng xiǎng bù xiǎng qù?"},{"c":"這件事究竟是誰的錯？","s":"这件事究竟是谁的错？","es":"¿De quién es la culpa de esto, a fin de cuentas?","en":"Whose fault is this, in the end?","p":"zhè jiàn shì jiù jìng shì shéi de cuò?"}]},{"id":"4-10-0","b":4,"l":10,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Usos de 著","en":"Summary of the Various Functions of 著","ens":"Summary of the Various Functions of 着","tc":"「著」的各種用法","sc":"「着」的各种用法"},"d":{"es":"著 marca un estado que continúa (牆上掛著畫), la manera en que se hace una acción (笑著說) y también una acción de fondo que sigue en curso.","en":"著 can mark a continuing state (牆上掛著畫), the manner of an action (笑著說), or an ongoing background action.","tc":"「著」可以表示狀態持續（牆上掛著畫）、動作的方式（笑著說），也可以表示背景動作正在進行。","sc":"「着」可以表示状态持续（墙上挂着画）、动作的方式（笑着说），也可以表示背景动作正在进行。"},"ex":[{"c":"牆上掛著一幅畫。","s":"墙上挂着一幅画。","es":"En la pared hay colgado un cuadro.","en":"There's a painting hanging on the wall.","p":"qiáng shàng guà zhe yì fú huà."},{"c":"他笑著對我說：「謝謝！」","s":"他笑着对我说：「谢谢！」","es":"Me dijo sonriendo: «¡Gracias!».","en":"He said to me with a smile, 'Thank you!'","p":"tā xiào zhe duì wǒ shuō: 「xiè xiè!」"}]},{"id":"4-10-1","b":4,"l":10,"k":"","t":{"es":"Usos de 中","en":"The Various Meanings of 中","ens":"The Various Meanings of 中","tc":"「中」的各種意思","sc":"「中」的各种意思"},"d":{"es":"中 (zhōng) = en, durante, dentro de; indica algo en proceso (討論中). Leído zhòng significa «acertar, ganar» (中獎).","en":"中 (zhōng) means 'in / during', showing something is in progress (討論中). Read zhòng, it means 'to hit / win' (中獎).","tc":"「中」（ㄓㄨㄥ）表示在某個範圍或過程裡，例如「討論中」；讀成ㄓㄨㄥˋ時是「打中、得到」的意思，例如「中獎」。","sc":"「中」（ㄓㄨㄥ）表示在某个范围或过程里，例如「讨论中」；读成ㄓㄨㄥˋ时是「打中、得到」的意思，例如「中奖」。"},"ex":[{"c":"這個問題還在討論中。","s":"这个问题还在讨论中。","es":"Este asunto todavía está en discusión.","en":"This issue is still under discussion.","p":"zhè ge wèn tí hái zài tǎo lùn zhōng."},{"c":"他中了大獎，高興得跳起來。","s":"他中了大奖，高兴得跳起来。","es":"Ganó el premio mayor y saltó de alegría.","en":"He won the jackpot and jumped for joy.","p":"tā zhōng le dà jiǎng, gāo xìng de tiào qǐ lái."}]},{"id":"4-10-2","b":4,"l":10,"k":"","t":{"es":"Parece que: 似乎","en":"似乎 it seems that, it gives somebody the impression that","ens":"似乎 it seems that, it gives somebody the impression that","tc":"似乎","sc":"似乎"},"d":{"es":"似乎 = parece que. Expresa una impresión o suposición, con tono algo más formal que 好像.","en":"似乎 means 'it seems that': an impression or guess based on what you see or hear, a bit more formal than 好像.","tc":"「似乎」表示根據看到或聽到的情況，覺得好像是這樣，語氣比「好像」稍微正式。","sc":"「似乎」表示根据看到或听到的情况，觉得好像是这样，语气比「好像」稍微正式。"},"ex":[{"c":"他似乎不太高興。","s":"他似乎不太高兴。","es":"Parece que no está muy contento.","en":"He doesn't seem very happy.","p":"tā sì hū bú tài gāo xìng."},{"c":"天氣似乎快要變了。","s":"天气似乎快要变了。","es":"Parece que el clima está por cambiar.","en":"It looks like the weather is about to change.","p":"tiān qì sì hū kuài yào biàn le."}]},{"id":"4-10-3","b":4,"l":10,"k":"","t":{"es":"«Con» formal: 以","en":"Classical Chinese Preposition 以","ens":"Classical Chinese Preposition 以","tc":"書面語介詞「以」","sc":"书面语介词「以」"},"d":{"es":"以 es una preposición de lengua escrita: «con, por medio de». Se ve en 以…為…, 以電話, 以免.","en":"以 is a written-language preposition meaning 'with / by means of', seen in 以…為…, 以電話, 以免.","tc":"「以」是書面語的介詞，意思是「用、憑」，常見於「以……為……」「以電話」「以免」等。","sc":"「以」是书面语的介词，意思是「用、凭」，常见于「以……为……」「以电话」「以免」等。"},"ex":[{"c":"請以電子郵件與我們聯絡。","s":"请以电子邮件与我们联络。","es":"Por favor, contáctenos por correo electrónico.","en":"Please contact us by email.","p":"qǐng yǐ diàn zǐ yóu jiàn yǔ wǒ men lián luò."},{"c":"他以流利的中文介紹了自己。","s":"他以流利的中文介绍了自己。","es":"Se presentó en un chino fluido.","en":"He introduced himself in fluent Chinese.","p":"tā yǐ liú lì de zhōng wén jiè shào le zì jǐ."}]},{"id":"4-10-4","b":4,"l":10,"k":"","t":{"es":"Tener madera: 是…的料","en":"是…的料 to be gifted in…","ens":"是…的料 to be gifted in…","tc":"是……的料","sc":"是……的料"},"d":{"es":"是…的料 = tener madera para, estar hecho para algo (un talento natural). Se usa más en la negación: 不是…的料.","en":"是…的料 means 'cut out for…': a natural talent for something, most often used negatively as 不是…的料.","tc":"「是……的料」表示天生適合做某件事，常用否定形式「不是……的料」。","sc":"「是……的料」表示天生适合做某件事，常用否定形式「不是……的料」。"},"ex":[{"c":"他不是念書的料，可是很會畫畫。","s":"他不是念书的料，可是很会画画。","es":"No tiene madera para estudiar, pero dibuja muy bien.","en":"He's not cut out for studying, but he draws very well.","p":"tā bú shì niàn shū de liào, kě shì hěn huì huà huà."},{"c":"你天生就是當老師的料。","s":"你天生就是当老师的料。","es":"Naciste para ser profesor.","en":"You were born to be a teacher.","p":"nǐ tiān shēng jiù shì dāng lǎo shī de liào."}]},{"id":"4-10-5","b":4,"l":10,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Usos de 下去","en":"Summary of 下去","ens":"Summary of 下去","tc":"「下去」的各種用法","sc":"「下去」的各种用法"},"d":{"es":"下去 después de un verbo puede significar: ir hacia abajo (走下去), seguir haciendo algo (做下去) y, en negativo, no poder continuar (撐不下去).","en":"下去 after a verb can mean going down (走下去), continuing (做下去), or, in the negative, being unable to carry on (撐不下去).","tc":"動詞後面的「下去」可以表示往下走（走下去）、繼續做下去（做下去），否定時表示沒辦法再繼續（撐不下去）。","sc":"动词后面的「下去」可以表示往下走（走下去）、继续做下去（做下去），否定时表示没办法再继续（撑不下去）。"},"ex":[{"c":"他從樓梯走下去了。","s":"他从楼梯走下去了。","es":"Bajó por las escaleras.","en":"He went down the stairs.","p":"tā cóng lóu tī zǒu xià qù le."},{"c":"這個工作太累了，我做不下去了。","s":"这个工作太累了，我做不下去了。","es":"Este trabajo es muy agotador; no puedo seguir con él.","en":"This job is too tiring; I can't keep doing it.","p":"zhè ge gōng zuò tài lèi le, wǒ zuò bú xià qù le."}]},{"id":"4-10-6","b":4,"l":10,"k":"","t":{"es":"«Desde» formal: 自","en":"自 from (formal)","ens":"自 from (formal)","tc":"書面語「自」","sc":"书面语「自」"},"d":{"es":"自 = desde (lengua escrita o formal): 自古以來, 自…起. Equivale a 從 en un registro más formal.","en":"自 is a formal, written word meaning 'from / since', as in 自古以來 and 自…起.","tc":"「自」是書面語，意思是「從」，常見於「自古以來」「自……起」。","sc":"「自」是书面语，意思是「从」，常见于「自古以来」「自……起」。"},"ex":[{"c":"這個習俗自古流傳至今。","s":"这个习俗自古流传至今。","es":"Esta costumbre se ha transmitido desde la antigüedad hasta hoy.","en":"This custom has been passed down from ancient times to the present.","p":"zhè ge xí sú zì gǔ liú chuán zhì jīn."},{"c":"本店自五月一日起調整營業時間。","s":"本店自五月一日起调整营业时间。","es":"A partir del 1 de mayo esta tienda cambia su horario.","en":"Starting May 1, this shop is changing its business hours.","p":"běn diàn zì wǔ yuè yí rì qǐ tiáo zhěng yíng yè shí jiān."}]},{"id":"4-11-0","b":4,"l":11,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Justo cuando: 偏偏","en":"偏偏 contrary to expectation, against the speaker’s wish, annoyingly","ens":"偏偏 contrary to expectation, against the speaker’s wish, annoyingly","tc":"偏偏","sc":"偏偏"},"d":{"es":"偏偏 = justo, precisamente (contra lo que se desea). Se usa para algo molesto o contrario a la voluntad de alguien.","en":"偏偏 means 'of all things / just when': things turn out contrary to what's wanted, or someone stubbornly does the opposite, often with an annoyed tone.","tc":"「偏偏」表示事情剛好跟希望的相反，或故意跟別人的意見相反，常有一點不高興或無奈的語氣。","sc":"「偏偏」表示事情刚好跟希望的相反，或故意跟别人的意见相反，常有一点不高兴或无奈的语气。"},"ex":[{"c":"我正要出門，偏偏下起雨來了。","s":"我正要出门，偏偏下起雨来了。","es":"Justo cuando iba a salir, se puso a llover.","en":"Just as I was about to go out, it started raining.","p":"wǒ zhèng yào chū mén, piān piān xià qǐ yǔ lái le."},{"c":"大家都說不要去，他偏偏要去。","s":"大家都说不要去，他偏偏要去。","es":"Todos dijeron que no fuera, pero él se empeñó en ir.","en":"Everyone told him not to go, but he insisted on going.","p":"dà jiā dōu shuō bú yào qù, tā piān piān yào qù."}]},{"id":"4-11-1","b":4,"l":11,"k":"","t":{"es":"Como siempre: 照","en":"照 persist","ens":"照 persist","tc":"照（照樣、照常）","sc":"照（照样、照常）"},"d":{"es":"照 + verbo (照樣, 照常) = hacer lo mismo que antes, a pesar del cambio o del obstáculo.","en":"照 + verb (照樣, 照常) means to carry on as before regardless of changes or obstacles.","tc":"「照」加動詞（照樣、照常）表示不管情況有沒有改變，還是照以前的方式做。","sc":"「照」加动词（照样、照常）表示不管情况有没有改变，还是照以前的方式做。"},"ex":[{"c":"下雨也照常上課。","s":"下雨也照常上课。","es":"Aunque llueva, la clase se da como siempre.","en":"Class goes on as usual even when it rains.","p":"xià yǔ yě zhào cháng shàng kè."},{"c":"他被罵了，可是還是照樣遲到。","s":"他被骂了，可是还是照样迟到。","es":"Lo regañaron, pero igual llegó tarde como siempre.","en":"He got scolded, but he still showed up late as usual.","p":"tā bèi mà le, kě shì hái shì zhào yàng chí dào."}]},{"id":"4-11-2","b":4,"l":11,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Raro: 難得","en":"難得 rarely","ens":"难得 rarely","tc":"難得","sc":"难得"},"d":{"es":"難得 = raro, poco frecuente; algo que no ocurre a menudo y por eso se valora. También es adjetivo: «valioso».","en":"難得 means 'rare / seldom': something that doesn't happen often and is therefore valued. It can also be an adjective meaning 'precious'.","tc":"「難得」表示不常有、很少發生，所以特別可貴。也可以當形容詞，意思是「珍貴」。","sc":"「难得」表示不常有、很少发生，所以特别可贵。也可以当形容词，意思是「珍贵」。"},"ex":[{"c":"今天難得有空，我們出去走走吧。","s":"今天难得有空，我们出去走走吧。","es":"Hoy por fin tengo tiempo libre, salgamos a pasear.","en":"For once I have some free time today; let's go for a walk.","p":"jīn tiān nán dé yǒu kòng, wǒ men chū qù zǒu zǒu ba."},{"c":"這麼好的機會很難得，不要錯過。","s":"这么好的机会很难得，不要错过。","es":"Una oportunidad así es poco común; no la dejes pasar.","en":"An opportunity this good is rare; don't miss it.","p":"zhè me hǎo de jī huì hěn nán dé, bú yào cuò guò."}]},{"id":"4-11-3","b":4,"l":11,"k":"","t":{"es":"En ratos libres: 在…之餘","en":"在…之餘 while not otherwise engaged in …, apart from…","ens":"在…之余 while not otherwise engaged in …, apart from…","tc":"在……之餘","sc":"在……之余"},"d":{"es":"在…之餘 = además de / en los ratos libres de (una actividad principal), también se hace otra cosa.","en":"在…之餘 means 'in the time left over from (a main activity)': besides the main thing, you also did something else.","tc":"「在……之餘」表示除了主要的事以外，在剩下的時間裡還做了別的事。","sc":"「在……之余」表示除了主要的事以外，在剩下的时间里还做了别的事。"},"ex":[{"c":"在工作之餘，他學會了彈吉他。","s":"在工作之余，他学会了弹吉他。","es":"En sus ratos libres del trabajo, aprendió a tocar la guitarra.","en":"In his spare time from work, he learned to play the guitar.","p":"zài gōng zuò zhī yú, tā xué huì le tán jí tā."},{"c":"在忙碌之餘，也要記得多休息。","s":"在忙碌之余，也要记得多休息。","es":"Aun con mucho trabajo, recuerda descansar.","en":"Even when you're busy, remember to rest more.","p":"zài máng lù zhī yú, yě yào jì dé duō xiū xí."}]},{"id":"4-11-4","b":4,"l":11,"k":"","t":{"es":"Difícil de: 難以","en":"難以 to find it difficult to…","ens":"难以 to find it difficult to…","tc":"難以","sc":"难以"},"d":{"es":"難以 + verbo = difícil de…. Es formal y se usa con verbos de dos sílabas: 難以相信, 難以想像.","en":"難以 + verb means 'difficult to…'. It is formal and usually pairs with two-syllable verbs, as in 難以相信 and 難以想像.","tc":"「難以」加動詞表示很難做到，語氣正式，常搭配雙音節動詞，例如「難以相信」「難以想像」。","sc":"「难以」加动词表示很难做到，语气正式，常搭配双音节动词，例如「难以相信」「难以想像」。"},"ex":[{"c":"這種感覺難以用言語形容。","s":"这种感觉难以用言语形容。","es":"Este sentimiento es difícil de describir con palabras.","en":"This feeling is hard to put into words.","p":"zhè zhǒng gǎn jué nán yǐ yòng yán yǔ xíng róng."},{"c":"他的話讓人難以相信。","s":"他的话让人难以相信。","es":"Sus palabras son difíciles de creer.","en":"His words are hard to believe.","p":"tā de huà ràng rén nán yǐ xiāng xìn."}]},{"id":"4-11-5","b":4,"l":11,"k":"","t":{"es":"Poco a poco: 漸漸","en":"漸漸 gradually, slowly","ens":"渐渐 gradually, slowly","tc":"漸漸","sc":"渐渐"},"d":{"es":"漸漸 = poco a poco, gradualmente. Describe un cambio lento que va avanzando.","en":"漸漸 means 'gradually': a change happens slowly, step by step.","tc":"「漸漸」表示變化慢慢地、一步一步地發生，意思是「慢慢地」。","sc":"「渐渐」表示变化慢慢地、一步一步地发生，意思是「慢慢地」。"},"ex":[{"c":"天氣漸漸變冷了。","s":"天气渐渐变冷了。","es":"El clima se está poniendo frío poco a poco.","en":"The weather is gradually getting colder.","p":"tiān qì jiàn jiàn biàn lěng le."},{"c":"住久了，我漸漸習慣了這裡的生活。","s":"住久了，我渐渐习惯了这里的生活。","es":"Con el tiempo me fui acostumbrando a la vida aquí.","en":"After living here a while, I gradually got used to life here.","p":"zhù jiǔ le, wǒ jiàn jiàn xí guàn le zhè lǐ de shēng huó."}]},{"id":"4-11-6","b":4,"l":11,"k":"","t":{"es":"Se ve que: 可見","en":"可見 It can thus be concluded that…","ens":"可见 It can thus be concluded that…","tc":"可見","sc":"可见"},"d":{"es":"可見 = se puede ver que, esto demuestra que. Saca una conclusión a partir de lo anterior.","en":"可見 means 'it can be seen that': you draw a conclusion from the facts just mentioned.","tc":"「可見」表示從前面的事實可以得到一個結論，意思是「由此可知」。","sc":"「可见」表示从前面的事实可以得到一个结论，意思是「由此可知」。"},"ex":[{"c":"他每天練習三個小時，可見他有多認真。","s":"他每天练习三个小时，可见他有多认真。","es":"Practica tres horas al día; eso demuestra lo aplicado que es.","en":"He practices three hours every day, which shows how dedicated he is.","p":"tā měi tiān liàn xí sān ge xiǎo shí, kě jiàn tā yǒu duō rèn zhēn."},{"c":"這家店天天大排長龍，可見很受歡迎。","s":"这家店天天大排长龙，可见很受欢迎。","es":"Esta tienda tiene fila larga todos los días; se ve que es muy popular.","en":"This shop has a long line every day, so clearly it's very popular.","p":"zhè jiā diàn tiān tiān dà pái cháng lóng, kě jiàn hěn shòu huān yíng."}]},{"id":"4-11-7","b":4,"l":11,"k":"","t":{"es":"Para X: 對於…而言","en":"對於…而言 as far as… is concerned","ens":"对于…而言 as far as… is concerned","tc":"對於……而言","sc":"对于……而言"},"d":{"es":"對於 X 而言 = para X, en lo que se refiere a X. Es la forma más formal de 對 X 來說.","en":"對於 X 而言 means 'as far as X is concerned': a more formal version of 對 X 來說.","tc":"「對於 X 而言」表示從 X 的角度來看，是「對 X 來說」的比較正式說法。","sc":"「对于 X 而言」表示从 X 的角度来看，是「对 X 来说」的比较正式说法。"},"ex":[{"c":"對於初學者而言，聲調是最難的部分。","s":"对于初学者而言，声调是最难的部分。","es":"Para los principiantes, los tonos son la parte más difícil.","en":"For beginners, the tones are the hardest part.","p":"duì yú chū xué zhě ér yán, shēng diào shì zuì nán de bù fēn."},{"c":"對於很多人而言，健康比賺錢更重要。","s":"对于很多人而言，健康比赚钱更重要。","es":"Para mucha gente, la salud es más importante que ganar dinero.","en":"For many people, health is more important than making money.","p":"duì yú hěn duō rén ér yán, jiàn kāng bǐ zhuàn qián gèng zhòng yào."}]},{"id":"4-12-0","b":4,"l":12,"k":"","t":{"es":"Da igual: 無所謂","en":"無所謂 does not matter","ens":"无所谓 does not matter","tc":"無所謂","sc":"无所谓"},"d":{"es":"無所謂 = da igual, no importa. Se dice cuando a uno le es indiferente la opción.","en":"無所謂 means 'it doesn't matter / I don't mind': you're indifferent to the choice.","tc":"「無所謂」表示怎麼樣都可以，不在意，沒有特別的意見。","sc":"「无所谓」表示怎么样都可以，不在意，没有特别的意见。"},"ex":[{"c":"吃什麼我都無所謂。","s":"吃什么我都无所谓。","es":"Me da igual qué comer.","en":"I don't mind what we eat.","p":"chī shén me wǒ dōu wú suǒ wèi."},{"c":"對他來說，輸贏無所謂。","s":"对他来说，输赢无所谓。","es":"Para él, ganar o perder no importa.","en":"For him, winning or losing doesn't matter.","p":"duì tā lái shuō, shū yíng wú suǒ wèi."}]},{"id":"4-12-1","b":4,"l":12,"k":"","t":{"es":"¿Quién iba a decir?: 誰知道","en":"誰知道 who would have thought…?","ens":"谁知道 who would have thought…?","tc":"誰知道","sc":"谁知道"},"d":{"es":"誰知道 = ¿quién iba a pensar…? (algo inesperado después de lo planeado). También puede significar «quién sabe».","en":"誰知道 means 'who would have thought': something unexpected happens after the plan. It can also mean 'who knows'.","tc":"「誰知道」表示出乎意料，常用在原本的計畫之後，意思是「沒想到」。也可以表示「不知道」。","sc":"「谁知道」表示出乎意料，常用在原本的计划之后，意思是「没想到」。也可以表示「不知道」。"},"ex":[{"c":"本來想去爬山，誰知道突然下起大雨。","s":"本来想去爬山，谁知道突然下起大雨。","es":"Pensábamos ir a la montaña, pero quién iba a decir que de repente llovería a cántaros.","en":"We meant to go hiking, but who would have thought it would suddenly pour.","p":"běn lái xiǎng qù pá shān, shéi zhī dào tú rán xià qǐ dà yǔ."},{"c":"誰知道他到底在想什麼？","s":"谁知道他到底在想什么？","es":"¿Quién sabe qué estará pensando en realidad?","en":"Who knows what he's really thinking?","p":"shéi zhī dào tā dào dǐ zài xiǎng shén me?"}]},{"id":"4-12-2","b":4,"l":12,"k":"","t":{"es":"De A hasta B: 小自…大至…","en":"小自…大至… everything from A to Z","ens":"小自…大至… everything from A to Z","tc":"小自……大至……","sc":"小自……大至……"},"d":{"es":"小自 A，大至 B = desde A (lo más pequeño) hasta B (lo más grande): abarca todo el rango.","en":"小自 A, 大至 B means 'from the smallest A to the biggest B': it covers the whole range.","tc":"「小自 A，大至 B」表示範圍很廣，從最小的 A 到最大的 B 都包括在內。","sc":"「小自 A，大至 B」表示范围很广，从最小的 A 到最大的 B 都包括在内。"},"ex":[{"c":"小自一杯咖啡，大至一棟房子，網路上什麼都買得到。","s":"小自一杯咖啡，大至一栋房子，网路上什么都买得到。","es":"Desde un café hasta una casa, en internet se puede comprar de todo.","en":"From a cup of coffee to a house, you can buy anything online.","p":"xiǎo zì yì bēi kā fēi, dà zhì yí dòng fáng zi, wǎng lù shàng shén me dōu mǎi dé dào."},{"c":"小自個人生活，大至國家大事，他都有自己的看法。","s":"小自个人生活，大至国家大事，他都有自己的看法。","es":"Desde la vida personal hasta los asuntos del país, tiene su propia opinión de todo.","en":"From personal life to affairs of state, he has his own opinion on everything.","p":"xiǎo zì gè rén shēng huó, dà zhì guó jiā dà shì, tā dōu yǒu zì jǐ de kàn fǎ."}]},{"id":"4-12-3","b":4,"l":12,"k":"","t":{"es":"¡Increíble!: 竟然","en":"竟然 to the speaker’s great surprise","ens":"竟然 to the speaker’s great surprise","tc":"竟然","sc":"竟然"},"d":{"es":"竟然 = ¡increíblemente!, ¡quién lo diría! Expresa gran sorpresa del hablante ante algo inesperado.","en":"竟然 expresses the speaker's great surprise that something turned out unexpectedly.","tc":"「竟然」表示說話的人覺得很意外，沒想到事情會這樣。","sc":"「竟然」表示说话的人觉得很意外，没想到事情会这样。"},"ex":[{"c":"他竟然沒有告訴我就搬家了。","s":"他竟然没有告诉我就搬家了。","es":"¡Increíble, se mudó sin decirme nada!","en":"Unbelievably, he moved without telling me.","p":"tā jìng rán méi yǒu gào sù wǒ jiù bān jiā le."},{"c":"這麼簡單的題目，他竟然答錯了。","s":"这么简单的题目，他竟然答错了。","es":"Una pregunta tan fácil, ¡y la respondió mal!","en":"Such an easy question, and he got it wrong!","p":"zhè me jiǎn dān de tí mù, tā jìng rán dá cuò le."}]},{"id":"4-12-4","b":4,"l":12,"k":"","t":{"es":"En teoría: 照理說","en":"照理說 normally","ens":"照理说 normally","tc":"照理說","sc":"照理说"},"d":{"es":"照理說 = en teoría, normalmente. Plantea lo que debería ser lo normal, y suele seguir un contraste.","en":"照理說 means 'normally / in theory': it states what should be the case, and is often followed by a contrast.","tc":"「照理說」表示依照一般的道理，事情應該是這樣，後面常常接著說實際上不是這樣。","sc":"「照理说」表示依照一般的道理，事情应该是这样，后面常常接着说实际上不是这样。"},"ex":[{"c":"照理說，他應該已經到了。","s":"照理说，他应该已经到了。","es":"En teoría, ya debería haber llegado.","en":"In theory, he should have arrived by now.","p":"zhào lǐ shuō, tā yīng gāi yǐ jīng dào le."},{"c":"照理說這個時間不會塞車，可是今天卻塞得很嚴重。","s":"照理说这个时间不会塞车，可是今天却塞得很严重。","es":"Normalmente a esta hora no hay tráfico, pero hoy hay mucho.","en":"Normally there's no traffic at this hour, but today it's really bad.","p":"zhào lǐ shuō zhè ge shí jiān bú huì sāi chē, kě shì jīn tiān què sāi dé hěn yán zhòng."}]},{"id":"4-12-5","b":4,"l":12,"k":"","t":{"es":"Tomar A como B: 以A為B","en":"以A為B to take A as B","ens":"以A为B to take A as B","tc":"以 A 為 B","sc":"以 A 为 B"},"d":{"es":"以 A 為 B = tomar A como B (como modelo, prioridad o base). Es formal.","en":"以 A 為 B means 'take A as B': as a model, priority or basis. It is formal.","tc":"「以 A 為 B」表示把 A 當作 B，例如當作榜樣、重點或基礎，語氣正式。","sc":"「以 A 为 B」表示把 A 当作 B，例如当作榜样、重点或基础，语气正式。"},"ex":[{"c":"這間公司以客戶為第一。","s":"这间公司以客户为第一。","es":"Esta empresa pone al cliente en primer lugar.","en":"This company puts customers first.","p":"zhè jiān gōng sī yǐ kè hù wéi dì yī."},{"c":"他以老師為榜樣，努力學習。","s":"他以老师为榜样，努力学习。","es":"Toma a su profesor como modelo y estudia con esfuerzo.","en":"He takes his teacher as a role model and studies hard.","p":"tā yǐ lǎo shī wéi bǎng yàng, nǔ lì xué xí."}]},{"id":"4-12-6","b":4,"l":12,"k":"","t":{"es":"No importa…: 無論…都…","en":"無論…都… regardless of what…","ens":"无论…都… regardless of what…","tc":"無論……都……","sc":"无论……都……"},"d":{"es":"無論…都… = no importa qué / cómo…, siempre…. Introduce una condición con varias opciones y el mismo resultado.","en":"無論…都… means 'no matter what/how…, always…': the result is the same in every case. 無論 is usually followed by a question word or choices.","tc":"「無論……都……」表示不管是哪一種情況，結果都一樣。「無論」後面通常有疑問詞或選擇。","sc":"「无论……都……」表示不管是哪一种情况，结果都一样。「无论」后面通常有疑问词或选择。"},"ex":[{"c":"無論天氣好不好，他都會去跑步。","s":"无论天气好不好，他都会去跑步。","es":"Haga buen tiempo o no, él siempre sale a correr.","en":"Whether the weather is good or not, he goes running.","p":"wú lùn tiān qì hǎo bù hǎo, tā dōu huì qù pǎo bù."},{"c":"無論你說什麼，我都不會改變主意。","s":"无论你说什么，我都不会改变主意。","es":"Digas lo que digas, no voy a cambiar de opinión.","en":"No matter what you say, I won't change my mind.","p":"wú lùn nǐ shuō shén me, wǒ dōu bú huì gǎi biàn zhǔ yì."}]},{"id":"4-12-7","b":4,"l":12,"k":"","t":{"es":"Claramente: 明明","en":"明明 It should be obvious to everyone that…","ens":"明明 It should be obvious to everyone that…","tc":"明明","sc":"明明"},"d":{"es":"明明 = claramente, a todas luces. Se usa cuando algo es obvio pero lo que se dice o hace lo contradice.","en":"明明 means 'obviously': the facts are clear, yet what is said or done contradicts them, often with a tone of blame or dissatisfaction.","tc":"「明明」表示事實很清楚，可是說的話或做的事卻和事實不一樣，常有責怪或不滿的語氣。","sc":"「明明」表示事实很清楚，可是说的话或做的事却和事实不一样，常有责怪或不满的语气。"},"ex":[{"c":"明明是你自己說要去的，現在怎麼又不去了？","s":"明明是你自己说要去的，现在怎么又不去了？","es":"Fuiste tú mismo quien dijo que iría, ¿cómo es que ahora no vas?","en":"You were the one who said you'd go; why aren't you going now?","p":"míng míng shì nǐ zì jǐ shuō yào qù de, xiàn zài zěn me yòu bú qù le?"},{"c":"他明明知道答案，卻假裝不知道。","s":"他明明知道答案，却假装不知道。","es":"Claramente sabe la respuesta, pero finge que no.","en":"He obviously knows the answer, but he pretends not to.","p":"tā míng míng zhī dào dá àn, què jiǎ zhuāng bù zhī dào."}]},{"id":"4-12-8","b":4,"l":12,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Hacer que: 使得","en":"Causation with 使得","ens":"Causation with 使得","tc":"使得","sc":"使得"},"d":{"es":"使得 = hacer que, provocar. Expresa que un hecho causa un resultado (suele ser un sujeto no humano).","en":"使得 means 'to cause / make': one event causes a result, and the subject is often not a person.","tc":"「使得」表示某件事造成了某個結果，主語常常不是人。","sc":"「使得」表示某件事造成了某个结果，主语常常不是人。"},"ex":[{"c":"這場大雨使得很多航班取消了。","s":"这场大雨使得很多航班取消了。","es":"Esta fuerte lluvia hizo que se cancelaran muchos vuelos.","en":"This heavy rain caused many flights to be canceled.","p":"zhè chǎng dà yǔ shǐ dé hěn duō háng bān qǔ xiāo le."},{"c":"網路的發展使得生活更方便。","s":"网路的发展使得生活更方便。","es":"El desarrollo de internet hizo la vida más cómoda.","en":"The development of the internet has made life more convenient.","p":"wǎng lù de fā zhǎn shǐ dé shēng huó gèng fāng biàn."}]},{"id":"5-1-0","b":5,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Incluso B no es la excepción","en":"Even B is no exception","ens":"Even B is no exception","tc":"A，即使是B也不例外","sc":"A，即使是B也不例外"},"d":{"es":"即使是 B 也不例外 = ni siquiera B es una excepción. Primero se afirma algo de A en general y luego se subraya que incluso el caso que se esperaría exento (B) cumple la misma regla. Registro algo formal.","en":"First state what holds for A in general, then stress that even B, the case you might expect to be exempt, is no different. More formal or written in tone.","tc":"先說 A 的一般情況，再強調連最特別、最容易被排除的 B 也一樣，沒有例外。多用在書面或正式的說明。","sc":"先说 A 的一般情况，再强调连最特别、最容易被排除的 B 也一样，没有例外。多用在书面或正式的说明。"},"ex":[{"c":"為了服務客戶，此公司員工幾乎沒有自己的假期，即使是過年也不例外。","s":"为了服务客户，此公司员工几乎没有自己的假期，即使是过年也不例外。","es":"Para atender a los clientes, los empleados de esta empresa casi no tienen vacaciones propias; ni siquiera en Año Nuevo es la excepción.","en":"To serve customers, employees of this company hardly have any time off of their own, and even the New Year holiday is no exception.","p":"wèi le fú wù kè hù, cǐ gōng sī yuán gōng jī hū méi yǒu zì jǐ de jià qí, jí shǐ shì guò nián yě bú lì wài."},{"c":"學校的規定對所有學生都一樣，即使是班長也不例外。","s":"学校的规定对所有学生都一样，即使是班长也不例外。","es":"El reglamento de la escuela es igual para todos los alumnos; ni siquiera el delegado de clase es la excepción.","en":"The school rules are the same for every student, and even the class monitor is no exception.","p":"xué xiào de guī dìng duì suǒ yǒu xué shēng dōu yí yàng, jí shǐ shì bān zhǎng yě bú lì wài."}]},{"id":"5-1-1","b":5,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Una vez que A, entonces B","en":"Once A happens, B follows","ens":"Once A happens, B follows","tc":"一旦A，（就/才) B","sc":"一旦A，（就/才) B"},"d":{"es":"一旦 = una vez que / en cuanto. A es una condición que, si llega a ocurrir, trae consigo una consecuencia importante B. B suele llevar 就 (más raro con 才). Registro escrito o formal; A suele ser algo que se quiere evitar o una decisión seria.","en":"一旦 means 'once' or 'the moment that'. A is a condition that, if it ever happens, brings a significant result B. B usually takes 就 (less commonly 才). Written or formal register.","tc":"「一旦」表示「一 A 發生，B 就會（可能）跟著發生」，A 通常是不容易發生、但一發生就會有大影響的情況。B 常搭配「就」，是書面、正式的說法。","sc":"「一旦」表示「一 A 发生，B 就会（可能）跟着发生」，A 通常是不容易发生、但一发生就会有大影响的情况。B 常搭配「就」，是书面、正式的说法。"},"ex":[{"c":"言論一旦太過自由，就可能發生網路霸凌。","s":"言论一旦太过自由，就可能发生网路霸凌。","es":"Una vez que la libertad de expresión se vuelve excesiva, puede surgir el acoso en línea.","en":"Once freedom of speech becomes too unrestricted, cyberbullying may well occur.","p":"yán lùn yí dàn tài guò zì yóu, jiù kě néng fā shēng wǎng lù bà líng."},{"c":"一旦下定決心，就不要輕易放棄。","s":"一旦下定决心，就不要轻易放弃。","es":"Una vez que tomas una decisión, no te rindas fácilmente.","en":"Once you have made up your mind, don't give up easily.","p":"yí dàn xià dìng jué xīn, jiù bú yào qīng yì fàng qì."}]},{"id":"5-1-2","b":5,"l":1,"k":"","t":{"es":"Hacer A solo por hacer A","en":"Doing A just for the sake of A","ens":"Doing A just for the sake of A","tc":"為A而A","sc":"为A而A"},"d":{"es":"為 A 而 A repite el mismo verbo (o palabra): hacer algo solo por hacerlo, sin una razón o un objetivo real (oponerse por oponerse, discutir por discutir). Suele llevar tono crítico.","en":"The same verb appears on both sides: doing something purely for the sake of doing it, with no real reason or goal. It usually carries a critical tone.","tc":"把同一個動詞放在「為」和「而」前後，表示只是為了做這件事而做，沒有真正的理由或目的。常帶批評的語氣。","sc":"把同一个动词放在「为」和「而」前后，表示只是为了做这件事而做，没有真正的理由或目的。常带批评的语气。"},"ex":[{"c":"他們只是為反對而反對，根本無法好好溝通。","s":"他们只是为反对而反对，根本无法好好沟通。","es":"Ellos solo se oponen por oponerse, así que es imposible comunicarse bien.","en":"They are just opposing for the sake of opposing, so there is simply no way to communicate properly.","p":"tā men zhǐ shì wéi fǎn duì ér fǎn duì, gēn běn wú fǎ hǎo hǎo gōu tōng."},{"c":"有些人為吵架而吵架，根本不想解決問題。","s":"有些人为吵架而吵架，根本不想解决问题。","es":"Algunas personas discuten por discutir y en realidad no quieren resolver el problema.","en":"Some people argue for the sake of arguing and don't actually want to solve the problem.","p":"yǒu xiē rén wéi chǎo jià ér chǎo jià, gēn běn bù xiǎng jiě jué wèn tí."}]},{"id":"5-1-3","b":5,"l":1,"k":"","t":{"es":"En realidad / de hecho","en":"In fact","ens":"In fact","tc":"事實上","sc":"事实上"},"d":{"es":"事實上 = en realidad, de hecho. Introduce lo que de verdad ocurre, a menudo corrigiendo o contradiciendo lo dicho antes. Suele ir al inicio de la oración, con frecuencia tras 但 o 可是, y seguido de coma.","en":"事實上 means 'in fact' or 'actually'. It introduces what is really the case, often correcting or contradicting what was just said. It usually opens a clause, often after 但/可是, followed by a comma.","tc":"引出與前面說法不同、或更接近真實情況的事，常放在「但」「可是」後面或句首，後面常有逗號。口語也能用，書面更常見。","sc":"引出与前面说法不同、或更接近真实情况的事，常放在「但」「可是」后面或句首，后面常有逗号。口语也能用，书面更常见。"},"ex":[{"c":"不少人認為公職福利好又穩定，但事實上，現在的情況已經不如以前了，許多福利早就都沒了。","s":"不少人认为公职福利好又稳定，但事实上，现在的情况已经不如以前了，许多福利早就都没了。","es":"Muchos piensan que los beneficios de los empleos públicos son buenos y estables, pero en realidad la situación ya no es como antes y muchos beneficios desaparecieron hace tiempo.","en":"Many people think public-sector jobs have good, stable benefits, but in fact things are no longer what they used to be, and many benefits are long gone.","p":"bù shǎo rén rèn wéi gōng zhí fú lì hǎo yòu wěn dìng, dàn shì shí shàng, xiàn zài de qíng kuàng yǐ jīng bù rú yǐ qián le, xǔ duō fú lì zǎo jiù dōu méi le."},{"c":"他看起來很有錢，事實上卻欠了很多債。","s":"他看起来很有钱，事实上却欠了很多债。","es":"Parece muy rico, pero en realidad tiene muchas deudas.","en":"He looks very rich, but in fact he is deep in debt.","p":"tā kàn qǐ lái hěn yǒu qián, shì shí shàng què qiàn le hěn duō zhài."}]},{"id":"5-1-4","b":5,"l":1,"k":"","t":{"es":"A se hace responsable de B","en":"A is responsible for B","ens":"A is responsible for B","tc":"A為B負責","sc":"A为B负责"},"d":{"es":"為 B 負責 = responsabilizarse de B, asumir la responsabilidad por B. B suele ser algo que A hizo, dijo o decidió. También se dice 對 B 負責 con un sentido muy parecido.","en":"為 B 負責 means to take responsibility for B; B is usually something A did, said or decided. 對 B 負責 is also possible with a very similar meaning.","tc":"「為 B 負責」表示對 B 這件事承擔責任，B 通常是自己做的事、說的話或決定。也可以說「對 B 負責」，意思很接近。","sc":"「为 B 负责」表示对 B 这件事承担责任，B 通常是自己做的事、说的话或决定。也可以说「对 B 负责」，意思很接近。"},"ex":[{"c":"汙染、教育、交通等問題都脫離不了政治，所以政府得為自己的政策負責。","s":"污染、教育、交通等问题都脱离不了政治，所以政府得为自己的政策负责。","es":"Problemas como la contaminación, la educación y el transporte no se pueden separar de la política, por eso el gobierno debe responder por sus propias políticas.","en":"Problems such as pollution, education and transportation cannot be separated from politics, so the government has to take responsibility for its own policies.","p":"wū rǎn, jiào yù, jiāo tōng děng wèn tí dōu tuō lí bù liǎo zhèng zhì, suǒ yǐ zhèng fǔ dé wèi zì jǐ de zhèng cè fù zé."},{"c":"每個人都應該為自己說的話負責。","s":"每个人都应该为自己说的话负责。","es":"Todos deberían responsabilizarse de lo que dicen.","en":"Everyone should take responsibility for what they say.","p":"měi ge rén dōu yīng gāi wèi zì jǐ shuō de huà fù zé."}]},{"id":"5-1-5","b":5,"l":1,"k":"","t":{"es":"Taparle la boca a ...","en":"To shut someone up / silence","ens":"To shut someone up / silence","tc":"封住…的嘴","sc":"封住…的嘴"},"d":{"es":"封住…的嘴 = taparle la boca a alguien (lit. sellar su boca). Figurado: impedir que alguien hable, critique o informe, mediante presión, dinero u otros medios. Connotación negativa.","en":"Literally 'seal someone's mouth'. Figuratively it means preventing a person or the media from speaking, criticizing or reporting, by pressure, money or other means. It has a negative tone.","tc":"字面是「把嘴封起來」，比喻用壓力、金錢或手段不讓某人（或媒體）說話、批評或報導，帶有負面意思。","sc":"字面是「把嘴封起来」，比喻用压力、金钱或手段不让某人（或媒体）说话、批评或报导，带有负面意思。"},"ex":[{"c":"因為這件事會讓人民抗議政府，所以政府打算先封住媒體的嘴，不讓媒體報導。","s":"因为这件事会让人民抗议政府，所以政府打算先封住媒体的嘴，不让媒体报导。","es":"Como este asunto haría que la gente protestara contra el gobierno, este piensa primero taparle la boca a los medios para que no informen.","en":"Because this matter would make people protest against the government, the government plans to silence the media first so that it cannot report on it.","p":"yīn wèi zhè jiàn shì huì ràng rén mín kàng yì zhèng fǔ, suǒ yǐ zhèng fǔ dǎ suàn xiān fēng zhù méi tǐ de zuǐ, bú ràng méi tǐ bào dǎo."},{"c":"公司用錢封住了證人的嘴。","s":"公司用钱封住了证人的嘴。","es":"La empresa le tapó la boca al testigo con dinero.","en":"The company bought the witness's silence with money.","p":"gōng sī yòng qián fēng zhù le zhèng rén de zuǐ."}]},{"id":"5-1-6","b":5,"l":1,"k":"","t":{"es":"A se esconde bajo el paraguas de B","en":"A hides under B's protective umbrella","ens":"A hides under B's protective umbrella","tc":"A躲在B的保護傘下","sc":"A躲在B的保护伞下"},"d":{"es":"保護傘 (paraguas protector) es una metáfora de amparo. A 躲在 B 的保護傘下 = A se esconde bajo el amparo de B, usándolo como excusa o escudo para evitar responsabilidad o críticas. Suele ser crítico.","en":"保護傘 ('protective umbrella') is a metaphor for cover or shelter. The pattern means A hides behind B, using it as a shield or excuse to avoid responsibility or criticism; it is usually critical.","tc":"「保護傘」比喻保護、庇護。這個句型表示 A 利用 B 當作擋箭牌或藉口，來避免責任或批評，通常帶批評的意思。","sc":"「保护伞」比喻保护、庇护。这个句型表示 A 利用 B 当作挡箭牌或借口，来避免责任或批评，通常带批评的意思。"},"ex":[{"c":"有些謠言躲在言論自由的保護傘下，傳到許多地方。","s":"有些谣言躲在言论自由的保护伞下，传到许多地方。","es":"Algunos rumores se esconden bajo el amparo de la libertad de expresión y se difunden por muchos lugares.","en":"Some rumors hide under the umbrella of freedom of speech and spread to many places.","p":"yǒu xiē yáo yán duǒ zài yán lùn zì yóu de bǎo hù sǎn xià, chuán dào xǔ duō dì fāng."},{"c":"有些人躲在匿名的保護傘下，說出傷人的話。","s":"有些人躲在匿名的保护伞下，说出伤人的话。","es":"Algunas personas se esconden bajo el amparo del anonimato para decir cosas hirientes.","en":"Some people hide behind anonymity to say hurtful things.","p":"yǒu xiē rén duǒ zài nì míng de bǎo hù sǎn xià, shuō chū shāng rén de huà."}]},{"id":"5-1-7","b":5,"l":1,"k":"","t":{"es":"Esto es especialmente cierto","en":"This is especially true","ens":"This is especially true","tc":"尤其如此","sc":"尤其如此"},"d":{"es":"尤其如此 = esto es especialmente cierto. Tras una afirmación general se añade que en un caso concreto se cumple todavía más; suele decirse 對…來說尤其如此 o simplemente …尤其如此.","en":"尤其如此 means 'this is especially so'. After a general statement it adds that in one particular case it holds even more; commonly 對…來說尤其如此.","tc":"先說一個一般的情況，再用「尤其如此」補充：在某個特定對象或情況下，更是這樣。常說「對…來說尤其如此」。","sc":"先说一个一般的情况，再用「尤其如此」补充：在某个特定对象或情况下，更是这样。常说「对…来说尤其如此」。"},"ex":[{"c":"運動可以放鬆心情，因此每個人都應該培養運動的習慣，對有憂鬱症的人來說尤其如此。","s":"运动可以放松心情，因此每个人都应该培养运动的习惯，对有忧郁症的人来说尤其如此。","es":"El ejercicio relaja el ánimo, por eso todos deberían adquirir el hábito de hacer deporte; esto es especialmente cierto para quienes tienen depresión.","en":"Exercise can help you relax, so everyone should develop an exercise habit, and this is especially true for people with depression.","p":"yùn dòng kě yǐ fàng sōng xīn qíng, yīn cǐ měi ge rén dōu yīng gāi péi yǎng yùn dòng de xí guàn, duì yǒu yōu yù zhèng de rén lái shuō yóu qí rú cǐ."},{"c":"冬天容易感冒，對小孩來說尤其如此。","s":"冬天容易感冒，对小孩来说尤其如此。","es":"En invierno es fácil resfriarse, y esto es especialmente cierto para los niños.","en":"It's easy to catch a cold in winter, and this is especially true for children.","p":"dōng tiān róng yì gǎn mào, duì xiǎo hái lái shuō yóu qí rú cǐ."}]},{"id":"5-1-8","b":5,"l":1,"k":"","t":{"es":"En cambio / por su parte","en":"On the other hand, whereas","ens":"On the other hand, whereas","tc":"則","sc":"则"},"d":{"es":"則 marca contraste entre dos partes: 有些…有些…則… (unos…, otros en cambio…). Va después del sujeto de la segunda parte y antes del verbo. Registro escrito.","en":"則 contrasts two parts: 有些…有些…則… ('some…, others…'). It goes after the subject of the second part and before the verb. Written register.","tc":"用來對比兩個部分：「有些…有些…則…」「…則…」。「則」放在第二部分的主語後面、動詞前面，是書面語。","sc":"用来对比两个部分：「有些…有些…则…」「…则…」。「则」放在第二部分的主语后面、动词前面，是书面语。"},"ex":[{"c":"畢業以後，有些人選擇繼續念研究所，有些人則直接工作。","s":"毕业以后，有些人选择继续念研究所，有些人则直接工作。","es":"Después de graduarse, algunos eligen seguir con un posgrado y otros, en cambio, empiezan a trabajar directamente.","en":"After graduation, some people choose to continue with graduate school, while others go straight to work.","p":"bì yè yǐ hòu, yǒu xiē rén xuǎn zé jì xù niàn yán jiù suǒ, yǒu xiē rén zé zhí jiē gōng zuò."},{"c":"哥哥喜歡運動，弟弟則喜歡看書。","s":"哥哥喜欢运动，弟弟则喜欢看书。","es":"A mi hermano mayor le gusta el deporte; a mi hermano menor, en cambio, le gusta leer.","en":"The older brother likes sports, whereas the younger brother likes reading.","p":"gē ge xǐ huān yùn dòng, dì di zé xǐ huān kàn shū."}]},{"id":"5-1-9","b":5,"l":1,"k":"","t":{"es":"A en nombre de B","en":"A in the name of B","ens":"A in the name of B","tc":"A以B之名","sc":"A以B之名"},"d":{"es":"以 B 之名 = en nombre de B, bajo el pretexto de B. B suele ser una causa noble (amor, justicia, seguridad) y a menudo se sugiere que es solo una excusa. Registro escrito.","en":"以 B 之名 means 'in the name of B' (often something noble like love, justice or safety), often hinting that it is only a pretext. Written register.","tc":"「以 B 之名」表示打著 B（常是好聽的理由，如愛、正義、安全）的名義做 A。常暗示這個理由只是藉口，是書面用法。","sc":"「以 B 之名」表示打着 B（常是好听的理由，如爱、正义、安全）的名义做 A。常暗示这个理由只是借口，是书面用法。"},"ex":[{"c":"政府以保護人民安全之名，禁止人民進入這個地區。","s":"政府以保护人民安全之名，禁止人民进入这个地区。","es":"En nombre de proteger la seguridad de la gente, el gobierno prohíbe el acceso a esta zona.","en":"In the name of protecting people's safety, the government forbids people from entering this area.","p":"zhèng fǔ yǐ bǎo hù rén mín ān quán zhī míng, jìn zhǐ rén mín jìn rù zhè ge dì qū."},{"c":"有人以愛之名，控制自己的孩子。","s":"有人以爱之名，控制自己的孩子。","es":"Hay quienes, en nombre del amor, controlan a sus hijos.","en":"Some people control their children in the name of love.","p":"yǒu rén yǐ ài zhī míng, kòng zhì zì jǐ de hái zi."}]},{"id":"5-1-10","b":5,"l":1,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Ni hablar de B","en":"Not to mention B","ens":"Not to mention B","tc":"B就更不用說了","sc":"B就更不用说了"},"d":{"es":"B 就更不用說了 = de B ni se diga. Primero se presenta A, que ya cumple lo dicho, y luego se señala que B (un caso más extremo) lo cumple con mayor razón. Sirve de remate.","en":"B 就更不用說了 means 'B goes without saying'. After presenting A, which already fits, it adds that B, a more extreme case, fits all the more.","tc":"先說 A 已經是這樣（常是比較容易的例子），再說 B 的程度更高，所以更是這樣，不用多說。B 通常是更極端的情況。","sc":"先说 A 已经是这样（常是比较容易的例子），再说 B 的程度更高，所以更是这样，不用多说。B 通常是更极端的情况。"},"ex":[{"c":"房價高漲，使得很多工作了十幾年的人也買不起房子。年輕人就更不用說了，他們連養活自己都很困難。","s":"房价高涨，使得很多工作了十几年的人也买不起房子。年轻人就更不用说了，他们连养活自己都很困难。","es":"Con la subida de los precios, hasta quienes llevan más de diez años trabajando no pueden comprar casa. De los jóvenes ni hablar: les cuesta hasta mantenerse a sí mismos.","en":"Soaring housing prices mean that even people who have worked for more than ten years cannot afford a home. Young people, needless to say, find it hard even to support themselves.","p":"fáng jià gāo zhǎng, shǐ dé hěn duō gōng zuò le shí jǐ nián de rén yě mǎi bù qǐ fáng zi. nián qīng rén jiù gèng bú yòng shuō le, tā men lián yǎng huó zì jǐ dōu hěn kùn nán."},{"c":"連大人都覺得這道題很難，小孩子就更不用說了。","s":"连大人都觉得这道题很难，小孩子就更不用说了。","es":"Hasta los adultos creen que este problema es difícil; de los niños ni hablar.","en":"Even adults find this question hard, let alone children.","p":"lián dà rén dōu jué dé zhè dào tí hěn nán, xiǎo hái zi jiù gèng bú yòng shuō le."}]},{"id":"5-1-11","b":5,"l":1,"k":"","t":{"es":"Al mismo tiempo que A, también B","en":"While A, also B","ens":"While A, also B","tc":"(在) A的同時，也B","sc":"(在) A的同时，也B"},"d":{"es":"(在) A 的同時，也 B = al mismo tiempo que A, también B. Se usa para recordar que, mientras se hace A, hay que hacer o cuidar también B (algo complementario o una advertencia). 在 es opcional.","en":"(在) A 的同時，也 B means 'while A, also B': while doing A you should also do or watch out for B, often a reminder or complementary point. 在 is optional.","tc":"表示做 A 的時候，也要同時做或注意 B。B 常是提醒、補充或相對的另一面。「在」可以省略，常用在書面或演講。","sc":"表示做 A 的时候，也要同时做或注意 B。B 常是提醒、补充或相对的另一面。「在」可以省略，常用在书面或演讲。"},"ex":[{"c":"享受雲端科技的同時，也要控制自己，不要沉迷在網路世界裡。","s":"享受云端科技的同时，也要控制自己，不要沉迷在网路世界里。","es":"Mientras disfrutamos de la tecnología en la nube, también debemos controlarnos y no obsesionarnos con el mundo de internet.","en":"While enjoying cloud technology, we also need to control ourselves and not get hooked on the online world.","p":"xiǎng shòu yún duān kē jì de tóng shí, yě yào kòng zhì zì jǐ, bú yào chén mí zài wǎng lù shì jiè lǐ."},{"c":"我們在享受便利的同時，也要保護環境。","s":"我们在享受便利的同时，也要保护环境。","es":"Mientras disfrutamos de la comodidad, también debemos proteger el medio ambiente.","en":"While enjoying convenience, we must also protect the environment.","p":"wǒ men zài xiǎng shòu biàn lì de tóng shí, yě yào bǎo hù huán jìng."}]},{"id":"5-2-0","b":5,"l":2,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 condicional condición si conditional condition if 條件 假設 如果 además adición también addition also besides 另外 而且 pregunta preguntar interrogativa question ask 疑问 问句 提问 condicional condición si conditional condition if 条件 假设 如果 además adición también addition also besides 另外 而且","t":{"es":"Ya que A, ¿por qué todavía B?","en":"Since A, why still B?","ens":"Since A, why still B?","tc":"既然A，為什麼還B呢？","sc":"既然A，为什么还B呢？"},"d":{"es":"既然 A，為什麼還 B 呢？ = ya que A, ¿por qué todavía B? A es un hecho ya aceptado y la pregunta retórica señala que B contradice a A. Tono de cuestionamiento o reproche.","en":"既然 A，為什麼還 B 呢？ means 'since A, why still B?'. A is an accepted fact, and the rhetorical question shows that B contradicts it. It carries a tone of challenge or reproach.","tc":"先承認一個已知的事實 A，再用反問表示 B 和 A 互相矛盾、不合理。是帶有質疑或責備語氣的問句。","sc":"先承认一个已知的事实 A，再用反问表示 B 和 A 互相矛盾、不合理。是带有质疑或责备语气的问句。"},"ex":[{"c":"你既然拿到了獎學金，為什麼還要放棄呢？","s":"你既然拿到了奖学金，为什么还要放弃呢？","es":"Ya que obtuviste la beca, ¿por qué todavía quieres renunciar?","en":"Since you got the scholarship, why would you still give it up?","p":"nǐ jì rán ná dào le jiǎng xué jīn, wèi shén me hái yào fàng qì ne?"},{"c":"你既然不喜歡這份工作，為什麼還做了三年呢？","s":"你既然不喜欢这份工作，为什么还做了三年呢？","es":"Ya que no te gusta este trabajo, ¿por qué llevas tres años en él?","en":"Since you don't like this job, why have you kept doing it for three years?","p":"nǐ jì rán bù xǐ huān zhè fèn gōng zuò, wèi shén me hái zuò le sān nián ne?"}]},{"id":"5-2-1","b":5,"l":2,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Tarde o temprano","en":"Sooner or later","ens":"Sooner or later","tc":"早晚","sc":"早晚"},"d":{"es":"早晚 = tarde o temprano. Puede funcionar como adverbio (早晚會…) o en la forma 是早晚的事, 'es cuestión de tiempo'.","en":"早晚 means 'sooner or later'. It can be an adverb (早晚會…) or appear as 是早晚的事, 'it is only a matter of time'.","tc":"「早晚」表示遲早、總有一天會發生。可以當副詞（早晚會…），也可以說「是早晚的事」，意思是只是時間問題。","sc":"「早晚」表示迟早、总有一天会发生。可以当副词（早晚会…），也可以说「是早晚的事」，意思是只是时间问题。"},"ex":[{"c":"選出這樣的總統，支持者早晚會失望的。","s":"选出这样的总统，支持者早晚会失望的。","es":"Si se elige a un presidente así, tarde o temprano sus seguidores se decepcionarán.","en":"If such a president is elected, his supporters will sooner or later be disappointed.","p":"xuǎn chū zhè yàng de zǒng tǒng, zhī chí zhě zǎo wǎn huì shī wàng de."},{"c":"玉玲跟孝剛結婚是早晚的事，只是沒想到這麼快。","s":"玉玲跟孝刚结婚是早晚的事，只是没想到这么快。","es":"Que Yuling y Xiaogang se casaran era cuestión de tiempo, solo que no esperaba que fuera tan pronto.","en":"It was only a matter of time before Yuling and Xiaogang got married; I just didn't expect it to be so soon.","p":"yù líng gēn xiào gāng jié hūn shì zǎo wǎn de shì, zhǐ shì méi xiǎng dào zhè me kuài."}]},{"id":"5-2-2","b":5,"l":2,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No solo A, sino sobre todo B","en":"Not only A, but more importantly B","ens":"Not only A, but more importantly B","tc":"不僅A，更重要的是B","sc":"不仅A，更重要的是B"},"d":{"es":"不僅 A，更重要的是 B = no solo A, sino sobre todo (lo más importante es) B. Se enumera A (puede haber varios elementos) y se destaca B como lo más importante. Registro escrito o formal.","en":"不僅 A，更重要的是 B means 'not only A, but more importantly B'. A may list several items and B is highlighted as the most important. Written or formal register.","tc":"先列出 A（可以有好幾項），再用「更重要的是」帶出最重要的一項 B。書面或正式說明常用，A 和 B 通常是同一類的事。","sc":"先列出 A（可以有好几项），再用「更重要的是」带出最重要的一项 B。书面或正式说明常用，A 和 B 通常是同一类的事。"},"ex":[{"c":"最近我的工作壓力很大，不僅天天開會、寫報告、更重要的是還要完成兩份市場調查的統計。","s":"最近我的工作压力很大，不仅天天开会、写报告、更重要的是还要完成两份市场调查的统计。","es":"Últimamente tengo mucha presión en el trabajo: no solo tengo reuniones y escribo informes todos los días, sino que, lo más importante, debo terminar las estadísticas de dos estudios de mercado.","en":"My work stress has been heavy lately: not only are there meetings and reports every day, but more importantly I also have to finish the statistics for two market surveys.","p":"zuì jìn wǒ de gōng zuò yā lì hěn dà, bù jǐn tiān tiān kāi huì, xiě bào gào, gèng zhòng yào de shì hái yào wán chéng liǎng fèn shì chǎng diào chá de tǒng jì."},{"c":"學中文不僅要會說，更重要的是要能夠運用。","s":"学中文不仅要会说，更重要的是要能够运用。","es":"Aprender chino no solo exige saber hablar; lo más importante es poder usarlo.","en":"Learning Chinese isn't just about being able to speak; more importantly, you have to be able to use it.","p":"xué zhōng wén bù jǐn yào huì shuō, gèng zhòng yào de shì yào néng gòu yùn yòng."}]},{"id":"5-2-3","b":5,"l":2,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Se supone que deberías… (¡debería…!)","en":"Should… (so it ought to be)","ens":"Should… (so it ought to be)","tc":"應該…才對！","sc":"应该…才对！"},"d":{"es":"應該…才對 = debería… / lo correcto es… Indica lo que es razonable o debido, y se usa para recordar, corregir o expresar queja por lo que ocurre. 才對 al final es indispensable.","en":"應該…才對 means 'should… (that would be the right thing)'. It states what is proper or reasonable, and is used to remind, correct or express dissatisfaction. 才對 at the end is essential.","tc":"「應該…才對」說明按道理或規定，正確的做法是這樣；常用來提醒別人、糾正，或表示對現況不滿。句尾「才對」不能省略。","sc":"「应该…才对」说明按道理或规定，正确的做法是这样；常用来提醒别人、纠正，或表示对现况不满。句尾「才对」不能省略。"},"ex":[{"c":"上密集班的學生都應該在上課以前把生詞準備好才對。","s":"上密集班的学生都应该在上课以前把生词准备好才对。","es":"Los estudiantes del curso intensivo deberían tener preparado el vocabulario nuevo antes de la clase.","en":"Students in the intensive class should have their new vocabulary prepared before class.","p":"shàng mì jí bān de xué shēng dōu yīng gāi zài shàng kè yǐ qián bǎ shēng cí zhǔn bèi hǎo cái duì."},{"c":"你應該早點告訴我才對！","s":"你应该早点告诉我才对！","es":"¡Deberías habérmelo dicho antes!","en":"You should have told me earlier!","p":"nǐ yīng gāi zǎo diǎn gào sù wǒ cái duì!"}]},{"id":"5-2-4","b":5,"l":2,"k":"","t":{"es":"No hay ... alguno / carecer de ...","en":"Utterly lacking …","ens":"Utterly lacking …","tc":"毫無…可言","sc":"毫无…可言"},"d":{"es":"毫無…可言 = no hay absolutamente nada de … que mencionar; carecer por completo de …. Tono muy fuerte y registro escrito. Se usa con sustantivos abstractos: 效果, 意義, 價值, 自由, 隱私.","en":"毫無…可言 means 'there is absolutely no … to speak of'. It is strong and written, used with abstract nouns such as 效果, 意義, 價值, 自由 and 隱私.","tc":"「毫無」是完全沒有，「可言」表示值得說的；合起來是「完全沒有…可說」，語氣很強。…處常放「效果、意義、價值、自由、隱私」等抽象名詞，是書面語。","sc":"「毫无」是完全没有，「可言」表示值得说的；合起来是「完全没有…可说」，语气很强。…处常放「效果、意义、价值、自由、隐私」等抽象名词，是书面语。"},"ex":[{"c":"這種藥我吃了一個星期了，病還沒好，簡直是毫無效果可言。","s":"这种药我吃了一个星期了，病还没好，简直是毫无效果可言。","es":"Llevo una semana tomando esta medicina y no me he curado; simplemente no tiene ningún efecto.","en":"I've taken this medicine for a week and I'm still not better; it's simply got no effect whatsoever.","p":"zhè zhǒng yào wǒ chī le yí ge xīng qí le, bìng hái méi hǎo, jiǎn zhí shì háo wú xiào guǒ kě yán."},{"c":"在這種環境下工作，毫無自由可言。","s":"在这种环境下工作，毫无自由可言。","es":"Trabajando en este tipo de ambiente no hay libertad alguna.","en":"Working in an environment like this, there is no freedom to speak of.","p":"zài zhè zhǒng huán jìng xià gōng zuò, háo wú zì yóu kě yán."}]},{"id":"5-2-5","b":5,"l":2,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"En realidad es A y no B","en":"It's actually A, not B","ens":"It's actually A, not B","tc":"其實是A而不是B","sc":"其实是A而不是B"},"d":{"es":"其實是 A 而不是 B = en realidad es A y no B. Corrige una idea o malentendido común: se piensa que es B, pero lo cierto es A. Lo que va tras 而不是 es lo que se descarta.","en":"其實是 A 而不是 B means 'it's actually A, not B'. It corrects a common assumption: people think B, but the truth is A. What follows 而不是 is the rejected view.","tc":"用來糾正一般人的想法或常見的誤會：大家以為是 B，但真正是 A。「而不是」後面的 B 就是被否定的說法。","sc":"用来纠正一般人的想法或常见的误会：大家以为是 B，但真正是 A。「而不是」后面的 B 就是被否定的说法。"},"ex":[{"c":"許多外籍生都認為，中文最難的其實是聲調而不是語法。","s":"许多外籍生都认为，中文最难的其实是声调而不是语法。","es":"Muchos estudiantes extranjeros piensan que lo más difícil del chino en realidad son los tonos y no la gramática.","en":"Many international students think that the hardest part of Chinese is actually the tones, not the grammar.","p":"xǔ duō wài jí shēng dōu rèn wéi, zhōng wén zuì nán de qí shí shì shēng diào ér bú shì yǔ fǎ."},{"c":"他生氣的原因其實是我沒有道歉，而不是我遲到。","s":"他生气的原因其实是我没有道歉，而不是我迟到。","es":"En realidad él se molestó porque no me disculpé, no porque llegué tarde.","en":"The reason he was angry was actually that I didn't apologize, not that I was late.","p":"tā shēng qì de yuán yīn qí shí shì wǒ méi yǒu dào qiàn, ér bú shì wǒ chí dào."}]},{"id":"5-2-6","b":5,"l":2,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 pregunta preguntar interrogativa question ask 疑问 问句 提问 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"¿Cómo se puede…?","en":"How could one…?","ens":"How could one…?","tc":"怎麼能…呢？","sc":"怎么能…呢？"},"d":{"es":"怎麼能…呢？ = ¿cómo se puede…? / ¿cómo es posible que…? Pregunta retórica que expresa que algo no debería hacerse o no es aceptable; indica desaprobación. No pide información sobre un método.","en":"怎麼能…呢？ means 'how could… ?' It is a rhetorical question meaning something should not be done or is unacceptable, showing disapproval rather than asking how.","tc":"反問句，表示「不應該／不可以」，語氣帶有不贊成或不滿。不是真的問方法。「呢」可以加強質問的語氣。","sc":"反问句，表示「不应该／不可以」，语气带有不赞成或不满。不是真的问方法。「呢」可以加强质问的语气。"},"ex":[{"c":"要是沒有言論自由，政府的決策，怎麼能受到人民的監督呢？","s":"要是没有言论自由，政府的决策，怎么能受到人民的监督呢？","es":"Si no existiera la libertad de expresión, ¿cómo podría el pueblo supervisar las decisiones del gobierno?","en":"Without freedom of speech, how could the government's decisions be monitored by the people?","p":"yào shì méi yǒu yán lùn zì yóu, zhèng fǔ de jué cè, zěn me néng shòu dào rén mín de jiān dū ne?"},{"c":"你怎麼能這樣對朋友說話呢？","s":"你怎么能这样对朋友说话呢？","es":"¿Cómo puedes hablarle así a un amigo?","en":"How can you talk to a friend like that?","p":"nǐ zěn me néng zhè yàng duì péng yǒu shuō huà ne?"}]},{"id":"5-2-7","b":5,"l":2,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 dirección movimiento direction movement 方向 趨向 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在 dirección movimiento direction movement 方向 趋向","t":{"es":"Desde el punto de vista de… / a juzgar por…","en":"Judging from…, from the standpoint of…","ens":"Judging from…, from the standpoint of…","tc":"從…來看","sc":"从…来看"},"d":{"es":"從…來看 = a juzgar por…, desde el punto de vista de…. Tras 從 se coloca un dato, un hecho o una perspectiva en que se basa la conclusión que sigue.","en":"從…來看 means 'judging from…' or 'from the perspective of…'. After 從 come the facts, data or viewpoint on which the following conclusion is based.","tc":"「從」後面放事實、資料或觀點，表示根據這個來判斷或分析，後面接結論。比「根據」更常用在說明角度。","sc":"「从」后面放事实、资料或观点，表示根据这个来判断或分析，后面接结论。比「根据」更常用在说明角度。"},"ex":[{"c":"從過度使用農藥的情形來看，消費者只能選擇購買有機食品了。","s":"从过度使用农药的情形来看，消费者只能选择购买有机食品了。","es":"A juzgar por el uso excesivo de pesticidas, a los consumidores no les queda más que comprar alimentos orgánicos.","en":"Judging from the excessive use of pesticides, consumers have no choice but to buy organic food.","p":"cóng guò dù shǐ yòng nóng yào de qíng xíng lái kàn, xiāo fèi zhě zhǐ néng xuǎn zé gòu mǎi yǒu jī shí pǐn le."},{"c":"從這次考試的成績來看，他進步了很多。","s":"从这次考试的成绩来看，他进步了很多。","es":"A juzgar por los resultados de este examen, ha mejorado mucho.","en":"Judging from his exam results this time, he has improved a lot.","p":"cóng zhè cì kǎo shì de chéng jī lái kàn, tā jìn bù le hěn duō."}]},{"id":"5-2-8","b":5,"l":2,"k":"","t":{"es":"…, para (con el fin de)…","en":"…, in order to…","ens":"…, in order to…","tc":"以…","sc":"以…"},"d":{"es":"以 + verbo, colocado en la segunda parte de la oración, indica la finalidad de lo anterior (como 為了, 'con el fin de'). Registro escrito; poco habitual en la lengua hablada.","en":"以 followed by a verb phrase, placed in the second half of the sentence, states the purpose of what came before, like 為了 ('in order to'). Written register, rarely used in speech.","tc":"放在句子後半，「以」後面接動詞（片語），表示前面做某件事的目的，意思像「為了」。是書面語，口語較少用。","sc":"放在句子后半，「以」后面接动词（片语），表示前面做某件事的目的，意思像「为了」。是书面语，口语较少用。"},"ex":[{"c":"我們應事先做好準備，以減少颱風帶來的災害。","s":"我们应事先做好准备，以减少台风带来的灾害。","es":"Debemos prepararnos con antelación para reducir los daños que causan los tifones.","en":"We should prepare in advance in order to reduce the damage typhoons cause.","p":"wǒ men yīng shì xiān zuò hǎo zhǔn bèi, yǐ jiǎn shǎo tái fēng dài lái de zāi hài."},{"c":"公司舉辦了培訓課程，以提高員工的專業能力。","s":"公司举办了培训课程，以提高员工的专业能力。","es":"La empresa organizó cursos de capacitación para mejorar la competencia profesional de sus empleados.","en":"The company held training courses to improve its employees' professional skills.","p":"gōng sī jǔ bàn le péi xùn kè chéng, yǐ tí gāo yuán gōng de zhuān yè néng lì."}]},{"id":"5-3-0","b":5,"l":3,"k":"","t":{"es":"Tener tendencia a…","en":"There is a trend toward…","ens":"There is a trend toward…","tc":"有…的趨勢","sc":"有…的趋势"},"d":{"es":"有…的趨勢 = hay una tendencia a… 趨勢 es la dirección en que algo evoluciona; suele combinarse con verbos como 增加, 減少, 上升, 普及. Común en textos escritos y noticias.","en":"有…的趨勢 means 'there is a trend toward…'. 趨勢 is the direction something is developing; it often combines with verbs like 增加, 減少, 上升 or 普及. Common in news and writing.","tc":"「趨勢」是發展的方向。「有…的趨勢」常接增加、減少、上升等動詞，說明事情正朝某個方向發展。書面、新聞常用。","sc":"「趋势」是发展的方向。「有…的趋势」常接增加、减少、上升等动词，说明事情正朝某个方向发展。书面、新闻常用。"},"ex":[{"c":"隨著國際的交流，跨國婚姻有增加的趨勢。","s":"随着国际的交流，跨国婚姻有增加的趋势。","es":"Con el intercambio internacional, los matrimonios entre personas de distintos países tienden a aumentar.","en":"With increasing international exchange, international marriages show a trend of growth.","p":"suí zhe guó jì de jiāo liú, kuà guó hūn yīn yǒu zēng jiā de qū shì."},{"c":"近年來，網路購物有越來越普及的趨勢。","s":"近年来，网路购物有越来越普及的趋势。","es":"En los últimos años, las compras por internet tienden a popularizarse cada vez más.","en":"In recent years, online shopping has tended to become more and more widespread.","p":"jìn nián lái, wǎng lù gòu wù yǒu yuè lái yuè pǔ jí de qū shì."}]},{"id":"5-3-1","b":5,"l":3,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Sin importar el costo","en":"Regardless of cost, at all costs","ens":"Regardless of cost, at all costs","tc":"不計一切","sc":"不计一切"},"d":{"es":"不計一切 = sin tener en cuenta nada, a cualquier costo. 不計 es 'no contar', 一切 'todo'. Frecuente en la expresión fija 不計一切代價. Registro escrito.","en":"不計一切 means 'disregarding everything', i.e. at any cost. 不計 is 'not count' and 一切 'everything'; the set phrase 不計一切代價 is common. Written register.","tc":"「不計」是不考慮，「一切」是所有；合起來是不管任何代價、後果，一心去做。常見搭配有「不計一切代價」，是書面語。","sc":"「不计」是不考虑，「一切」是所有；合起来是不管任何代价、后果，一心去做。常见搭配有「不计一切代价」，是书面语。"},"ex":[{"c":"弟弟曾經不計一切幫助我，重建我的事業。","s":"弟弟曾经不计一切帮助我，重建我的事业。","es":"Mi hermano menor una vez me ayudó sin importarle nada para reconstruir mi negocio.","en":"My younger brother once helped me rebuild my business at all costs.","p":"dì di céng jīng bú jì yí qiè bāng zhù wǒ, chóng jiàn wǒ de shì yè."},{"c":"他不計一切代價，只為了要得到世界第一。","s":"他不计一切代价，只为了要得到世界第一。","es":"Él está dispuesto a pagar cualquier precio con tal de ser el número uno del mundo.","en":"He is willing to pay any price just to become number one in the world.","p":"tā bú jì yí qiè dài jià, zhǐ wèi le yào dé dào shì jiè dì yī."}]},{"id":"5-3-2","b":5,"l":3,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Ganarse el favor de…","en":"To win the favor of…","ens":"To win the favor of…","tc":"獲得…(的)青睞","sc":"获得…(的)青睐"},"d":{"es":"獲得…(的)青睞 = ganarse el favor (la preferencia) de…. 青睞 es una especial predilección. Se usa en escritos y puede negarse: 沒有獲得…的青睞 (no convencer a…).","en":"獲得…(的)青睞 means 'to win someone's favor'. 青睞 is special liking or preference. Written register; it can be negated as 沒有獲得…的青睞.","tc":"「青睞」是特別的喜愛、重視。「獲得…青睞」表示受到某人或某群人的歡迎、看重，是書面語。也可以反過來否定：「沒有獲得…的青睞」。","sc":"「青睐」是特别的喜爱、重视。「获得…青睐」表示受到某人或某群人的欢迎、看重，是书面语。也可以反过来否定：「没有获得…的青睐」。"},"ex":[{"c":"政府多項鼓勵生育的措施，並沒有獲得年輕人的青睞，因此少子化仍是目前的問題。","s":"政府多项鼓励生育的措施，并没有获得年轻人的青睐，因此少子化仍是目前的问题。","es":"Varias medidas del gobierno para fomentar la natalidad no han convencido a los jóvenes, por eso la baja natalidad sigue siendo un problema.","en":"Several government measures encouraging childbirth have not won the favor of young people, so the declining birthrate remains a problem.","p":"zhèng fǔ duō xiàng gǔ lì shēng yù de cuò shī, bìng méi yǒu huò dé nián qīng rén de qīng lài, yīn cǐ shǎo zi huà réng shì mù qián de wèn tí."},{"c":"這款手機的設計獲得了年輕人的青睞。","s":"这款手机的设计获得了年轻人的青睐。","es":"El diseño de este teléfono se ganó el favor de los jóvenes.","en":"The design of this phone won favor with young people.","p":"zhè kuǎn shǒu jī de shè jì huò dé le nián qīng rén de qīng lài."}]},{"id":"5-3-3","b":5,"l":3,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Invertir A en B","en":"To invest A in B","ens":"To invest A in B","tc":"把A投資在B上","sc":"把A投资在B上"},"d":{"es":"把 A 投資在 B 上 = invertir A en B. A es un recurso (dinero, tiempo, energía) y B es en lo que se invierte. Estructura con 把.","en":"把 A 投資在 B 上 means 'to invest A in B'. A is a resource (money, time, energy) and B is where it goes. It is a 把 sentence.","tc":"A 是金錢、時間、精力等資源，B 是要投入的對象。用「把」字句，表示把資源放在 B 上。也可以說「在 B 上投資 A」。","sc":"A 是金钱、时间、精力等资源，B 是要投入的对象。用「把」字句，表示把资源放在 B 上。也可以说「在 B 上投资 A」。"},"ex":[{"c":"由於以貌取人是人的天性，因此不能怪那些把金錢投資在外表上的人。","s":"由于以貌取人是人的天性，因此不能怪那些把金钱投资在外表上的人。","es":"Como juzgar por las apariencias es parte de la naturaleza humana, no se puede culpar a quienes invierten dinero en su aspecto.","en":"Since judging people by their looks is human nature, we can't blame those who invest money in their appearance.","p":"yóu yú yǐ mào qǔ rén shì rén de tiān xìng, yīn cǐ bù néng guài nà xiē bǎ jīn qián tóu zī zài wài biǎo shàng de rén."},{"c":"他把大部分時間投資在學習語言上。","s":"他把大部分时间投资在学习语言上。","es":"Él invierte la mayor parte de su tiempo en aprender idiomas.","en":"He invests most of his time in learning languages.","p":"tā bǎ dà bù fēn shí jiān tóu zī zài xué xí yǔ yán shàng."}]},{"id":"5-3-4","b":5,"l":3,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Padecer mucho de…","en":"To suffer greatly from…","ens":"To suffer greatly from…","tc":"飽受…之苦","sc":"饱受…之苦"},"d":{"es":"飽受…之苦 = sufrir mucho de…, padecer…. 飽受 indica sufrir mucho o por mucho tiempo; se combina con sustantivos negativos (戰爭, 疾病, 貧窮, 天災). Registro escrito.","en":"飽受…之苦 means 'to suffer a great deal from…'. 飽受 implies suffering heavily or for a long time; it goes with negative nouns like 戰爭, 疾病, 貧窮, 天災. Written register.","tc":"「飽受」是受了很多、很久；「之苦」是…的痛苦。常接戰爭、疾病、貧窮、天災等不好的事，是書面語。","sc":"「饱受」是受了很多、很久；「之苦」是…的痛苦。常接战争、疾病、贫穷、天灾等不好的事，是书面语。"},"ex":[{"c":"由於政府過度發展經濟、不重視環保，因此許多國家飽受自然災害之苦。","s":"由于政府过度发展经济、不重视环保，因此许多国家饱受自然灾害之苦。","es":"Como los gobiernos desarrollan la economía en exceso y no valoran la protección ambiental, muchos países sufren mucho por los desastres naturales.","en":"Because governments over-develop their economies and neglect environmental protection, many countries suffer greatly from natural disasters.","p":"yóu yú zhèng fǔ guò dù fā zhǎn jīng jì, bú zhòng shì huán bǎo, yīn cǐ xǔ duō guó jiā bǎo shòu zì rán zāi hài zhī kǔ."},{"c":"這個地區長年飽受乾旱之苦。","s":"这个地区长年饱受干旱之苦。","es":"Esta región padece la sequía desde hace años.","en":"This region has suffered from drought for years.","p":"zhè ge dì qū cháng nián bǎo shòu gān hàn zhī kǔ."}]},{"id":"5-3-5","b":5,"l":3,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Antes A, ahora B","en":"Originally A, now B","ens":"Originally A, now B","tc":"原來A，如今B","sc":"原来A，如今B"},"d":{"es":"原來 A，如今 B = antes A, ahora B. 原來 es 'originalmente'; 如今 es 'hoy en día' (escrito). Contrasta un pasado con el presente. Ojo: aquí 原來 no significa '¡ah, así que era eso!'.","en":"原來 A，如今 B means 'originally A, but now B'. 原來 is 'originally'; 如今 is 'nowadays' (written). It contrasts past and present. Note: 原來 here is not the 'oh, I see!' sense.","tc":"「原來」是本來、起初；「如今」是現在，書面語。用來對比以前和現在的變化。注意這裡的「原來」不是「原來如此」的恍然大悟。","sc":"「原来」是本来、起初；「如今」是现在，书面语。用来对比以前和现在的变化。注意这里的「原来」不是「原来如此」的恍然大悟。"},"ex":[{"c":"這個地方原來是政治經濟中心，如今卻沒落了。","s":"这个地方原来是政治经济中心，如今却没落了。","es":"Este lugar era originalmente un centro político y económico, pero hoy ha decaído.","en":"This place used to be a political and economic center, but now it has declined.","p":"zhè ge dì fāng yuán lái shì zhèng zhì jīng jì zhōng xīn, rú jīn què mò luò le."},{"c":"這條街原來很安靜，如今卻變得非常熱鬧。","s":"这条街原来很安静，如今却变得非常热闹。","es":"Esta calle antes era muy tranquila, pero ahora se ha vuelto muy animada.","en":"This street used to be very quiet, but now it has become very lively.","p":"zhè tiáo jiē yuán lái hěn ān jìng, rú jīn què biàn dé fēi cháng rè nào."}]},{"id":"5-3-6","b":5,"l":3,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"De A, y de ahí, B","en":"From A, and then on to B","ens":"From A, and then on to B","tc":"從A，進而B","sc":"从A，进而B"},"d":{"es":"從 A，進而 B = de A, y a partir de ahí, B. 進而 indica que, sobre la base de A, se avanza un paso más hasta B; es un proceso gradual. Registro escrito.","en":"從 A，進而 B means 'from A, and going a step further, B'. 進而 shows progress from A to B in a gradual process. Written register.","tc":"「進而」表示在 A 的基礎上更進一步，發展成 B。A 到 B 是一個逐步進展的過程。書面語。","sc":"「进而」表示在 A 的基础上更进一步，发展成 B。A 到 B 是一个逐步进展的过程。书面语。"},"ex":[{"c":"他在世界沖煮咖啡大賽獲得冠軍後，從一個咖啡師變成咖啡明星，進而成了大老闆，開了許多家咖啡連鎖店。","s":"他在世界冲煮咖啡大赛获得冠军后，从一个咖啡师变成咖啡明星，进而成了大老板，开了许多家咖啡连锁店。","es":"Tras ganar el campeonato mundial de preparación de café, pasó de ser barista a estrella del café y luego a gran empresario, con muchas cafeterías en cadena.","en":"After winning a world coffee brewing championship, he went from being a barista to a coffee star and then a big boss, opening many coffee chain stores.","p":"tā zài shì jiè chōng zhǔ kā fēi dà sài huò dé guàn jūn hòu, cóng yí ge kā fēi shī biàn chéng kā fēi míng xīng, jìn ér chéng le dà lǎo bǎn, kāi le xǔ duō jiā kā fēi lián suǒ diàn."},{"c":"他從打工開始，進而創辦了自己的公司。","s":"他从打工开始，进而创办了自己的公司。","es":"Empezó con trabajos temporales y luego fundó su propia empresa.","en":"He started with part-time work and went on to found his own company.","p":"tā cóng dǎ gōng kāi shǐ, jìn ér chuàng bàn le zì jǐ de gōng sī."}]},{"id":"5-3-7","b":5,"l":3,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 pregunta preguntar interrogativa question ask 疑问 问句 提问 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Si A, ¿cómo es que B?","en":"If A, how could B?","ens":"If A, how could B?","tc":"若A，怎麼會B？","sc":"若A，怎么会B？"},"d":{"es":"若 A，怎麼會 B？ = si A, ¿cómo es que B? 若 equivale a 如果 pero más escrito. La pregunta retórica señala que, siendo cierto A, B no tendría sentido.","en":"若 A，怎麼會 B？ means 'if A, how could B?'. 若 is a more formal 如果. The rhetorical question shows that if A were true, B would not make sense.","tc":"「若」是「如果」，比較書面。這個句型用反問表示：如果 A 是真的，B 就不合理，所以 B 不應該發生。","sc":"「若」是「如果」，比较书面。这个句型用反问表示：如果 A 是真的，B 就不合理，所以 B 不应该发生。"},"ex":[{"c":"若學中文對將來的前途沒有幫助，怎麼會有那麼多人選中文系？","s":"若学中文对将来的前途没有帮助，怎么会有那么多人选中文系？","es":"Si estudiar chino no ayudara al futuro, ¿cómo es que tanta gente elegiría la carrera de chino?","en":"If studying Chinese didn't help one's future prospects, why would so many people choose the Chinese department?","p":"ruò xué zhōng wén duì jiāng lái de qián tú méi yǒu bāng zhù, zěn me huì yǒu nà me duō rén xuǎn zhōng wén xì?"},{"c":"若他真的不在乎，怎麼會每天打電話給你？","s":"若他真的不在乎，怎么会每天打电话给你？","es":"Si de verdad no le importara, ¿cómo es que te llamaría todos los días?","en":"If he really didn't care, why would he call you every day?","p":"ruò tā zhēn de bú zài hū, zěn me huì měi tiān dǎ diàn huà gěi nǐ?"}]},{"id":"5-3-8","b":5,"l":3,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Incluir A en B","en":"To include A in B","ens":"To include A in B","tc":"把A列入B","sc":"把A列入B"},"d":{"es":"把 A 列入 B = incluir A en B (en una lista, un plan, una agenda o una categoría). 列入 significa 'poner dentro de la lista'. Estructura con 把.","en":"把 A 列入 B means 'to put A on B', where B is a list, plan, agenda or category. 列入 is 'to list/include'. It is a 把 sentence.","tc":"「列入」是放進名單、計畫或類別裡。「把 A 列入 B」表示把 A 放進 B 中，B 通常是名單、計畫、議程或項目。","sc":"「列入」是放进名单、计划或类别里。「把 A 列入 B」表示把 A 放进 B 中，B 通常是名单、计划、议程或项目。"},"ex":[{"c":"政府把少子化、高齡化等問題，列入今年必須解決的問題名單中。","s":"政府把少子化、高龄化等问题，列入今年必须解决的问题名单中。","es":"El gobierno incluyó problemas como la baja natalidad y el envejecimiento en la lista de problemas que deben resolverse este año.","en":"The government put problems such as the declining birthrate and the aging population on this year's list of issues that must be solved.","p":"zhèng fǔ bǎ shǎo zi huà, gāo líng huà děng wèn tí, liè rù jīn nián bì xū jiě jué de wèn tí míng dān zhōng."},{"c":"聯合國教科文組織把這座古城列入世界遺產。","s":"联合国教科文组织把这座古城列入世界遗产。","es":"La UNESCO incluyó esta ciudad antigua en el Patrimonio Mundial.","en":"UNESCO put this ancient city on the World Heritage list.","p":"lián hé guó jiào kē wén zǔ zhī bǎ zhè zuò gǔ chéng liè rù shì jiè yí chǎn."}]},{"id":"5-3-9","b":5,"l":3,"k":"","t":{"es":"Ponerle a A la etiqueta de B","en":"To label A as B","ens":"To label A as B","tc":"給A貼上B的標籤","sc":"给A贴上B的标签"},"d":{"es":"給 A 貼上 B 的標籤 = ponerle a A la etiqueta de B. Figurado: definir a una persona o grupo con una impresión simple, a menudo un estereotipo. B es la etiqueta.","en":"給 A 貼上 B 的標籤 means 'to stick the label B on A', figuratively defining a person or group with a simple impression, often a stereotype.","tc":"「貼標籤」比喻用一個簡單的印象或名稱來定義一個人或一群人，常帶有刻板印象的意思。B 是被貼上的標籤。","sc":"「贴标签」比喻用一个简单的印象或名称来定义一个人或一群人，常带有刻板印象的意思。B 是被贴上的标签。"},"ex":[{"c":"我從小到大，都被貼上了大大小小的標籤，像是會讀書，有禮貌。","s":"我从小到大，都被贴上了大大小小的标签，像是会读书，有礼貌。","es":"Desde niño me han puesto todo tipo de etiquetas, como «buen estudiante» o «educado».","en":"Ever since I was little I have been given all kinds of labels, such as being studious and polite.","p":"wǒ cóng xiǎo dào dà, dōu bèi tiē shàng le dà dà xiǎo xiǎo de biāo qiān, xiàng shì huì dú shū, yǒu lǐ mào."},{"c":"不要因為他來自鄉下，就給他貼上「落後」的標籤。","s":"不要因为他来自乡下，就给他贴上「落后」的标签。","es":"No le pongas la etiqueta de «atrasado» solo porque viene del campo.","en":"Don't stick the label 'backward' on him just because he comes from the countryside.","p":"bú yào yīn wèi tā lái zì xiāng xià, jiù gěi tā tiē shàng 「luò hòu」 de biāo qiān."}]},{"id":"5-3-10","b":5,"l":3,"k":"","t":{"es":"Sin duda es…","en":"Undoubtedly it is…","ens":"Undoubtedly it is…","tc":"無疑是…","sc":"无疑是…"},"d":{"es":"無疑是… = sin duda es…. 無疑 significa 'sin lugar a dudas'. El hablante hace un juicio muy seguro; es más formal que 一定是 y típico de comentarios escritos.","en":"無疑是… means 'it is without doubt…'. 無疑 is 'no doubt', expressing a firm judgment; more formal than 一定是 and typical of written commentary.","tc":"「無疑」是沒有疑問，「無疑是…」表示說話者很肯定地判斷。常用在書面評論或說明，語氣比「一定是」更正式。","sc":"「无疑」是没有疑问，「无疑是…」表示说话者很肯定地判断。常用在书面评论或说明，语气比「一定是」更正式。"},"ex":[{"c":"居住在紐約的人來自世界各地，那裡無疑是一個文化、種族大熔爐。","s":"居住在纽约的人来自世界各地，那里无疑是一个文化、种族大熔炉。","es":"Los habitantes de Nueva York vienen de todo el mundo; sin duda es un gran crisol de culturas y razas.","en":"People living in New York come from all over the world, so it is undoubtedly a great melting pot of cultures and races.","p":"jū zhù zài niǔ yuē de rén lái zì shì jiè gè dì, nà lǐ wú yí shì yí ge wén huà, zhǒng zú dà róng lú."},{"c":"這次的成功無疑是大家努力的結果。","s":"这次的成功无疑是大家努力的结果。","es":"Este éxito es, sin duda, el resultado del esfuerzo de todos.","en":"This success is without doubt the result of everyone's hard work.","p":"zhè cì de chéng gōng wú yí shì dà jiā nǔ lì de jié guǒ."}]},{"id":"5-4-0","b":5,"l":4,"k":"","t":{"es":"Desde… hasta hoy","en":"From… until now","ens":"From… until now","tc":"自…至今","sc":"自…至今"},"d":{"es":"自…至今 = desde… hasta hoy. 自 equivale a 從 (escrito) y 至今 a 'hasta ahora'. Indica que algo continúa desde un momento del pasado hasta el presente; tras 自 va un momento o un hecho.","en":"自…至今 means 'from… until now'. 自 is a written 從 and 至今 is 'up to the present'. After 自 comes a point in time or an event.","tc":"「自」表示從（書面語），「至今」是到現在。用來說明某件事從過去某個時間開始一直到現在。「自」後面放時間點或事件。","sc":"「自」表示从（书面语），「至今」是到现在。用来说明某件事从过去某个时间开始一直到现在。「自」后面放时间点或事件。"},"ex":[{"c":"這所大學的國語中心自1956年成立至今幾十年，是台灣歷史最久，也是最大的華語教學機構。","s":"这所大学的国语中心自1956年成立至今几十年，是台湾历史最久，也是最大的华语教学机构。","es":"El centro de mandarín de esta universidad, desde su fundación en 1956 hasta hoy, ya con varias décadas, es la institución de enseñanza de chino más antigua y también la más grande de Taiwán.","en":"The Mandarin center of this university has been around for decades since it was founded in 1956, and it is the oldest and largest Chinese-teaching institution in Taiwan.","p":"zhè suǒ dà xué de guó yǔ zhōng xīn zì1 9 5 6 nián chéng lì zhì jīn jǐ shí nián, shì tái wān lì shǐ zuì jiǔ, yě shì zuì dà de huá yǔ jiào xué jī gòu."},{"c":"這家書店自1990年開業至今，一直受到讀者的喜愛。","s":"这家书店自1990年开业至今，一直受到读者的喜爱。","es":"Esta librería, desde que abrió en 1990 hasta hoy, siempre ha gustado a los lectores.","en":"This bookstore has been loved by readers from its opening in 1990 until now.","p":"zhè jiā shū diàn zì1 9 9 0 nián kāi yè zhì jīn, yì zhí shòu dào dú zhě de xǐ ài."}]},{"id":"5-4-1","b":5,"l":4,"k":"","t":{"es":"Hacer A mientras se hace B","en":"Doing A while doing B","ens":"Doing A while doing B","tc":"一面A一面B","sc":"一面A一面B"},"d":{"es":"一面 A 一面 B = hacer A mientras (al mismo tiempo) se hace B. Una misma persona realiza dos acciones simultáneas. Similar a 一邊…一邊…, pero 一面 es algo más escrito. Los dos verbos suelen ser acciones continuas.","en":"一面 A 一面 B means doing A and B at the same time by the same person. Similar to 一邊…一邊…, but 一面 is somewhat more written. Both verbs are typically continuing actions.","tc":"表示同一個人同時做兩件事。常寫成「一面…一面…」，和「一邊…一邊…」相近，「一面」比較書面。兩個動作通常都是持續的。","sc":"表示同一个人同时做两件事。常写成「一面…一面…」，和「一边…一边…」相近，「一面」比较书面。两个动作通常都是持续的。"},"ex":[{"c":"地震後，救災人員進入災難發生現場，一面搜尋來不及逃生的民眾，一面還得注意可能再次倒塌的大樓，情況十分危險。","s":"地震后，救灾人员进入灾难发生现场，一面搜寻来不及逃生的民众，一面还得注意可能再次倒塌的大楼，情况十分危险。","es":"Después del terremoto, los rescatistas entraron al lugar del desastre; mientras buscaban a las personas que no alcanzaron a escapar, tenían que vigilar los edificios que podían volver a derrumbarse, y la situación era muy peligrosa.","en":"After the earthquake, rescue workers entered the disaster site; while searching for people who could not escape in time, they also had to watch out for buildings that might collapse again, so the situation was very dangerous.","p":"dì zhèn hòu, jiù zāi rén yuán jìn rù zāi nán fā shēng xiàn chǎng, yí miàn sōu xún lái bù jí táo shēng de mín zhòng, yí miàn hái děi zhù yì kě néng zài cì dǎo tā de dà lóu, qíng kuàng shí fēn wéi xiǎn."},{"c":"他一面看電視，一面吃晚餐。","s":"他一面看电视，一面吃晚餐。","es":"Él ve la televisión mientras cena.","en":"He watches TV while eating dinner.","p":"tā yí miàn kàn diàn shì, yí miàn chī wǎn cān."}]},{"id":"5-4-2","b":5,"l":4,"k":"","t":{"es":"Ser necesario…","en":"There is a need to…","ens":"There is a need to…","tc":"有…的必要","sc":"有…的必要"},"d":{"es":"有…的必要 = es necesario…, hay necesidad de…. Su negación 沒有…的必要 significa 'no hace falta…'. Registro algo formal.","en":"有…的必要 means 'there is a need to…'. Its negative 沒有…的必要 means 'there is no need to…'. Somewhat formal.","tc":"「必要」是需要。「有…的必要」表示有做某件事的需要或理由；否定用「沒有…的必要」，表示不需要。","sc":"「必要」是需要。「有…的必要」表示有做某件事的需要或理由；否定用「没有…的必要」，表示不需要。"},"ex":[{"c":"政府宣布放颱風假後卻無風又無雨。看來，颱風假到底該不該放，政府相關部會絕對有討論的必要。","s":"政府宣布放台风假后却无风又无雨。看来，台风假到底该不该放，政府相关部会绝对有讨论的必要。","es":"El gobierno declaró día libre por tifón, pero luego no hubo ni viento ni lluvia. Al parecer, las autoridades pertinentes sin duda necesitan discutir si de verdad debían dar el día libre.","en":"The government announced a typhoon day off, but then there was neither wind nor rain. It seems the relevant government agencies definitely need to discuss whether a typhoon day off should really be declared.","p":"zhèng fǔ xuān bù fàng tái fēng jiǎ hòu què wú fēng yòu wú yǔ. kàn lái, tái fēng jiǎ dào dǐ gāi bù gāi fàng, zhèng fǔ xiāng guān bù huì jué duì yǒu tǎo lùn de bì yào."},{"c":"這件事很簡單，沒有再開會討論的必要。","s":"这件事很简单，没有再开会讨论的必要。","es":"Este asunto es muy sencillo; no hace falta volver a reunirse para discutirlo.","en":"This matter is very simple, so there is no need to hold another meeting to discuss it.","p":"zhè jiàn shì hěn jiǎn dān, méi yǒu zài kāi huì tǎo lùn de bì yào."}]},{"id":"5-4-3","b":5,"l":4,"k":"negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No solo no A, sino que más bien B","en":"Not only not A, but rather B","ens":"Not only not A, but rather B","tc":"不但不（沒）A反而B","sc":"不但不（没）A反而B"},"d":{"es":"不但不（沒）A 反而 B = no solo no A, sino que (al contrario) B. Se esperaba A, pero no solo no ocurrió sino que pasó lo opuesto. 反而 marca el resultado contrario a lo esperado.","en":"不但不（沒）A 反而 B means 'not only did A not happen, but on the contrary B'. A was expected but didn't happen and the opposite B did. 反而 marks the unexpected opposite result.","tc":"預期是 A，結果卻不是，而且出現相反的 B。「反而」表示結果與預期相反。A 常是「好轉、改善」等期待的結果，B 是更差的情況。","sc":"预期是 A，结果却不是，而且出现相反的 B。「反而」表示结果与预期相反。A 常是「好转、改善」等期待的结果，B 是更差的情况。"},"ex":[{"c":"我認為整型不但不能讓人更有自信，反而會帶來生理和心理的巨大衝擊。","s":"我认为整型不但不能让人更有自信，反而会带来生理和心理的巨大冲击。","es":"Creo que la cirugía estética no solo no hace que uno tenga más confianza, sino que más bien provoca un gran impacto físico y psicológico.","en":"I think plastic surgery not only fails to make people more confident, but on the contrary brings huge physical and psychological shocks.","p":"wǒ rèn wéi zhěng xíng bú dàn bù néng ràng rén gèng yǒu zì xìn, fǎn ér huì dài lái shēng lǐ hàn xīn lǐ de jù dà chōng jí."},{"c":"吃了藥以後，他的病不但沒好，反而更嚴重了。","s":"吃了药以后，他的病不但没好，反而更严重了。","es":"Después de tomar la medicina, no solo no mejoró, sino que se puso más grave.","en":"After taking the medicine, he not only didn't get better, but got worse.","p":"chī le yào yǐ hòu, tā de bìng bú dàn méi hǎo, fǎn ér gèng yán zhòng le."}]},{"id":"5-4-4","b":5,"l":4,"k":"","t":{"es":"Clasificar A como B","en":"To list A as B","ens":"To list A as B","tc":"將A列為B","sc":"将A列为B"},"d":{"es":"將 A 列為 B = clasificar (declarar, designar) A como B. 將 es la forma escrita de 把. 列為 indica incluir formalmente en una categoría o nivel. Típico de comunicados y noticias.","en":"將 A 列為 B means 'to designate A as B'. 將 is the written version of 把; 列為 is to formally place something in a category or rank. Typical of official announcements and news.","tc":"「將」是「把」的書面語。「列為」是正式列入、指定成為某種類別或等級。多用在政府公告、新聞，B 是新的身分或類別。","sc":"「将」是「把」的书面语。「列为」是正式列入、指定成为某种类别或等级。多用在政府公告、新闻，B 是新的身分或类别。"},"ex":[{"c":"為保存傳統語言，政府將原住民族的語言列為國家語言。","s":"为保存传统语言，政府将原住民族的语言列为国家语言。","es":"Para preservar las lenguas tradicionales, el gobierno declaró las lenguas de los pueblos indígenas como lenguas nacionales.","en":"To preserve traditional languages, the government designated the languages of indigenous peoples as national languages.","p":"wéi bǎo cún chuán tǒng yǔ yán, zhèng fǔ jiāng yuán zhù mín zú de yǔ yán liè wéi guó jiā yǔ yán."},{"c":"政府將這條老街列為歷史保護區。","s":"政府将这条老街列为历史保护区。","es":"El gobierno declaró esta calle antigua zona de protección histórica.","en":"The government has designated this old street a historic preservation area.","p":"zhèng fǔ jiāng zhè tiáo lǎo jiē liè wéi lì shǐ bǎo hù qū."}]},{"id":"5-4-5","b":5,"l":4,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Perjudicial / favorable para…","en":"Detrimental / beneficial to…","ens":"Detrimental / beneficial to…","tc":"不利(於) / 有利(於)A","sc":"不利(于) / 有利(于)A"},"d":{"es":"有利(於)A = favorable para A, beneficioso para A; 不利(於)A = perjudicial para A. 於 puede omitirse. A suele ser un sustantivo o acción (健康, 發展, 學習). Frecuente en textos formales.","en":"有利(於)A means 'beneficial to A' and 不利(於)A 'detrimental to A'. 於 is optional. A is often a noun or an action such as 健康, 發展 or 學習. Common in formal writing.","tc":"「有利於 A」是對 A 有好處，「不利於 A」是對 A 不好。「於」可以省略。A 常是名詞或動作，如健康、發展、學習。書面、正式說明常用。","sc":"「有利于 A」是对 A 有好处，「不利于 A」是对 A 不好。「于」可以省略。A 常是名词或动作，如健康、发展、学习。书面、正式说明常用。"},"ex":[{"c":"過度依賴進口不利於經濟發展。","s":"过度依赖进口不利于经济发展。","es":"Depender demasiado de las importaciones es perjudicial para el desarrollo económico.","en":"Over-reliance on imports is detrimental to economic development.","p":"guò dù yī lài jìn kǒu bú lì yú jīng jì fā zhǎn."},{"c":"多吃蔬果多運動有利於身體健康。","s":"多吃蔬果多运动有利于身体健康。","es":"Comer más frutas y verduras y hacer más ejercicio es bueno para la salud.","en":"Eating more fruit and vegetables and exercising more benefits one's health.","p":"duō chī shū guǒ duō yùn dòng yǒu lì yú shēn tǐ jiàn kāng."}]},{"id":"5-4-6","b":5,"l":4,"k":"","t":{"es":"En el proceso de…","en":"In the course of…","ens":"In the course of…","tc":"在…過程中","sc":"在…过程中"},"d":{"es":"在…過程中 = en el proceso de…, durante…. 過程 es el desarrollo de algo de principio a fin; la oración dice lo que ocurre o se hace durante ese proceso.","en":"在…過程中 means 'in the course of…'. 過程 is the process from start to finish; the sentence states what happens or is done during it.","tc":"「過程」是從開始到結束的經過。「在…過程中」表示在做某件事的期間，後面說這期間發生的事或做的事。","sc":"「过程」是从开始到结束的经过。「在…过程中」表示在做某件事的期间，后面说这期间发生的事或做的事。"},"ex":[{"c":"經過多次的沙盤推演，家明在面試的過程中很有自信地展現出自己的優點，因此獲得面試官的青睞。","s":"经过多次的沙盘推演，家明在面试的过程中很有自信地展现出自己的优点，因此获得面试官的青睐。","es":"Después de varias simulaciones, durante la entrevista Jiaming mostró con mucha confianza sus puntos fuertes y así se ganó el favor del entrevistador.","en":"After many rehearsals, Jiaming confidently showed off his strengths during the interview and thus won the interviewer's favor.","p":"jīng guò duō cì de shā pán tuī yǎn, jiā míng zài miàn shì de guò chéng zhōng hěn yǒu zì xìn dì zhǎn xiàn chū zì jǐ de yōu diǎn, yīn cǐ huò dé miàn shì guān de qīng lài."},{"c":"在學習中文的過程中，他遇到了很多困難。","s":"在学习中文的过程中，他遇到了很多困难。","es":"En el proceso de aprender chino se encontró con muchas dificultades.","en":"In the process of learning Chinese, he ran into many difficulties.","p":"zài xué xí zhōng wén de guò chéng zhōng, tā yù dào le hěn duō kùn nán."}]},{"id":"5-4-7","b":5,"l":4,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Ya es hora de…","en":"It's time to…","ens":"It's time to…","tc":"是…的時候了","sc":"是…的时候了"},"d":{"es":"是…的時候了 = ya es hora de…. Suele decirse 現在該是…的時候了. La negación 不是…的時候 (還不是…的時候) indica que todavía no es el momento o que no conviene hacerlo ahora.","en":"是…的時候了 means 'it's time to…', often 現在該是…的時候了. The negative 不是…的時候 means it's not yet the time or not appropriate now.","tc":"表示現在正是該做某件事的時機，常說「現在該是…的時候了」。否定時說「不是…的時候」，表示還不是時候或不適合現在做。","sc":"表示现在正是该做某件事的时机，常说「现在该是…的时候了」。否定时说「不是…的时候」，表示还不是时候或不适合现在做。"},"ex":[{"c":"已經12點了，別再上網了！現在該是睡覺的時候了。","s":"已经12点了，别再上网了！现在该是睡觉的时候了。","es":"¡Ya son las 12, deja de navegar en internet! Ahora es hora de dormir.","en":"It's already 12 o'clock, stop surfing the net! Now it's time to go to sleep.","p":"yǐ jīng1 2 diǎn le, bié zài shàng wǎng le! xiàn zài gāi shì shuì jiào de shí hòu le."},{"c":"才下午四點呢！還不是吃飯的時候，我們先去看個電影吧！","s":"才下午四点呢！还不是吃饭的时候，我们先去看个电影吧！","es":"¡Apenas son las cuatro de la tarde! Todavía no es hora de comer; primero vayamos a ver una película.","en":"It's only four in the afternoon! It's not yet time to eat, so let's go see a movie first.","p":"cái xià wǔ sì diǎn ne! hái bú shì chī fàn de shí hòu, wǒ men xiān qù kàn gè diàn yǐng ba!"}]},{"id":"5-4-8","b":5,"l":4,"k":"","t":{"es":"A supera con mucho a B","en":"A far exceeds B","ens":"A far exceeds B","tc":"A遠遠超過B","sc":"A远远超过B"},"d":{"es":"A 遠遠超過 B = A supera con mucho a B. 遠遠 indica una gran diferencia y 超過 'sobrepasar'. B suele ser un estándar, una expectativa o una capacidad.","en":"A 遠遠超過 B means 'A far exceeds B'. 遠遠 stresses a big gap and 超過 is 'exceed'. B is often a standard, expectation or ability.","tc":"「遠遠」表示差距很大，「超過」是高於、多於。這個句型說明 A 比 B 高出很多，B 常是標準、預期或能力。","sc":"「远远」表示差距很大，「超过」是高于、多于。这个句型说明 A 比 B 高出很多，B 常是标准、预期或能力。"},"ex":[{"c":"業務經理對這份工作的要求遠遠超過我的能力，看來，現在該是另謀發展的時候了。","s":"业务经理对这份工作的要求远远超过我的能力，看来，现在该是另谋发展的时候了。","es":"Las exigencias del gerente de ventas para este puesto superan con mucho mi capacidad; parece que ya es hora de buscar otro camino.","en":"The sales manager's requirements for this job far exceed my abilities; it seems it is time to look for opportunities elsewhere.","p":"yè wù jīng lǐ duì zhè fèn gōng zuò de yào qiú yuǎn yuǎn chāo guò wǒ de néng lì, kàn lái, xiàn zài gāi shì lìng móu fā zhǎn de shí hòu le."},{"c":"這次的報名人數遠遠超過我們的預期。","s":"这次的报名人数远远超过我们的预期。","es":"El número de inscritos esta vez supera con mucho lo que esperábamos.","en":"The number of sign-ups this time far exceeds our expectations.","p":"zhè cì de bào míng rén shù yuǎn yuǎn chāo guò wǒ men de yù qí."}]},{"id":"5-5-0","b":5,"l":5,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No tener más remedio / verse obligado a…","en":"To have no choice but to…","ens":"To have no choice but to…","tc":"不得已…","sc":"不得已…"},"d":{"es":"不得已 = no tener más remedio, verse obligado. Se puede usar como adjetivo (是不得已的事) o delante del verbo, con 只好: 不得已只好… = no queda más remedio que….","en":"不得已 means 'having no choice', not by one's own wish. It can be used as 是不得已的事 or before a verb, often with 只好: 不得已只好… 'had no choice but to…'.","tc":"「不得已」是沒有辦法、不是自己願意的。可以說「是不得已的事」，也可以放在動詞前，常搭配「只好」：不得已只好…。","sc":"「不得已」是没有办法、不是自己愿意的。可以说「是不得已的事」，也可以放在动词前，常搭配「只好」：不得已只好…。"},"ex":[{"c":"家明為了改善家裡的生活，休學去工作是不得已的事。","s":"家明为了改善家里的生活，休学去工作是不得已的事。","es":"Jiaming, para mejorar la vida de su familia, dejó los estudios para trabajar; no tuvo otro remedio.","en":"To improve his family's life, Jiaming had no choice but to take a leave from school and go to work.","p":"jiā míng wèi le gǎi shàn jiā lǐ de shēng huó, xiū xué qù gōng zuò shì bù dé yǐ de shì."},{"c":"儘管很多人反對，可是為了使國家退休金制度符合公平正義，政府不得已只好刪減軍、公、教人員的退休金。","s":"尽管很多人反对，可是为了使国家退休金制度符合公平正义，政府不得已只好删减军、公、教人员的退休金。","es":"Aunque mucha gente se oponía, para que el sistema de pensiones del país fuera justo y equitativo, el gobierno no tuvo más remedio que recortar las pensiones de militares, funcionarios y docentes.","en":"Although many people opposed it, in order to make the national pension system fair and just, the government had no choice but to cut the pensions of military, civil-service and teaching personnel.","p":"jǐn guǎn hěn duō rén fǎn duì, kě shì wèi le shǐ guó jiā tuì xiū jīn zhì dù fú hé gōng píng zhèng yì, zhèng fǔ bù dé yǐ zhǐ hǎo shān jiǎn jūn, gōng, jiào rén yuán de tuì xiū jīn."}]},{"id":"5-5-1","b":5,"l":5,"k":"","t":{"es":"En cambio / mirando el otro lado","en":"By contrast, looking at the other side","ens":"By contrast, looking at the other side","tc":"反觀","sc":"反观"},"d":{"es":"反觀 = en cambio, por el contrario (si miramos el otro lado). Tras describir una situación, introduce otra que se le opone, para comparar. Registro escrito, típico de comentarios y reportajes.","en":"反觀 means 'by contrast' or 'looking at the other side'. After describing one situation it introduces the opposite one for comparison. Written register, typical of commentary and reports.","tc":"先說一個情況，再用「反觀」帶出相對、相反的情況，用來比較。是書面語，常用在評論或報導，後面常有逗號。","sc":"先说一个情况，再用「反观」带出相对、相反的情况，用来比较。是书面语，常用在评论或报导，后面常有逗号。"},"ex":[{"c":"城市的孩子教育資源豐富，下了課去補習班或參加各式各樣的活動，反觀鄉下的教育資源卻遠遠不如城市，城鄉差距越來越大。","s":"城市的孩子教育资源丰富，下了课去补习班或参加各式各样的活动，反观乡下的教育资源却远远不如城市，城乡差距越来越大。","es":"Los niños de la ciudad tienen abundantes recursos educativos y después de clase van a academias o participan en todo tipo de actividades; en cambio, los recursos educativos del campo están muy por debajo de los de la ciudad, y la brecha entre ciudad y campo es cada vez mayor.","en":"City children have abundant educational resources and go to cram schools or take part in all kinds of activities after class; by contrast, rural educational resources are far below those of the city, and the urban-rural gap keeps widening.","p":"chéng shì de hái zi jiào yù zī yuán fēng fù, xià le kè qù bǔ xí bān huò cān jiā gè shì gè yàng de huó dòng, fǎn guān xiāng xià de jiào yù zī yuán què yuǎn yuǎn bù rú chéng shì, chéng xiāng chā jù yuè lái yuè dà."},{"c":"台灣夏天又濕又熱，反觀北歐的夏天卻涼爽舒適。","s":"台湾夏天又湿又热，反观北欧的夏天却凉爽舒适。","es":"El verano en Taiwán es húmedo y caluroso; en cambio, el verano en el norte de Europa es fresco y agradable.","en":"Summers in Taiwan are humid and hot; by contrast, summers in Northern Europe are cool and comfortable.","p":"tái wān xià tiān yòu shī yòu rè, fǎn guān běi ōu de xià tiān què liáng shuǎng shū shì."}]},{"id":"5-5-2","b":5,"l":5,"k":"","t":{"es":"Siempre / desde el principio hasta ahora","en":"All along, throughout","ens":"All along, throughout","tc":"始終","sc":"始终"},"d":{"es":"始終 = siempre, desde el principio hasta ahora (o hasta el final) sin cambiar. Suele usarse con negación: 始終沒有／始終不…. Como 一直, pero más escrito y con más énfasis en que nada cambió.","en":"始終 means 'all along', from beginning to now (or to the end) without change. Often with negation (始終沒有/始終不…). Like 一直 but more written and stressing no change.","tc":"「始終」表示從開始到現在（或到最後）一直沒有變。常搭配否定「始終沒有／始終不…」，意思像「一直」，但更書面、更強調沒有改變。","sc":"「始终」表示从开始到现在（或到最后）一直没有变。常搭配否定「始终没有／始终不…」，意思像「一直」，但更书面、更强调没有改变。"},"ex":[{"c":"媒體在標題加上「？、懷疑、可能」這種模糊方式來避開責任，法律卻始終處罰不到他們。","s":"媒体在标题加上「？、怀疑、可能」这种模糊方式来避开责任，法律却始终处罚不到他们。","es":"Los medios añaden en los titulares signos como «¿?», «duda» o «posible» para eludir su responsabilidad, y aun así la ley nunca ha logrado castigarlos.","en":"The media add vague words such as '?', 'suspect' and 'possibly' to headlines to avoid responsibility, yet the law has never been able to punish them.","p":"méi tǐ zài biāo tí jiā shàng 「?, huái yí, kě néng」 zhè zhǒng mó hú fāng shì lái bì kāi zé rèn, fǎ lǜ què shǐ zhōng chǔ fá bú dào tā men."},{"c":"他始終沒有告訴我真正的原因。","s":"他始终没有告诉我真正的原因。","es":"Él nunca me dijo la verdadera razón.","en":"He never told me the real reason.","p":"tā shǐ zhōng méi yǒu gào sù wǒ zhēn zhèng de yuán yīn."}]},{"id":"5-5-3","b":5,"l":5,"k":"","t":{"es":"Tanto A como B","en":"Both A and B","ens":"Both A and B","tc":"既A，也B","sc":"既A，也B"},"d":{"es":"既 A，也 B = tanto A como B; a la vez A y B. Une dos cualidades o hechos que coexisten, normalmente adjetivos o verbos; suena algo escrito. También existe 既…又…. A y B suelen apuntar en la misma dirección (ambos buenos o ambos malos).","en":"既 A，也 B means 'both A and B', joining two qualities or facts that coexist, usually adjectives or verbs, with a somewhat written feel. 既…又… is similar. A and B usually point the same way (both good or both bad).","tc":"表示同時具備兩個特點或兩件事，常連接兩個形容詞或動詞，書面感較強。也可說「既…又…」。A、B 通常是同一方向的好處或壞處。","sc":"表示同时具备两个特点或两件事，常连接两个形容词或动词，书面感较强。也可说「既…又…」。A、B 通常是同一方向的好处或坏处。"},"ex":[{"c":"捷運站附近的「張家牛肉麵」，既美味，價錢也合理。","s":"捷运站附近的「张家牛肉面」，既美味，价钱也合理。","es":"El «Zhang Niu Rou Mian» cerca de la estación del metro es sabroso y además su precio es razonable.","en":"Near the MRT station, 'Zhang's Beef Noodles' is both delicious and reasonably priced.","p":"jié yùn zhàn fù jìn de 「zhāng jiā niú ròu miàn」, jì měi wèi, jià qián yě hé lǐ."},{"c":"這家餐廳既乾淨，環境也很安靜。","s":"这家餐厅既干净，环境也很安静。","es":"Este restaurante es limpio y, además, el ambiente es muy tranquilo.","en":"This restaurant is clean and its atmosphere is quiet too.","p":"zhè jiā cān tīng jì gān jìng, huán jìng yě hěn ān jìng."}]},{"id":"5-5-4","b":5,"l":5,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Es verdad que A, pero B","en":"Granted A, but B","ens":"Granted A, but B","tc":"…固然A但B","sc":"…固然A但B"},"d":{"es":"…固然 A 但 B = es cierto que A, pero B. 固然 concede primero que A es verdad o un hecho, y luego introduce con 但 / 但是 / 也 la idea que se quiere subrayar, B. Como 雖然…但是…, pero más escrito.","en":"…固然 A 但 B means 'it is true that A, but B'. 固然 first concedes that A is correct or a fact, then 但/但是/也 introduces B, the real point. Like 雖然…但是… but more written.","tc":"「固然」先承認 A 是對的、是事實，再用「但」「但是」「也」引出 B，真正想強調的是 B。像是「雖然 A，但是 B」，更書面。","sc":"「固然」先承认 A 是对的、是事实，再用「但」「但是」「也」引出 B，真正想强调的是 B。像是「虽然 A，但是 B」，更书面。"},"ex":[{"c":"網路科技固然給人們帶來便利，但也不該因過於使用網路而忽視人際關係。","s":"网路科技固然给人们带来便利，但也不该因过于使用网路而忽视人际关系。","es":"Es cierto que la tecnología de internet nos trae comodidad, pero no debemos descuidar las relaciones personales por usar demasiado la red.","en":"Internet technology does bring people convenience, but we shouldn't neglect interpersonal relationships by overusing the internet.","p":"wǎng lù kē jì gù rán gěi rén men dài lái biàn lì, dàn yě bù gāi yīn guò yú shǐ yòng wǎng lù ér hū shì rén jì guān xì."},{"c":"學歷固然重要，但經驗也同樣重要。","s":"学历固然重要，但经验也同样重要。","es":"Es verdad que el título es importante, pero la experiencia también lo es.","en":"Educational background is important, to be sure, but experience is just as important.","p":"xué lì gù rán zhòng yào, dàn jīng yàn yě tóng yàng zhòng yào."}]},{"id":"5-5-5","b":5,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"En cuanto a… / por lo que respecta a…","en":"As far as … is concerned","ens":"As far as … is concerned","tc":"就…而言","sc":"就…而言"},"d":{"es":"就…而言 = en cuanto a…, por lo que respecta a…. Tras 就 va el ámbito o el punto de vista desde el que se hace la valoración; luego sigue un juicio o conclusión. Frecuente en textos formales.","en":"就…而言 means 'as far as… is concerned'. After 就 comes the scope or angle from which the judgment is made, followed by a conclusion. Common in formal writing.","tc":"「就」後面放一個範圍或角度，表示只從這個角度來說、評價。常用「就 A 而言」，後面接判斷或結論。書面、正式說明常見。","sc":"「就」后面放一个范围或角度，表示只从这个角度来说、评价。常用「就 A 而言」，后面接判断或结论。书面、正式说明常见。"},"ex":[{"c":"外國人學習中文，就寫漢字而言，是比學習其他語言難一些。","s":"外国人学习中文，就写汉字而言，是比学习其他语言难一些。","es":"Para los extranjeros que estudian chino, en cuanto a escribir caracteres, es algo más difícil que aprender otros idiomas.","en":"For foreigners learning Chinese, writing Chinese characters is somewhat harder than learning other languages.","p":"wài guó rén xué xí zhōng wén, jiù xiě hàn zì ér yán, shì bǐ xué xí qí tā yǔ yán nán yì xiē."},{"c":"就價格而言，這家店比別家便宜。","s":"就价格而言，这家店比别家便宜。","es":"En cuanto al precio, esta tienda es más barata que las demás.","en":"As far as price is concerned, this shop is cheaper than the others.","p":"jiù jià gé ér yán, zhè jiā diàn bǐ bié jiā pián yí."}]},{"id":"5-5-6","b":5,"l":5,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Definitivamente no es algo que…","en":"Is definitely not something that…","ens":"Is definitely not something that…","tc":"絕對不是…的","sc":"绝对不是…的"},"d":{"es":"絕對不是…的 = definitivamente no es algo que…. Combina la estructura 是…的 con 絕對 para negar con mucha fuerza; sirve para corregir una idea, p. ej. 'X no es algo que se pueda conseguir con Y'.","en":"絕對不是…的 means 'is definitely not something that…'. It uses the 是…的 frame with 絕對 for a very strong denial, often to correct an idea, e.g. 'X is not something Y can buy'.","tc":"用「是…的」句型加強語氣，「絕對」表示完全否定。常用來糾正想法，說明某事物不是靠某種方法或條件就能得到，例如「…絕對不是…能夠…的」。","sc":"用「是…的」句型加强语气，「绝对」表示完全否定。常用来纠正想法，说明某事物不是靠某种方法或条件就能得到，例如「…绝对不是…能够…的」。"},"ex":[{"c":"俗話說得好「金錢不是萬能的」。也就是說，有些東西，比方說，「愛情」絕對不是金錢能夠買到的。","s":"俗话说得好「金钱不是万能的」。也就是说，有些东西，比方说，「爱情」绝对不是金钱能够买到的。","es":"Como dice el refrán, «el dinero no lo puede todo». Es decir, hay cosas, por ejemplo, «el amor», que definitivamente el dinero no puede comprar.","en":"As the saying goes, 'money isn't everything'. In other words, some things, for example 'love', are definitely not something money can buy.","p":"sú huà shuō de hǎo 「jīn qián bú shì wàn néng de」. yě jiù shì shuō, yǒu xiē dōng xi, bǐ fāng shuō, 「ài qíng」 jué duì bú shì jīn qián néng gòu mǎi dào de."},{"c":"健康絕對不是靠吃藥就能換來的。","s":"健康绝对不是靠吃药就能换来的。","es":"La salud definitivamente no se consigue solo tomando medicinas.","en":"Health is definitely not something you can get just by taking medicine.","p":"jiàn kāng jué duì bú shì kào chī yào jiù néng huàn lái de."}]},{"id":"5-6-0","b":5,"l":6,"k":"","t":{"es":"Desde la postura de…","en":"From the standpoint of…","ens":"From the standpoint of…","tc":"站在…的立場","sc":"站在…的立场"},"d":{"es":"站在 X 的立場 = ponerse en el lugar de X, ver el asunto desde su posición. Suele ir con 考慮／想／看 y es de registro algo formal; no significa «estar de pie en un lugar».","en":"站在…的立場 means to look at an issue from someone's position and way of thinking. It is often followed by verbs like 考慮, 想 or 看 and is somewhat formal.","tc":"「站在…的立場」是「從某人的位置和想法來看事情」，常接「考慮、想、看」，語氣偏正式。","sc":"「站在…的立场」是「从某人的位置和想法来看事情」，常接「考虑、想、看」，语气偏正式。"},"ex":[{"c":"企業合作時，必須能站在對方的立場考慮問題，才能達到雙贏。","s":"企业合作时，必须能站在对方的立场考虑问题，才能达到双赢。","es":"En una colaboración entre empresas hay que poder ponerse en el lugar de la otra parte para llegar a un beneficio mutuo.","en":"In business cooperation, you must be able to consider problems from the other side's standpoint in order to achieve a win-win.","p":"qì yè hé zuò shí, bì xū néng zhàn zài duì fāng de lì chǎng kǎo lǜ wèn tí, cái néng dá dào shuāng yíng."},{"c":"父母應該站在孩子的立場想一想，不要只用自己的標準要求他們。","s":"父母应该站在孩子的立场想一想，不要只用自己的标准要求他们。","es":"Los padres deberían ponerse en el lugar de sus hijos y no exigirles solo con sus propios criterios.","en":"Parents should think from their children's standpoint instead of demanding things of them by their own standards alone.","p":"fù mǔ yīng gāi zhàn zài hái zi de lì chǎng xiǎng yì xiǎng, bú yào zhǐ yòng zì jǐ de biāo zhǔn yào qiú tā men."}]},{"id":"5-6-1","b":5,"l":6,"k":"","t":{"es":"Tomar … como ejemplo","en":"Take … as an example","ens":"Take … as an example","tc":"以…為例","sc":"以…为例"},"d":{"es":"以 X 為例 = tomando X como ejemplo. Se usa después de una afirmación general para dar un caso concreto; suele ir al inicio de la oración, seguido de coma. Es más formal que 比如說.","en":"以…為例 introduces a concrete example after a general statement. It usually comes at the beginning of a sentence followed by a comma.","tc":"「以…為例」用在說明一般情況之後，舉出一個具體的例子，通常放在句首，後面加逗號。","sc":"「以…为例」用在说明一般情况之后，举出一个具体的例子，通常放在句首，后面加逗号。"},"ex":[{"c":"法律規定不可以有性別歧視。以找工作為例，不能在廣告上限制性別。","s":"法律规定不可以有性别歧视。以找工作为例，不能在广告上限制性别。","es":"La ley prohíbe la discriminación de género. Tomemos como ejemplo la búsqueda de empleo: no se puede limitar el género en los anuncios.","en":"The law forbids gender discrimination. Take job hunting as an example: you cannot restrict gender in job ads.","p":"fǎ lǜ guī dìng bù kě yǐ yǒu xìng bié qí shì. yǐ zhǎo gōng zuò wéi lì, bù néng zài guǎng gào shàng xiàn zhì xìng bié."},{"c":"台灣的夜市文化很有特色。以士林夜市為例，每天都有許多觀光客前往。","s":"台湾的夜市文化很有特色。以士林夜市为例，每天都有许多观光客前往。","es":"La cultura de los mercados nocturnos de Taiwán es muy peculiar. Tomando como ejemplo el mercado nocturno de Shilin, cada día lo visitan muchos turistas.","en":"Taiwan's night market culture is distinctive. Take Shilin Night Market as an example: many tourists go there every day.","p":"tái wān de yè shì wén huà hěn yǒu tè sè. yǐ shì lín yè shì wéi lì, měi tiān dōu yǒu xǔ duō guān guāng kè qián wǎng."}]},{"id":"5-6-2","b":5,"l":6,"k":"","t":{"es":"En otras palabras","en":"In other words","ens":"In other words","tc":"換句話說","sc":"换句话说"},"d":{"es":"換句話說 = en otras palabras, dicho de otro modo. Reformula o aclara lo dicho antes; va al inicio de la segunda oración, seguido de coma. Aparece tanto en habla como en escritura.","en":"換句話說 restates the previous idea in different words. It is placed at the start of the next sentence, followed by a comma.","tc":"「換句話說」用另一種說法重新解釋前面的話，放在後一句句首，後面加逗號。","sc":"「换句话说」用另一种说法重新解释前面的话，放在后一句句首，后面加逗号。"},"ex":[{"c":"阿月退休後就養隻貓當寵物，離鄉的孩子只有過年才回去看她。換句話說，平常的日子她都自己一個人。","s":"阿月退休后就养只猫当宠物，离乡的孩子只有过年才回去看她。换句话说，平常的日子她都自己一个人。","es":"Tras jubilarse, A-Yue adoptó un gato como mascota, y sus hijos, que viven lejos, solo la visitan en Año Nuevo. En otras palabras, el resto del año está sola.","en":"After retiring, A-Yue got a cat as a pet, and her children who live far away only visit her at Chinese New Year. In other words, she is on her own the rest of the time.","p":"ā yuè tuì xiū hòu jiù yǎng zhī māo dāng chǒng wù, lí xiāng de hái zi zhǐ yǒu guò nián cái huí qù kàn tā. huàn jù huà shuō, píng cháng de rì zi tā dōu zì jǐ yí ge rén."},{"c":"這家餐廳只接受預約。換句話說，沒有訂位就吃不到。","s":"这家餐厅只接受预约。换句话说，没有订位就吃不到。","es":"Este restaurante solo acepta reservaciones. En otras palabras, sin reservar no puedes comer ahí.","en":"This restaurant only takes reservations. In other words, you can't eat there without booking.","p":"zhè jiā cān tīng zhǐ jiē shòu yù yuē. huàn jù huà shuō, méi yǒu dìng wèi jiù chī bú dào."}]},{"id":"5-6-3","b":5,"l":6,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 dirección movimiento direction movement 方向 趨向 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 dirección movimiento direction movement 方向 趋向","t":{"es":"Comparado con A, B es más…","en":"Compared with A, B is more…","ens":"Compared with A, B is more…","tc":"和A比起來，B比較…","sc":"和A比起来，B比较…"},"d":{"es":"和 A 比起來，B 比較… = comparado con A, B es más…. «比起來» introduce el punto de referencia y el adjetivo va con 比較／更／得多, no con 比 otra vez. Se puede sustituir por 相較於 (más formal), como en el ejemplo.","en":"和A比起來，B比較… compares B against A as a reference point; the predicate usually uses 比較, 更 or …得多. 相較於 is a more formal alternative with a similar meaning.","tc":"「和A比起來，B比較…」用A當標準來比較B，後面常接「比較、更、…得多」；「相較於」比較正式，意思相近。","sc":"「和A比起来，B比较…」用A当标准来比较B，后面常接「比较、更、…得多」；「相较于」比较正式，意思相近。"},"ex":[{"c":"相較於歐美的物價，這裡的食物則是便宜很多。","s":"相较于欧美的物价，这里的食物则是便宜很多。","es":"Comparada con los precios de Europa y América, la comida aquí es mucho más barata.","en":"Compared with prices in Europe and America, food here is much cheaper.","p":"xiāng jiào yú ōu měi de wù jià, zhè lǐ de shí wù zé shì pián yí hěn duō."},{"c":"和去年比起來，今年夏天熱得多。","s":"和去年比起来，今年夏天热得多。","es":"Comparado con el año pasado, este verano hace mucho más calor.","en":"Compared with last year, this summer is much hotter.","p":"hé qù nián bǐ qǐ lái, jīn nián xià tiān rè de duō."}]},{"id":"5-6-4","b":5,"l":6,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"A menos que A, de lo contrario B","en":"Unless A, otherwise B","ens":"Unless A, otherwise B","tc":"除非A，不然B","sc":"除非A，不然B"},"d":{"es":"除非 A，不然 B = a menos que ocurra A, de lo contrario B. A es la única condición para evitar B, y B suele ser un resultado negativo. «不然» puede cambiarse por 否則 (más formal).","en":"除非A，不然B means B will happen unless A is met; A is the only way to avoid B, and B is usually a bad outcome. 不然 can be replaced by the more formal 否則.","tc":"「除非A，不然B」表示只有做到A才能避免B，B通常是不好的結果；「不然」可換成較正式的「否則」。","sc":"「除非A，不然B」表示只有做到A才能避免B，B通常是不好的结果；「不然」可换成较正式的「否则」。"},"ex":[{"c":"他的電腦中了勒索病毒，所有的資料都被鎖起來了。現在除非在一個星期內付對方錢，不然就永遠打不開。","s":"他的电脑中了勒索病毒，所有的资料都被锁起来了。现在除非在一个星期内付对方钱，不然就永远打不开。","es":"Su computadora fue infectada con un virus de secuestro de datos y toda la información quedó bloqueada. Ahora, a menos que pague en una semana, nunca podrá abrirla.","en":"His computer was infected by ransomware and all the data has been locked. Unless he pays within a week, it will never open again.","p":"tā de diàn nǎo zhōng le lè suǒ bìng dú, suǒ yǒu de zī liào dōu bèi suǒ qǐ lái le. xiàn zài chú fēi zài yí ge xīng qí nèi fù duì fāng qián, bù rán jiù yǒng yuǎn dǎ bù kāi."},{"c":"除非你現在出發，不然趕不上最後一班火車。","s":"除非你现在出发，不然赶不上最后一班火车。","es":"A menos que salgas ahora, no alcanzarás el último tren.","en":"Unless you leave now, you won't catch the last train.","p":"chú fēi nǐ xiàn zài chū fā, bù rán gǎn bú shàng zuì hòu yì bān huǒ chē."}]},{"id":"5-6-5","b":5,"l":6,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Verse / parecer (por contraste)","en":"To appear / look (in contrast)","ens":"To appear / look (in contrast)","tc":"顯得＋VP/S","sc":"显得＋VP/S"},"d":{"es":"顯得 = verse, parecer, dar la impresión de. Describe la impresión que algo o alguien da por la situación o por contraste; va seguido de adjetivo o verbo y suele llevar 特別／很／格外. No se usa para opiniones personales («yo creo que»).","en":"顯得 means to look or appear a certain way because of the situation or by contrast. It is followed by an adjective or verb and often used with 特別, 很 or 格外.","tc":"「顯得」表示因為情況或對比，而給人某種樣子或印象，後面接形容詞或動詞，常搭配「特別、很、格外」。","sc":"「显得」表示因为情况或对比，而给人某种样子或印象，后面接形容词或动词，常搭配「特别、很、格外」。"},"ex":[{"c":"他第一次參加演講比賽，相較於其他有經驗的參賽者，顯得特別緊張。","s":"他第一次参加演讲比赛，相较于其他有经验的参赛者，显得特别紧张。","es":"Era su primera vez en un concurso de oratoria y, comparado con los demás participantes con experiencia, se le veía especialmente nervioso.","en":"It was his first speech contest, and compared with the other experienced contestants he looked especially nervous.","p":"tā dì yī cì cān jiā yǎn jiǎng bǐ sài, xiāng jiào yú qí tā yǒu jīng yàn de cān sài zhě, xiǎn dé tè bié jǐn zhāng."},{"c":"他穿上西裝，顯得比平常成熟。","s":"他穿上西装，显得比平常成熟。","es":"Con el traje puesto, se ve más maduro que de costumbre.","en":"In a suit, he looks more mature than usual.","p":"tā chuān shàng xī zhuāng, xiǎn dé bǐ píng cháng chéng shóu."}]},{"id":"5-6-6","b":5,"l":6,"k":"","t":{"es":"Tener el lado de…","en":"To have a … side","ens":"To have a … side","tc":"有…的一面","sc":"有…的一面"},"d":{"es":"有…的一面 = tener un lado/aspecto… Sirve para presentar una faceta de algo, a menudo en pares: 有好的一面，也有壞的一面. Es neutral y común en textos argumentativos.","en":"有…的一面 presents one side or aspect of something and is often used in pairs, such as 有好的一面，也有壞的一面. It is common in argumentative writing.","tc":"「有…的一面」用來說明事情的某一個方面，常成對使用，例如「有好的一面，也有壞的一面」，常見於議論文。","sc":"「有…的一面」用来说明事情的某一个方面，常成对使用，例如「有好的一面，也有坏的一面」，常见于议论文。"},"ex":[{"c":"廢除死刑這個議題，因為有好的一面，也有壞的一面，沒有一定的答案，所以產生極大的爭議。","s":"废除死刑这个议题，因为有好的一面，也有坏的一面，没有一定的答案，所以产生极大的争议。","es":"El tema de abolir la pena de muerte tiene un lado bueno y uno malo, no hay una respuesta fija y por eso genera una gran controversia.","en":"The issue of abolishing the death penalty has both a good side and a bad side with no fixed answer, so it causes great controversy.","p":"fèi chú sǐ xíng zhè ge yì tí, yīn wèi yǒu hǎo de yí miàn, yě yǒu huài de yí miàn, méi yǒu yí dìng de dá àn, suǒ yǐ chǎn shēng jí dà de zhēng yì."},{"c":"網路有方便的一面，也有讓人上癮的一面。","s":"网路有方便的一面，也有让人上瘾的一面。","es":"Internet tiene un lado práctico y también uno que causa adicción.","en":"The internet has a convenient side, but also a side that can be addictive.","p":"wǎng lù yǒu fāng biàn de yí miàn, yě yǒu ràng rén shàng yǐn de yí miàn."}]},{"id":"5-6-7","b":5,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Es decir","en":"That is to say","ens":"That is to say","tc":"也就是說","sc":"也就是说"},"d":{"es":"也就是說 = es decir, o sea. Saca una conclusión o aclara el significado a partir de lo anterior (a veces con un cálculo). Se diferencia de 換句話說, que solo reformula; 也就是說 suele ir seguido del resultado.","en":"也就是說 draws a conclusion or clarification from what was just said, often after a calculation. It differs slightly from 換句話說, which only restates.","tc":"「也就是說」根據前面的內容做出結論或解釋，常接計算或推論的結果；和只重新說明的「換句話說」稍有不同。","sc":"「也就是说」根据前面的内容做出结论或解释，常接计算或推论的结果；和只重新说明的「换句话说」稍有不同。"},"ex":[{"c":"「光」每秒可走30萬公里，「一光年」是「光」走一年的距離。而地球距離月亮約38萬公里，也就是說，月光只要約1.3秒的時間就傳到地球了。","s":"「光」每秒可走30万公里，「一光年」是「光」走一年的距离。而地球距离月亮约38万公里，也就是说，月光只要约1.3秒的时间就传到地球了。","es":"La luz recorre 300 000 km por segundo, y un año luz es la distancia que recorre en un año. La Tierra está a unos 380 000 km de la Luna; es decir, la luz lunar tarda solo 1.3 segundos en llegar a la Tierra.","en":"Light travels 300,000 km per second, and a light-year is the distance light travels in a year. The Moon is about 380,000 km from Earth, which means moonlight reaches Earth in only about 1.3 seconds.","p":"「guāng」 měi miǎo kě zǒu3 0 wàn gōng lǐ, 「yì guāng nián」 shì 「guāng」 zǒu yì nián de jù lí. ér dì qiú jù lí yuè liàng yuē3 8 wàn gōng lǐ, yě jiù shì shuō, yuè guāng zhǐ yào yuē1. 3 miǎo de shí jiān jiù chuán dào dì qiú le."},{"c":"這家店每週休息兩天，也就是說，一個月只營業二十二天左右。","s":"这家店每周休息两天，也就是说，一个月只营业二十二天左右。","es":"Esta tienda descansa dos días por semana; es decir, abre solo unos veintidós días al mes.","en":"This shop closes two days a week, which means it is open only about twenty-two days a month.","p":"zhè jiā diàn měi zhōu xiū xí liǎng tiān, yě jiù shì shuō, yí ge yuè zhǐ yíng yè èr shí èr tiān zuǒ yòu."}]},{"id":"5-6-8","b":5,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Solo si A, entonces B","en":"Only if A, then B","ens":"Only if A, then B","tc":"唯有A，才B","sc":"唯有A，才B"},"d":{"es":"唯有 A，才 B = solo si A, entonces B. Equivale a 只有 A 才 B, pero es más enfático y de registro escrito/formal. «才» es obligatorio en la segunda parte.","en":"唯有A，才B is the same as 只有A才B but more emphatic and literary. 才 is required in the second clause.","tc":"「唯有A，才B」和「只有A才B」意思相同，但語氣更強、較書面，後半句要用「才」。","sc":"「唯有A，才B」和「只有A才B」意思相同，但语气更强、较书面，后半句要用「才」。"},"ex":[{"c":"唯有注意飲食、保持運動的習慣，才能有健康的身體。","s":"唯有注意饮食、保持运动的习惯，才能有健康的身体。","es":"Solo cuidando la alimentación y manteniendo el hábito de hacer ejercicio se puede tener un cuerpo sano.","en":"Only by watching your diet and keeping up the habit of exercising can you have a healthy body.","p":"wéi yǒu zhù yì yǐn shí, bǎo chí yùn dòng de xí guàn, cái néng yǒu jiàn kāng de shēn tǐ."},{"c":"唯有不斷練習，才能把中文說得流利。","s":"唯有不断练习，才能把中文说得流利。","es":"Solo practicando sin parar se puede hablar chino con fluidez.","en":"Only by practicing constantly can you speak Chinese fluently.","p":"wéi yǒu bú duàn liàn xí, cái néng bǎ zhōng wén shuō de liú lì."}]},{"id":"5-7-0","b":5,"l":7,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Romperse la cabeza por…","en":"To rack one's brains over…","ens":"To rack one's brains over…","tc":"為了…傷腦筋","sc":"为了…伤脑筋"},"d":{"es":"為了 X 傷腦筋 = preocuparse / romperse la cabeza por X. 傷腦筋 es coloquial y significa «dar dolor de cabeza» (un problema difícil de resolver). X es el asunto que preocupa.","en":"為了…傷腦筋 means to rack one's brains or be troubled over something. 傷腦筋 is colloquial for 'giving someone a headache'.","tc":"「為了…傷腦筋」表示為了某件事想不出好辦法、很煩惱，「傷腦筋」是口語說法。","sc":"「为了…伤脑筋」表示为了某件事想不出好办法、很烦恼，「伤脑筋」是口语说法。"},"ex":[{"c":"林小姐下個月得參加一場正式的宴會，現在她為了當天得怎麼打扮、要穿什麼禮服而傷腦筋。","s":"林小姐下个月得参加一场正式的宴会，现在她为了当天得怎么打扮、要穿什么礼服而伤脑筋。","es":"La señorita Lin debe asistir el próximo mes a una fiesta formal y ahora se rompe la cabeza pensando cómo arreglarse y qué vestido ponerse ese día.","en":"Miss Lin has to attend a formal banquet next month, and she is now racking her brains over how to dress and which gown to wear.","p":"lín xiǎo jiě xià gè yuè dé cān jiā yì chǎng zhèng shì de yàn huì, xiàn zài tā wèi le dāng tiān dé zěn me dǎ bàn, yào chuān shén me lǐ fú ér shāng nǎo jīn."},{"c":"爸媽為了孩子的教育費用傷腦筋。","s":"爸妈为了孩子的教育费用伤脑筋。","es":"Los padres se preocupan mucho por el costo de la educación de sus hijos.","en":"The parents are worried sick about their children's education costs.","p":"bà mā wèi le hái zi de jiào yù fèi yòng shāng nǎo jīn."}]},{"id":"5-7-1","b":5,"l":7,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No como A, sino B","en":"Not like A, but B","ens":"Not like A, but B","tc":"不像A，而是B","sc":"不像A，而是B"},"d":{"es":"不像 A，而是 B = no como A, sino B. Contrasta la forma o el modo: A es lo esperado o habitual y B es lo que realmente ocurre. «而是» introduce la corrección.","en":"不像A，而是B contrasts what is usual or expected (A) with what is actually the case (B). 而是 introduces the correction.","tc":"「不像A，而是B」用A（一般的、大家以為的）和B（實際的）作對比，「而是」帶出真正的情況。","sc":"「不像A，而是B」用A（一般的、大家以为的）和B（实际的）作对比，「而是」带出真正的情况。"},"ex":[{"c":"小陳的日文很好，但其實小陳不像一般人花錢去語言中心學，而是在家聽著流行歌學的。","s":"小陈的日文很好，但其实小陈不像一般人花钱去语言中心学，而是在家听着流行歌学的。","es":"El japonés de Chen es muy bueno, pero en realidad no lo aprendió como la mayoría, pagando en un centro de idiomas, sino escuchando canciones pop en casa.","en":"Chen's Japanese is very good, but he didn't learn it the way most people do by paying for a language center; he learned it at home listening to pop songs.","p":"xiǎo chén de rì wén hěn hǎo, dàn qí shí xiǎo chén bú xiàng yì bān rén huā qián qù yǔ yán zhōng xīn xué, ér shì zài jiā tīng zhe liú xíng gē xué de."},{"c":"他不像哥哥那樣愛說話，而是比較安靜害羞。","s":"他不像哥哥那样爱说话，而是比较安静害羞。","es":"No es hablador como su hermano mayor, sino más bien callado y tímido.","en":"He is not talkative like his older brother, but rather quiet and shy.","p":"tā bú xiàng gē ge nà yàng ài shuō huà, ér shì bǐ jiào ān jìng hài xiū."}]},{"id":"5-7-2","b":5,"l":7,"k":"","t":{"es":"A equivale a B","en":"A is equivalent to B","ens":"A is equivalent to B","tc":"A等同於B","sc":"A等同于B"},"d":{"es":"A 等同於 B = A equivale a B, es lo mismo que B. Es formal y a menudo expresa un juicio fuerte (por ejemplo, «X equivale a un suicidio»). Más neutro que 無異於, que es más retórico.","en":"A等同於B means A is the same as B. It is formal and often used for strong judgments.","tc":"「A等同於B」表示A和B相同、沒有差別，語氣正式，常用來下很強的判斷。","sc":"「A等同于B」表示A和B相同、没有差别，语气正式，常用来下很强的判断。"},"ex":[{"c":"專家說長期又喝酒又抽菸等同於慢性自殺。","s":"专家说长期又喝酒又抽烟等同于慢性自杀。","es":"Los expertos dicen que beber y fumar a largo plazo equivale a un suicidio lento.","en":"Experts say that drinking and smoking over a long period is equivalent to slow suicide.","p":"zhuān jiā shuō cháng qí yòu hē jiǔ yòu chōu yān děng tóng yú màn xìng zì shā."},{"c":"小明打傷了同學，對方父母打算告小明，小明的父親知道後急著去跟對方說，坐牢等同於毀了這個孩子的人生，希望對方能給小明一次機會。","s":"小明打伤了同学，对方父母打算告小明，小明的父亲知道后急着去跟对方说，坐牢等同于毁了这个孩子的人生，希望对方能给小明一次机会。","es":"Xiaoming lastimó a un compañero y los padres de este pensaban denunciarlo. Al enterarse, su padre fue de inmediato a decirles que ir a la cárcel equivale a arruinar la vida del muchacho y les pidió darle otra oportunidad.","en":"Xiaoming injured a classmate, and the classmate's parents planned to sue him. When Xiaoming's father found out, he hurried to tell them that going to prison would be equivalent to ruining the boy's life, and begged them to give Xiaoming another chance.","p":"xiǎo míng dǎ shāng le tóng xué, duì fāng fù mǔ dǎ suàn gào xiǎo míng, xiǎo míng de fù qīn zhī dào hòu jí zhe qù gēn duì fāng shuō, zuò láo děng tóng yú huǐ le zhè ge hái zi de rén shēng, xī wàng duì fāng néng gěi xiǎo míng yí cì jī huì."}]},{"id":"5-7-3","b":5,"l":7,"k":"tiempo momento orden secuencia time order sequence 時間 順序 causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 tiempo momento orden secuencia time order sequence 时间 顺序 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"La razón por la que A… radica en B","en":"The reason A … lies in B","ens":"The reason A … lies in B","tc":"A之所以…就在於B","sc":"A之所以…就在于B"},"d":{"es":"A 之所以… 就在於 B = la razón por la que A…, radica en B. «之所以» presenta el resultado y «在於» la causa. Es formal y se usa en explicaciones; no se puede usar «因為» en la misma estructura.","en":"A之所以…就在於B states a result first (之所以) and then its reason (在於). It is formal and used for explanations.","tc":"「A之所以…，就在於B」先說結果（A…），再說原因（B），語氣正式，常用在解釋原因。","sc":"「A之所以…，就在于B」先说结果（A…），再说原因（B），语气正式，常用在解释原因。"},"ex":[{"c":"看了那個企業家的自傳後才明白，他之所以那麼成功，就在於他對待人們的態度。","s":"看了那个企业家的自传后才明白，他之所以那么成功，就在于他对待人们的态度。","es":"Después de leer la autobiografía de ese empresario entendí que la razón de su éxito radica en cómo trata a la gente.","en":"After reading that entrepreneur's autobiography, I understood that the reason he is so successful lies in his attitude toward people.","p":"kàn le nà ge qì yè jiā de zì zhuàn hòu cái míng bái, tā zhī suǒ yǐ nà me chéng gōng, jiù zài yú tā duì dài rén men de tài dù."},{"c":"這個城市之所以吸引人，就在於它兼具傳統與現代。","s":"这个城市之所以吸引人，就在于它兼具传统与现代。","es":"Lo que hace atractiva a esta ciudad es que combina lo tradicional con lo moderno.","en":"The reason this city is so appealing lies in how it combines tradition and modernity.","p":"zhè ge chéng shì zhī suǒ yǐ xī yǐn rén, jiù zài yú tā jiān jù chuán tǒng yǔ xiàn dài."}]},{"id":"5-7-4","b":5,"l":7,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 dirección movimiento direction movement 方向 趨向 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在 dirección movimiento direction movement 方向 趋向","t":{"es":"Desde la perspectiva de… (analizar)","en":"From the perspective of… (+V)","ens":"From the perspective of… (+V)","tc":"從…的角度來+V","sc":"从…的角度来+V"},"d":{"es":"從 X 的角度來 + V = desde la perspectiva de X (ver/pensar/analizar). Los verbos habituales son 看、想、思考、分析. Presenta el punto de vista desde el que se juzga algo; es de registro formal.","en":"從…的角度來+V states the viewpoint from which something is seen. Common verbs are 看, 想, 思考 and 分析.","tc":"「從…的角度來+V」說明從哪一個方面或立場看事情，動詞常用「看、想、思考、分析」。","sc":"「从…的角度来+V」说明从哪一个方面或立场看事情，动词常用「看、想、思考、分析」。"},"ex":[{"c":"餐廳老闆如果能從客人的角度來思考，就會了解客人真正的需求。","s":"餐厅老板如果能从客人的角度来思考，就会了解客人真正的需求。","es":"Si el dueño del restaurante pudiera pensar desde la perspectiva del cliente, entendería lo que este realmente necesita.","en":"If restaurant owners could think from the customer's perspective, they would understand customers' real needs.","p":"cān tīng lǎo bǎn rú guǒ néng cóng kè rén de jiǎo dù lái sī kǎo, jiù huì liǎo jiě kè rén zhēn zhèng de xū qiú."},{"c":"從經濟的角度來看，這項政策並不划算。","s":"从经济的角度来看，这项政策并不划算。","es":"Desde el punto de vista económico, esta política no conviene.","en":"From an economic perspective, this policy is not worthwhile.","p":"cóng jīng jì de jiǎo dù lái kàn, zhè xiàng zhèng cè bìng bú huá suàn."}]},{"id":"5-7-5","b":5,"l":7,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Hacer B por (el fin de) A","en":"Do B for the sake of A","ens":"Do B for the sake of A","tc":"為了A而B","sc":"为了A而B"},"d":{"es":"為了 A 而 B = hacer B con el fin de A / por A. A es el propósito o motivo y B la acción. «而» conecta ambas partes y es de registro formal. Se usa mucho en negativo: 不應該為了 A 而 B.","en":"為了A而B means doing B for the sake or purpose of A. 而 is a formal connector, and the negative form 不應該為了A而B is common.","tc":"「為了A而B」表示為了A這個目的或原因，做B這件事；「而」是連接詞，語氣較正式，常用「不應該為了A而B」。","sc":"「为了A而B」表示为了A这个目的或原因，做B这件事；「而」是连接词，语气较正式，常用「不应该为了A而B」。"},"ex":[{"c":"地球上已經有很多種類的動物逐漸消失了，人們實在不應該為了滿足自己生活的享受而破壞環境。","s":"地球上已经有很多种类的动物逐渐消失了，人们实在不应该为了满足自己生活的享受而破坏环境。","es":"En la Tierra muchas especies animales ya están desapareciendo; la gente realmente no debería destruir el medio ambiente solo para satisfacer sus propios placeres.","en":"Many kinds of animals on Earth are already disappearing, and people really should not destroy the environment just to satisfy their own enjoyment.","p":"dì qiú shàng yǐ jīng yǒu hěn duō zhǒng lèi de dòng wù zhú jiàn xiāo shī le, rén men shí zài bù yīng gāi wèi le mǎn zú zì jǐ shēng huó de xiǎng shòu ér pò huài huán jìng."},{"c":"他為了照顧生病的母親而辭去工作。","s":"他为了照顾生病的母亲而辞去工作。","es":"Renunció a su trabajo para cuidar a su madre enferma.","en":"He quit his job in order to take care of his sick mother.","p":"tā wèi le zhào gù shēng bìng de mǔ qīn ér cí qù gōng zuò."}]},{"id":"5-7-6","b":5,"l":7,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Verse obligado a + V","en":"To be forced to + V","ens":"To be forced to + V","tc":"被迫＋VP","sc":"被迫＋VP"},"d":{"es":"被迫 + V = verse obligado a hacer algo. Es una pasiva sin agente: no se menciona quién obliga y el resultado es contra la voluntad del sujeto. Se usa en contextos formales o de noticias.","en":"被迫+VP means being forced to do something against one's will. The one who forces is usually not mentioned.","tc":"「被迫＋VP」表示在不得已的情況下，不得不做某事，通常不說是誰逼的，帶有違反意願的意思。","sc":"「被迫＋VP」表示在不得已的情况下，不得不做某事，通常不说是谁逼的，带有违反意愿的意思。"},"ex":[{"c":"當年政府為了國家發展收了許多土地，許多原住民被迫離開平地，搬往深山裡。","s":"当年政府为了国家发展收了许多土地，许多原住民被迫离开平地，搬往深山里。","es":"En aquella época el gobierno expropió muchas tierras para el desarrollo del país, y muchos indígenas se vieron obligados a dejar la llanura y mudarse a lo profundo de las montañas.","en":"Back then the government took a lot of land for national development, and many Indigenous people were forced to leave the plains and move deep into the mountains.","p":"dāng nián zhèng fǔ wèi le guó jiā fā zhǎn shōu le xǔ duō tǔ dì, xǔ duō yuán zhù mín bèi pò lí kāi píng dì, bān wǎng shēn shān lǐ."},{"c":"因為颱風，航班被迫取消。","s":"因为台风，航班被迫取消。","es":"Por el tifón, los vuelos tuvieron que cancelarse.","en":"Because of the typhoon, flights were forced to be cancelled.","p":"yīn wèi tái fēng, háng bān bèi pò qǔ xiāo."}]},{"id":"5-7-7","b":5,"l":7,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Si A todavía está por B","en":"Whether A still awaits B","ens":"Whether A still awaits B","tc":"是否A還有待B","sc":"是否A还有待B"},"d":{"es":"是否 A 還有待 B = si A todavía está por (ser) B. «是否» es la forma escrita de 是不是 y 有待 + verbo significa «queda pendiente de, requiere». B suele ser 觀察／研究／證實. Muy formal.","en":"是否A還有待B means whether A is true still needs B (such as observation or study). 是否 is the written form of 是不是, and 有待 means 'remains to be'.","tc":"「是否A還有待B」表示A是不是成立，還需要再B（例如觀察、研究）才能知道；「是否」是書面語，等於「是不是」。","sc":"「是否A还有待B」表示A是不是成立，还需要再B（例如观察、研究）才能知道；「是否」是书面语，等于「是不是」。"},"ex":[{"c":"這個方法目前看起來的效果不錯，但是否真的可以全面施行，還有待進一步的觀察。","s":"这个方法目前看起来的效果不错，但是否真的可以全面施行，还有待进一步的观察。","es":"Por ahora este método parece funcionar bien, pero si realmente puede aplicarse en su totalidad queda por verse con más observación.","en":"This method seems effective for now, but whether it can truly be implemented across the board still needs further observation.","p":"zhè ge fāng fǎ mù qián kàn qǐ lái de xiào guǒ bú cuò, dàn shì fǒu zhēn de kě yǐ quán miàn shī xíng, hái yǒu dài jìn yí bù de guān chá."},{"c":"這種藥是否安全，還有待更多研究證實。","s":"这种药是否安全，还有待更多研究证实。","es":"Si este medicamento es seguro todavía debe confirmarse con más estudios.","en":"Whether this drug is safe remains to be confirmed by more research.","p":"zhè zhǒng yào shì fǒu ān quán, hái yǒu dài gèng duō yán jiù zhèng shí."}]},{"id":"5-8-0","b":5,"l":8,"k":"","t":{"es":"Convertir A en B","en":"To turn A into B","ens":"To turn A into B","tc":"化A為B","sc":"化A为B"},"d":{"es":"化 A 為 B = convertir A en B. Es una estructura formal/literaria; A y B suelen ser sustantivos abstractos opuestos o relacionados (化危機為轉機, 化悲憤為力量). Pertenece sobre todo a la lengua escrita.","en":"化A為B means to transform A into B. It is literary, and A and B are usually abstract nouns, as in 化危機為轉機.","tc":"「化A為B」是把A轉變成B，語氣書面，A、B常是抽象名詞，例如「化危機為轉機」「化悲憤為力量」。","sc":"「化A为B」是把A转变成B，语气书面，A、B常是抽象名词，例如「化危机为转机」「化悲愤为力量」。"},"ex":[{"c":"俗話說「化悲憤為力量」，是希望有人在難過時，可以把負面的情緒轉成幫助前進的力量。","s":"俗话说「化悲愤为力量」，是希望有人在难过时，可以把负面的情绪转成帮助前进的力量。","es":"El dicho «convertir la tristeza e indignación en fuerza» expresa el deseo de que, cuando alguien está mal, pueda transformar esas emociones negativas en una fuerza que le ayude a avanzar.","en":"The saying 'turn grief and anger into strength' expresses the hope that when people are sad, they can turn negative emotions into strength that helps them move forward.","p":"sú huà shuō 「huà bēi fèn wéi lì liàng」, shì xī wàng yǒu rén zài nán guò shí, kě yǐ bǎ fù miàn de qíng xù zhuǎn chéng bāng zhù qián jìn de lì liàng."},{"c":"他化危機為轉機，讓公司重新站了起來。","s":"他化危机为转机，让公司重新站了起来。","es":"Convirtió la crisis en oportunidad y la empresa volvió a levantarse.","en":"He turned the crisis into an opportunity and got the company back on its feet.","p":"tā huà wéi jī wéi zhuǎn jī, ràng gōng sī chóng xīn zhàn le qǐ lái."}]},{"id":"5-8-1","b":5,"l":8,"k":"","t":{"es":"Según las estadísticas / los datos de…","en":"According to the statistics / data of…","ens":"According to the statistics / data of…","tc":"根據…的統計／根據…的資料顯示","sc":"根据…的统计／根据…的资料显示"},"d":{"es":"根據…的統計／資料顯示 = según las estadísticas (los datos) de…. Introduce la fuente de una cifra o conclusión y es muy común en noticias e informes. La parte «顯示» va antes de la conclusión.","en":"根據…的統計／資料顯示 cites the source of figures or conclusions and is common in news and reports.","tc":"「根據…的統計」「根據…的資料顯示」用來說明數字或結論的來源，常見於新聞和報告。","sc":"「根据…的统计」「根据…的资料显示」用来说明数字或结论的来源，常见于新闻和报告。"},"ex":[{"c":"每個人都應有運動的習慣，但不應過度。根據對舞者問卷的統計，從小學跳舞的女生，約有八成都受過傷。","s":"每个人都应有运动的习惯，但不应过度。根据对舞者问卷的统计，从小学跳舞的女生，约有八成都受过伤。","es":"Todos deberíamos hacer ejercicio, pero sin excederse. Según las estadísticas de una encuesta a bailarinas, cerca del ochenta por ciento de las chicas que empezaron a bailar desde niñas se ha lesionado.","en":"Everyone should exercise regularly but not to excess. According to statistics from a questionnaire on dancers, about eighty percent of girls who started dancing in childhood have been injured.","p":"měi ge rén dōu yīng yǒu yùn dòng de xí guàn, dàn bù yīng guò dù. gēn jù duì wǔ zhě wèn juàn de tǒng jì, cóng xiǎo xué tiào wǔ de nǚ shēng, yuē yǒu bā chéng dōu shòu guò shāng."},{"c":"根據政府的統計，台灣的出生率逐年下降。","s":"根据政府的统计，台湾的出生率逐年下降。","es":"Según las estadísticas del gobierno, la tasa de natalidad de Taiwán baja año tras año.","en":"According to government statistics, Taiwan's birth rate is falling year by year.","p":"gēn jù zhèng fǔ de tǒng jì, tái wān de chū shēng lǜ zhú nián xià jiàng."}]},{"id":"5-8-2","b":5,"l":8,"k":"dirección movimiento direction movement 方向 趨向 siempre nunca frecuencia always never frequency 經常 從來 dirección movimiento direction movement 方向 趋向 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Siempre (hasta ahora), desde siempre","en":"Always (all along), has always been","ens":"Always (all along), has always been","tc":"向來","sc":"向来"},"d":{"es":"向來 = siempre, desde siempre. Indica algo que ha sido así de manera constante hasta el presente. Se usa con hechos habituales o características; no se usa con acciones futuras ni de una sola vez.","en":"向來 means 'always, all along up to now'. It is used for habits or characteristics, not for future or one-time events.","tc":"「向來」表示從以前到現在一直是這樣，用在習慣或特點上，不用在未來或只發生一次的事。","sc":"「向来」表示从以前到现在一直是这样，用在习惯或特点上，不用在未来或只发生一次的事。"},"ex":[{"c":"這家企業的錄取標準向來嚴格，其政策是「寧缺勿濫」。","s":"这家企业的录取标准向来严格，其政策是「宁缺勿滥」。","es":"Los criterios de admisión de esta empresa siempre han sido estrictos; su política es «mejor que falte alguien a contratar a cualquiera».","en":"This company's hiring standards have always been strict; its policy is 'better to have a vacancy than hire carelessly'.","p":"zhè jiā qì yè de lù qǔ biāo zhǔn xiàng lái yán gé, qí zhèng cè shì 「níng quē wù làn」."},{"c":"他做事向來很認真，從不遲到。","s":"他做事向来很认真，从不迟到。","es":"Siempre ha sido muy dedicado en su trabajo y nunca llega tarde.","en":"He has always been very conscientious and has never been late.","p":"tā zuò shì xiàng lái hěn rèn zhēn, cóng bù chí dào."}]},{"id":"5-8-3","b":5,"l":8,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"A tiene prioridad sobre B","en":"A takes priority over B","ens":"A takes priority over B","tc":"A優先於B","sc":"A优先于B"},"d":{"es":"A 優先於 B = A tiene prioridad sobre B. «於» marca la comparación en el estilo formal. Se usa para decir qué se pone primero cuando hay dos valores en conflicto.","en":"A優先於B means A comes before B in importance. 於 is a literary comparison marker.","tc":"「A優先於B」表示A比B更重要、要先處理；「於」是書面語，用來比較。","sc":"「A优先于B」表示A比B更重要、要先处理；「于」是书面语，用来比较。"},"ex":[{"c":"對王太太來說，家庭永遠優先於她的事業。","s":"对王太太来说，家庭永远优先于她的事业。","es":"Para la señora Wang, la familia siempre está por encima de su carrera.","en":"For Mrs. Wang, family always takes priority over her career.","p":"duì wáng tài tài lái shuō, jiā tíng yǒng yuǎn yōu xiān yú tā de shì yè."},{"c":"在這家醫院，病人的安全優先於一切。","s":"在这家医院，病人的安全优先于一切。","es":"En este hospital la seguridad del paciente tiene prioridad sobre todo.","en":"In this hospital, patient safety takes priority over everything.","p":"zài zhè jiā yī yuàn, bìng rén de ān quán yōu xiān yú yí qiè."}]},{"id":"5-8-4","b":5,"l":8,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No es más que… / solo…","en":"Nothing more than… / just…","ens":"Nothing more than… / just…","tc":"只不過…罷了","sc":"只不过…罢了"},"d":{"es":"只不過…罷了 = no es más que…, solo…. Minimiza algo: «solo es», «nada más». 罷了 va al final de la oración. Suele usarse para restarle importancia o para explicar que la diferencia es pequeña.","en":"只不過…罷了 downplays something, meaning 'it's nothing more than…'. 罷了 goes at the end of the sentence.","tc":"「只不過…罷了」表示事情沒那麼嚴重或不複雜，「罷了」放在句尾，用來把事情說得很輕。","sc":"「只不过…罢了」表示事情没那么严重或不复杂，「罢了」放在句尾，用来把事情说得很轻。"},"ex":[{"c":"這件事沒有所謂的對與錯，你們兩個只不過立場不同罷了。","s":"这件事没有所谓的对与错，你们两个只不过立场不同罢了。","es":"En esto no hay un correcto o incorrecto; ustedes dos simplemente tienen posturas distintas.","en":"There is no such thing as right or wrong in this matter; the two of you simply have different standpoints.","p":"zhè jiàn shì méi yǒu suǒ wèi de duì yǔ cuò, nǐ men liǎng ge zhǐ bú guò lì chǎng bù tóng bà le."},{"c":"我只不過是開個玩笑罷了，你別當真。","s":"我只不过是开个玩笑罢了，你别当真。","es":"Solo fue una broma, no lo tomes en serio.","en":"I was just joking, so don't take it seriously.","p":"wǒ zhǐ bú guò shì kāi gè wán xiào bà le, nǐ bié dāng zhēn."}]},{"id":"5-8-5","b":5,"l":8,"k":"","t":{"es":"A y B están estrechamente relacionados","en":"A and B are closely related","ens":"A and B are closely related","tc":"A與B息息相關","sc":"A与B息息相关"},"d":{"es":"A 與 B 息息相關 = A y B están estrechamente relacionados. «息息» refuerza «相關» (el uno afecta al otro continuamente). «與» es la forma formal de 和／跟. Se usa en textos formales.","en":"A與B息息相關 means A and B are very closely connected and affect each other. 與 is the formal version of 和／跟.","tc":"「A與B息息相關」表示A和B關係非常密切、互相影響；「與」比較正式。","sc":"「A与B息息相关」表示A和B关系非常密切、互相影响；「与」比较正式。"},"ex":[{"c":"房地產的趨勢與國家的經濟情況息息相關。","s":"房地产的趋势与国家的经济情况息息相关。","es":"La tendencia del sector inmobiliario está estrechamente relacionada con la situación económica del país.","en":"Real estate trends are closely related to a country's economic situation.","p":"fáng dì chǎn de qū shì yǔ guó jiā de jīng jì qíng kuàng xí xí xiāng guān."},{"c":"我們的健康與生活習慣息息相關。","s":"我们的健康与生活习惯息息相关。","es":"Nuestra salud está estrechamente ligada a nuestros hábitos de vida.","en":"Our health is closely tied to our lifestyle habits.","p":"wǒ men de jiàn kāng yǔ shēng huó xí guàn xí xí xiāng guān."}]},{"id":"5-9-0","b":5,"l":9,"k":"","t":{"es":"A, B e incluso C","en":"A, B and even C","ens":"A, B and even C","tc":"A、B乃至（於）C","sc":"A、B乃至（于）C"},"d":{"es":"A、B 乃至（於）C = A, B e incluso C. Enumera elementos de alcance creciente: C es el más amplio o el más extremo. Es formal, propio de la lengua escrita; «於» es opcional.","en":"A、B乃至（於）C lists items of increasing scope, with C the widest or most extreme. It is formal and 於 is optional.","tc":"「A、B乃至（於）C」把範圍由小到大列出來，C是最大或最極端的，語氣正式，「於」可以省略。","sc":"「A、B乃至（于）C」把范围由小到大列出来，C是最大或最极端的，语气正式，「于」可以省略。"},"ex":[{"c":"螢幕上消失多年的大明星王小姐突然出現在這家健身中心，她的出現引起了現場的人、媒體記者，乃至於國外新聞媒體的注意。","s":"萤幕上消失多年的大明星王小姐突然出现在这家健身中心，她的出现引起了现场的人、媒体记者，乃至于国外新闻媒体的注意。","es":"La gran estrella Wang, desaparecida de las pantallas durante años, apareció de repente en este gimnasio y su presencia atrajo la atención de los presentes, de los periodistas e incluso de los medios extranjeros.","en":"Superstar Ms. Wang, who had been off screen for years, suddenly appeared at this gym, and her appearance drew the attention of the people there, reporters and even foreign news media.","p":"yíng mù shàng xiāo shī duō nián de dà míng xīng wáng xiǎo jiě tú rán chū xiàn zài zhè jiā jiàn shēn zhōng xīn, tā de chū xiàn yǐn qǐ le xiàn chǎng de rén, méi tǐ jì zhě, nǎi zhì yú guó wài xīn wén méi tǐ de zhù yì."},{"c":"這個問題影響到學生、家長，乃至於整個社會。","s":"这个问题影响到学生、家长，乃至于整个社会。","es":"Este problema afecta a los estudiantes, a los padres e incluso a toda la sociedad.","en":"This problem affects students, parents and even society as a whole.","p":"zhè ge wèn tí yǐng xiǎng dào xué shēng, jiā zhǎng, nǎi zhì yú zhěng gè shè huì."}]},{"id":"5-9-1","b":5,"l":9,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"A; también se puede decir que B","en":"A; one could also say B","ens":"A; one could also say B","tc":"A，也可以說B","sc":"A，也可以说B"},"d":{"es":"A，也可以說（是）B = A; también se puede decir que B. Ofrece una segunda formulación, a menudo más fuerte o más valorativa que la primera. Va después de una coma, sin cambiar de sujeto.","en":"A，也可以說B gives a second way of putting it, often stronger or more evaluative than the first.","tc":"「A，也可以說B」先說一個說法A，再補上另一個常常更強或帶評價的說法B。","sc":"「A，也可以说B」先说一个说法A，再补上另一个常常更强或带评价的说法B。"},"ex":[{"c":"海洋公園一個個關閉了，因大家慢慢意識到所謂的動物表演，其實是違反動物的自然天性，也可以說是在虐待動物。","s":"海洋公园一个个关闭了，因大家慢慢意识到所谓的动物表演，其实是违反动物的自然天性，也可以说是在虐待动物。","es":"Los parques marinos van cerrando uno tras otro, porque poco a poco la gente se da cuenta de que los llamados espectáculos con animales van contra su naturaleza; incluso se puede decir que son maltrato animal.","en":"Marine parks are closing one by one because people are gradually realizing that so-called animal shows go against animals' natural instincts; one could also say they amount to animal abuse.","p":"hǎi yáng gōng yuán yí ge gè guān bì le, yīn dà jiā màn màn yì shì dào suǒ wèi de dòng wù biǎo yǎn, qí shí shì wéi fǎn dòng wù de zì rán tiān xìng, yě kě yǐ shuō shì zài nüè dài dòng wù."},{"c":"他幾乎沒有休假，也可以說是把全部時間都給了公司。","s":"他几乎没有休假，也可以说是把全部时间都给了公司。","es":"Casi no tiene vacaciones; también se puede decir que le ha dado todo su tiempo a la empresa.","en":"He hardly takes any days off; one could also say he has given all his time to the company.","p":"tā jī hū méi yǒu xiū jià, yě kě yǐ shuō shì bǎ quán bù shí jiān dōu gěi le gōng sī."}]},{"id":"5-9-2","b":5,"l":9,"k":"","t":{"es":"Cualquiera… (quien sea)","en":"Anyone would…","ens":"Anyone would…","tc":"任誰都…","sc":"任谁都…"},"d":{"es":"任誰都 + V/adj = cualquiera, sea quien sea, … (en esa situación). «任誰» equivale a 不論是誰 y se combina con 都 o 也. El hablante da por hecho que la reacción es universal; es de registro algo formal.","en":"任誰都… means 'no matter who it is, everyone would…'. It is usually followed by 都 or 也 and implies that anyone would react the same way.","tc":"「任誰都…」意思是「不論是誰都…」，後面常接「都／也」，表示在那種情況下，每個人的反應都一樣。","sc":"「任谁都…」意思是「不论是谁都…」，后面常接「都／也」，表示在那种情况下，每个人的反应都一样。"},"ex":[{"c":"《看見台灣》的導演齊柏林在拍攝《看見台灣2》時，不幸因飛機掉落而過世，這個新聞任誰都感到震驚、遺憾與難過。","s":"《看见台湾》的导演齐柏林在拍摄《看见台湾2》时，不幸因飞机掉落而过世，这个新闻任谁都感到震惊、遗憾与难过。","es":"El director de «Beyond Beauty: Taiwan from Above», Chi Po-lin, murió trágicamente al caer su avión durante el rodaje de la segunda parte; esa noticia dejó a cualquiera conmocionado, apenado y con pesar.","en":"Chi Po-lin, director of Beyond Beauty: Taiwan from Above, died in a plane crash while filming the sequel; anyone would be shocked, saddened and filled with regret by this news.","p":"《 kàn jiàn tái wān》 de dǎo yǎn qí bó lín zài pāi shè《 kàn jiàn tái wān2 》 shí, bú xìng yīn fēi jī diào luò ér guò shì, zhè ge xīn wén rèn shéi dōu gǎn dào zhèn jīng, yí hàn yǔ nán guò."},{"c":"這麼不公平的待遇，任誰都會生氣。","s":"这么不公平的待遇，任谁都会生气。","es":"Con un trato tan injusto, cualquiera se enojaría.","en":"With such unfair treatment, anyone would get angry.","p":"zhè me bù gōng píng de dài yù, rèn shéi dōu huì shēng qì."}]},{"id":"5-9-3","b":5,"l":9,"k":"","t":{"es":"Hacer frente a / responder a","en":"To respond to / cope with","ens":"To respond to / cope with","tc":"因應","sc":"因应"},"d":{"es":"因應 = hacer frente a, responder a un cambio o situación. Es un verbo formal que lleva como objeto la situación a la que se responde (因應需求、因應變化); se usa mucho con 為了 al inicio.","en":"因應 is a formal verb meaning to respond to or cope with a situation or change. It is often used as 為了因應….","tc":"「因應」是正式的動詞，表示針對某個情況或變化採取辦法，後面接情況，常說「為了因應…」。","sc":"「因应」是正式的动词，表示针对某个情况或变化采取办法，后面接情况，常说「为了因应…」。"},"ex":[{"c":"政府為了因應遊行所可能帶來的交通混亂而派出一千名警力。","s":"政府为了因应游行所可能带来的交通混乱而派出一千名警力。","es":"Para hacer frente al posible caos de tránsito que traería la marcha, el gobierno envió a mil policías.","en":"To deal with the traffic chaos the march might bring, the government sent out a thousand police officers.","p":"zhèng fǔ wèi le yīn yìng yóu xíng suǒ kě néng dài lái de jiāo tōng hùn luàn ér pài chū yì qiān míng jǐng lì."},{"c":"公司為了因應市場變化，調整了銷售策略。","s":"公司为了因应市场变化，调整了销售策略。","es":"Para responder a los cambios del mercado, la empresa ajustó su estrategia de ventas.","en":"To respond to market changes, the company adjusted its sales strategy.","p":"gōng sī wèi le yīn yìng shì chǎng biàn huà, tiáo zhěng le xiāo shòu cè lüè."}]},{"id":"5-9-4","b":5,"l":9,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Comparado con B, A…","en":"Compared with B, A…","ens":"Compared with B, A…","tc":"A與B相比，…","sc":"A与B相比，…"},"d":{"es":"A 與 B 相比，… = comparado con B, A…. Forma formal de «A 和 B 比起來». Primero se presenta el tema A, luego se da el resultado de la comparación (con números o adjetivos). «與» es de registro escrito.","en":"A與B相比，… is the formal version of A和B比起來. It states the topic A and then the result of the comparison, often with figures.","tc":"「A與B相比，…」是「A和B比起來」的正式說法，先說A，再說比較的結果，常出現在說明數字的文章裡。","sc":"「A与B相比，…」是「A和B比起来」的正式说法，先说A，再说比较的结果，常出现在说明数字的文章里。"},"ex":[{"c":"現代女性越來越晚婚，與二十年前相比，平均結婚年齡晚了三歲多，約二十九歲左右。","s":"现代女性越来越晚婚，与二十年前相比，平均结婚年龄晚了三岁多，约二十九岁左右。","es":"Las mujeres modernas se casan cada vez más tarde; comparado con hace veinte años, la edad promedio de matrimonio se retrasó más de tres años, a unos veintinueve.","en":"Modern women are marrying later and later; compared with twenty years ago, the average age at marriage is over three years later, at around twenty-nine.","p":"xiàn dài nǚ xìng yuè lái yuè wǎn hūn, yǔ èr shí nián qián xiāng bǐ, píng jūn jié hūn nián líng wǎn le sān suì duō, yuē èr shí jiǔ suì zuǒ yòu."},{"c":"這個城市的房價與十年前相比，漲了將近一倍。","s":"这个城市的房价与十年前相比，涨了将近一倍。","es":"Comparado con hace diez años, el precio de la vivienda en esta ciudad casi se duplicó.","en":"Compared with ten years ago, housing prices in this city have nearly doubled.","p":"zhè ge chéng shì de fáng jià yǔ shí nián qián xiāng bǐ, zhǎng le jiāng jìn yí bèi."}]},{"id":"5-9-5","b":5,"l":9,"k":"","t":{"es":"Mucho más/menos … que…","en":"Far more/less … than…","ens":"Far more/less … than…","tc":"遠V於…","sc":"远V于…"},"d":{"es":"遠 + V於… = mucho más/menos … que…. Se forma con 遠 + adjetivo + 於 (遠高於、遠低於、遠大於、遠多於). «於» marca la comparación, por eso no se usa 比 ni 很. Es propio de textos escritos con cifras.","en":"遠V於… means 'far more/less than…', as in 遠高於, 遠低於, 遠大於, 遠多於. 於 marks the comparison, so 比 is not needed. It is used in written texts.","tc":"「遠＋V於…」表示「比…高很多／低很多」，常見的有「遠高於、遠低於、遠大於、遠多於」，不需要再用「比」，多用在書面語。","sc":"「远＋V于…」表示「比…高很多／低很多」，常见的有「远高于、远低于、远大于、远多于」，不需要再用「比」，多用在书面语。"},"ex":[{"c":"經國家健康單位調查發現，民眾若有三個孩子，第三胎是男孩的比率遠高於女孩，這有可能是重男輕女的現象。","s":"经国家健康单位调查发现，民众若有三个孩子，第三胎是男孩的比率远高于女孩，这有可能是重男轻女的现象。","es":"Una investigación de las autoridades de salud encontró que, entre quienes tienen tres hijos, la proporción de varones en el tercer embarazo es mucho mayor que la de niñas, lo que podría reflejar la preferencia por los hijos varones.","en":"A survey by national health authorities found that among people with three children, the rate of the third child being a boy is far higher than a girl, which may reflect a preference for sons.","p":"jīng guó jiā jiàn kāng dān wèi diào chá fā xiàn, mín zhòng ruò yǒu sān ge hái zi, dì sān tāi shì nán hái de bǐ lǜ yuǎn gāo yú nǚ hái, zhè yǒu kě néng shì zhòng nán qīng nǚ de xiàn xiàng."},{"c":"這家店的價格遠低於其他同類型的商店。","s":"这家店的价格远低于其他同类型的商店。","es":"Los precios de esta tienda son muy inferiores a los de otras tiendas del mismo tipo.","en":"This shop's prices are far lower than those of other similar shops.","p":"zhè jiā diàn de jià gé yuǎn dī yú qí tā tóng lèi xíng de shāng diàn."}]},{"id":"5-9-6","b":5,"l":9,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Por A, hay cierto B","en":"Because of A, there is some B","ens":"Because of A, there is some B","tc":"受A而有所B","sc":"受A而有所B"},"d":{"es":"受 A 而有所 B = por verse afectado por A, hay cierto B. «有所» + verbo de dos sílabas (顧慮、改變、不同、改善) expresa «en cierta medida». A es el factor que influye. Formal.","en":"受A而有所B means that being affected by A leads to some degree of B. 有所 is usually followed by a two-character word like 顧慮, 改變 or 不同.","tc":"「受A而有所B」表示因為受到A的影響，而在某種程度上B；「有所」後面常接兩個字的詞，例如「顧慮、改變、不同」。","sc":"「受A而有所B」表示因为受到A的影响，而在某种程度上B；「有所」后面常接两个字的词，例如「顾虑、改变、不同」。"},"ex":[{"c":"許多人在安排旅行時，常會受交通預算限制而有所顧慮。","s":"许多人在安排旅行时，常会受交通预算限制而有所顾虑。","es":"Al planear un viaje, mucha gente suele tener cierta preocupación por las limitaciones del presupuesto de transporte.","en":"When planning trips, many people often have some concerns because they are limited by their transportation budget.","p":"xǔ duō rén zài ān pái lǚ xíng shí, cháng huì shòu jiāo tōng yù suàn xiàn zhì ér yǒu suǒ gù lǜ."},{"c":"他的想法受朋友的影響而有所改變。","s":"他的想法受朋友的影响而有所改变。","es":"Sus ideas cambiaron en cierta medida por la influencia de sus amigos.","en":"His thinking changed somewhat under his friends' influence.","p":"tā de xiǎng fǎ shòu péng yǒu de yǐng xiǎng ér yǒu suǒ gǎi biàn."}]},{"id":"5-10-0","b":5,"l":10,"k":"","t":{"es":"A y B están del mismo lado","en":"A and B stand on the same side","ens":"A and B stand on the same side","tc":"A跟B站在同一陣線","sc":"A跟B站在同一阵线"},"d":{"es":"A 跟 B 站在同一陣線 = A y B están del mismo lado (en el mismo frente). 陣線 es «frente, bando»; se usa en sentido figurado para quien apoya la misma causa. Puede ir con 和 o 跟.","en":"A跟B站在同一陣線 means A and B are on the same side and support each other. 陣線 originally means a battle line and is used figuratively here.","tc":"「A跟B站在同一陣線」表示A和B立場一致、互相支持；「陣線」原本是戰爭用語，這裡是比喻。","sc":"「A跟B站在同一阵线」表示A和B立场一致、互相支持；「阵线」原本是战争用语，这里是比喻。"},"ex":[{"c":"總統承諾會傾聽人民的心聲，並且帶領政府，和人民站在同一陣線。","s":"总统承诺会倾听人民的心声，并且带领政府，和人民站在同一阵线。","es":"El presidente prometió escuchar la voz del pueblo y guiar al gobierno para estar del mismo lado que la gente.","en":"The president promised to listen to the people's voices and lead the government to stand on the same side as the people.","p":"zǒng tǒng chéng nuò huì qīng tīng rén mín de xīn shēng, bìng qiě dài lǐng zhèng fǔ, hé rén mín zhàn zài tóng yí zhèn xiàn."},{"c":"在這個議題上，老師和家長站在同一陣線，希望孩子少用手機。","s":"在这个议题上，老师和家长站在同一阵线，希望孩子少用手机。","es":"En este tema, maestros y padres están del mismo lado: quieren que los niños usen menos el celular.","en":"On this issue, teachers and parents stand on the same side, hoping children will use their phones less.","p":"zài zhè ge yì tí shàng, lǎo shī hàn jiā zhǎng zhàn zài tóng yí zhèn xiàn, xī wàng hái zi shǎo yòng shǒu jī."}]},{"id":"5-10-1","b":5,"l":10,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定","t":{"es":"A no se diferencia de B","en":"A is no different from B","ens":"A is no different from B","tc":"A和（跟）B沒有兩樣","sc":"A和（跟）B没有两样"},"d":{"es":"A 和（跟）B 沒有兩樣 = A no se diferencia de B, es igual que B. «沒有兩樣» = no hay diferencia; se usa a menudo con 看起來／吃起來／聽起來 para impresiones. Suele implicar sorpresa o crítica.","en":"A和（跟）B沒有兩樣 means A is no different from B. It is often used with 看起來 or 吃起來 and may carry surprise or criticism.","tc":"「A和B沒有兩樣」表示A和B看不出差別，常搭配「看起來、吃起來」，有時帶一點驚訝或批評的意思。","sc":"「A和B没有两样」表示A和B看不出差别，常搭配「看起来、吃起来」，有时带一点惊讶或批评的意思。"},"ex":[{"c":"基改食品看起來跟一般食品沒有兩樣，大部分的人很難從外觀辨別，因此怎麼能吃得安心呢？","s":"基改食品看起来跟一般食品没有两样，大部分的人很难从外观辨别，因此怎么能吃得安心呢？","es":"Los alimentos transgénicos se ven igual que los comunes y a la mayoría le cuesta distinguirlos por su aspecto; ¿cómo se puede comer con tranquilidad?","en":"GM foods look no different from ordinary food, and most people can hardly tell them apart by appearance, so how can anyone eat them with peace of mind?","p":"jī gǎi shí pǐn kàn qǐ lái gēn yì bān shí pǐn méi yǒu liǎng yàng, dà bù fēn de rén hěn nán cóng wài guān biàn bié, yīn cǐ zěn me néng chī de ān xīn ne?"},{"c":"這個仿製包看起來和真品沒有兩樣。","s":"这个仿制包看起来和真品没有两样。","es":"Esta bolsa imitación se ve igual que la original.","en":"This imitation bag looks no different from the real thing.","p":"zhè ge fǎng zhì bāo kàn qǐ lái hàn zhēn pǐn méi yǒu liǎng yàng."}]},{"id":"5-10-2","b":5,"l":10,"k":"","t":{"es":"A no tiene que ver con B","en":"A has nothing to do with B","ens":"A has nothing to do with B","tc":"A與（跟）B無關","sc":"A与（跟）B无关"},"d":{"es":"A 與（跟）B 無關 = A no tiene nada que ver con B. «無關» = 沒有關係, más formal; «與» es formal y «跟» coloquial. Se usa para negar una relación causal o de responsabilidad.","en":"A與（跟）B無關 means A has no connection to B. 與 is formal while 跟 is colloquial; it is often used to deny causes or responsibility.","tc":"「A與B無關」表示A和B沒有關係；「與」較正式，「跟」較口語，常用來否認原因或責任。","sc":"「A与B无关」表示A和B没有关系；「与」较正式，「跟」较口语，常用来否认原因或责任。"},"ex":[{"c":"某些科學家認為，從地球的歷史來看，氣候變化是自然的一部分，跟人類活動無關。","s":"某些科学家认为，从地球的历史来看，气候变化是自然的一部分，跟人类活动无关。","es":"Algunos científicos creen que, según la historia de la Tierra, el cambio climático es parte de la naturaleza y no tiene que ver con la actividad humana.","en":"Some scientists believe that, judging from Earth's history, climate change is a natural part of things and has nothing to do with human activity.","p":"mǒu xiē kē xué jiā rèn wéi, cóng dì qiú de lì shǐ lái kàn, qì hòu biàn huà shì zì rán de yí bù fēn, gēn rén lèi huó dòng wú guān."},{"c":"這次的失敗與運氣無關，是準備不夠。","s":"这次的失败与运气无关，是准备不够。","es":"Este fracaso no tiene que ver con la suerte, sino con que no nos preparamos lo suficiente.","en":"This failure has nothing to do with luck; we simply did not prepare enough.","p":"zhè cì de shī bài yǔ yùn qì wú guān, shì zhǔn bèi bú gòu."}]},{"id":"5-10-3","b":5,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 énfasis enfático incluso emphasis emphatic even 強調 甚至 disposición objeto complemento disposal object ba 处置 把字句 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Unir / vincular A con B","en":"To link A and B together","ens":"To link A and B together","tc":"把A跟B連在一起","sc":"把A跟B连在一起"},"d":{"es":"把 A 跟 B 連在一起 = unir/vincular A con B (en la mente, en los hechos o en la política). Usa la estructura 把 con el resultado «連在一起». Con frecuencia aparece en negativo: 不要把 A 跟 B 連在一起.","en":"把A跟B連在一起 means to link two things together, mentally or in practice. It is a 把 sentence and often appears negatively, as 不要把A跟B連在一起.","tc":"「把A跟B連在一起」是把兩件事聯繫起來看，用「把」字句，常見的否定說法是「不要把A跟B連在一起」。","sc":"「把A跟B连在一起」是把两件事联系起来看，用「把」字句，常见的否定说法是「不要把A跟B连在一起」。"},"ex":[{"c":"專家分析，商人早就把都市計畫與房價連在一起，使得現在房地產價格居高不下。","s":"专家分析，商人早就把都市计划与房价连在一起，使得现在房地产价格居高不下。","es":"Los expertos analizan que los empresarios hace tiempo vincularon la planificación urbana con el precio de la vivienda, de ahí que hoy los precios inmobiliarios se mantengan altos.","en":"Experts say businesspeople long ago tied urban planning to housing prices, which is why real estate prices remain so high now.","p":"zhuān jiā fēn xī, shāng rén zǎo jiù bǎ dū shì jì huà yǔ fáng jià lián zài yì qǐ, shǐ dé xiàn zài fáng dì chǎn jià gé jū gāo bú xià."},{"c":"不應該把成績跟一個人的價值連在一起。","s":"不应该把成绩跟一个人的价值连在一起。","es":"No se debería vincular las calificaciones con el valor de una persona.","en":"Grades should not be tied to a person's worth.","p":"bù yīng gāi bǎ chéng jī gēn yí ge rén de jià zhí lián zài yì qǐ."}]},{"id":"5-10-4","b":5,"l":10,"k":"","t":{"es":"Usar … como lema","en":"To use … as a slogan","ens":"To use … as a slogan","tc":"以…做為口號","sc":"以…做为口号"},"d":{"es":"以 X 做為口號 = usar X como lema/consigna. 以…做為… es una estructura formal («tomar X como Y»); 口號 es un eslogan que un grupo repite para movilizar o convencer. Se usa en política y campañas.","en":"以…做為口號 means to use a phrase as a slogan, often in politics, campaigns and social movements. 以…做為… is a formal pattern.","tc":"「以…做為口號」是把某句話當作口號，常用在政治、社會運動或宣傳；「以…做為…」比較正式。","sc":"「以…做为口号」是把某句话当作口号，常用在政治、社会运动或宣传；「以…做为…」比较正式。"},"ex":[{"c":"人權團體往往以「尊重生命」做為口號，要求廢除死刑。","s":"人权团体往往以「尊重生命」做为口号，要求废除死刑。","es":"Las organizaciones de derechos humanos suelen usar «respetar la vida» como lema para exigir la abolición de la pena de muerte.","en":"Human rights groups often use 'respect life' as their slogan to demand the abolition of the death penalty.","p":"rén quán tuán tǐ wǎng wǎng yǐ 「zūn zhòng shēng mìng」 zuò wéi kǒu hào, yào qiú fèi chú sǐ xíng."},{"c":"這家公司以「環保第一」做為口號，推廣無塑料包裝。","s":"这家公司以「环保第一」做为口号，推广无塑料包装。","es":"Esta empresa usa «lo ecológico primero» como lema para promover empaques sin plástico.","en":"This company uses 'environment first' as its slogan to promote plastic-free packaging.","p":"zhè jiā gōng sī yǐ 「huán bǎo dì yī」 zuò wéi kǒu hào, tuī guǎng wú sù liào bāo zhuāng."}]},{"id":"5-10-5","b":5,"l":10,"k":"","t":{"es":"Hacer caso omiso de… (N)","en":"To disregard the N of…","ens":"To disregard the N of…","tc":"無視…的N","sc":"无视…的N"},"d":{"es":"無視 X 的 N = hacer caso omiso de / ignorar a propósito el N de X (權益、安全、感受). Implica ignorarlo deliberadamente y tiene un tono de crítica. Es formal y se usa en noticias y comentarios.","en":"無視…的N means to deliberately disregard something, such as someone's rights, safety or feelings. It has a critical tone and is used in news and commentary.","tc":"「無視…的N」表示故意不理會，常接「權益、安全、感受」等名詞，語氣帶批評，多用在新聞和評論。","sc":"「无视…的N」表示故意不理会，常接「权益、安全、感受」等名词，语气带批评，多用在新闻和评论。"},"ex":[{"c":"做為政治人物，不應該為了滿足自己的利益而無視人民的權益。","s":"做为政治人物，不应该为了满足自己的利益而无视人民的权益。","es":"Como político, no se debe ignorar los derechos de la gente para satisfacer los intereses propios.","en":"As a politician, one should not disregard the people's rights in order to serve one's own interests.","p":"zuò wéi zhèng zhì rén wù, bù yīng gāi wèi le mǎn zú zì jǐ de lì yì ér wú shì rén mín de quán yì."},{"c":"這家工廠無視員工的安全，繼續使用老舊設備。","s":"这家工厂无视员工的安全，继续使用老旧设备。","es":"Esta fábrica ignora la seguridad de sus empleados y sigue usando equipo viejo.","en":"This factory disregards its employees' safety and keeps using outdated equipment.","p":"zhè jiā gōng chǎng wú shì yuán gōng de ān quán, jì xù shǐ yòng lǎo jiù shè bèi."}]},{"id":"5-10-6","b":5,"l":10,"k":"","t":{"es":"A no es otra cosa que B","en":"A is no different from B","ens":"A is no different from B","tc":"A，無異（於）B","sc":"A，无异（于）B"},"d":{"es":"A，無異（於）B = A no es otra cosa que B, equivale a B. Es una comparación retórica y a menudo negativa (無異於自殺, 無異於強盜). Es más fuerte que 等同於, que solo indica equivalencia. Registro formal.","en":"A，無異（於）B says A is no different from B, usually as a strong or negative comparison. It is stronger than 等同於 and is literary.","tc":"「A，無異於B」表示A和B沒有差別，常用來強烈批評或比喻（例如「無異於自殺」），比「等同於」語氣更強，較書面。","sc":"「A，无异于B」表示A和B没有差别，常用来强烈批评或比喻（例如「无异于自杀」），比「等同于」语气更强，较书面。"},"ex":[{"c":"政府強制收富人稅養窮人，這種劫富濟貧的手段，無異於強盜。","s":"政府强制收富人税养穷人，这种劫富济贫的手段，无异于强盗。","es":"Que el gobierno cobre impuestos obligatorios a los ricos para mantener a los pobres, ese método de quitar a los ricos para dar a los pobres, no es distinto del bandidaje.","en":"The government forcing a tax on the rich to support the poor, this robbing-the-rich-to-help-the-poor approach, is no different from robbery.","p":"zhèng fǔ qiáng zhì shōu fù rén shuì yǎng qióng rén, zhè zhǒng jié fù jì pín de shǒu duàn, wú yì yú qiáng dào."},{"c":"明知有危險還要去，這無異於自殺。","s":"明知有危险还要去，这无异于自杀。","es":"Ir sabiendo que hay peligro no es otra cosa que suicidarse.","en":"Going despite knowing it is dangerous is no different from suicide.","p":"míng zhī yǒu wéi xiǎn hái yào qù, zhè wú yì yú zì shā."}]},{"id":"5-10-7","b":5,"l":10,"k":"","t":{"es":"A depende de B","en":"A depends on B","ens":"A depends on B","tc":"A，有賴B","sc":"A，有赖B"},"d":{"es":"A，有賴 B = A depende de B (se necesita B). «有賴» = 依靠, formal; B es la persona o el factor que se necesita para lograr A. Aparece mucho en frases como 有賴大家的努力.","en":"A，有賴B means A relies on B to be achieved. 有賴 is literary, as in 有賴大家的努力.","tc":"「A，有賴B」表示要做成A，需要依靠B；「有賴」是書面語，常說「有賴大家的努力」。","sc":"「A，有赖B」表示要做成A，需要依靠B；「有赖」是书面语，常说「有赖大家的努力」。"},"ex":[{"c":"市長表示，如何解決停滯不前的發展問題，有賴政府和地方討論出合理的預算分配。","s":"市长表示，如何解决停滞不前的发展问题，有赖政府和地方讨论出合理的预算分配。","es":"El alcalde dijo que resolver el problema del desarrollo estancado depende de que el gobierno y las localidades acuerden una distribución razonable del presupuesto.","en":"The mayor said that solving the stalled development problem depends on the government and localities working out a reasonable budget allocation.","p":"shì zhǎng biǎo shì, rú hé jiě jué tíng zhì bù qián de fā zhǎn wèn tí, yǒu lài zhèng fǔ hàn dì fāng tǎo lùn chū hé lǐ de yù suàn fēn pèi."},{"c":"這個計畫能不能成功，有賴每個人的合作。","s":"这个计划能不能成功，有赖每个人的合作。","es":"Que este proyecto tenga éxito depende de la colaboración de todos.","en":"Whether this plan succeeds depends on everyone's cooperation.","p":"zhè ge jì huà néng bù néng chéng gōng, yǒu lài měi ge rén de hé zuò."}]},{"id":"6-1-0","b":6,"l":1,"k":"","t":{"es":"Mirar al panorama: 放眼","en":"Looking across: 放眼","ens":"Looking across: 放眼","tc":"放眼","sc":"放眼"},"d":{"es":"放眼 + ámbito amplio (世界, 未來, 二十一世紀) = «si se mira / abarcando con la vista…». Registro formal y escrito; abre la oración y después se comenta una tendencia o conclusión.","en":"放眼 means 'to cast one's eyes broadly over…'. It is followed by a wide scope (the world, the future, the 21st century) and then a trend or conclusion. Formal, written or speech style.","tc":"「放眼」是「把目光放遠、放寬來看」的意思，後面接範圍大的名詞（世界、未來、全球），再說明看到的趨勢。多用在書面或演講。","sc":"「放眼」是「把目光放远、放宽来看」的意思，后面接范围大的名词（世界、未来、全球），再说明看到的趋势。多用在书面或演讲。"},"ex":[{"c":"放眼二十一世紀的國際關係，逐漸由對立、衝突走向對話、合作。","s":"放眼二十一世纪的国际关系，逐渐由对立、冲突走向对话、合作。","es":"Si se observan las relaciones internacionales del siglo XXI, estas pasan poco a poco del antagonismo y el conflicto al diálogo y la cooperación.","en":"Looking across international relations in the 21st century, they are gradually moving from opposition and conflict toward dialogue and cooperation.","p":"fàng yǎn èr shí yī shì jì de guó jì guān xì, zhú jiàn yóu duì lì, chōng tú zǒu xiàng duì huà, hé zuò."},{"c":"放眼全球，越來越多國家重視環境保護。","s":"放眼全球，越来越多国家重视环境保护。","es":"Mirando al mundo entero, cada vez más países dan importancia a la protección del medio ambiente.","en":"Looking around the globe, more and more countries value environmental protection.","p":"fàng yǎn quán qiú, yuè lái yuè duō guó jiā zhòng shì huán jìng bǎo hù."}]},{"id":"6-1-1","b":6,"l":1,"k":"","t":{"es":"Lo importante de X radica en Y","en":"The key point of X lies in Y","ens":"The key point of X lies in Y","tc":"……之處，在於……","sc":"……之处，在于……"},"d":{"es":"X 之處，在於 Y = «lo (importante / especial / difícil) de X radica en Y». Se usa para señalar dónde está el punto clave; adjetivos típicos: 重要、特別、困難、可貴. Registro formal.","en":"'The important/special/difficult point of X lies in Y.' The part before 之處 is usually 重要, 特別, 困難 or 可貴. Fairly formal.","tc":"用來指出某件事的重點、特別或困難「就在於」什麼。「……之處」前面常放「重要、特別、困難、可貴」等詞，語氣比較正式。","sc":"用来指出某件事的重点、特别或困难「就在于」什么。「……之处」前面常放「重要、特别、困难、可贵」等词，语气比较正式。"},"ex":[{"c":"這份報告的重要之處，在於將各國競爭力的高低，做了清楚的評比排名。","s":"这份报告的重要之处，在于将各国竞争力的高低，做了清楚的评比排名。","es":"Lo importante de este informe radica en que clasifica con claridad el nivel de competitividad de cada país.","en":"The important point of this report is that it clearly ranks the competitiveness of each country.","p":"zhè fèn bào gào de zhòng yào zhī chǔ, zài yú jiāng gè guó jìng zhēng lì de gāo dī, zuò le qīng chǔ de píng bǐ pái míng."},{"c":"這個計畫困難之處，在於需要很多人同時配合。","s":"这个计划困难之处，在于需要很多人同时配合。","es":"La dificultad de este proyecto radica en que se necesita que mucha gente coopere al mismo tiempo.","en":"The difficulty of this project lies in needing many people to cooperate at the same time.","p":"zhè ge jì huà kùn nán zhī chǔ, zài yú xū yào hěn duō rén tóng shí pèi hé."}]},{"id":"6-1-2","b":6,"l":1,"k":"","t":{"es":"Competir por hacer algo: 爭相","en":"Vying to do something: 爭相","ens":"Vying to do something: 争相","tc":"爭相","sc":"争相"},"d":{"es":"爭相 + verbo = hacer algo a porfía, peleándose por ser el primero. El sujeto suele ser plural (mucha gente). Registro formal/escrito.","en":"爭相 + verb means many people compete or rush to do something. The subject is usually a group. Mostly written style.","tc":"「爭相＋動詞」表示很多人搶著做某件事，主詞通常是一群人，多用在書面語。","sc":"「争相＋动词」表示很多人抢着做某件事，主词通常是一群人，多用在书面语。"},"ex":[{"c":"可以拿獎學金的人數有限，難怪學生爭相上網，申請參加考試。","s":"可以拿奖学金的人数有限，难怪学生争相上网，申请参加考试。","es":"El número de becas es limitado, así que no es raro que los estudiantes se apresuren a conectarse para inscribirse al examen.","en":"The number of scholarships is limited, so no wonder students rush online to sign up for the exam.","p":"kě yǐ ná jiǎng xué jīn de rén shù yǒu xiàn, nán guài xué shēng zhēng xiāng shàng wǎng, shēn qǐng cān jiā kǎo shì."},{"c":"新手機一上市，消費者就爭相購買。","s":"新手机一上市，消费者就争相购买。","es":"En cuanto sale el nuevo celular, los consumidores se pelean por comprarlo.","en":"As soon as the new phone came out, consumers rushed to buy it.","p":"xīn shǒu jī yí shàng shì, xiāo fèi zhě jiù zhēng xiāng gòu mǎi."}]},{"id":"6-1-3","b":6,"l":1,"k":"","t":{"es":"Siendo (rol): 身為","en":"As (a role): 身為","ens":"As (a role): 身为","tc":"身為","sc":"身为"},"d":{"es":"身為 + identidad o rol = «siendo / como (tal cosa)». Introduce una responsabilidad o expectativa ligada a ese rol; después suelen aparecer 應該、必須、要.","en":"身為 + role means 'being / as a (role)'. What follows is usually a duty or expectation of that role, often with 應該, 必須 or 要.","tc":"「身為＋身分」表示「作為某種身分的人」，後面常接這個身分應該做的事，例如「應該、必須、要」。","sc":"「身为＋身分」表示「作为某种身分的人」，后面常接这个身分应该做的事，例如「应该、必须、要」。"},"ex":[{"c":"身為職校畢業生，必須一技在身，能一畢業就上工。","s":"身为职校毕业生，必须一技在身，能一毕业就上工。","es":"Como egresado de una escuela técnica, hay que dominar un oficio y poder ponerse a trabajar nada más graduarse.","en":"As a vocational school graduate, one must have a skill and be able to start working right after graduation.","p":"shēn wéi zhí xiào bì yè shēng, bì xū yí jì zài shēn, néng yí bì yè jiù shàng gōng."},{"c":"身為老師，我們應該以身作則。","s":"身为老师，我们应该以身作则。","es":"Como docentes, debemos dar el ejemplo.","en":"As teachers, we should set an example.","p":"shēn wéi lǎo shī, wǒ men yīng gāi yǐ shēn zuò zé."}]},{"id":"6-1-4","b":6,"l":1,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Al contrario, fue…: 反而是","en":"On the contrary, it was…: 反而是","ens":"On the contrary, it was…: 反而是","tc":"反而是","sc":"反而是"},"d":{"es":"A，反而是 B = «pero, al contrario, fue B (lo que…)». Señala un resultado inesperado o contrario a lo que se esperaba, poniendo énfasis en B. Se puede decir también solo 反而.","en":"After stating a situation, 反而是 introduces the unexpected or opposite result, stressing B.","tc":"先說一個情況，再用「反而是」帶出和預期相反、出乎意料的結果，重點放在後面的 B。","sc":"先说一个情况，再用「反而是」带出和预期相反、出乎意料的结果，重点放在后面的 B。"},"ex":[{"c":"老王夫婦年輕時身體相當差，反而是年老退休後，比較健康了。","s":"老王夫妇年轻时身体相当差，反而是年老退休后，比较健康了。","es":"El matrimonio Wang tenía muy mala salud de jóvenes; al contrario, fue al jubilarse, ya mayores, cuando se volvieron más sanos.","en":"Mr. and Mrs. Wang were in quite poor health when young; it was only after retiring in old age that they became healthier.","p":"lǎo wáng fū fù nián qīng shí shēn tǐ xiāng dāng chāi, fǎn ér shì nián lǎo tuì xiū hòu, bǐ jiào jiàn kāng le."},{"c":"大家以為他會緊張，反而是他最放鬆。","s":"大家以为他会紧张，反而是他最放松。","es":"Todos pensaban que estaría nervioso, pero al contrario, fue el más relajado.","en":"Everyone thought he would be nervous, but on the contrary he was the most relaxed.","p":"dà jiā yǐ wéi tā huì jǐn zhāng, fǎn ér shì tā zuì fàng sōng."}]},{"id":"6-1-5","b":6,"l":1,"k":"","t":{"es":"Año tras año: 逐年","en":"Year by year: 逐年","ens":"Year by year: 逐年","tc":"逐年","sc":"逐年"},"d":{"es":"逐年 + verbo/cambio = «año tras año, cada año más». Registro formal; relacionados: 逐漸 (poco a poco), 逐步 (paso a paso), 逐日 (día a día).","en":"逐年 means 'year by year' and is followed by a change such as an increase or decrease. Formal. Similar words: 逐漸, 逐步, 逐日.","tc":"「逐年」是「一年一年地」的意思，後面常接增加、減少等變化，多用在書面語。類似的詞還有「逐漸、逐步、逐日」。","sc":"「逐年」是「一年一年地」的意思，后面常接增加、减少等变化，多用在书面语。类似的词还有「逐渐、逐步、逐日」。"},"ex":[{"c":"世界競爭力年度報告逐年將這些新興國家列入評比。","s":"世界竞争力年度报告逐年将这些新兴国家列入评比。","es":"El informe anual de competitividad mundial ha ido incluyendo año tras año a estos países emergentes en la evaluación.","en":"The annual world competitiveness report has added these emerging countries to its rankings year by year.","p":"shì jiè jìng zhēng lì nián dù bào gào zhú nián jiāng zhè xiē xīn xīng guó jiā liè rù píng bǐ."},{"c":"這個城市的人口逐年增加。","s":"这个城市的人口逐年增加。","es":"La población de esta ciudad aumenta año tras año.","en":"The population of this city increases year after year.","p":"zhè ge chéng shì de rén kǒu zhú nián zēng jiā."}]},{"id":"6-1-6","b":6,"l":1,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Orientar A de X hacia Y: 將A轉向Y","en":"Shift A (from X) toward Y","ens":"Shift A (from X) toward Y","tc":"將A（從X）轉向Y","sc":"将A（从X）转向Y"},"d":{"es":"將 A（從 X）轉向 Y = «desplazar A (de X) hacia Y». 將 equivale a 把 en el registro escrito; X (de dónde viene) es opcional.","en":"'To shift A (from X) toward Y.' 將 is the written form of 把; 從X can be omitted.","tc":"表示把 A（從原本的 X）改變方向，轉到 Y。「將」就是書面語的「把」，「從 X」可以省略。","sc":"表示把 A（从原本的 X）改变方向，转到 Y。「将」就是书面语的「把」，「从 X」可以省略。"},"ex":[{"c":"人們將聯絡方式轉向網路，以傳訊息及電子郵件為主。","s":"人们将联络方式转向网路，以传讯息及电子邮件为主。","es":"La gente ha trasladado su forma de contacto a internet, sobre todo mediante mensajes y correo electrónico.","en":"People have shifted their way of keeping in touch to the Internet, mainly through messages and email.","p":"rén men jiāng lián luò fāng shì zhuǎn xiàng wǎng lù, yǐ chuán xùn xí jí diàn zǐ yóu jiàn wéi zhǔ."},{"c":"許多公司將重心從工廠轉向研發。","s":"许多公司将重心从工厂转向研发。","es":"Muchas empresas han desplazado su foco de las fábricas a la investigación y el desarrollo.","en":"Many companies have shifted their focus from factories to research and development.","p":"xǔ duō gōng sī jiāng zhòng xīn cóng gōng chǎng zhuǎn xiàng yán fā."}]},{"id":"6-1-7","b":6,"l":1,"k":"","t":{"es":"Limitarse a: 自限於","en":"Confine oneself to: 自限於","ens":"Confine oneself to: 自限于","tc":"自限於","sc":"自限于"},"d":{"es":"自限於 + X = «limitarse a / encerrarse uno mismo en X» (título, experiencia, ideas). Tono crítico o de consejo; registro formal.","en":"自限於 X means 'to limit oneself to X' (qualifications, experience, ideas), often used critically or as advice. Formal.","tc":"「自限於 X」是「把自己限制在 X 的範圍裡」，常用來勸人不要被學歷、經驗、想法綁住。語氣較正式。","sc":"「自限于 X」是「把自己限制在 X 的范围里」，常用来劝人不要被学历、经验、想法绑住。语气较正式。"},"ex":[{"c":"一位成功的企業家在場演講中直言，目前許多年輕人常自限於學歷、經驗，而缺乏冒險的精神，失去不少嘗試的機會，相當可惜。","s":"一位成功的企业家在场演讲中直言，目前许多年轻人常自限于学历、经验，而缺乏冒险的精神，失去不少尝试的机会，相当可惜。","es":"Un empresario exitoso dijo abiertamente en una conferencia que hoy muchos jóvenes se limitan a su título y su experiencia, carecen de espíritu aventurero y pierden muchas oportunidades de probar cosas, lo cual es una lástima.","en":"A successful entrepreneur said frankly in a talk that many young people today confine themselves to their degrees and experience, lack a spirit of adventure and miss many chances to try, which is a pity.","p":"yí wèi chéng gōng de qì yè jiā zài chǎng yǎn jiǎng zhōng zhí yán, mù qián xǔ duō nián qīng rén cháng zì xiàn yú xué lì, jīng yàn, ér quē fá mào xiǎn de jīng shén, shī qù bù shǎo cháng shì de jī huì, xiāng dāng kě xí."},{"c":"不要自限於現有的想法，多聽聽別人的意見。","s":"不要自限于现有的想法，多听听别人的意见。","es":"No te encierres en tus ideas actuales; escucha más las opiniones de los demás.","en":"Don't limit yourself to your current ideas; listen to other people's opinions more.","p":"bú yào zì xiàn yú xiàn yǒu de xiǎng fǎ, duō tīng tīng bié rén de yì jiàn."}]},{"id":"6-1-8","b":6,"l":1,"k":"","t":{"es":"Obligar a: 迫使","en":"Force / compel: 迫使","ens":"Force / compel: 迫使","tc":"迫使","sc":"迫使"},"d":{"es":"A 迫使 B + verbo = «A obliga a B a…». El sujeto es una circunstancia o presión (la contaminación, la crisis…), no una persona que da una orden; B no tiene opción. Registro formal.","en":"A 迫使 B + verb: a situation or pressure (pollution, recession) leaves B no choice but to do something. Formal.","tc":"「A 迫使 B＋動詞」表示因為某種情況或壓力，讓 B 不得不做某件事。主詞通常是情況（汙染、不景氣），不是下命令的人。","sc":"「A 迫使 B＋动词」表示因为某种情况或压力，让 B 不得不做某件事。主词通常是情况（污染、不景气），不是下命令的人。"},"ex":[{"c":"嚴重的河海汙染，迫使大家不吃魚、蝦等水產，因為吃水產就等於吃進有毒物質，甚至極小的塑膠粒子。","s":"严重的河海污染，迫使大家不吃鱼、虾等水产，因为吃水产就等于吃进有毒物质，甚至极小的塑胶粒子。","es":"La grave contaminación de ríos y mares obliga a la gente a dejar de comer pescado, camarones y otros productos del agua, porque comerlos equivale a ingerir sustancias tóxicas e incluso diminutas partículas de plástico.","en":"Serious river and sea pollution forces people to stop eating fish, shrimp and other seafood, because eating them is like taking in toxic substances and even tiny plastic particles.","p":"yán zhòng de hé hǎi wū rǎn, pò shǐ dà jiā bù chī yú, xiā děng shuǐ chǎn, yīn wèi chī shuǐ chǎn jiù děng yú chī jìn yǒu dú wù zhí, shèn zhì jí xiǎo de sù jiāo lì zǐ."},{"c":"經濟不景氣迫使不少公司裁員。","s":"经济不景气迫使不少公司裁员。","es":"La recesión económica ha obligado a muchas empresas a despedir personal.","en":"The economic downturn has forced many companies to lay off staff.","p":"jīng jì bù jǐng qì pò shǐ bù shǎo gōng sī cái yuán."}]},{"id":"6-1-9","b":6,"l":1,"k":"","t":{"es":"Empezar a base de: 靠……起家","en":"Start from / rise through …","ens":"Start from / rise through …","tc":"靠……起家","sc":"靠……起家"},"d":{"es":"靠 X 起家 = «levantarse (un negocio, una familia) a base de X», es decir, haber empezado desde abajo gracias a X. Registro neutro-escrito; X suele ser un negocio o un oficio.","en":"靠 X 起家 means to build up a business or family fortune starting from X; X is usually a trade or a skill.","tc":"「靠 X 起家」是說憑著 X 從無到有、慢慢發展起來，X 常是一種生意或技能。","sc":"「靠 X 起家」是说凭着 X 从无到有、慢慢发展起来，X 常是一种生意或技能。"},"ex":[{"c":"小秦家族中的人都很優秀，個個事業成功，祖父母靠餐飲業起家，從夜市的小吃攤發展到現在，已是米其林三星的大餐廳了。","s":"小秦家族中的人都很优秀，个个事业成功，祖父母靠餐饮业起家，从夜市的小吃摊发展到现在，已是米其林三星的大餐厅了。","es":"En la familia de Xiao Qin todos son sobresalientes y exitosos; los abuelos se levantaron con la restauración y, de un puesto de comida en el mercado nocturno, han llegado hoy a tener un gran restaurante de tres estrellas Michelin.","en":"Everyone in Xiao Qin's family is excellent and successful; the grandparents started out in the restaurant business, growing from a snack stall at the night market to a three-star Michelin restaurant today.","p":"xiǎo qín jiā zú zhōng de rén dōu hěn yōu xiù, gè gè shì yè chéng gōng, zǔ fù mǔ kào cān yǐn yè qǐ jiā, cóng yè shì de xiǎo chī tān fā zhǎn dào xiàn zài, yǐ shì mǐ qí lín sān xīng de dà cān tīng le."},{"c":"這家公司靠賣手機殼起家，現在已經是大企業。","s":"这家公司靠卖手机壳起家，现在已经是大企业。","es":"Esta empresa empezó vendiendo fundas de celular y ahora ya es una gran corporación.","en":"This company started by selling phone cases and is now a large corporation.","p":"zhè jiā gōng sī kào mài shǒu jī ké qǐ jiā, xiàn zài yǐ jīng shì dà qì yè."}]},{"id":"6-2-0","b":6,"l":2,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Partir de X: 從X出發","en":"Starting from X","ens":"Starting from X","tc":"從X出發","sc":"从X出发"},"d":{"es":"從 X 出發 = «partir de X» (una necesidad, un punto de vista, la experiencia). También tiene el sentido literal de «salir desde un lugar» (從台北出發). Aquí es el sentido figurado.","en":"從 X 出發 means 'to start from X' (a need, a viewpoint, experience). It can also mean literally 'to set out from a place'.","tc":"「從 X 出發」是「以 X 為起點或基礎」，X 常是需要、角度、經驗。字面上也能指「從某地出發」。","sc":"「从 X 出发」是「以 X 为起点或基础」，X 常是需要、角度、经验。字面上也能指「从某地出发」。"},"ex":[{"c":"有的人從生活中常用的詞語出發，希望馬上就可以跟當地人打招呼或是購物。","s":"有的人从生活中常用的词语出发，希望马上就可以跟当地人打招呼或是购物。","es":"Algunas personas parten de las palabras de uso cotidiano, con la esperanza de poder saludar enseguida a la gente local o hacer compras.","en":"Some people start from words used in daily life, hoping to greet locals or go shopping right away.","p":"yǒu de rén cóng shēng huó zhōng cháng yòng de cí yǔ chū fā, xī wàng mǎ shàng jiù kě yǐ gēn dāng dì rén dǎ zhāo hū huò shì gòu wù."},{"c":"設計產品時，應該從使用者的需要出發。","s":"设计产品时，应该从使用者的需要出发。","es":"Al diseñar un producto hay que partir de las necesidades del usuario.","en":"When designing a product, one should start from the user's needs.","p":"shè jì chǎn pǐn shí, yīng gāi cóng shǐ yòng zhě de xū yào chū fā."}]},{"id":"6-2-1","b":6,"l":2,"k":"","t":{"es":"Llegar a la cifra de: 有X之多","en":"As many as X","ens":"As many as X","tc":"有X之多","sc":"有X之多"},"d":{"es":"有 + cantidad + 之多 = «llegar a haber nada menos que…». Subraya que la cantidad es mayor de lo que se esperaría; suele combinarse con 竟然 o 高達.","en":"有 + quantity + 之多 stresses that the amount is larger than expected ('as many as…'); often used with 竟然.","tc":"「有＋數量＋之多」強調數量很大，比想像的還多，常和「竟然」一起用。","sc":"「有＋数量＋之多」强调数量很大，比想像的还多，常和「竟然」一起用。"},"ex":[{"c":"烹飪美食的方法：煎、煮、炒、炸……，竟然有數百種之多。","s":"烹饪美食的方法：煎、煮、炒、炸……，竟然有数百种之多。","es":"Los métodos de cocinar: freír a la plancha, hervir, saltear, freír en aceite… ¡hay nada menos que cientos!","en":"Cooking methods: pan-fry, boil, stir-fry, deep-fry… there are as many as several hundred.","p":"pēng rèn měi shí de fāng fǎ: jiān, zhǔ, chǎo, zhà… …, jìng rán yǒu shù bǎi zhǒng zhī duō."},{"c":"這間圖書館的藏書有三百萬冊之多。","s":"这间图书馆的藏书有三百万册之多。","es":"La colección de esta biblioteca llega a tres millones de libros.","en":"This library's collection runs to as many as three million volumes.","p":"zhè jiān tú shū guǎn de cáng shū yǒu sān bǎi wàn cè zhī duō."}]},{"id":"6-2-2","b":6,"l":2,"k":"","t":{"es":"Proviene de: 出自","en":"Come from / originate from: 出自","ens":"Come from / originate from: 出自","tc":"出自","sc":"出自"},"d":{"es":"出自 + origen = «proviene de» (una obra, un autor, un libro clásico, la boca de alguien). Sirve para citar la fuente de una frase, una historia o una idea. Formal-neutro.","en":"出自 X means 'originates from X' (a work, an author, a classic, a historical story), used to cite a source.","tc":"「出自 X」表示來源是 X，常指文章、作者、典籍、歷史故事等，可用來說明某句話或某個故事的出處。","sc":"「出自 X」表示来源是 X，常指文章、作者、典籍、历史故事等，可用来说明某句话或某个故事的出处。"},"ex":[{"c":"台灣有許多連續劇或電影都是出自中國歷史，因為歷史上的真人真事比想像的更有意思。","s":"台湾有许多连续剧或电影都是出自中国历史，因为历史上的真人真事比想像的更有意思。","es":"En Taiwán hay muchas series y películas que se basan en la historia de China, porque los hechos y personajes reales de la historia son más interesantes que lo imaginado.","en":"Many Taiwanese TV dramas and films come from Chinese history, because real people and events in history are more interesting than imagination.","p":"tái wān yǒu xǔ duō lián xù jù huò diàn yǐng dōu shì chū zì zhōng guó lì shǐ, yīn wèi lì shǐ shàng de zhēn rén zhēn shì bǐ xiǎng xiàng de gèng yǒu yì sī."},{"c":"這句話出自《論語》。","s":"这句话出自《论语》。","es":"Esta frase proviene de las *Analectas* de Confucio.","en":"This saying comes from the Analects.","p":"zhè jù huà chū zì《 lùn yǔ》."}]},{"id":"6-2-3","b":6,"l":2,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Y así, por lo cual: 從而","en":"Thereby: 從而","ens":"Thereby: 从而","tc":"從而","sc":"从而"},"d":{"es":"A，從而 B = «A, y así / con lo cual B». Une dos cláusulas con el mismo sujeto: B es el resultado o el propósito de A. Solo se usa en el lenguaje escrito o formal.","en":"A，從而 B means 'A, thereby B': B is the result or purpose of A, usually with the same subject. Written/formal only.","tc":"「A，從而 B」表示 B 是由 A 帶來的結果或目的，兩句通常是同一個主詞。只用在書面語。","sc":"「A，从而 B」表示 B 是由 A 带来的结果或目的，两句通常是同一个主词。只用在书面语。"},"ex":[{"c":"人類是透過科學研究，從而發現生命的根源。","s":"人类是透过科学研究，从而发现生命的根源。","es":"El ser humano, mediante la investigación científica, descubre así el origen de la vida.","en":"Humans discover the roots of life through scientific research.","p":"rén lèi shì tòu guò kē xué yán jiù, cóng ér fā xiàn shēng mìng de gēn yuán."},{"c":"他每天運動，從而改善了健康狀況。","s":"他每天运动，从而改善了健康状况。","es":"Hace ejercicio todos los días y con ello mejoró su estado de salud.","en":"He exercises every day and thereby improved his health.","p":"tā měi tiān yùn dòng, cóng ér gǎi shàn le jiàn kāng zhuàng kuàng."}]},{"id":"6-2-4","b":6,"l":2,"k":"","t":{"es":"Estar acostumbrado a X: 對X習以為常","en":"Take X for granted","ens":"Take X for granted","tc":"對X習以為常","sc":"对X习以为常"},"d":{"es":"對 X 習以為常 = «estar tan acostumbrado a X que ya no resulta extraño». Implica que algo que a otros les parecería raro ya es normal para esa persona.","en":"對 X 習以為常 means to be so used to X that it no longer seems strange.","tc":"「對 X 習以為常」是對 X 已經很習慣，不覺得奇怪或特別。","sc":"「对 X 习以为常」是对 X 已经很习惯，不觉得奇怪或特别。"},"ex":[{"c":"學生對考試、寫報告習以為常，會早做準備。","s":"学生对考试、写报告习以为常，会早做准备。","es":"Los estudiantes están acostumbrados a los exámenes y a escribir informes, así que se preparan con tiempo.","en":"Students are used to exams and writing reports, so they prepare early.","p":"xué shēng duì kǎo shì, xiě bào gào xí yǐ wéi cháng, huì zǎo zuò zhǔn bèi."},{"c":"住在海邊的人對颱風習以為常。","s":"住在海边的人对台风习以为常。","es":"La gente que vive junto al mar está acostumbrada a los tifones.","en":"People who live by the sea take typhoons for granted.","p":"zhù zài hǎi biān de rén duì tái fēng xí yǐ wéi cháng."}]},{"id":"6-2-5","b":6,"l":2,"k":"","t":{"es":"Formar Y con X: 利用X組成Y","en":"Use X to form Y","ens":"Use X to form Y","tc":"利用X組成Y","sc":"利用X组成Y"},"d":{"es":"利用 X 組成 Y = «usar X para formar / armar Y». X es el material y Y es el resultado; se dice 利用 antes de 組成 para indicar el medio.","en":"利用 X 組成 Y: using X as the material to put together Y.","tc":"「利用 X 組成 Y」是用 X 當材料或工具，組合成 Y。X 是材料，Y 是完成的東西。","sc":"「利用 X 组成 Y」是用 X 当材料或工具，组合成 Y。X 是材料，Y 是完成的东西。"},"ex":[{"c":"這個樂團的特色是利用空罐子、空瓶子組成樂器。","s":"这个乐团的特色是利用空罐子、空瓶子组成乐器。","es":"La característica de esta banda es que arma sus instrumentos con latas y botellas vacías.","en":"This band's special feature is using empty cans and bottles to make instruments.","p":"zhè ge yuè tuán de tè sè shì lì yòng kōng guàn zi, kōng píng zi zǔ chéng yuè qì."},{"c":"孩子們利用積木組成一座小城市。","s":"孩子们利用积木组成一座小城市。","es":"Los niños armaron una pequeña ciudad con bloques.","en":"The children used building blocks to put together a little city.","p":"hái zi men lì yòng jī mù zǔ chéng yí zuò xiǎo chéng shì."}]},{"id":"6-2-6","b":6,"l":2,"k":"","t":{"es":"Equivale a: 等於是","en":"Is equivalent to: 等於是","ens":"Is equivalent to: 等于是","tc":"等於是","sc":"等于是"},"d":{"es":"A 等於是 B = «A equivale a B / es como B». Es un juicio subjetivo que presenta A como lo mismo que B, a menudo con tono exagerado o crítico. Sinónimo: 就等於、無異於.","en":"A 等於是 B means the speaker sees A as the same as B, often with an exaggerated or critical tone. Similar: 就等於, 無異於.","tc":"「A 等於是 B」表示說話者認為 A 就和 B 一樣，常帶有誇張或批評的語氣。類似的說法有「就等於、無異於」。","sc":"「A 等于是 B」表示说话者认为 A 就和 B 一样，常带有夸张或批评的语气。类似的说法有「就等于、无异于」。"},"ex":[{"c":"慢跑或走樓梯等於是懲罰膝蓋。","s":"慢跑或走楼梯等于是惩罚膝盖。","es":"Trotar o subir escaleras equivale a castigar las rodillas.","en":"Jogging or climbing stairs is like punishing your knees.","p":"màn pǎo huò zǒu lóu tī děng yú shì chéng fá xī gài."},{"c":"不遵守規定等於是給別人添麻煩。","s":"不遵守规定等于是给别人添麻烦。","es":"No cumplir las reglas equivale a causarles problemas a los demás.","en":"Not following the rules is equivalent to making trouble for others.","p":"bù zūn shǒu guī dìng děng yú shì gěi bié rén tiān má fán."}]},{"id":"6-3-0","b":6,"l":3,"k":"","t":{"es":"Sin reservas: 盡情","en":"To one's heart's content: 盡情","ens":"To one's heart's content: 尽情","tc":"盡情 (Adv)","sc":"尽情 (Adv)"},"d":{"es":"盡情 + verbo = hacer algo sin reservas, a todo gusto (盡情享受、盡情玩、盡情唱). Es un adverbio que va antes del verbo; expresa que se disfruta sin contenerse.","en":"盡情 is an adverb placed before a verb: to do something wholeheartedly, without holding back (盡情享受, 盡情玩, 盡情唱歌).","tc":"「盡情＋動詞」是毫無保留、盡量地做某件事，常見搭配有盡情享受、盡情玩、盡情唱歌。它是副詞，放在動詞前面。","sc":"「尽情＋动词」是毫无保留、尽量地做某件事，常见搭配有尽情享受、尽情玩、尽情唱歌。它是副词，放在动词前面。"},"ex":[{"c":"你覺得什麼時候可以盡情享受美食，為什麼？","s":"你觉得什么时候可以尽情享受美食，为什么？","es":"¿Cuándo sientes que puedes disfrutar de la buena comida sin reservas, y por qué?","en":"When do you feel you can enjoy good food to your heart's content, and why?","p":"nǐ jué dé shén me shí hòu kě yǐ jìn qíng xiǎng shòu měi shí, wèi shén me?"},{"c":"我覺得和朋友在一起的時候可以盡情享受美食，因為很開心、很放鬆。","s":"我觉得和朋友在一起的时候可以尽情享受美食，因为很开心、很放松。","es":"Siento que puedo disfrutar de la buena comida a mis anchas cuando estoy con amigos, porque me divierto y me relajo.","en":"I feel I can enjoy good food to my heart's content when I'm with friends, because I'm happy and relaxed.","p":"wǒ jué dé hàn péng yǒu zài yì qǐ de shí hòu kě yǐ jìn qíng xiǎng shòu měi shí, yīn wèi hěn kāi xīn, hěn fàng sōng."}]},{"id":"6-3-1","b":6,"l":3,"k":"","t":{"es":"En calidad de: 以X（的）身分","en":"In the capacity of X","ens":"In the capacity of X","tc":"以X（的）身分","sc":"以X（的）身分"},"d":{"es":"以 X（的）身分 + verbo = «en calidad de / como X». Indica el papel o posición desde el que se actúa o se habla (representante, testigo, observador…).","en":"以 X（的）身分 means 'in the capacity / role of X' — the position from which someone acts or speaks.","tc":"「以 X（的）身分」表示用 X 的立場或角色來做事或說話，例如代表、旁觀者、朋友。","sc":"「以 X（的）身分」表示用 X 的立场或角色来做事或说话，例如代表、旁观者、朋友。"},"ex":[{"c":"我以旁觀者的身分直言，你的消費力實在太驚人了。","s":"我以旁观者的身分直言，你的消费力实在太惊人了。","es":"Hablando con franqueza en mi calidad de observador externo, tu capacidad de gasto es realmente asombrosa.","en":"Speaking frankly as a bystander, your spending power is truly astonishing.","p":"wǒ yǐ páng guān zhě de shēn fēn zhí yán, nǐ de xiāo fèi lì shí zài tài jīng rén le."},{"c":"他以學生代表的身分上台致詞。","s":"他以学生代表的身分上台致词。","es":"Subió al escenario a dar un discurso como representante de los estudiantes.","en":"He went on stage to give a speech as the student representative.","p":"tā yǐ xué shēng dài biǎo de shēn fēn shàng tái zhì cí."}]},{"id":"6-3-2","b":6,"l":3,"k":"dirección movimiento direction movement 方向 趨向 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 dirección movimiento direction movement 方向 趋向 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Hacer un «gran encuentro» de X y Y: 來個X大會Y","en":"Hold a big 'X meets Y'","ens":"Hold a big 'X meets Y'","tc":"來個X (大)會Y","sc":"来个X (大)会Y"},"d":{"es":"來個 X 大會 Y = forma humorística y coloquial de «organizar un gran encuentro entre X y Y» (aquí 會 es «reunirse»). Se usa para dar un toque juguetón a la frase; es creativa, no una estructura rígida.","en":"來個 X 大會 Y is a playful, colloquial pattern meaning roughly 'let's hold a big X-meets-Y gathering' (會 = to meet). It is a humorous coinage rather than a rigid structure.","tc":"「來個 X 大會 Y」是一種有點幽默的口語說法，意思像「來辦一場 X 和 Y 的大會面（大聚會）」，用來讓句子比較活潑，不是很固定的句型。","sc":"「来个 X 大会 Y」是一种有点幽默的口语说法，意思像「来办一场 X 和 Y 的大会面（大聚会）」，用来让句子比较活泼，不是很固定的句型。"},"ex":[{"c":"你是否喜歡在假日玩手機，沉迷在虛擬世界中，來個人腦大會電腦？為什麼？","s":"你是否喜欢在假日玩手机，沉迷在虚拟世界中，来个人脑大会电脑？为什么？","es":"¿Te gusta usar el celular los días de descanso, absorto en el mundo virtual, y hacer un «gran encuentro entre el cerebro humano y la computadora»? ¿Por qué?","en":"Do you like playing on your phone on holidays, lost in the virtual world, holding a big 'human brain meets computer' event? Why?","p":"nǐ shì fǒu xǐ huān zài jià rì wán shǒu jī, chén mí zài xū nǐ shì jiè zhōng, lái gè rén nǎo dà huì diàn nǎo? wèi shén me?"},{"c":"週末我們來個火鍋大會餐，好好慶祝一下吧！","s":"周末我们来个火锅大会餐，好好庆祝一下吧！","es":"El fin de semana hagamos una gran comilona de hot pot para celebrar.","en":"Let's have a big hot pot feast this weekend and celebrate properly!","p":"zhōu mò wǒ men lái gè huǒ guō dà huì cān, hǎo hǎo qìng zhù yí xià ba!"}]},{"id":"6-3-3","b":6,"l":3,"k":"","t":{"es":"X se convierte en Y: X化為Y","en":"X turns into Y","ens":"X turns into Y","tc":"X化為Y","sc":"X化为Y"},"d":{"es":"X 化為 Y = «X se transforma en Y». Muestra un cambio de naturaleza o forma (basura → recursos, tristeza → fuerza). 化為 es más escrito que 變成. También se usa 把 X 化為 Y.","en":"X 化為 Y means X is transformed into Y (waste → resources, grief → strength). More written than 變成; also 把 X 化為 Y.","tc":"「X 化為 Y」是 X 變成了另一種東西 Y，比「變成」更書面。也可以說「把 X 化為 Y」。","sc":"「X 化为 Y」是 X 变成了另一种东西 Y，比「变成」更书面。也可以说「把 X 化为 Y」。"},"ex":[{"c":"現代科技能使垃圾化為資源。","s":"现代科技能使垃圾化为资源。","es":"La tecnología moderna puede convertir la basura en recursos.","en":"Modern technology can turn garbage into resources.","p":"xiàn dài kē jì néng shǐ lè sè huà wéi zī yuán."},{"c":"他把悲傷化為力量，繼續往前走。","s":"他把悲伤化为力量，继续往前走。","es":"Convirtió su tristeza en fuerza y siguió adelante.","en":"He turned his sadness into strength and kept moving forward.","p":"tā bǎ bēi shāng huà wéi lì liàng, jì xù wǎng qián zǒu."}]},{"id":"6-3-4","b":6,"l":3,"k":"","t":{"es":"En el instante en que: 在……（的）剎那","en":"At the instant when…","ens":"At the instant when…","tc":"在……（的）剎那","sc":"在……（的）刹那"},"d":{"es":"在 + evento + （的）剎那 = «en el instante en que…». Marca un momento muy breve en el que ocurre algo importante; es literario y dramático. Se puede abreviar como 在…剎那.","en":"在…（的）剎那 means 'at the very instant when…', a brief, dramatic moment. Literary tone.","tc":"「在……（的）剎那」指某件事發生的那一瞬間，很短暫，語氣有點文學或戲劇性。","sc":"「在……（的）刹那」指某件事发生的那一瞬间，很短暂，语气有点文学或戏剧性。"},"ex":[{"c":"在大地震發生的剎那，地動天搖，大家爭先恐後跑到戶外，躲避可能發生的災難。","s":"在大地震发生的刹那，地动天摇，大家争先恐后跑到户外，躲避可能发生的灾难。","es":"En el instante en que ocurrió el gran terremoto, cielo y tierra se sacudieron, y todos corrieron a empujones al exterior para evitar un posible desastre.","en":"At the instant the big earthquake struck, the ground shook, and everyone rushed outdoors to avoid a possible disaster.","p":"zài dà dì zhèn fā shēng de chà nà, dì dòng tiān yáo, dà jiā zhēng xiān kǒng hòu pǎo dào hù wài, duǒ bì kě néng fā shēng de zāi nán."},{"c":"在車子撞上來的剎那，他本能地閉上了眼睛。","s":"在车子撞上来的刹那，他本能地闭上了眼睛。","es":"En el instante en que el auto se le vino encima, cerró los ojos por instinto.","en":"The instant the car crashed into him, he instinctively closed his eyes.","p":"zài chē zi zhuàng shàng lái de chà nà, tā běn néng dì bì shàng le yǎn jīng."}]},{"id":"6-3-5","b":6,"l":3,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Tarde o temprano: 終會……的","en":"In the end will surely…: 終會…的","ens":"In the end will surely…: 终会…的","tc":"終會……的","sc":"终会……的"},"d":{"es":"終會 + verbo + 的 = «tarde o temprano se… / al final seguramente…». Expresa confianza en un resultado futuro; suele ir con 只要 y se cierra con 的 para dar certeza.","en":"終會…的 expresses confidence that something will surely happen in the end; often paired with 只要, with sentence-final 的 adding certainty.","tc":"「終會……的」表示相信將來一定會有某個結果，常和「只要」一起用，句尾的「的」加強肯定的語氣。","sc":"「终会……的」表示相信将来一定会有某个结果，常和「只要」一起用，句尾的「的」加强肯定的语气。"},"ex":[{"c":"你相信「只要努力，終會成功的」嗎？","s":"你相信「只要努力，终会成功的」吗？","es":"¿Crees que «si te esfuerzas, tarde o temprano tendrás éxito»?","en":"Do you believe that 'as long as you work hard, you will succeed in the end'?","p":"nǐ xiāng xìn 「zhǐ yào nǔ lì, zhōng huì chéng gōng de」 ma?"},{"c":"只要不放棄，夢想終會實現的。","s":"只要不放弃，梦想终会实现的。","es":"Mientras no te rindas, tarde o temprano tus sueños se harán realidad.","en":"As long as you don't give up, your dreams will come true in the end.","p":"zhǐ yào bú fàng qì, mèng xiǎng zhōng huì shí xiàn de."}]},{"id":"6-3-6","b":6,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Con solo mirar: 一眼就……","en":"At a single glance: 一眼就…","ens":"At a single glance: 一眼就…","tc":"一眼就……","sc":"一眼就……"},"d":{"es":"一眼就 + verbo = «con solo echar un vistazo, enseguida…» (一眼就看出、一眼就愛上). Indica que algo se percibe o se decide muy rápido al ver.","en":"一眼就… means 'at a single glance, immediately…' (一眼就看出, 一眼就愛上).","tc":"「一眼就……」表示一看就馬上知道或決定，例如一眼就看出、一眼就愛上。","sc":"「一眼就……」表示一看就马上知道或决定，例如一眼就看出、一眼就爱上。"},"ex":[{"c":"你是否會一眼就愛上一個人呢？","s":"你是否会一眼就爱上一个人呢？","es":"¿Podrías enamorarte de alguien con solo verlo?","en":"Could you fall in love with someone at first sight?","p":"nǐ shì fǒu huì yì yǎn jiù ài shàng yí ge rén ne?"},{"c":"我一眼就看出他在說謊。","s":"我一眼就看出他在说谎。","es":"Me di cuenta de un vistazo de que estaba mintiendo.","en":"I saw at a glance that he was lying.","p":"wǒ yì yǎn jiù kàn chū tā zài shuō huǎng."}]},{"id":"6-3-7","b":6,"l":3,"k":"","t":{"es":"Gracias a / basándose en: 憑","en":"Relying on / by virtue of: 憑","ens":"Relying on / by virtue of: 凭","tc":"憑","sc":"凭"},"d":{"es":"憑 + condición (una habilidad, un esfuerzo, una prueba) = «gracias a / basándose en…». Después se presenta lo que se logra o se concluye. También se usa en preguntas retóricas: 憑什麼 «¿con qué derecho?».","en":"憑 + condition means 'relying on / on the strength of' a skill, effort or evidence. Also in rhetorical questions: 憑什麼 'on what grounds?'.","tc":"「憑＋條件」表示依靠或根據某種能力、努力、證據，後面說能做到的事。也可以用在反問：「憑什麼？」","sc":"「凭＋条件」表示依靠或根据某种能力、努力、证据，后面说能做到的事。也可以用在反问：「凭什么？」"},"ex":[{"c":"技職生憑一技在身，一畢業就能上工，比大學畢業生更受廠商的歡迎。","s":"技职生凭一技在身，一毕业就能上工，比大学毕业生更受厂商的欢迎。","es":"Los egresados de educación técnica, gracias a que dominan un oficio, pueden ponerse a trabajar nada más graduarse y son mejor recibidos por las empresas que los universitarios.","en":"Vocational graduates, relying on a skill, can start work as soon as they graduate and are more welcome to employers than university graduates.","p":"jì zhí shēng píng yí jì zài shēn, yí bì yè jiù néng shàng gōng, bǐ dà xué bì yè shēng gèng shòu chǎng shāng de huān yíng."},{"c":"他憑著自己的努力，考上了理想的學校。","s":"他凭着自己的努力，考上了理想的学校。","es":"Gracias a su propio esfuerzo, entró a la escuela que quería.","en":"By his own efforts, he got into the school he wanted.","p":"tā píng zhe zì jǐ de nǔ lì, kǎo shàng le lǐ xiǎng de xué xiào."}]},{"id":"6-3-8","b":6,"l":3,"k":"","t":{"es":"Imponer sobre: 加諸（在）","en":"Impose on: 加諸（在）","ens":"Impose on: 加诸（在）","tc":"加諸（在）","sc":"加诸（在）"},"d":{"es":"加諸（在）+ persona = «imponer / cargar sobre». 加諸 = 加在…上 (諸 = 之於). Se usa con cosas abstractas negativas o pesadas: 壓力、責任、痛苦、期望. Registro formal y escrito.","en":"加諸（在）means 'to impose upon / place on someone' (加諸 = 加在…上). Used with abstract burdens: pressure, responsibility, expectations, suffering. Formal.","tc":"「加諸（在）」就是「加在……身上」，常接壓力、責任、期望、痛苦等抽象的東西，語氣正式、書面。","sc":"「加诸（在）」就是「加在……身上」，常接压力、责任、期望、痛苦等抽象的东西，语气正式、书面。"},"ex":[{"c":"貼補家用的壓力，常加諸在弱勢家庭的孩童身上，迫使他們不得不放棄學業。","s":"贴补家用的压力，常加诸在弱势家庭的孩童身上，迫使他们不得不放弃学业。","es":"La presión de contribuir a los gastos de la casa suele recaer sobre los niños de familias vulnerables, obligándolos a abandonar los estudios.","en":"The pressure to supplement the family income is often placed on children from disadvantaged families, forcing them to give up their studies.","p":"tiē bǔ jiā yòng de yā lì, cháng jiā zhū zài ruò shì jiā tíng de hái tóng shēn shàng, pò shǐ tā men bù dé bú fàng qì xué yè."},{"c":"不要把自己的期望加諸在孩子身上。","s":"不要把自己的期望加诸在孩子身上。","es":"No impongas tus propias expectativas a tus hijos.","en":"Don't impose your own expectations on your children.","p":"bú yào bǎ zì jǐ de qí wàng jiā zhū zài hái zi shēn shàng."}]},{"id":"6-3-9","b":6,"l":3,"k":"","t":{"es":"¿Acaso no…?: 何嘗","en":"How could it be that…not: 何嘗","ens":"How could it be that…not: 何尝","tc":"何嘗","sc":"何尝"},"d":{"es":"何嘗 introduce una pregunta retórica. Lo más común es 何嘗不／何嘗沒 + verbo = «¿cómo no iba a…?, en realidad sí…»; a veces 何嘗 + afirmativo implica «nada de eso». El hablante expresa en el fondo lo contrario a lo que parece. Registro escrito/formal.","en":"何嘗 introduces a rhetorical question. Most common is 何嘗不／何嘗沒…, meaning 'it's not that I don't…; in fact I do'. The speaker means the opposite of the literal question. Written/formal.","tc":"「何嘗」用來反問，最常見的是「何嘗不／何嘗沒……」，意思是「其實是……的」，說話者要表達的和字面相反。多用於書面或比較正式的場合。","sc":"「何尝」用来反问，最常见的是「何尝不／何尝没……」，意思是「其实是……的」，说话者要表达的和字面相反。多用于书面或比较正式的场合。"},"ex":[{"c":"創新才能突破困境，我們何嘗不了解？不過實際上創新需要熱情與勇氣，這正是我們所缺乏的。","s":"创新才能突破困境，我们何尝不了解？不过实际上创新需要热情与勇气，这正是我们所缺乏的。","es":"Solo innovando se puede salir de las dificultades, ¿acaso no lo entendemos? Pero en la práctica innovar requiere pasión y valentía, y eso es justo lo que nos falta.","en":"Only innovation can break through difficulties — don't we understand that? But in practice innovation needs passion and courage, which is exactly what we lack.","p":"chuàng xīn cái néng tú pò kùn jìng, wǒ men hé cháng bù liǎo jiě? bú guò shí jì shàng chuàng xīn xū yào rè qíng yǔ yǒng qì, zhè zhèng shì wǒ men suǒ quē fá de."},{"c":"我何嘗不想早點回家，只是工作還沒做完。","s":"我何尝不想早点回家，只是工作还没做完。","es":"¿Cómo no voy a querer volver a casa temprano? Es que todavía no he terminado el trabajo.","en":"It's not that I don't want to go home early; I just haven't finished my work.","p":"wǒ hé cháng bù xiǎng zǎo diǎn huí jiā, zhǐ shì gōng zuò hái méi zuò wán."}]},{"id":"6-3-10","b":6,"l":3,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Sin darse cuenta: 不自覺（地）","en":"Unconsciously: 不自覺（地）","ens":"Unconsciously: 不自觉（地）","tc":"不自覺（地）","sc":"不自觉（地）"},"d":{"es":"不自覺（地）+ verbo = «sin darse cuenta, de forma involuntaria». Describe una reacción o acción que ocurre sin decisión consciente; muy parecido a 不知不覺, pero más centrado en la acción del cuerpo o los gestos.","en":"不自覺（地）+ verb means doing something without realizing it or meaning to; close to 不知不覺.","tc":"「不自覺（地）＋動詞」表示自己沒有注意到、不是故意地做了某個動作或反應，和「不知不覺」很接近。","sc":"「不自觉（地）＋动词」表示自己没有注意到、不是故意地做了某个动作或反应，和「不知不觉」很接近。"},"ex":[{"c":"剛烤好出爐的麵包，會讓人不自覺地垂涎三尺，因此烘焙業者總將麵包出爐的時間選在下午四點，大家肚子有點餓的時候。","s":"刚烤好出炉的面包，会让人不自觉地垂涎三尺，因此烘焙业者总将面包出炉的时间选在下午四点，大家肚子有点饿的时候。","es":"El pan recién salido del horno hace que uno se salive sin darse cuenta; por eso los panaderos suelen sacar el pan a las cuatro de la tarde, cuando la gente ya tiene un poco de hambre.","en":"Freshly baked bread makes people drool without realizing it, so bakers always schedule their bread to come out at four in the afternoon, when everyone is a little hungry.","p":"gāng kǎo hǎo chū lú de miàn bāo, huì ràng rén bú zì jué dì chuí xián sān chǐ, yīn cǐ hōng bèi yè zhě zǒng jiāng miàn bāo chū lú de shí jiān xuǎn zài xià wǔ sì diǎn, dà jiā dù zi yǒu diǎn è de shí hòu."},{"c":"聽到那首老歌，我不自覺地跟著唱了起來。","s":"听到那首老歌，我不自觉地跟着唱了起来。","es":"Al oír esa canción antigua, me puse a cantar sin darme cuenta.","en":"Hearing that old song, I found myself singing along without realizing it.","p":"tīng dào nà shǒu lǎo gē, wǒ bú zì jué dì gēn zhe chàng le qǐ lái."}]},{"id":"6-4-0","b":6,"l":4,"k":"","t":{"es":"Compartir Y con X: 與X分享Y","en":"Share Y with X","ens":"Share Y with X","tc":"與X分享Y","sc":"与X分享Y"},"d":{"es":"與 X 分享 Y = «compartir Y con X». 與 es la forma escrita de 跟/和; Y suele ser algo agradable (alegría, suerte, experiencia, fotos). Se puede invertir: 把 Y 與 X 分享.","en":"與 X 分享 Y means 'to share Y with X'. 與 is the written form of 跟/和; Y is usually something good (joy, luck, experience).","tc":"「與 X 分享 Y」是和 X 一起分享 Y，「與」是書面語的「跟／和」，Y 常是好的事物，如快樂、幸運、經驗。","sc":"「与 X 分享 Y」是和 X 一起分享 Y，「与」是书面语的「跟／和」，Y 常是好的事物，如快乐、幸运、经验。"},"ex":[{"c":"如果有人送我免費的電影票，我希望與室友分享這份幸運，因為他是我在台灣最好的朋友。","s":"如果有人送我免费的电影票，我希望与室友分享这份幸运，因为他是我在台湾最好的朋友。","es":"Si alguien me regalara entradas de cine gratis, me gustaría compartir esa suerte con mi compañero de cuarto, porque es mi mejor amigo en Taiwán.","en":"If someone gave me free movie tickets, I would want to share that luck with my roommate, because he is my best friend in Taiwan.","p":"rú guǒ yǒu rén sòng wǒ miǎn fèi de diàn yǐng piào, wǒ xī wàng yǔ shì yǒu fēn xiǎng zhè fèn xìng yùn, yīn wèi tā shì wǒ zài tái wān zuì hǎo de péng yǒu."},{"c":"我喜歡與家人分享旅行中的照片。","s":"我喜欢与家人分享旅行中的照片。","es":"Me gusta compartir con mi familia las fotos de mis viajes.","en":"I like to share photos from my trips with my family.","p":"wǒ xǐ huān yǔ jiā rén fēn xiǎng lǚ xíng zhōng de zhào piàn."}]},{"id":"6-4-1","b":6,"l":4,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Vivir con la filosofía de…: 抱持著……的哲學","en":"Hold the philosophy of…","ens":"Hold the philosophy of…","tc":"抱持著……的哲學","sc":"抱持着……的哲学"},"d":{"es":"抱持著 + «lema» + 的哲學 = «mantener la filosofía de…». Entre las comillas se pone una frase corta que resume la actitud de vida. 抱持 = mantener una actitud, creencia o expectativa (抱持希望、抱持懷疑).","en":"抱持著…的哲學 means 'to hold the philosophy of…'; a short life motto goes in between. 抱持 takes attitudes and beliefs (抱持希望, 抱持懷疑).","tc":"「抱持著……的哲學」是說一個人的生活態度像這句話一樣，中間常放一句短短的人生信條。「抱持」常接態度、信念，例如抱持希望、抱持懷疑。","sc":"「抱持着……的哲学」是说一个人的生活态度像这句话一样，中间常放一句短短的人生信条。「抱持」常接态度、信念，例如抱持希望、抱持怀疑。"},"ex":[{"c":"最近老王的身體相當不好，常進出醫院，難怪一直抱持著｢活一天，賺一天｣的哲學過日子。","s":"最近老王的身体相当不好，常进出医院，难怪一直抱持着｢活一天，赚一天｣的哲学过日子。","es":"Últimamente la salud del señor Wang está bastante mal y entra y sale del hospital; no es de extrañar que viva con la filosofía de «un día vivido es un día ganado».","en":"Lately Lao Wang's health has been poor and he often goes in and out of the hospital; no wonder he lives by the philosophy of 'every day lived is a day gained'.","p":"zuì jìn lǎo wáng de shēn tǐ xiāng dāng bù hǎo, cháng jìn chū yī yuàn, nán guài yì zhí bào chí zhe｢ huó yì tiān, zhuàn yì tiān｣ de zhé xué guò rì zi."},{"c":"他抱持著「船到橋頭自然直」的哲學，從不擔心未來。","s":"他抱持着「船到桥头自然直」的哲学，从不担心未来。","es":"Vive con la filosofía de «todo se arregla sobre la marcha» y nunca se preocupa por el futuro.","en":"He lives by the philosophy of 'things will work out when the time comes' and never worries about the future.","p":"tā bào chí zhe 「chuán dào qiáo tóu zì rán zhí」 de zhé xué, cóng bù dān xīn wèi lái."}]},{"id":"6-4-2","b":6,"l":4,"k":"","t":{"es":"Dar el primer paso: 踏出……的第一步","en":"Take the first step toward…","ens":"Take the first step toward…","tc":"踏出……的第一步","sc":"踏出……的第一步"},"d":{"es":"踏出 + meta + 的第一步 = «dar el primer paso hacia / de…». Se usa en sentido figurado para el comienzo de un proceso o proyecto importante.","en":"踏出…的第一步 is a figurative expression for starting something important ('take the first step of/toward…').","tc":"「踏出……的第一步」是比喻說法，表示開始做某件重要的事情，例如踏出成功的第一步。","sc":"「踏出……的第一步」是比喻说法，表示开始做某件重要的事情，例如踏出成功的第一步。"},"ex":[{"c":"產業與技職教育緊密合作是踏出競爭力的第一步。","s":"产业与技职教育紧密合作是踏出竞争力的第一步。","es":"La estrecha colaboración entre la industria y la educación técnica es el primer paso hacia la competitividad.","en":"Close cooperation between industry and vocational education is the first step toward competitiveness.","p":"chǎn yè yǔ jì zhí jiào yù jǐn mì hé zuò shì tà chū jìng zhēng lì de dì yī bù."},{"c":"參加這個課程，是我踏出學習中文的第一步。","s":"参加这个课程，是我踏出学习中文的第一步。","es":"Inscribirme en este curso fue mi primer paso para aprender chino.","en":"Joining this course was my first step in learning Chinese.","p":"cān jiā zhè ge kè chéng, shì wǒ tà chū xué xí zhōng wén de dì yī bù."}]},{"id":"6-4-3","b":6,"l":4,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Bien podrías: 不妨","en":"Might as well: 不妨","ens":"Might as well: 不妨","tc":"不妨","sc":"不妨"},"d":{"es":"不妨 + verbo = «bien podrías / no está de más…». Es una sugerencia suave y amable: no es obligatoria y no hay inconveniente en hacerlo. No se usa para ordenar ni sobre uno mismo con tono de obligación.","en":"不妨 + verb is a gentle suggestion: 'there's no harm in…, you might as well…'. It is not a command.","tc":"「不妨＋動詞」是一種客氣的建議，表示「這樣做也沒有壞處，可以試試看」，不是命令。","sc":"「不妨＋动词」是一种客气的建议，表示「这样做也没有坏处，可以试试看」，不是命令。"},"ex":[{"c":"踏出建立人際關係的第一步，不妨與同桌吃飯的人交換名片，因為主動與熱忱才能帶來好機緣。","s":"踏出建立人际关系的第一步，不妨与同桌吃饭的人交换名片，因为主动与热忱才能带来好机缘。","es":"Para dar el primer paso en la construcción de relaciones, bien podrías intercambiar tarjetas de presentación con quien comparte tu mesa, porque solo la iniciativa y el entusiasmo traen buenas oportunidades.","en":"To take the first step in building relationships, you might exchange business cards with the people at your table, since only initiative and enthusiasm bring good opportunities.","p":"tà chū jiàn lì rén jì guān xì de dì yī bù, bù fáng yǔ tóng zhuō chī fàn de rén jiāo huàn míng piàn, yīn wèi zhǔ dòng yǔ rè chén cái néng dài lái hǎo jī yuán."},{"c":"如果你覺得累，不妨先休息一下。","s":"如果你觉得累，不妨先休息一下。","es":"Si te sientes cansado, bien podrías descansar un poco primero.","en":"If you feel tired, you might as well rest for a bit first.","p":"rú guǒ nǐ jué dé lèi, bù fáng xiān xiū xí yí xià."}]},{"id":"6-4-4","b":6,"l":4,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Haber margen para…: （沒）有……的餘地","en":"(No) room for…","ens":"(No) room for…","tc":"（沒）有……的餘地","sc":"（没）有……的余地"},"d":{"es":"（沒）有 + acción + 的餘地 = «(no) haber margen / espacio para…». 餘地 es el margen que queda para negociar, discutir o elegir. Frases típicas: 沒有討論的餘地、有改進的餘地、沒有選擇的餘地.","en":"（沒）有…的餘地 means there is (no) room or leeway to do something, e.g. 沒有選擇的餘地, 有改進的餘地.","tc":"「（沒）有……的餘地」表示（沒有）空間或機會可以做某件事，常見的有「沒有選擇的餘地、有改進的餘地、沒有討價還價的餘地」。","sc":"「（没）有……的余地」表示（没有）空间或机会可以做某件事，常见的有「没有选择的余地、有改进的余地、没有讨价还价的余地」。"},"ex":[{"c":"店員表示不二價，不使顧客有講價的餘地，免得浪費時間。","s":"店员表示不二价，不使顾客有讲价的余地，免得浪费时间。","es":"El dependiente dijo que el precio es fijo para que el cliente no tenga margen de regateo y no se pierda tiempo.","en":"The clerk said the price was fixed, giving customers no room to bargain, to avoid wasting time.","p":"diàn yuán biǎo shì bú èr jià, bù shǐ gù kè yǒu jiǎng jià de yú dì, miǎn dé làng fèi shí jiān."},{"c":"這件事已經決定了，沒有討論的餘地。","s":"这件事已经决定了，没有讨论的余地。","es":"Esto ya está decidido; no hay margen para discutirlo.","en":"This has already been decided; there is no room for discussion.","p":"zhè jiàn shì yǐ jīng jué dìng le, méi yǒu tǎo lùn de yú dì."}]},{"id":"6-4-5","b":6,"l":4,"k":"","t":{"es":"De modo que (resultado): 以致（於）","en":"As a result / so that (bad outcome): 以致（於）","ens":"As a result / so that (bad outcome): 以致（于）","tc":"以致（於）","sc":"以致（于）"},"d":{"es":"A，以致（於）B = «A, de modo que / con el resultado de que B». B es una consecuencia, casi siempre negativa o no deseada, de A. No se usa para expresar un propósito (para eso: 以便、為了).","en":"A，以致（於）B: A leads to the result B, which is usually unfavorable. It cannot express purpose (use 以便 or 為了 instead).","tc":"「A，以致（於）B」表示因為 A 而造成 B 這個結果，B 通常是不好的、不希望發生的結果。不能用來表示目的。","sc":"「A，以致（于）B」表示因为 A 而造成 B 这个结果，B 通常是不好的、不希望发生的结果。不能用来表示目的。"},"ex":[{"c":"空氣汙染愈來愈嚴重，以致於有呼吸道疾病的人愈來愈多。","s":"空气污染愈来愈严重，以致于有呼吸道疾病的人愈来愈多。","es":"La contaminación del aire es cada vez más grave, de modo que cada vez hay más personas con enfermedades respiratorias.","en":"Air pollution is getting worse, so that more and more people have respiratory diseases.","p":"kōng qì wū rǎn yù lái yù yán zhòng, yǐ zhì yú yǒu hū xī dào jí bìng de rén yù lái yù duō."},{"c":"他昨晚熬夜，以致今天上課一直打瞌睡。","s":"他昨晚熬夜，以致今天上课一直打瞌睡。","es":"Se desveló anoche y por eso hoy se durmió todo el rato en clase.","en":"He stayed up late last night, with the result that he kept dozing off in class today.","p":"tā zuó wǎn áo yè, yǐ zhì jīn tiān shàng kè yì zhí dǎ kē shuì."}]},{"id":"6-4-6","b":6,"l":4,"k":"","t":{"es":"Es fácil imaginar: 可想而知","en":"It's easy to imagine: 可想而知","ens":"It's easy to imagine: 可想而知","tc":"可想而知","sc":"可想而知"},"d":{"es":"可想而知 = «se puede imaginar fácilmente / es de suponer». Va entre comas o al final para decir que la conclusión es obvia a partir de lo dicho. Registro escrito y de uso fijo.","en":"可想而知 is a fixed phrase meaning 'it is easy to imagine / as one can imagine', concluding something obvious from what was said.","tc":"「可想而知」是說從前面的情況就能知道結果，不用多說，常放在句中或句尾，是固定說法。","sc":"「可想而知」是说从前面的情况就能知道结果，不用多说，常放在句中或句尾，是固定说法。"},"ex":[{"c":"父母辛苦地工作，而孩子卻整天吃喝玩樂，可想而知，父母很寵愛孩子。","s":"父母辛苦地工作，而孩子却整天吃喝玩乐，可想而知，父母很宠爱孩子。","es":"Los padres trabajan duro mientras el hijo se pasa el día comiendo, bebiendo y divirtiéndose; es fácil imaginar que los padres lo consienten mucho.","en":"The parents work hard while the child spends all day eating, drinking and having fun; one can imagine the parents dote on him.","p":"fù mǔ xīn kǔ dì gōng zuò, ér hái zi què zhěng tiān chī hē wán lè, kě xiǎng ér zhī, fù mǔ hěn chǒng ài hái zi."},{"c":"連專家都解決不了的問題，可想而知有多困難。","s":"连专家都解决不了的问题，可想而知有多困难。","es":"Si ni los expertos pueden resolver el problema, es fácil imaginar lo difícil que es.","en":"If even experts can't solve the problem, you can imagine how hard it is.","p":"lián zhuān jiā dōu jiě jué bù le de wèn tí, kě xiǎng ér zhī yǒu duō kùn nán."}]},{"id":"6-4-7","b":6,"l":4,"k":"","t":{"es":"Nace de: 發自","en":"Come from (within): 發自","ens":"Come from (within): 发自","tc":"發自","sc":"发自"},"d":{"es":"發自 + origen = «nace de / proviene de» (un sentimiento que sale desde dentro). Colocaciones fijas: 發自內心、發自肺腑 (desde lo más profundo del corazón). Registro formal/escrito.","en":"發自 X means 'to come from X', typically a feeling from within: 發自內心, 發自肺腑. Formal.","tc":"「發自 X」表示從 X 發出來，常指感情從內心發出，固定說法有「發自內心、發自肺腑」。","sc":"「发自 X」表示从 X 发出来，常指感情从内心发出，固定说法有「发自内心、发自肺腑」。"},"ex":[{"c":"窮困環境中的孩子之所以苦學，是發自對成功的渴望，驅策他們鍥而不舍。","s":"穷困环境中的孩子之所以苦学，是发自对成功的渴望，驱策他们锲而不舍。","es":"Si los niños de entornos pobres estudian con tanto empeño es porque nace de su deseo de triunfar, que los impulsa a perseverar sin rendirse.","en":"The reason children from poor backgrounds study so hard is that it comes from a longing for success, which drives them to persevere.","p":"qióng kùn huán jìng zhōng de hái zi zhī suǒ yǐ kǔ xué, shì fā zì duì chéng gōng de kě wàng, qū cè tā men qiè ér bù shě."},{"c":"他發自內心地感謝每一位幫助過他的人。","s":"他发自内心地感谢每一位帮助过他的人。","es":"Agradeció desde el fondo del corazón a todos los que lo ayudaron.","en":"He thanked everyone who had helped him from the bottom of his heart.","p":"tā fā zì nèi xīn dì gǎn xiè měi yí wèi bāng zhù guò tā de rén."}]},{"id":"6-4-8","b":6,"l":4,"k":"","t":{"es":"Poco después: 隨後","en":"Soon afterwards: 隨後","ens":"Soon afterwards: 随后","tc":"隨後","sc":"随后"},"d":{"es":"隨後 = «luego, poco después, a continuación». Indica que un hecho sigue inmediatamente a otro; se usa en la segunda cláusula, a menudo con 就 (隨後就). Es más formal que 然後.","en":"隨後 means 'soon after / right afterwards', used in the second clause (often 隨後就…). More formal than 然後.","tc":"「隨後」表示緊接著前一件事之後，常用在第二句，可說「隨後就……」。比「然後」正式。","sc":"「随后」表示紧接着前一件事之后，常用在第二句，可说「随后就……」。比「然后」正式。"},"ex":[{"c":"小林結束了一天的工作，隨後就匆匆忙忙地回家，因為家中有老有小，她得趕回家準備晚餐。","s":"小林结束了一天的工作，随后就匆匆忙忙地回家，因为家中有老有小，她得赶回家准备晚餐。","es":"Xiao Lin terminó su jornada de trabajo y enseguida se fue apresuradamente a casa, porque tiene mayores y niños y debe llegar a preparar la cena.","en":"Xiao Lin finished her day's work and then hurried home, because she has both old and young at home and had to rush back to cook dinner.","p":"xiǎo lín jié shù le yì tiān de gōng zuò, suí hòu jiù cōng cōng máng máng dì huí jiā, yīn wèi jiā zhōng yǒu lǎo yǒu xiǎo, tā děi gǎn huí jiā zhǔn bèi wǎn cān."},{"c":"老師先介紹了課程內容，隨後開始回答同學的問題。","s":"老师先介绍了课程内容，随后开始回答同学的问题。","es":"El profesor presentó primero el contenido del curso y a continuación empezó a responder las preguntas.","en":"The teacher first introduced the course content and then began answering students' questions.","p":"lǎo shī xiān jiè shào le kè chéng nèi róng, suí hòu kāi shǐ huí dá tóng xué de wèn tí."}]},{"id":"6-4-9","b":6,"l":4,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Con eso, para…: 以此來……","en":"Using this to…: 以此來…","ens":"Using this to…: 以此来…","tc":"以此來……","sc":"以此来……"},"d":{"es":"以此來 + verbo = «usando esto para… / con ello para…». 此 recoge lo dicho antes (un hecho o criterio), y lo que sigue es el propósito o el método. Registro formal y escrito.","en":"以此來 + verb means 'using this (what was just mentioned) to…', giving the method or purpose. Formal, written.","tc":"「以此來＋動詞」表示拿前面說的事情（此）當作方法或根據，去做後面的事。語氣正式、書面。","sc":"「以此来＋动词」表示拿前面说的事情（此）当作方法或根据，去做后面的事。语气正式、书面。"},"ex":[{"c":"外表美醜，人各不同，若以此來決定其本質與天分，恐怕會造成誤解。","s":"外表美丑，人各不同，若以此来决定其本质与天分，恐怕会造成误解。","es":"La belleza o fealdad exterior varía de una persona a otra; si se usa eso para determinar su esencia o su talento, me temo que causaría malentendidos.","en":"Looks, beautiful or plain, differ from person to person; using them to decide someone's essence and talent would probably lead to misunderstanding.","p":"wài biǎo měi chǒu, rén gè bù tóng, ruò yǐ cǐ lái jué dìng qí běn zhí yǔ tiān fēn, kǒng pà huì zào chéng wù jiě."},{"c":"公司舉辦活動，以此來增加員工之間的互動。","s":"公司举办活动，以此来增加员工之间的互动。","es":"La empresa organiza actividades para, con ello, aumentar la interacción entre los empleados.","en":"The company holds events to increase interaction between employees.","p":"gōng sī jǔ bàn huó dòng, yǐ cǐ lái zēng jiā yuán gōng zhī jiān de hù dòng."}]},{"id":"6-4-10","b":6,"l":4,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Gracias a la acumulación de…: 藉著……的累積","en":"By means of the accumulation of…","ens":"By means of the accumulation of…","tc":"藉著……的累積","sc":"借着……的累积"},"d":{"es":"藉著 + X + 的累積 = «aprovechando / gracias a la acumulación de X» (經驗、知識、時間). 藉著 = «valiéndose de». Registro escrito; 累積 se combina con experiencia, riqueza, conocimiento.","en":"藉著 X 的累積 means 'by means of the accumulation of X' (experience, knowledge, time). Written style.","tc":"「藉著 X 的累積」表示靠著 X 一點一點累積起來，達到後面的結果。「藉著」是「憑藉」的意思，X 常是經驗、知識、時間。","sc":"「借着 X 的累积」表示靠着 X 一点一点累积起来，达到后面的结果。「借着」是「凭借」的意思，X 常是经验、知识、时间。"},"ex":[{"c":"雖然祖母是文盲，不過藉著經驗的累積，教導我們年輕人許多生活上的知識。","s":"虽然祖母是文盲，不过借着经验的累积，教导我们年轻人许多生活上的知识。","es":"Aunque mi abuela era analfabeta, gracias a la acumulación de experiencia nos enseñó a los jóvenes muchos conocimientos de la vida.","en":"Although my grandmother was illiterate, through accumulated experience she taught us young people a lot about life.","p":"suī rán zǔ mǔ shì wén máng, bú guò jiè zhe jīng yàn de lèi jī, jiào dǎo wǒ men nián qīng rén xǔ duō shēng huó shàng de zhī shì."},{"c":"藉著長期的練習，他的中文進步很多。","s":"借着长期的练习，他的中文进步很多。","es":"Gracias a la práctica constante, su chino ha mejorado mucho.","en":"Through long-term practice, his Chinese has improved a lot.","p":"jiè zhe cháng qí de liàn xí, tā de zhōng wén jìn bù hěn duō."}]},{"id":"6-5-0","b":6,"l":5,"k":"","t":{"es":"Al enfrentarse a…: 面對……時","en":"When faced with…","ens":"When faced with…","tc":"面對……時","sc":"面对……时"},"d":{"es":"面對 + situación/cosa + 時 = «al enfrentarse a / ante…». Marca el momento en que se reacciona ante algo (una tentación, un problema, una decisión). Registro neutro-escrito.","en":"面對…時 means 'when faced with…', followed by the reaction or the right way to respond.","tc":"「面對……時」表示遇到某種人、事、物的時候，後面說當時的反應或應該怎麼做。","sc":"「面对……时」表示遇到某种人、事、物的时候，后面说当时的反应或应该怎么做。"},"ex":[{"c":"面對瓜香果豔的水果攤時，很難不被吸引，於是許多遊客就不自覺地停下來購買。","s":"面对瓜香果艳的水果摊时，很难不被吸引，于是许多游客就不自觉地停下来购买。","es":"Ante un puesto de frutas de aroma dulce y colores vivos es difícil no sentirse atraído, así que muchos turistas se detienen sin darse cuenta a comprar.","en":"Faced with a fruit stall of fragrant melons and brightly colored fruit, it is hard not to be attracted, so many tourists stop to buy without realizing it.","p":"miàn duì guā xiāng guǒ yàn de shuǐ guǒ tān shí, hěn nán bú bèi xī yǐn, yú shì xǔ duō yóu kè jiù bú zì jué dì tíng xià lái gòu mǎi."},{"c":"面對突如其來的問題時，最重要的是保持冷靜。","s":"面对突如其来的问题时，最重要的是保持冷静。","es":"Ante un problema repentino, lo más importante es mantener la calma.","en":"When faced with a sudden problem, the most important thing is to stay calm.","p":"miàn duì tú rú qí lái de wèn tí shí, zuì zhòng yào de shì bǎo chí lěng jìng."}]},{"id":"6-5-1","b":6,"l":5,"k":"","t":{"es":"Quedar atrapado en: 身陷……（裡）","en":"Be trapped in…","ens":"Be trapped in…","tc":"身陷……（裡）","sc":"身陷……（里）"},"d":{"es":"身陷 + situación difícil (險境、困境、車海、債務) = «estar metido / atrapado en…». Se usa para situaciones de las que cuesta salir; se puede añadir 裡 con lugares o espacios.","en":"身陷… means being trapped in a bad situation that is hard to escape: 身陷困境, 身陷險境, 身陷車海.","tc":"「身陷……」是自己被困在某個不好的環境或處境裡，不容易離開，例如身陷困境、身陷險境、身陷車海。","sc":"「身陷……」是自己被困在某个不好的环境或处境里，不容易离开，例如身陷困境、身陷险境、身陷车海。"},"ex":[{"c":"發生嚴重車禍，高速公路像停車場似的，停滿了大小車輛，我們身陷車海，急死了，恨不得車子能立刻飛到目的地。","s":"发生严重车祸，高速公路像停车场似的，停满了大小车辆，我们身陷车海，急死了，恨不得车子能立刻飞到目的地。","es":"Hubo un grave accidente y la autopista parecía un estacionamiento lleno de vehículos de todos los tamaños; atrapados en el mar de coches, estábamos desesperados, deseando que el auto pudiera volar de inmediato a su destino.","en":"There was a serious accident and the highway was packed with vehicles like a parking lot; trapped in a sea of cars, we were frantic, wishing the car could fly straight to our destination.","p":"fā shēng yán zhòng chē huò, gāo sù gōng lù xiàng tíng chē chǎng sì de, tíng mǎn le dà xiǎo chē liàng, wǒ men shēn xiàn chē hǎi, jí sǐ le, hèn bù dé chē zi néng lì kè fēi dào mù dì dì."},{"c":"他身陷債務問題裡，每天都睡不好。","s":"他身陷债务问题里，每天都睡不好。","es":"Está metido en un problema de deudas y todos los días duerme mal.","en":"Caught up in debt problems, he doesn't sleep well every day.","p":"tā shēn xiàn zhài wù wèn tí lǐ, měi tiān dōu shuì bù hǎo."}]},{"id":"6-5-2","b":6,"l":5,"k":"","t":{"es":"Dar las gracias a X: 向X道謝／致謝","en":"Thank X: 向X道謝／致謝","ens":"Thank X: 向X道谢／致谢","tc":"向X道謝／致謝","sc":"向X道谢／致谢"},"d":{"es":"向 X 道謝／致謝 = «dar las gracias a X». 道謝 es neutro y de uso cotidiano; 致謝 es más formal (discursos, escritos). Se puede añadir 說: 向他說謝謝.","en":"向 X 道謝／致謝 means 'to thank X'. 道謝 is everyday, 致謝 is more formal (speeches, writing).","tc":"「向 X 道謝」是對 X 說謝謝，「致謝」比較正式，常用在演講或書面。","sc":"「向 X 道谢」是对 X 说谢谢，「致谢」比较正式，常用在演讲或书面。"},"ex":[{"c":"泰國人雙手合十向觀光客致謝，因為觀光產業對泰國的經濟有不小的貢獻。","s":"泰国人双手合十向观光客致谢，因为观光产业对泰国的经济有不小的贡献。","es":"Los tailandeses juntan las manos y dan las gracias a los turistas, porque el turismo contribuye no poco a la economía de Tailandia.","en":"Thai people press their palms together to thank tourists, because the tourism industry contributes considerably to Thailand's economy.","p":"tài guó rén shuāng shǒu hé shí xiàng guān guāng kè zhì xiè, yīn wèi guān guāng chǎn yè duì tài guó de jīng jì yǒu bù xiǎo de gòng xiàn."},{"c":"演講結束後，他向所有幫忙的志工致謝。","s":"演讲结束后，他向所有帮忙的志工致谢。","es":"Al terminar la conferencia, agradeció a todos los voluntarios que ayudaron.","en":"After the talk, he thanked all the volunteers who helped.","p":"yǎn jiǎng jié shù hòu, tā xiàng suǒ yǒu bāng máng de zhì gōng zhì xiè."}]},{"id":"6-5-3","b":6,"l":5,"k":"","t":{"es":"Formar (talento): 培養出（了）","en":"Cultivate / produce (people): 培養出（了）","ens":"Cultivate / produce (people): 培养出（了）","tc":"培養出（了）","sc":"培养出（了）"},"d":{"es":"培養出（了）+ tipo de persona = «formar / haber formado a…». 培養 se usa con talentos, hábitos o capacidades; 出 indica que se obtiene un resultado. Sujeto típico: escuela, política, familia.","en":"培養出（了）+ type of person means a school, policy or family has nurtured and produced such people or abilities.","tc":"「培養出（了）＋人才」表示經過教育或訓練，造就出某種人才或能力。主詞常是學校、政策或家庭。","sc":"「培养出（了）＋人才」表示经过教育或训练，造就出某种人才或能力。主词常是学校、政策或家庭。"},"ex":[{"c":"只有具有國際觀的教育政策，才能培養出思想開闊的學生來與國際接軌。","s":"只有具有国际观的教育政策，才能培养出思想开阔的学生来与国际接轨。","es":"Solo una política educativa con visión internacional puede formar estudiantes de mente abierta capaces de integrarse al mundo.","en":"Only an education policy with an international outlook can produce open-minded students who connect with the world.","p":"zhǐ yǒu jù yǒu guó jì guān de jiào yù zhèng cè, cái néng péi yǎng chū sī xiǎng kāi kuò de xué shēng lái yǔ guó jì jiē guǐ."},{"c":"這所學校培養出了不少優秀的運動員。","s":"这所学校培养出了不少优秀的运动员。","es":"Esta escuela ha formado a muchos deportistas destacados.","en":"This school has produced quite a few outstanding athletes.","p":"zhè suǒ xué xiào péi yǎng chū le bù shǎo yōu xiù de yùn dòng yuán."}]},{"id":"6-5-4","b":6,"l":5,"k":"condicional condición si conditional condition if 條件 假設 如果 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Principalmente: 主要是","en":"Mainly: 主要是","ens":"Mainly: 主要是","tc":"主要是","sc":"主要是"},"d":{"es":"主要是 + razón/elemento = «sobre todo es / se debe principalmente a…». Se usa para señalar la causa más importante entre varias; muy frecuente con 因為: 主要是因為….","en":"主要是… singles out the most important reason or element among several; often 主要是因為…","tc":"「主要是……」用來指出眾多原因或項目裡最重要的一個，常說「主要是因為……」。","sc":"「主要是……」用来指出众多原因或项目里最重要的一个，常说「主要是因为……」。"},"ex":[{"c":"小江之所以變成「月光族」，主要是收入不如開支多，因此到了月底常連吃飯的錢也不夠。","s":"小江之所以变成「月光族」，主要是收入不如开支多，因此到了月底常连吃饭的钱也不够。","es":"La razón por la que Xiao Jiang se volvió de los que «se gastan todo el sueldo cada mes» es, sobre todo, que sus ingresos son menores que sus gastos, así que a fin de mes a veces ni le alcanza para comer.","en":"The reason Xiao Jiang became a 'moonlight clan' person (spending everything each month) is mainly that his income is less than his spending, so at the end of the month he often can't even afford meals.","p":"xiǎo jiāng zhī suǒ yǐ biàn chéng 「yuè guāng zú」, zhǔ yào shì shōu rù bù rú kāi zhī duō, yīn cǐ dào le yuè dǐ cháng lián chī fàn de qián yě bú gòu."},{"c":"這次比賽輸了，主要是因為我們準備得不夠。","s":"这次比赛输了，主要是因为我们准备得不够。","es":"Perdimos este partido principalmente porque no nos preparamos lo suficiente.","en":"We lost this match mainly because we weren't prepared enough.","p":"zhè cì bǐ sài shū le, zhǔ yào shì yīn wèi wǒ men zhǔn bèi dé bú gòu."}]},{"id":"6-5-5","b":6,"l":5,"k":"","t":{"es":"Conectar con X: 跟X接軌","en":"Be in line with X","ens":"Be in line with X","tc":"跟X接軌","sc":"跟X接轨"},"d":{"es":"跟 X 接軌 = «conectarse / alinearse con X» (el mundo, el mercado, los estándares internacionales). Literalmente «unir los rieles». Se usa para integrarse en un sistema o estándar más amplio: 與國際接軌.","en":"跟 X 接軌 literally 'to join the rails'; figuratively to link up with / align with X (the world, society, the market): also 與國際接軌.","tc":"「跟 X 接軌」本來是鐵軌接在一起，比喻和 X（國際、社會、市場）連接、同步，也說「與國際接軌」。","sc":"「跟 X 接轨」本来是铁轨接在一起，比喻和 X（国际、社会、市场）连接、同步，也说「与国际接轨」。"},"ex":[{"c":"政府多方面補助，好讓弱勢族群能跟社會接軌。","s":"政府多方面补助，好让弱势族群能跟社会接轨。","es":"El gobierno otorga subsidios de múltiples formas para que los grupos vulnerables puedan integrarse a la sociedad.","en":"The government provides support in many ways so that disadvantaged groups can connect with society.","p":"zhèng fǔ duō fāng miàn bǔ zhù, hǎo ràng ruò shì zú qún néng gēn shè huì jiē guǐ."},{"c":"這個課程讓學生的學習內容跟國際接軌。","s":"这个课程让学生的学习内容跟国际接轨。","es":"Este curso hace que lo que estudian los alumnos esté a la par de los estándares internacionales.","en":"This course brings what students learn in line with international standards.","p":"zhè ge kè chéng ràng xué shēng de xué xí nèi róng gēn guó jì jiē guǐ."}]},{"id":"6-5-6","b":6,"l":5,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Ser dejado atrás: 被X（給）拋在後（面）","en":"Be left behind by X","ens":"Be left behind by X","tc":"被X（給）拋在後（面）","sc":"被X（给）抛在后（面）"},"d":{"es":"A 被 X（給）拋在後（面）= «A es dejado atrás por X». Es una pasiva con 被: X es quien avanza más rápido y A se queda rezagado. 給 refuerza el tono coloquial. Sentido literal (carrera) o figurado.","en":"A 被 X（給）拋在後（面）: A is left behind (outpaced) by X. 給 adds a colloquial touch. Literal (races) or figurative.","tc":"「A 被 X（給）拋在後（面）」是 A 被 X 超過、落在後面。「給」讓語氣比較口語。可以是比賽，也可以比喻落後。","sc":"「A 被 X（给）抛在后（面）」是 A 被 X 超过、落在后面。「给」让语气比较口语。可以是比赛，也可以比喻落后。"},"ex":[{"c":"眼見本國選手被其他選手給拋在後，觀眾紛紛站起來給選手加油。","s":"眼见本国选手被其他选手给抛在后，观众纷纷站起来给选手加油。","es":"Al ver que el atleta nacional era dejado atrás por los otros competidores, el público se fue poniendo de pie para animarlo.","en":"Seeing the home athlete left behind by the other competitors, spectators stood up one after another to cheer him on.","p":"yǎn jiàn běn guó xuǎn shǒu bèi qí tā xuǎn shǒu gěi pāo zài hòu, guān zhòng fēn fēn zhàn qǐ lái gěi xuǎn shǒu jiā yóu."},{"c":"如果不努力學習，你就會被別人拋在後面。","s":"如果不努力学习，你就会被别人抛在后面。","es":"Si no estudias con esfuerzo, los demás te dejarán atrás.","en":"If you don't study hard, others will leave you behind.","p":"rú guǒ bù nǔ lì xué xí, nǐ jiù huì bèi bié rén pāo zài hòu miàn."}]},{"id":"6-5-7","b":6,"l":5,"k":"","t":{"es":"Multiplicarse: 倍增","en":"Multiply / double (or more): 倍增","ens":"Multiply / double (or more): 倍增","tc":"倍增","sc":"倍增"},"d":{"es":"倍增 = «multiplicarse / aumentar varias veces» (por lo menos se duplica). Se usa con ingresos, cantidad, riesgo; es un verbo intransitivo, sin objeto, y formal.","en":"倍增 means to multiply by a factor (at least double). It takes no object and is formal; used for income, numbers, risk.","tc":"「倍增」是數量增加好幾倍（至少一倍），後面不接受詞，語氣較正式，常用於收入、人數、風險等。","sc":"「倍增」是数量增加好几倍（至少一倍），后面不接受词，语气较正式，常用于收入、人数、风险等。"},"ex":[{"c":"他職位升級後收入倍增。","s":"他职位升级后收入倍增。","es":"Tras su ascenso, sus ingresos se multiplicaron.","en":"After his promotion, his income multiplied.","p":"tā zhí wèi shēng jí hòu shōu rù bèi zēng."},{"c":"廣告播出後，網站的訪客人數倍增。","s":"广告播出后，网站的访客人数倍增。","es":"Tras salir el anuncio, el número de visitantes del sitio web se multiplicó.","en":"After the ad aired, the number of website visitors multiplied.","p":"guǎng gào bò chū hòu, wǎng zhàn de fǎng kè rén shù bèi zēng."}]},{"id":"6-5-8","b":6,"l":5,"k":"","t":{"es":"Tener cierto X: 有一定的X","en":"Have a certain (degree of) X","ens":"Have a certain (degree of) X","tc":"有一定的X","sc":"有一定的X"},"d":{"es":"有一定的 + sustantivo abstracto = «tener cierto/a… (influencia, efecto, impacto, límite)». 一定 aquí no es «seguro», sino «determinado, cierto grado». Suele ser un grado moderado y razonable. Colocaciones: 有一定的影響／幫助／程度.","en":"有一定的 X: here 一定 means 'a certain degree of', not 'definitely'. Common with 影響, 幫助, 程度, 難度.","tc":"「有一定的 X」的「一定」是「某個程度」的意思，不是「必定」，表示有某種程度的 X，常見搭配有影響、幫助、程度、難度。","sc":"「有一定的 X」的「一定」是「某个程度」的意思，不是「必定」，表示有某种程度的 X，常见搭配有影响、帮助、程度、难度。"},"ex":[{"c":"國家的經濟衰敗，各產業在國際間逐年失去競爭力，對世界競爭力評比有一定的影響。","s":"国家的经济衰败，各产业在国际间逐年失去竞争力，对世界竞争力评比有一定的影响。","es":"La decadencia económica del país y la pérdida anual de competitividad internacional de sus industrias tienen cierto impacto en la clasificación mundial de competitividad.","en":"The country's economic decline and its industries' loss of international competitiveness year by year have a certain impact on world competitiveness rankings.","p":"guó jiā de jīng jì shuāi bài, gè chǎn yè zài guó jì jiān zhú nián shī qù jìng zhēng lì, duì shì jiè jìng zhēng lì píng bǐ yǒu yí dìng de yǐng xiǎng."},{"c":"多運動對健康有一定的幫助。","s":"多运动对健康有一定的帮助。","es":"Hacer más ejercicio ayuda en cierta medida a la salud.","en":"More exercise helps health to a certain extent.","p":"duō yùn dòng duì jiàn kāng yǒu yí dìng de bāng zhù."}]},{"id":"6-5-9","b":6,"l":5,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Atraer a X para que venga: 吸引X前來","en":"Attract X to come","ens":"Attract X to come","tc":"吸引X前來","sc":"吸引X前来"},"d":{"es":"吸引 X 前來 = «atraer a X para que venga». 前來 = venir hacia aquí (formal), con 前往 como contrario (ir hacia allá). El sujeto es lo que atrae (un sonido, un precio, un evento).","en":"吸引 X 前來 means to attract X so that they come. 前來 is a formal 'come' (opposite: 前往 'go').","tc":"「吸引 X 前來」是讓 X 被吸引而來到這裡。「前來」是比較正式的「來」，相反的是「前往」。","sc":"「吸引 X 前来」是让 X 被吸引而来到这里。「前来」是比较正式的「来」，相反的是「前往」。"},"ex":[{"c":"不少動物都是靠特殊的叫聲，吸引異性前來，因為他們需要傳宗接代。","s":"不少动物都是靠特殊的叫声，吸引异性前来，因为他们需要传宗接代。","es":"Muchos animales atraen al sexo opuesto con llamadas especiales, porque necesitan reproducirse.","en":"Many animals rely on special calls to attract the opposite sex, because they need to reproduce.","p":"bù shǎo dòng wù dōu shì kào tè shū de jiào shēng, xī yǐn yì xìng qián lái, yīn wèi tā men xū yào chuán zōng jiē dài."},{"c":"這家餐廳靠便宜的價格吸引不少學生前來用餐。","s":"这家餐厅靠便宜的价格吸引不少学生前来用餐。","es":"Este restaurante atrae a muchos estudiantes a comer con sus precios bajos.","en":"This restaurant attracts many students to dine there with its low prices.","p":"zhè jiā cān tīng kào pián yí de jià gé xī yǐn bù shǎo xué shēng qián lái yòng cān."}]},{"id":"6-5-10","b":6,"l":5,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 dirección movimiento direction movement 方向 趨向 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在 dirección movimiento direction movement 方向 趋向","t":{"es":"Desde el punto de vista de X: 從X（的）角度來看","en":"From the perspective of X","ens":"From the perspective of X","tc":"從X（的）角度來看","sc":"从X（的）角度来看"},"d":{"es":"從 X（的）角度來看 = «desde el punto de vista de X». X es una persona, una posición o un tema (環保、消費者、老師). Después se da un juicio o una conclusión. También: 從 X 來看, 從 X 的立場來說.","en":"從 X（的）角度來看 means 'from X's point of view'; X can be a person, position or topic, followed by a judgment.","tc":"「從 X（的）角度來看」是站在 X 的立場或方面來看事情，後面說看法。X 可以是人、立場或主題。","sc":"「从 X（的）角度来看」是站在 X 的立场或方面来看事情，后面说看法。X 可以是人、立场或主题。"},"ex":[{"c":"從打工遊學者的角度來看，學外語的同時，還有錢賺，再辛苦也值得。","s":"从打工游学者的角度来看，学外语的同时，还有钱赚，再辛苦也值得。","es":"Desde el punto de vista de quienes viajan para trabajar y estudiar, aprender un idioma y a la vez ganar dinero vale la pena por muy duro que sea.","en":"From the perspective of those who work while studying abroad, learning a foreign language and earning money at the same time is worth it however hard it is.","p":"cóng dǎ gōng yóu xué zhě de jiǎo dù lái kàn, xué wài yǔ de tóng shí, hái yǒu qián zhuàn, zài xīn kǔ yě zhí dé."},{"c":"從環保的角度來看，少用塑膠袋是對的。","s":"从环保的角度来看，少用塑胶袋是对的。","es":"Desde el punto de vista ecológico, usar menos bolsas de plástico es lo correcto.","en":"From an environmental perspective, using fewer plastic bags is the right thing.","p":"cóng huán bǎo de jiǎo dù lái kàn, shǎo yòng sù jiāo dài shì duì de."}]},{"id":"6-6-0","b":6,"l":6,"k":"","t":{"es":"Cambio de X a Y: 由X轉Y","en":"Change from X to Y: 由X轉Y","ens":"Change from X to Y: 由X转Y","tc":"由X轉Y","sc":"由X转Y"},"d":{"es":"由 X 轉 Y = cambiar de X a Y. Describe un cambio de estado, sobre todo en clima, ánimo o situación; X e Y suelen ser adjetivos opuestos. Es más escrito que hablado.","en":"Describes a gradual change from state X to state Y (weather, mood, situation). More written in style.","tc":"表示情況從 X 的狀態逐漸變成 Y 的狀態，常用在天氣、心情、局勢等變化，偏書面。","sc":"表示情况从 X 的状态逐渐变成 Y 的状态，常用在天气、心情、局势等变化，偏书面。"},"ex":[{"c":"天氣由熱轉涼。","s":"天气由热转凉。","es":"El clima pasa de caluroso a fresco.","en":"The weather turns from hot to cool.","p":"tiān qì yóu rè zhuǎn liáng."},{"c":"他的心情由喜轉憂，整晚都睡不著。","s":"他的心情由喜转忧，整晚都睡不着。","es":"Su ánimo pasó de la alegría a la preocupación y no pudo dormir en toda la noche.","en":"His mood changed from joy to worry, and he couldn't sleep all night.","p":"tā de xīn qíng yóu xǐ zhuǎn yōu, zhěng wǎn dōu shuì bù zháo."}]},{"id":"6-6-1","b":6,"l":6,"k":"","t":{"es":"Remontarse a: 追溯至／到","en":"Trace back to: 追溯至／到","ens":"Trace back to: 追溯至／到","tc":"追溯至／到","sc":"追溯至／到"},"d":{"es":"追溯至／到 = remontarse a, tener su origen en. Se usa para rastrear el origen de algo en el pasado y va seguido de una época o un hecho. Es de registro escrito; es frecuente «可以追溯到…».","en":"Traces something back to its origin in the past; followed by a time or event. Written style, often 可以追溯到….","tc":"往過去查找事情的起點或源頭，後面接時間或事件。書面用法，常說「可以追溯到……」。","sc":"往过去查找事情的起点或源头，后面接时间或事件。书面用法，常说「可以追溯到……」。"},"ex":[{"c":"你學習外語的經驗可以追溯到什麼時候？追溯至中小學的時候。","s":"你学习外语的经验可以追溯到什么时候？追溯至中小学的时候。","es":"¿Hasta cuándo se remonta tu experiencia aprendiendo idiomas? Se remonta a la época de la escuela primaria y secundaria.","en":"How far back does your experience of learning foreign languages go? It goes back to my primary and middle school years.","p":"nǐ xué xí wài yǔ de jīng yàn kě yǐ zhuī sù dào shén me shí hòu? zhuī sù zhì zhōng xiǎo xué de shí hòu."},{"c":"這座廟的歷史可以追溯到三百年前。","s":"这座庙的历史可以追溯到三百年前。","es":"La historia de este templo se remonta a trescientos años atrás.","en":"The history of this temple can be traced back three hundred years.","p":"zhè zuò miào de lì shǐ kě yǐ zhuī sù dào sān bǎi nián qián."}]},{"id":"6-6-2","b":6,"l":6,"k":"","t":{"es":"Para expresar gratitud: 以表……的謝意","en":"To express thanks: 以表……的謝意","ens":"To express thanks: 以表……的谢意","tc":"以表……的謝意／為表……的謝意","sc":"以表……的谢意／为表……的谢意"},"d":{"es":"以表（對）…的謝意 / 為表（對）…的謝意 = para expresar nuestro agradecimiento por…. Es muy formal (comunicados, discursos). Se coloca después de la acción: «hacemos X para agradecer…».","en":"Shows that something is done to express thanks; used in formal or written settings (announcements, speeches), rarely in speech.","tc":"表示做某件事是為了表達感謝，用在正式、書面的場合（如公告、致詞）。口語不常這樣說。","sc":"表示做某件事是为了表达感谢，用在正式、书面的场合（如公告、致词）。口语不常这样说。"},"ex":[{"c":"在警察節時，政府表揚優良警察並贈送獎金，以表對警察人員維護社會安全的謝意。","s":"在警察节时，政府表扬优良警察并赠送奖金，以表对警察人员维护社会安全的谢意。","es":"En el Día de la Policía, el gobierno reconoció a los mejores policías y les entregó un bono, como muestra de agradecimiento por su labor de mantener la seguridad de la sociedad.","en":"On Police Day, the government honored outstanding police officers and gave them bonuses to express thanks for their work in keeping society safe.","p":"zài jǐng chá jié shí, zhèng fǔ biǎo yáng yōu liáng jǐng chá bìng zèng sòng jiǎng jīn, yǐ biǎo duì jǐng chá rén yuán wéi hù shè huì ān quán de xiè yì."},{"c":"公司特別舉辦聚餐，以表對全體同仁辛勤工作的謝意。","s":"公司特别举办聚餐，以表对全体同仁辛勤工作的谢意。","es":"La empresa organizó una cena especial para agradecer el arduo trabajo de todos los colegas.","en":"The company held a special dinner to express its thanks for all colleagues' hard work.","p":"gōng sī tè bié jǔ bàn jù cān, yǐ biǎo duì quán tǐ tóng rén xīn qín gōng zuò de xiè yì."}]},{"id":"6-6-3","b":6,"l":6,"k":"","t":{"es":"A partir de entonces: 自此","en":"From then on: 自此","ens":"From then on: 自此","tc":"自此","sc":"自此"},"d":{"es":"自此 = a partir de entonces, desde ese momento. Marca un punto de inicio tras el cual la situación continúa. Es más escrito que 從此 o 從那以後, y va antes del verbo.","en":"From a certain point on, a new situation continues. Written style; similar to 從此.","tc":"從某個時間點開始，後面一直是同一種情況。偏書面，相當於「從此」。","sc":"从某个时间点开始，后面一直是同一种情况。偏书面，相当于「从此」。"},"ex":[{"c":"華人相信過了端午節，氣溫自此由低轉高，正式邁入夏季，冬季的衣服就可以洗乾淨收起來了。","s":"华人相信过了端午节，气温自此由低转高，正式迈入夏季，冬季的衣服就可以洗干净收起来了。","es":"Los chinos creen que, pasado el Festival del Bote del Dragón, la temperatura sube desde entonces y se entra de lleno en el verano, así que ya se puede lavar y guardar la ropa de invierno.","en":"Chinese people believe that after the Dragon Boat Festival the temperature rises from then on and summer officially begins, so winter clothes can be washed and put away.","p":"huá rén xiāng xìn guò le duān wǔ jié, qì wēn zì cǐ yóu dī zhuǎn gāo, zhèng shì mài rù xià jì, dōng jì de yī fú jiù kě yǐ xǐ gān jìng shōu qǐ lái le."},{"c":"他在那次比賽中輸得很慘，自此不再參加任何比賽。","s":"他在那次比赛中输得很惨，自此不再参加任何比赛。","es":"Perdió muy mal en esa competencia y desde entonces no volvió a participar en ninguna.","en":"He lost badly in that contest and never entered another one after that.","p":"tā zài nà cì bǐ sài zhōng shū dé hěn cǎn, zì cǐ bú zài cān jiā rèn hé bǐ sài."}]},{"id":"6-6-4","b":6,"l":6,"k":"","t":{"es":"Ser aficionado a: 熱衷於","en":"Be keen on: 熱衷於","ens":"Be keen on: 热衷于","tc":"熱衷於","sc":"热衷于"},"d":{"es":"熱衷於 = ser muy aficionado a, estar entusiasmado con. Va seguido de una actividad o cosa. Puede tener matiz de exceso (como en el ejemplo), según el contexto. Registro algo formal.","en":"Being very keen on and devoted to something; followed by an activity or thing. Common in written or formal speech.","tc":"對某件事非常有興趣、很投入。後面接活動或事物，常見於書面或較正式的說法。","sc":"对某件事非常有兴趣、很投入。后面接活动或事物，常见于书面或较正式的说法。"},"ex":[{"c":"你或是你身邊的人對什麼很熱衷？室友熱衷於玩手機遊戲，到了無意與人互動的程度。","s":"你或是你身边的人对什么很热衷？室友热衷于玩手机游戏，到了无意与人互动的程度。","es":"¿Tú o alguien cercano está muy entusiasmado con algo? Mi compañero de cuarto está tan metido en los juegos del celular que no tiene ganas de interactuar con nadie.","en":"Are you or people around you passionate about something? My roommate is so absorbed in mobile games that he doesn't want to interact with anyone.","p":"nǐ huò shì nǐ shēn biān de rén duì shén me hěn rè zhōng? shì yǒu rè zhōng yú wán shǒu jī yóu xì, dào liǎo wú yì yǔ rén hù dòng de chéng dù."},{"c":"她從年輕就熱衷於登山，每個週末都去爬山。","s":"她从年轻就热衷于登山，每个周末都去爬山。","es":"Desde joven es muy aficionada al montañismo y sube montañas todos los fines de semana.","en":"She has been passionate about mountain climbing since she was young and goes hiking every weekend.","p":"tā cóng nián qīng jiù rè zhōng yú dēng shān, měi ge zhōu mò dōu qù pá shān."}]},{"id":"6-6-5","b":6,"l":6,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Respectivamente, por separado: 分別","en":"Respectively: 分別","ens":"Respectively: 分别","tc":"分別","sc":"分别"},"d":{"es":"分別 = respectivamente, cada uno por separado. Se pone antes del verbo y presupone dos o más sujetos o elementos que se tratan de forma individual. No es el 分別 de «despedirse» ni el de «diferencia».","en":"Shows that two or more people or things each do something or have something separately; placed before the verb.","tc":"表示兩個以上的人或事物各自做某事、各有某種情況，放在動詞前。","sc":"表示两个以上的人或事物各自做某事、各有某种情况，放在动词前。"},"ex":[{"c":"手機和平板電腦分別擁有不同的使用者。","s":"手机和平板电脑分别拥有不同的使用者。","es":"El celular y la tableta tienen cada uno usuarios distintos.","en":"Phones and tablets each have different users.","p":"shǒu jī hé píng bǎn diàn nǎo fēn bié yǒng yǒu bù tóng de shǐ yòng zhě."},{"c":"小明和小華分別來自西班牙和墨西哥。","s":"小明和小华分别来自西班牙和墨西哥。","es":"Xiaoming y Xiaohua vienen de España y de México, respectivamente.","en":"Xiaoming and Xiaohua come from Spain and Mexico respectively.","p":"xiǎo míng hàn xiǎo huá fēn bié lái zì xī bān yá hàn mò xī gē."}]},{"id":"6-6-6","b":6,"l":6,"k":"","t":{"es":"Fijar condiciones: 設下……的條件","en":"Set conditions: 設下……的條件","ens":"Set conditions: 设下……的条件","tc":"設下……的條件","sc":"设下……的条件"},"d":{"es":"設下…的條件 = establecer la condición de…. El contenido concreto de la condición va antes de 的條件. Es de tono formal (trámites, reglamentos, negociaciones). También se dice 訂下條件 o 設定條件.","en":"Setting out requirements or restrictions, with the specific content before 條件. Fairly formal; used for rules, applications, negotiations.","tc":"訂出某些要求或限制，「條件」前面放具體內容。偏正式，用於規定、申請、談判。","sc":"订出某些要求或限制，「条件」前面放具体内容。偏正式，用于规定、申请、谈判。"},"ex":[{"c":"你認為銀行對信用卡的申請者應該設下哪些條件？設下收入達一定標準的條件。","s":"你认为银行对信用卡的申请者应该设下哪些条件？设下收入达一定标准的条件。","es":"¿Qué condiciones crees que el banco debería poner a quienes solicitan una tarjeta de crédito? Poner la condición de que el ingreso alcance cierto nivel.","en":"What conditions do you think banks should set for credit card applicants? Setting the condition that income reach a certain standard.","p":"nǐ rèn wéi yín háng duì xìn yòng kǎ de shēn qǐng zhě yīng gāi shè xià nǎ xiē tiáo jiàn? shè xià shōu rù dá yí dìng biāo zhǔn de tiáo jiàn."},{"c":"學校設下成績達到八十分的條件，才能申請獎學金。","s":"学校设下成绩达到八十分的条件，才能申请奖学金。","es":"La escuela puso como condición tener un promedio de ochenta para poder solicitar la beca.","en":"The school set the condition of a score of eighty or above for applying for the scholarship.","p":"xué xiào shè xià chéng jī dá dào bā shí fēn de tiáo jiàn, cái néng shēn qǐng jiǎng xué jīn."}]},{"id":"6-6-7","b":6,"l":6,"k":"","t":{"es":"Sufrir (algo negativo): 遭（X）……","en":"Suffer (something bad): 遭（X）……","ens":"Suffer (something bad): 遭（X）……","tc":"遭（X）……","sc":"遭（X）……"},"d":{"es":"遭（X）… = sufrir, ser víctima de (algo adverso). Sirve como una pasiva de sentido negativo, más escrita que 被. Va seguido de un verbo o nombre negativo (遭淘汰, 遭拒絕, 遭殃). No se usa con hechos positivos.","en":"Meets something unfortunate, such as being eliminated or rejected; usually followed by a verb or a negative word. Written tone.","tc":"表示碰到不好的事，像被淘汰、被拒絕。後面多是動詞或帶有負面意思的詞，書面語氣。","sc":"表示碰到不好的事，像被淘汰、被拒绝。后面多是动词或带有负面意思的词，书面语气。"},"ex":[{"c":"競爭力低→遭淘汰","s":"竞争力低→遭淘汰","es":"Poca competitividad → ser eliminado","en":"Low competitiveness → get eliminated","p":"jìng zhēng lì dī→ zāo táo tài"},{"c":"這家店因為服務太差而遭到顧客批評。","s":"这家店因为服务太差而遭到顾客批评。","es":"Ese local fue criticado por los clientes por su pésimo servicio.","en":"The shop was criticized by customers because its service was so poor.","p":"zhè jiā diàn yīn wèi fú wù tài chā ér zāo dào gù kè pī píng."}]},{"id":"6-6-8","b":6,"l":6,"k":"","t":{"es":"Por eso: 因而","en":"Therefore: 因而","ens":"Therefore: 因而","tc":"因而","sc":"因而"},"d":{"es":"因而 = por eso, de ahí que. Une una causa con su consecuencia como 所以, pero es más escrito y suele ir en medio de la oración (no al inicio con sujeto propio). No se combina con 因為 en la misma cláusula.","en":"Shows that the preceding reason leads to the result; like 所以 but more written, often in the middle of a sentence.","tc":"表示前面的原因造成後面的結果，相當於「所以」，但更書面，常用在句子中間。","sc":"表示前面的原因造成后面的结果，相当于「所以」，但更书面，常用在句子中间。"},"ex":[{"c":"小林快要回國了，因而不常來上課了。","s":"小林快要回国了，因而不常来上课了。","es":"Xiaolin pronto regresará a su país, por eso ya no viene seguido a clase.","en":"Xiaolin is about to go back to his home country, so he doesn't come to class often anymore.","p":"xiǎo lín kuài yào huí guó le, yīn ér bù cháng lái shàng kè le."},{"c":"他最近工作壓力很大，因而常常失眠。","s":"他最近工作压力很大，因而常常失眠。","es":"Últimamente tiene mucho estrés laboral, por lo que a menudo sufre de insomnio.","en":"He has been under great work pressure lately, and as a result often can't sleep.","p":"tā zuì jìn gōng zuò yā lì hěn dà, yīn ér cháng cháng shī mián."}]},{"id":"6-6-9","b":6,"l":6,"k":"","t":{"es":"Cambiar a (una modalidad): 改由……（方式）","en":"Switch to…: 改由……（方式）","ens":"Switch to…: 改由……（方式）","tc":"改由……（方式）","sc":"改由……（方式）"},"d":{"es":"改由…（方式）= pasar a hacerse por…, cambiar a… Indica que se abandona la forma anterior y otra persona o modalidad toma su lugar. 由 introduce al agente o al método. Frecuente en explicaciones y descripciones.","en":"Says the old way is dropped and replaced by another person or method; after 由 can be a person or a method, often followed by 方式.","tc":"表示原來的做法不用了，換成另一種人或方式來做。「由」後面可以是人，也可以是方式，常接「方式」。","sc":"表示原来的做法不用了，换成另一种人或方式来做。「由」后面可以是人，也可以是方式，常接「方式」。"},"ex":[{"c":"所謂的「飢餓行銷」，就是從原本的無限制供應，改由限量提供的方式販售。","s":"所谓的「饥饿行销」，就是从原本的无限制供应，改由限量提供的方式贩售。","es":"El llamado «marketing del hambre» consiste en pasar de un suministro ilimitado a venderlo en cantidad limitada.","en":"So-called 'hunger marketing' means changing from unlimited supply to selling in limited quantities.","p":"suǒ wèi de 「jī è xíng xiāo」, jiù shì cóng yuán běn de wú xiàn zhì gōng yìng, gǎi yóu xiàn liàng tí gōng de fāng shì fàn shòu."},{"c":"這家公司的客服改由人工智慧來處理。","s":"这家公司的客服改由人工智慧来处理。","es":"El servicio al cliente de esta empresa pasó a ser atendido por inteligencia artificial.","en":"This company's customer service is now handled by artificial intelligence instead.","p":"zhè jiā gōng sī de kè fú gǎi yóu rén gōng zhì huì lái chǔ lǐ."}]},{"id":"6-6-10","b":6,"l":6,"k":"","t":{"es":"Abrir la puerta a…: 打開……的大門","en":"Open the door to…: 打開……的大門","ens":"Open the door to…: 打开……的大门","tc":"打開……的大門","sc":"打开……的大门"},"d":{"es":"打開…的大門 = abrir las puertas a…. Metáfora que significa dar paso a una oportunidad, un ámbito o una relación. Lo que se abre va antes de 的大門. Frecuente en prensa y textos formales.","en":"A metaphor for opening up an opportunity, field or relationship; the thing being opened goes before 的大門. Common in writing and news.","tc":"比喻讓某個機會、領域或關係開始出現。「的大門」前面放要開放的對象，書面、新聞常用。","sc":"比喻让某个机会、领域或关系开始出现。「的大门」前面放要开放的对象，书面、新闻常用。"},"ex":[{"c":"吸引觀光客，賺取外匯→打開對外開放的大門。","s":"吸引观光客，赚取外汇→打开对外开放的大门。","es":"Atraer turistas y ganar divisas → abrir la puerta a la apertura al exterior.","en":"Attract tourists and earn foreign exchange → open the door to opening up to the outside world.","p":"xī yǐn guān guāng kè, zhuàn qǔ wài huì→ dǎ kāi duì wài kāi fàng de dà mén."},{"c":"這項新技術為年輕人打開了創業的大門。","s":"这项新技术为年轻人打开了创业的大门。","es":"Esta nueva tecnología abrió a los jóvenes las puertas del emprendimiento.","en":"This new technology opened the door to starting a business for young people.","p":"zhè xiàng xīn jì shù wéi nián qīng rén dǎ kāi le chuàng yè de dà mén."}]},{"id":"6-6-11","b":6,"l":6,"k":"","t":{"es":"En nombre de / bajo la figura de: 以X的名義","en":"In the name of X: 以X的名義","ens":"In the name of X: 以X的名义","tc":"以X的名義","sc":"以X的名义"},"d":{"es":"以 X 的名義 = en nombre de X, bajo el título/pretexto de X. Indica la calidad o el motivo con el que se hace algo; X puede ser una función real o solo un pretexto, según el contexto.","en":"Doing something under a certain status, reason or name; X may be a genuine capacity or just a pretext.","tc":"表示用某種身分、理由或名稱來做事，X 可能是真實的身分，也可能只是名義。","sc":"表示用某种身分、理由或名称来做事，X 可能是真实的身分，也可能只是名义。"},"ex":[{"c":"剛以訪問的名義抵達台北的導演，將會傳授運用鏡頭的祕訣，達到交流的目的。","s":"刚以访问的名义抵达台北的导演，将会传授运用镜头的秘诀，达到交流的目的。","es":"El director, que acaba de llegar a Taipéi en calidad de visitante, enseñará los secretos del uso de la cámara para lograr el intercambio.","en":"The director who just arrived in Taipei on a visit will teach secrets of using the camera, in order to achieve exchange.","p":"gāng yǐ fǎng wèn de míng yì dǐ dá tái běi de dǎo yǎn, jiāng huì chuán shòu yùn yòng jìng tóu de mì jué, dá dào jiāo liú de mù dì."},{"c":"他以朋友的名義借了一大筆錢，卻一直沒有還。","s":"他以朋友的名义借了一大笔钱，却一直没有还。","es":"Pidió prestada una gran suma de dinero invocando la amistad, y nunca la devolvió.","en":"He borrowed a large sum of money in the name of friendship and never paid it back.","p":"tā yǐ péng yǒu de míng yì jiè le yí dà bǐ qián, què yì zhí méi yǒu hái."}]},{"id":"6-7-0","b":6,"l":7,"k":"","t":{"es":"En el momento de…: 在……（的）當下","en":"At the moment of…: 在……（的）當下","ens":"At the moment of…: 在……（的）当下","tc":"在……（的）當下","sc":"在……（的）当下"},"d":{"es":"在…（的）當下 = en el momento en que…, en el acto de…. Marca el instante exacto de un suceso, que va antes de 當下. Más escrito; 當下 solo también significa «en ese momento».","en":"Means at the very moment something happens; the event goes before 當下. Written or formal; can also be just 當下.","tc":"指事情發生的那一刻，「當下」前面放事件或動作。書面或較正式，也可只說「當下」。","sc":"指事情发生的那一刻，「当下」前面放事件或动作。书面或较正式，也可只说「当下」。"},"ex":[{"c":"該國在提出交換條件的當下，已立刻遭聯合國否決，因此該國無法順利完成提案。","s":"该国在提出交换条件的当下，已立刻遭联合国否决，因此该国无法顺利完成提案。","es":"En el momento en que ese país presentó condiciones de intercambio, la ONU las rechazó de inmediato, por lo que no pudo concretar la propuesta.","en":"The moment that country put forward its exchange conditions, the UN rejected them immediately, so the country could not complete its proposal.","p":"gāi guó zài tí chū jiāo huàn tiáo jiàn de dāng xià, yǐ lì kè zāo lián hé guó fǒu jué, yīn cǐ gāi guó wú fǎ shùn lì wán chéng tí àn."},{"c":"在聽到這個消息的當下，他整個人愣住了。","s":"在听到这个消息的当下，他整个人愣住了。","es":"En el momento de oír la noticia, se quedó pasmado.","en":"The moment he heard the news, he was stunned.","p":"zài tīng dào zhè ge xiāo xí de dāng xià, tā zhěng gè rén lèng zhù le."}]},{"id":"6-7-1","b":6,"l":7,"k":"","t":{"es":"Ser fiel a: 忠於","en":"Be faithful to: 忠於","ens":"Be faithful to: 忠于","tc":"忠於","sc":"忠于"},"d":{"es":"忠於 = ser fiel a, mantenerse leal a. Va seguido de una persona, ideal, principio o también «uno mismo» (忠於自己). Registro escrito. En el ejemplo se usa con matiz de «apegarse demasiado» a la lengua materna.","en":"Remaining loyal to a person, ideal or principle; followed by a person or abstract thing. Rather written.","tc":"對人、理想、原則等保持忠誠，不背叛。後面接人或抽象的對象，較書面。","sc":"对人、理想、原则等保持忠诚，不背叛。后面接人或抽象的对象，较书面。"},"ex":[{"c":"眾所皆知，學習外語時不能過於忠於母語，免得受母語影響，造成外語文法錯亂。","s":"众所皆知，学习外语时不能过于忠于母语，免得受母语影响，造成外语文法错乱。","es":"Es bien sabido que al aprender un idioma extranjero no hay que apegarse demasiado a la lengua materna, para que esta no influya y cause errores de gramática.","en":"As is well known, when learning a foreign language one shouldn't stick too closely to the mother tongue, lest it interfere and cause grammar errors.","p":"zhòng suǒ jiē zhī, xué xí wài yǔ shí bù néng guò yú zhōng yú mǔ yǔ, miǎn dé shòu mǔ yǔ yǐng xiǎng, zào chéng wài yǔ wén fǎ cuò luàn."},{"c":"記者應該忠於事實，不能隨意改寫新聞。","s":"记者应该忠于事实，不能随意改写新闻。","es":"Los periodistas deben ser fieles a los hechos y no alterar las noticias a su antojo.","en":"Journalists should be faithful to the facts and not rewrite the news at will.","p":"jì zhě yīng gāi zhōng yú shì shí, bù néng suí yì gǎi xiě xīn wén."}]},{"id":"6-7-2","b":6,"l":7,"k":"","t":{"es":"Aunque…, igualmente…: 縱使……，也……","en":"Even if…, still…: 縱使……，也……","ens":"Even if…, still…: 纵使……，也……","tc":"縱使……，也……","sc":"纵使……，也……"},"d":{"es":"縱使…，也… = aun si…, de todas formas…. Concesiva literaria, más escrita que 即使; la segunda parte lleva 也 y expresa que la decisión no cambia. Introduce una hipótesis desfavorable (no un hecho ya ocurrido).","en":"Even if a very unfavorable situation arises, the result or decision stays the same. More written than 即使; the second clause usually has 也.","tc":"表示就算出現很不利的情況，結果或決定也不會改變。比「即使」更書面，後半句常有「也」。","sc":"表示就算出现很不利的情况，结果或决定也不会改变。比「即使」更书面，后半句常有「也」。"},"ex":[{"c":"縱使中文愈學愈難，我也要堅持學下去，因為中文有一定的國際市場。","s":"纵使中文愈学愈难，我也要坚持学下去，因为中文有一定的国际市场。","es":"Aunque el chino se vuelva cada vez más difícil, seguiré estudiándolo, porque el chino tiene un mercado internacional establecido.","en":"Even if Chinese gets harder and harder, I'll keep studying it, because Chinese has a certain international market.","p":"zòng shǐ zhōng wén yù xué yù nán, wǒ yě yào jiān chí xué xià qù, yīn wèi zhōng wén yǒu yí dìng de guó jì shì chǎng."},{"c":"縱使明天下大雨，我們也要按照計畫出發。","s":"纵使明天下大雨，我们也要按照计划出发。","es":"Aunque mañana llueva a cántaros, saldremos tal como estaba planeado.","en":"Even if it pours tomorrow, we will set off as planned.","p":"zòng shǐ míng tiān xià dà yǔ, wǒ men yě yào àn zhào jì huà chū fā."}]},{"id":"6-7-3","b":6,"l":7,"k":"","t":{"es":"Autoproclamarse: 自詡為X","en":"Style oneself as X: 自詡為X","ens":"Style oneself as X: 自诩为X","tc":"自詡為X","sc":"自诩为X"},"d":{"es":"自詡為 X = autoproclamarse X, presumir de ser X. Alguien se atribuye un título o cualidad positiva; con frecuencia implica ironía o cierta duda del hablante. Registro escrito.","en":"Calling oneself something impressive, such as an expert; often with an ironic hint that it may not be true.","tc":"自己認為、並向別人說自己是某種很好的人或專家，常帶有「未必真是這樣」的諷刺意味。","sc":"自己认为、并向别人说自己是某种很好的人或专家，常带有「未必真是这样」的讽刺意味。"},"ex":[{"c":"陳經理幫公司克服了一場危機，自此自詡為危機處理專家。","s":"陈经理帮公司克服了一场危机，自此自诩为危机处理专家。","es":"El gerente Chen ayudó a la empresa a superar una crisis y desde entonces se autoproclama experto en manejo de crisis.","en":"Manager Chen helped the company overcome a crisis and has since styled himself a crisis-management expert.","p":"chén jīng lǐ bāng gōng sī kè fú le yì chǎng wéi jī, zì cǐ zì xǔ wéi wéi jī chǔ lǐ zhuān jiā."},{"c":"他自詡為美食家，其實連最基本的調味都不太懂。","s":"他自诩为美食家，其实连最基本的调味都不太懂。","es":"Se autoproclama gourmet, pero en realidad ni siquiera sabe sazonar lo más básico.","en":"He fancies himself a gourmet, but actually barely understands basic seasoning.","p":"tā zì xǔ wéi měi shí jiā, qí shí lián zuì jī běn de tiáo wèi dōu bú tài dǒng."}]},{"id":"6-7-4","b":6,"l":7,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Llevar X al máximo: 把X發揮到極致","en":"Take X to the fullest: 把X發揮到極致","ens":"Take X to the fullest: 把X发挥到极致","tc":"把X發揮到極致","sc":"把X发挥到极致"},"d":{"es":"把 X 發揮到極致 = llevar X a su máxima expresión. Estructura con 把: X es la cualidad, habilidad o característica que se explota al máximo. Tono positivo, frecuente en elogios.","en":"Bringing an ability, feature or flavor to its fullest, best expression. X is what is brought out; positive tone.","tc":"把某種能力、特色或味道表現到最好、最完整的程度。X 是被發揮的對象，語氣褒義。","sc":"把某种能力、特色或味道表现到最好、最完整的程度。X 是被发挥的对象，语气褒义。"},"ex":[{"c":"該素食餐廳有不少創新菜色，總能把新鮮蔬果的味道發揮到極致，難怪在素食餐廳界無人不知、無人不曉。","s":"该素食餐厅有不少创新菜色，总能把新鲜蔬果的味道发挥到极致，难怪在素食餐厅界无人不知、无人不晓。","es":"Ese restaurante vegetariano tiene muchos platos innovadores y siempre logra llevar al máximo el sabor de las frutas y verduras frescas; no es de extrañar que sea conocido por todos en el mundo de los restaurantes vegetarianos.","en":"That vegetarian restaurant has many innovative dishes and always brings out the flavor of fresh fruits and vegetables to the fullest; no wonder everyone in the vegetarian restaurant world knows it.","p":"gāi sù shí cān tīng yǒu bù shǎo chuàng xīn cài sè, zǒng néng bǎ xīn xiān shū guǒ de wèi dào fā huī dào jí zhì, nán guài zài sù shí cān tīng jiè wú rén bù zhī, wú rén bù xiǎo."},{"c":"這位設計師把簡約風格發揮到極致。","s":"这位设计师把简约风格发挥到极致。","es":"Este diseñador llevó el estilo minimalista a su máxima expresión.","en":"This designer took the minimalist style to the extreme.","p":"zhè wèi shè jì shī bǎ jiǎn yuē fēng gé fā huī dào jí zhì."}]},{"id":"6-7-5","b":6,"l":7,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Sin poder evitarlo: 不由自主地","en":"Involuntarily: 不由自主地","ens":"Involuntarily: 不由自主地","tc":"不由自主地","sc":"不由自主地"},"d":{"es":"不由自主地 = involuntariamente, sin poder evitarlo. Describe una reacción física o emocional que uno no controla. Va antes del verbo con 地; suele hablar de emociones, risas, lágrimas o impulsos.","en":"Unable to control oneself; the body or emotions react on their own. Placed before the verb, linked with 地.","tc":"沒辦法控制自己，身體或情緒自然就做出某個動作或反應。放在動詞前，用「地」連接。","sc":"没办法控制自己，身体或情绪自然就做出某个动作或反应。放在动词前，用「地」连接。"},"ex":[{"c":"參加喜宴時，看見新人幸福的笑容，常讓人不由自主地也想結束單身生活，早點請大家吃喜酒。","s":"参加喜宴时，看见新人幸福的笑容，常让人不由自主地也想结束单身生活，早点请大家吃喜酒。","es":"Al ver la sonrisa feliz de los novios en una boda, a menudo uno no puede evitar querer dejar la soltería y casarse pronto.","en":"When attending a wedding banquet and seeing the couple's happy smiles, one often can't help wanting to end single life and invite everyone to one's own wedding soon.","p":"cān jiā xǐ yàn shí, kàn jiàn xīn rén xìng fú de xiào róng, cháng ràng rén bù yóu zì zhǔ dì yě xiǎng jié shù dān shēn shēng huó, zǎo diǎn qǐng dà jiā chī xǐ jiǔ."},{"c":"聽到那首老歌，他不由自主地哼了起來。","s":"听到那首老歌，他不由自主地哼了起来。","es":"Al oír esa vieja canción, empezó a tararearla sin darse cuenta.","en":"Hearing that old song, he began to hum along involuntarily.","p":"tīng dào nà shǒu lǎo gē, tā bù yóu zì zhǔ dì hēng le qǐ lái."}]},{"id":"6-7-6","b":6,"l":7,"k":"","t":{"es":"Ponerse del mismo lado: 和X站在同一陣線","en":"Be on the same side as X: 和X站在同一陣線","ens":"Be on the same side as X: 和X站在同一阵线","tc":"和X站在同一陣線","sc":"和X站在同一阵线"},"d":{"es":"和 X 站在同一陣線 = estar del mismo lado que X, unirse a X frente a un tercero. «陣線» (frente) es metafórico. Se usa en política, debates y conflictos; el contrario es 站在對立面.","en":"Sharing someone's stance and facing the other side together; common in politics, debates and competition; 陣線 is figurative.","tc":"與某人立場一致、共同對抗另一方。常見於政治、爭論或競爭場合，「陣線」是比喻。","sc":"与某人立场一致、共同对抗另一方。常见于政治、争论或竞争场合，「阵线」是比喻。"},"ex":[{"c":"學生和老師站在同一陣線，反對教育部的新政策。","s":"学生和老师站在同一阵线，反对教育部的新政策。","es":"Los estudiantes y los profesores se pusieron del mismo lado para oponerse a la nueva política del Ministerio de Educación.","en":"Students and teachers stood on the same side to oppose the Ministry of Education's new policy.","p":"xué shēng hàn lǎo shī zhàn zài tóng yí zhèn xiàn, fǎn duì jiào yù bù de xīn zhèng cè."},{"c":"為了保護這片森林，居民和環保團體站在同一陣線。","s":"为了保护这片森林，居民和环保团体站在同一阵线。","es":"Para proteger este bosque, los habitantes y los grupos ecologistas se unieron en un mismo frente.","en":"To protect this forest, residents and environmental groups stood together on the same front.","p":"wèi le bǎo hù zhè piàn sēn lín, jū mín hàn huán bǎo tuán tǐ zhàn zài tóng yí zhèn xiàn."}]},{"id":"6-7-7","b":6,"l":7,"k":"","t":{"es":"Usar y tirar: X過即Y","en":"Use then discard: X過即Y","ens":"Use then discard: X过即Y","tc":"X過即Y","sc":"X过即Y"},"d":{"es":"X 過即 Y = una vez X, enseguida Y. Estructura de aire clásico: tras hacer X se hace Y inmediatamente; la usan expresiones como 用過即丟 (usar y tirar) o 看過即焚. X suele ser un verbo monosilábico. Registro escrito.","en":"Means doing Y right after X, often describing single-use things like 用過即丟. X is usually a verb; idiom-like and written.","tc":"表示做完 X 之後馬上做 Y，常用來形容「用過就丟」這類一次性的東西。X 通常是動詞，格式像成語，偏書面。","sc":"表示做完 X 之后马上做 Y，常用来形容「用过就丢」这类一次性的东西。X 通常是动词，格式像成语，偏书面。"},"ex":[{"c":"如何處理越來越多用過即丟的垃圾，是環保工作的一大難題。","s":"如何处理越来越多用过即丢的垃圾，是环保工作的一大难题。","es":"Cómo manejar la creciente cantidad de basura de «usar y tirar» es uno de los grandes problemas de la protección ambiental.","en":"How to handle the growing amount of use-and-throw-away garbage is one of the big challenges of environmental work.","p":"rú hé chǔ lǐ yuè lái yuè duō yòng guò jí diū de lè sè, shì huán bǎo gōng zuò de yí dà nán tí."},{"c":"這種口罩是用過即丟的，不能重複使用。","s":"这种口罩是用过即丢的，不能重复使用。","es":"Este tipo de mascarilla es de usar y tirar; no se puede reutilizar.","en":"This kind of mask is single-use, throw away after use, and can't be reused.","p":"zhè zhǒng kǒu zhào shì yòng guò jí diū de, bù néng chóng fù shǐ yòng."}]},{"id":"6-7-8","b":6,"l":7,"k":"","t":{"es":"Ni tener en cuenta: ……（都）看在眼裡","en":"Take into account/regard: ……（都）看在眼裡","ens":"Take into account/regard: ……（都）看在眼里","tc":"……（都）看在眼裡","sc":"……（都）看在眼里"},"d":{"es":"…（都）看在眼裡 = tener en cuenta / darle importancia a…. En afirmativo indica que algo importa o se aprecia; en negativo (不看在眼裡) significa no darle importancia o menospreciar. En el ejemplo: «la fama y el dinero nunca le importaron».","en":"Literally 'put in one's eyes'. Affirmative shows concern or esteem; the negative 不看在眼裡 means disregard or not caring.","tc":"字面是「放在眼裡」。肯定時表示在意、重視；否定「不看在眼裡」表示瞧不起或毫不在乎。","sc":"字面是「放在眼里」。肯定时表示在意、重视；否定「不看在眼里」表示瞧不起或毫不在乎。"},"ex":[{"c":"那位大師表示，名利他從來不看在眼裡，他傳授心法，既不為名，也不為利。","s":"那位大师表示，名利他从来不看在眼里，他传授心法，既不为名，也不为利。","es":"El maestro dijo que nunca le han importado la fama ni el dinero; transmite su método sin buscar ni lo uno ni lo otro.","en":"That master said he has never cared about fame and fortune; he passes on his method neither for fame nor for profit.","p":"nà wèi dà shī biǎo shì, míng lì tā cóng lái bú kàn zài yǎn lǐ, tā chuán shòu xīn fǎ, jì bù wéi míng, yě bù wéi lì."},{"c":"他一心只想做研究，根本不把名利看在眼裡。","s":"他一心只想做研究，根本不把名利看在眼里。","es":"Solo piensa en investigar y no le da ninguna importancia a la fama ni al dinero.","en":"He only wants to do research and doesn't care about fame or wealth at all.","p":"tā yì xīn zhǐ xiǎng zuò yán jiù, gēn běn bù bǎ míng lì kàn zài yǎn lǐ."}]},{"id":"6-7-9","b":6,"l":7,"k":"","t":{"es":"Comparar y sacar lo común: V（出）其中的共同點","en":"Draw out the common points: V（出）其中的共同點","ens":"Draw out the common points: V（出）其中的共同点","tc":"V（出）其中的共同點","sc":"V（出）其中的共同点"},"d":{"es":"V（出）其中的共同點 = hallar/sacar los puntos en común entre ellos. Un verbo (比較, 找, 歸納, 看) con el complemento 出 expresa extraer o identificar algo de un conjunto. «其中» remite a los elementos ya mencionados.","en":"A verb (compare, find, sum up, see) plus 出 shows picking out or identifying the shared point among things.","tc":"動詞（比較、找、歸納、看）加「出」表示從一些事物裡把共同的地方找出來或整理出來。","sc":"动词（比较、找、归纳、看）加「出」表示从一些事物里把共同的地方找出来或整理出来。"},"ex":[{"c":"專家當然能對兩種工程比較其中的共同點，並給民眾介紹說明。","s":"专家当然能对两种工程比较其中的共同点，并给民众介绍说明。","es":"Por supuesto, los expertos pueden comparar los puntos en común entre los dos tipos de obras y explicárselos al público.","en":"Of course experts can compare the common points of the two kinds of engineering and explain them to the public.","p":"zhuān jiā dāng rán néng duì liǎng zhǒng gōng chéng bǐ jiào qí zhōng de gòng tóng diǎn, bìng gěi mín zhòng jiè shào shuō míng."},{"c":"請你從這幾篇文章裡找出其中的共同點。","s":"请你从这几篇文章里找出其中的共同点。","es":"Por favor, encuentra los puntos en común de estos artículos.","en":"Please find the common points among these articles.","p":"qǐng nǐ cóng zhè jǐ piān wén zhāng lǐ zhǎo chū qí zhōng de gòng tóng diǎn."}]},{"id":"6-7-10","b":6,"l":7,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Existe la posibilidad de…: 有……的可能","en":"There is a possibility of…: 有……的可能","ens":"There is a possibility of…: 有……的可能","tc":"有……的可能","sc":"有……的可能"},"d":{"es":"有…的可能 = existe la posibilidad de…. Tras 有 va el suceso y luego 的可能. Es un registro más objetivo, propio de informes y análisis. También en negativo: 沒有…的可能.","en":"Says something may happen; the event goes before 的可能. Common in reports and analyses, more objective in tone than 可能.","tc":"說某件事有可能發生，「的可能」前面是事件。常用於報導、分析，語氣比「可能」更客觀。","sc":"说某件事有可能发生，「的可能」前面是事件。常用于报导、分析，语气比「可能」更客观。"},"ex":[{"c":"經濟學家指出，全球經濟有衰敗的可能，呼籲政府與民眾合作，再創經濟奇蹟。","s":"经济学家指出，全球经济有衰败的可能，呼吁政府与民众合作，再创经济奇迹。","es":"Los economistas señalan que la economía global podría decaer y piden a gobierno y ciudadanos que cooperen para crear de nuevo un milagro económico.","en":"Economists point out that the global economy may decline and call for the government and the public to cooperate to create another economic miracle.","p":"jīng jì xué jiā zhǐ chū, quán qiú jīng jì yǒu shuāi bài de kě néng, hū yù zhèng fǔ yǔ mín zhòng hé zuò, zài chuàng jīng jì qí jī."},{"c":"這場颱風有影響明天航班的可能。","s":"这场台风有影响明天航班的可能。","es":"Este tifón podría afectar los vuelos de mañana.","en":"This typhoon may affect tomorrow's flights.","p":"zhè chǎng tái fēng yǒu yǐng xiǎng míng tiān háng bān de kě néng."}]},{"id":"6-8-0","b":6,"l":8,"k":"","t":{"es":"Después de pasar por…: 在歷經……之後","en":"After going through…: 在歷經……之後","ens":"After going through…: 在历经……之后","tc":"在歷經……之後","sc":"在历经……之后"},"d":{"es":"在歷經…之後 = tras haber pasado por…. 歷經 se usa con experiencias importantes o duras (crisis, años de esfuerzo) y es de registro escrito. Equivale a «después de atravesar…».","en":"After going through a series of (usually hard or long) events; 歷經 takes serious or arduous experiences. Written.","tc":"經過一連串（通常是困難或長期的）事情以後。「歷經」多接重大、辛苦的經驗，書面。","sc":"经过一连串（通常是困难或长期的）事情以后。「历经」多接重大、辛苦的经验，书面。"},"ex":[{"c":"舞團並沒有在歷經接二連三的災害之後解散，反而是徵求了更多的舞者，逐年培育新團員。","s":"舞团并没有在历经接二连三的灾害之后解散，反而是征求了更多的舞者，逐年培育新团员。","es":"La compañía de danza no se disolvió tras pasar por desastres sucesivos; al contrario, reclutó más bailarines y formó nuevos miembros año tras año.","en":"The dance troupe did not disband after going through one disaster after another; instead it recruited more dancers and trained new members year by year.","p":"wǔ tuán bìng méi yǒu zài lì jīng jiē èr lián sān de zāi hài zhī hòu jiě sàn, fǎn ér shì zhēng qiú le gèng duō de wǔ zhě, zhú nián péi yù xīn tuán yuán."},{"c":"在歷經多年的努力之後，他終於完成了博士學位。","s":"在历经多年的努力之后，他终于完成了博士学位。","es":"Después de muchos años de esfuerzo, por fin terminó el doctorado.","en":"After years of effort, he finally completed his doctorate.","p":"zài lì jīng duō nián de nǔ lì zhī hòu, tā zhōng yú wán chéng le bó shì xué wèi."}]},{"id":"6-8-1","b":6,"l":8,"k":"","t":{"es":"Tantos como…: ……之多，是……","en":"As many as…: ……之多，是……","ens":"As many as…: ……之多，是……","tc":"……之多，是……","sc":"……之多，是……"},"d":{"es":"…之多，是… = tantos como…, hasta… (más que…). 之多 subraya que la cantidad es sorprendentemente grande; luego se compara, a menudo con «es N veces…». Registro escrito, común en noticias.","en":"First says the amount is large (之多 implies surprisingly many), then gives the comparison, often 'X times as many as…'.","tc":"先說數量非常多（「之多」表示多到令人驚訝），再說比較的結果，常是「是……的幾倍」。","sc":"先说数量非常多（「之多」表示多到令人惊讶），再说比较的结果，常是「是……的几倍」。"},"ex":[{"c":"這次申奧城市之多，是上次的三倍，看來舉辦奧運的經濟利益相當吸引人。","s":"这次申奥城市之多，是上次的三倍，看来举办奥运的经济利益相当吸引人。","es":"El número de ciudades que se postularon para los Juegos Olímpicos fue tres veces el de la vez anterior; parece que el beneficio económico de organizarlos es muy atractivo.","en":"The number of cities bidding for the Olympics was three times that of last time; apparently the economic benefits of hosting are very attractive.","p":"zhè cì shēn ào chéng shì zhī duō, shì shàng cì de sān bèi, kàn lái jǔ bàn ào yùn de jīng jì lì yì xiāng dāng xī yǐn rén."},{"c":"這次參加的人數之多，是去年的兩倍。","s":"这次参加的人数之多，是去年的两倍。","es":"El número de participantes fue tan alto que duplicó el del año pasado.","en":"The number of participants this time was so large it was double last year's.","p":"zhè cì cān jiā de rén shù zhī duō, shì qù nián de liǎng bèi."}]},{"id":"6-8-2","b":6,"l":8,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Desde siempre: 一直以來","en":"All along: 一直以來","ens":"All along: 一直以来","tc":"一直以來","sc":"一直以来"},"d":{"es":"一直以來 = desde siempre, durante todo este tiempo (hasta ahora). Expresa continuidad desde el pasado hasta el presente; suele ir al comienzo de la oración o tras el sujeto, con frecuencia seguido de 都.","en":"From some time in the past until now, with no change; placed at the start of a sentence or after the subject, often with 都.","tc":"從過去某個時候一直到現在，情況沒有改變。放在句首或主語後面，常接「都」。","sc":"从过去某个时候一直到现在，情况没有改变。放在句首或主语后面，常接「都」。"},"ex":[{"c":"真誠的讚美一直以來都是予人真切的肯定，因此若希望掌握做人的魅力，不妨試著多讚美別人。","s":"真诚的赞美一直以来都是予人真切的肯定，因此若希望掌握做人的魅力，不妨试着多赞美别人。","es":"Un elogio sincero siempre ha sido un reconocimiento genuino para los demás; por eso, si quieres tener encanto personal, conviene elogiar más a los otros.","en":"Sincere praise has always given people genuine affirmation, so if you want to have charm, try praising others more.","p":"zhēn chéng de zàn měi yì zhí yǐ lái dōu shì yǔ rén zhēn qiè de kěn dìng, yīn cǐ ruò xī wàng zhǎng wò zuò rén de mèi lì, bù fáng shì zhe duō zàn měi bié rén."},{"c":"一直以來，他都是班上最認真的學生。","s":"一直以来，他都是班上最认真的学生。","es":"Desde siempre, él ha sido el estudiante más aplicado de la clase.","en":"All along, he has been the most diligent student in the class.","p":"yì zhí yǐ lái, tā dōu shì bān shàng zuì rèn zhēn de xué shēng."}]},{"id":"6-8-3","b":6,"l":8,"k":"","t":{"es":"Ver como muestra de…: 視為……的展現","en":"Regard as a display of…: 視為……的展現","ens":"Regard as a display of…: 视为……的展现","tc":"視為……的展現","sc":"视为……的展现"},"d":{"es":"視為…的展現 = considerar (algo) una muestra de…. 視為 equivale a «considerar como»; 展現 es la manifestación de una cualidad o capacidad. Registro escrito, frecuente en comentarios y noticias.","en":"Regards a behavior as a display of a quality or ability; 視為 means 'regard as', written style.","tc":"把某個行為看成是某種特質、能力的表現。前面常有主語，「視為」是「把……看成」，書面。","sc":"把某个行为看成是某种特质、能力的表现。前面常有主语，「视为」是「把……看成」，书面。"},"ex":[{"c":"某媒體將他參加總統大選，視為企圖心的展現，予以高度肯定。","s":"某媒体将他参加总统大选，视为企图心的展现，予以高度肯定。","es":"Cierto medio consideró su participación en las elecciones presidenciales una muestra de ambición y la elogió mucho.","en":"A certain media outlet regarded his entering the presidential election as a display of ambition and strongly approved.","p":"mǒu méi tǐ jiāng tā cān jiā zǒng tǒng dà xuǎn, shì wéi qì tú xīn de zhǎn xiàn, yǔ yǐ gāo dù kěn dìng."},{"c":"許多人把這次的道歉視為誠意的展現。","s":"许多人把这次的道歉视为诚意的展现。","es":"Mucha gente considera esta disculpa una muestra de sinceridad.","en":"Many people regard this apology as a show of sincerity.","p":"xǔ duō rén bǎ zhè cì de dào qiàn shì wéi chéng yì de zhǎn xiàn."}]},{"id":"6-8-4","b":6,"l":8,"k":"","t":{"es":"Volver a / ser devuelto a: 歸於","en":"Return to: 歸於","ens":"Return to: 归于","tc":"歸於","sc":"归于"},"d":{"es":"歸於 = volver a, regresar a (un lugar o estado). Aparece en combinaciones fijas como 歸於平靜 (volver a la calma) o 歸於山林 (volver a los montes). Es de registro escrito y requiere un destino o estado que lo complete.","en":"Returning to a place or entering a state, as in 歸於平靜 or 歸於山林. Written, mostly fixed collocations.","tc":"回到某處或進入某種狀態，如「歸於平靜」「歸於山林」。書面，常見固定搭配。","sc":"回到某处或进入某种状态，如「归于平静」「归于山林」。书面，常见固定搭配。"},"ex":[{"c":"貓熊野放歸於山林之後，難以適應，失去生存能力，是保育工作的一大難題。","s":"猫熊野放归于山林之后，难以适应，失去生存能力，是保育工作的一大难题。","es":"Tras ser liberados en la naturaleza, los pandas tienen dificultades para adaptarse y pierden la capacidad de sobrevivir, lo que es un gran problema de la conservación.","en":"After being released into the wild, pandas find it hard to adapt and lose their ability to survive, which is a major problem in conservation work.","p":"māo xióng yě fàng guī yú shān lín zhī hòu, nán yǐ shì yìng, shī qù shēng cún néng lì, shì bǎo yù gōng zuò de yí dà nán tí."},{"c":"風波過後，一切又歸於平靜。","s":"风波过后，一切又归于平静。","es":"Después de la tormenta, todo volvió a la calma.","en":"After the uproar, everything returned to calm.","p":"fēng bō guò hòu, yí qiè yòu guī yú píng jìng."}]},{"id":"6-8-5","b":6,"l":8,"k":"","t":{"es":"X es Y: X即是Y","en":"X is precisely Y: X即是Y","ens":"X is precisely Y: X即是Y","tc":"X即是Y","sc":"X即是Y"},"d":{"es":"X 即是 Y = X es precisamente Y. 即是 es la versión escrita de 就是 y sirve para definir o afirmar la esencia de algo. En el ejemplo: «lo que más anhela el ser humano es ser reconocido».","en":"即是 equals 就是 and states directly what X means or is; used for definitions and statements, written.","tc":"「即是」相當於「就是」，用來直接說明 X 的意思或本質，常用來下定義、說道理，書面。","sc":"「即是」相当于「就是」，用来直接说明 X 的意思或本质，常用来下定义、说道理，书面。"},"ex":[{"c":"專家說，人內心深切的渴望即是得到肯定與讚美，可想而知，真誠讚美可贏得好人緣。","s":"专家说，人内心深切的渴望即是得到肯定与赞美，可想而知，真诚赞美可赢得好人缘。","es":"Los expertos dicen que el deseo más profundo de las personas es ser reconocidas y elogiadas; es fácil entender que un elogio sincero gana buena reputación.","en":"Experts say that people's deepest longing is to be affirmed and praised; it is easy to see that sincere praise wins popularity.","p":"zhuān jiā shuō, rén nèi xīn shēn qiè de kě wàng jí shì dé dào kěn dìng yǔ zàn měi, kě xiǎng ér zhī, zhēn chéng zàn měi kě yíng dé hǎo rén yuán."},{"c":"教育的目的即是幫助孩子成為更好的人。","s":"教育的目的即是帮助孩子成为更好的人。","es":"El propósito de la educación es, precisamente, ayudar a los niños a ser mejores personas.","en":"The purpose of education is to help children become better people.","p":"jiào yù de mù dì jí shì bāng zhù hái zi chéng wéi gèng hǎo de rén."}]},{"id":"6-8-6","b":6,"l":8,"k":"","t":{"es":"Mucho después de…: 遠在……之後","en":"Long after…: 遠在……之後","ens":"Long after…: 远在……之后","tc":"遠在……之後","sc":"远在……之后"},"d":{"es":"遠在…之後 = mucho después de…. 遠 enfatiza la gran distancia temporal respecto de un punto de referencia; su opuesto es 遠在…之前 (mucho antes de…). Registro escrito.","en":"Says the time is much later than a reference time; 遠 stresses the large gap; the counterpart is 遠在…之前.","tc":"表示時間比某個基準時間晚很多。「遠」強調差得很多，也可與「之前」對比成「遠在……之前」。","sc":"表示时间比某个基准时间晚很多。「远」强调差得很多，也可与「之前」对比成「远在……之前」。"},"ex":[{"c":"許多年輕人打算成家的時間，遠在適婚年齡之後，是因為收入不足以養家，不得不等到有足夠存款之後。","s":"许多年轻人打算成家的时间，远在适婚年龄之后，是因为收入不足以养家，不得不等到有足够存款之后。","es":"Muchos jóvenes planean formar una familia mucho después de la edad apropiada para casarse, porque sus ingresos no bastan para mantenerla y deben esperar a tener suficientes ahorros.","en":"Many young people plan to start a family long after the typical marriage age, because their income can't support a family and they have to wait until they have enough savings.","p":"xǔ duō nián qīng rén dǎ suàn chéng jiā de shí jiān, yuǎn zài shì hūn nián líng zhī hòu, shì yīn wèi shōu rù bù zú yǐ yǎng jiā, bù dé bù děng dào yǒu zú gòu cún kuǎn zhī hòu."},{"c":"他的成名遠在他去世之後，生前沒有人欣賞他的畫。","s":"他的成名远在他去世之后，生前没有人欣赏他的画。","es":"Se hizo famoso mucho después de su muerte; en vida nadie apreció sus pinturas.","en":"His fame came long after his death; no one appreciated his paintings in his lifetime.","p":"tā de chéng míng yuǎn zài tā qù shì zhī hòu, shēng qián méi yǒu rén xīn shǎng tā de huà."}]},{"id":"6-8-7","b":6,"l":8,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"X supera a Y en N veces o más: X比Y多（了）N倍有餘","en":"More than N times as many: X比Y多（了）N倍有餘","ens":"More than N times as many: X比Y多（了）N倍有余","tc":"X比Y多（了）N倍有餘","sc":"X比Y多（了）N倍有余"},"d":{"es":"X 比 Y 多（了）N 倍有餘 = X supera a Y en más de N veces. 有餘 significa «y más». Atención: en chino «多 N 倍» suele entenderse como N veces más (X = (N+1)·Y). Estilo escrito, de comparación numérica.","en":"Says X exceeds Y by more than N times; 有餘 means 'with some to spare'. For comparing quantities, written.","tc":"表示 X 比 Y 多出 N 倍還不止。「有餘」是「超過」，用在數量的比較，書面。","sc":"表示 X 比 Y 多出 N 倍还不止。「有余」是「超过」，用在数量的比较，书面。"},"ex":[{"c":"夏季奧運的比賽項目比冬季奧運的多三倍有餘，鉅額的花費也比冬季奧運多了數倍有餘，讓申奧城市不得不想各種辦法找贊助商。","s":"夏季奥运的比赛项目比冬季奥运的多三倍有余，巨额的花费也比冬季奥运多了数倍有余，让申奥城市不得不想各种办法找赞助商。","es":"Las pruebas de los Juegos de Verano son más de tres veces las de los de Invierno, y los enormes gastos también son varias veces mayores, por lo que las ciudades candidatas tienen que buscar patrocinadores de mil maneras.","en":"The Summer Olympics have more than three times as many events as the Winter Games, and the huge costs are also several times higher, so bidding cities have to find all kinds of ways to get sponsors.","p":"xià jì ào yùn de bǐ sài xiàng mù bǐ dōng jì ào yùn de duō sān bèi yǒu yú, jù é de huā fèi yě bǐ dōng jì ào yùn duō le shù bèi yǒu yú, ràng shēn ào chéng shì bù dé bù xiǎng gè zhǒng bàn fǎ zhǎo zàn zhù shāng."},{"c":"這個城市的人口比十年前多了兩倍有餘。","s":"这个城市的人口比十年前多了两倍有余。","es":"La población de esta ciudad es más del doble de más que hace diez años.","en":"This city's population has grown by more than two times compared to ten years ago.","p":"zhè ge chéng shì de rén kǒu bǐ shí nián qián duō le liǎng bèi yǒu yú."}]},{"id":"6-8-8","b":6,"l":8,"k":"","t":{"es":"Terminar en…: 以……收場","en":"End in…: 以……收場","ens":"End in…: 以……收场","tc":"以……收場","sc":"以……收场"},"d":{"es":"以…收場 = terminar en…, acabar con…. Indica el modo en que concluye algo; lo habitual es que lo antecedan resultados no deseados (失敗, 悲劇, 道歉). Registro escrito.","en":"Shows how something ends or turns out; 失敗, 悲劇, 和局 and so on often precede 收場, usually with a regrettable or negative sense.","tc":"表示事情最後的結果或結束方式。「收場」前面常放「失敗」「悲劇」「和局」等，多帶遺憾或負面意味。","sc":"表示事情最后的结果或结束方式。「收场」前面常放「失败」「悲剧」「和局」等，多带遗憾或负面意味。"},"ex":[{"c":"由於事前缺乏評估，對該產業投入的資金，想以損益平衡收場，恐怕有一定程度的困難。","s":"由于事前缺乏评估，对该产业投入的资金，想以损益平衡收场，恐怕有一定程度的困难。","es":"Por falta de evaluación previa, será difícil que la inversión en esa industria termine en un equilibrio entre ganancias y pérdidas.","en":"Due to the lack of prior assessment, it will probably be hard for the money invested in that industry to end at break-even.","p":"yóu yú shì qián quē fá píng gū, duì gāi chǎn yè tóu rù de zī jīn, xiǎng yǐ sǔn yì píng héng shōu chǎng, kǒng pà yǒu yí dìng chéng dù de kùn nán."},{"c":"這場比賽以平手收場，雙方都不滿意。","s":"这场比赛以平手收场，双方都不满意。","es":"El partido terminó en empate y ninguno de los dos bandos quedó satisfecho.","en":"The match ended in a tie, and neither side was satisfied.","p":"zhè chǎng bǐ sài yǐ píng shǒu shōu chǎng, shuāng fāng dōu bù mǎn yì."}]},{"id":"6-8-9","b":6,"l":8,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Significar: 意味著","en":"Mean/imply: 意味著","ens":"Mean/imply: 意味着","tc":"意味著","sc":"意味着"},"d":{"es":"意味著 = significar, implicar. El sujeto suele ser un hecho o fenómeno, y lo que sigue es la conclusión o consecuencia. Propio del registro escrito. No se usa para el «significado» de una palabra (para eso, 意思是).","en":"Shows that something implies or indicates a certain meaning or result. The subject is often a phenomenon; a conclusion follows. Written.","tc":"表示某件事帶有或顯示出某種含義、結果。主語常是現象或情況，後面接結論，書面。","sc":"表示某件事带有或显示出某种含义、结果。主语常是现象或情况，后面接结论，书面。"},"ex":[{"c":"在行為上表現得我行我素，通常意味著自我膨脹得看不清人事物的真正面貌，在人際關係上將缺乏競爭力。","s":"在行为上表现得我行我素，通常意味着自我膨胀得看不清人事物的真正面貌，在人际关系上将缺乏竞争力。","es":"Actuar a su antojo suele significar un ego tan inflado que no se ve la verdadera cara de las personas y las cosas, y se carecerá de competitividad en las relaciones interpersonales.","en":"Behaving in a self-willed way usually means one's ego has swelled so much that one cannot see things as they really are, and one will lack competitiveness in interpersonal relationships.","p":"zài xíng wéi shàng biǎo xiàn dé wǒ xíng wǒ sù, tōng cháng yì wèi zhe zì wǒ péng zhàng dé kàn bù qīng rén shì wù de zhēn zhèng miàn mào, zài rén jì guān xì shàng jiāng quē fá jìng zhēng lì."},{"c":"這個數字意味著經濟正在慢慢恢復。","s":"这个数字意味着经济正在慢慢恢复。","es":"Esta cifra significa que la economía se está recuperando poco a poco.","en":"This figure means the economy is slowly recovering.","p":"zhè ge shù zì yì wèi zhe jīng jì zhèng zài màn màn huī fù."}]},{"id":"6-8-10","b":6,"l":8,"k":"","t":{"es":"Asumir: 接下","en":"Take on: 接下","ens":"Take on: 接下","tc":"接下","sc":"接下"},"d":{"es":"接下 = asumir, hacerse cargo de (una tarea o responsabilidad). Se usa con 責任, 工作, 重擔, 任務. «下» indica que se recibe y se acepta. No es «recibir» físicamente un objeto (eso es 接到).","en":"Accepting and taking charge of a job, responsibility or task. 接下 is V+下, meaning taking over; often with 責任, 工作, 重擔.","tc":"接受並負責某個工作、責任或任務。「接下」是 V＋下，表示承接。常和「責任」「工作」「重擔」搭配。","sc":"接受并负责某个工作、责任或任务。「接下」是 V＋下，表示承接。常和「责任」「工作」「重担」搭配。"},"ex":[{"c":"父親過世後，家中失去收入來源，母親只好接下養家活口的責任，出外工作，並且訓練孩子獨立。","s":"父亲过世后，家中失去收入来源，母亲只好接下养家活口的责任，出外工作，并且训练孩子独立。","es":"Tras la muerte del padre, la familia perdió su fuente de ingresos y la madre tuvo que asumir el sustento del hogar, salió a trabajar y enseñó a sus hijos a ser independientes.","en":"After the father died and the family lost its source of income, the mother had to take on the responsibility of supporting the family, went out to work, and trained the children to be independent.","p":"fù qīn guò shì hòu, jiā zhōng shī qù shōu rù lái yuán, mǔ qīn zhǐ hǎo jiē xià yǎng jiā huó kǒu de zé rèn, chū wài gōng zuò, bìng qiě xùn liàn hái zi dú lì."},{"c":"他接下了這份重要的任務。","s":"他接下了这份重要的任务。","es":"Asumió esta importante misión.","en":"He took on this important task.","p":"tā jiē xià le zhè fèn zhòng yào de rèn wù."}]},{"id":"6-8-11","b":6,"l":8,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Provenir de / lograrse mediante: 經由……而來","en":"Come through…: 經由……而來","ens":"Come through…: 经由……而来","tc":"經由……而來","sc":"经由……而来"},"d":{"es":"經由…而來 = provenir de, lograrse a través de…. 經由 introduce el medio o proceso y 而來 cierra la estructura. Enfatiza que algo se obtiene mediante un cierto camino (entrenamiento, aprendizaje). Registro escrito.","en":"Shows that a result or ability is obtained through a certain way or route; 經由 introduces the route, 而來 closes it. Written.","tc":"表示某種結果或能力是透過某個方式、途徑得來的。「經由」後接途徑，「而來」收尾，書面。","sc":"表示某种结果或能力是透过某个方式、途径得来的。「经由」后接途径，「而来」收尾，书面。"},"ex":[{"c":"孩童良好的生活習慣，必須經由父母耐心地訓練而來，如此才能有健康的身心。","s":"孩童良好的生活习惯，必须经由父母耐心地训练而来，如此才能有健康的身心。","es":"Los buenos hábitos de los niños deben lograrse mediante el entrenamiento paciente de los padres; solo así habrá un cuerpo y una mente sanos.","en":"Children's good living habits must come through patient training by their parents; only then can they have a healthy body and mind.","p":"hái tóng liáng hǎo de shēng huó xí guàn, bì xū jīng yóu fù mǔ nài xīn dì xùn liàn ér lái, rú cǐ cái néng yǒu jiàn kāng de shēn xīn."},{"c":"這項能力是經由長期練習而來的。","s":"这项能力是经由长期练习而来的。","es":"Esta habilidad se adquiere mediante años de práctica.","en":"This skill comes from long-term practice.","p":"zhè xiàng néng lì shì jīng yóu cháng qí liàn xí ér lái de."}]},{"id":"6-8-12","b":6,"l":8,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Además: 再者","en":"Moreover: 再者","ens":"Moreover: 再者","tc":"再者","sc":"再者"},"d":{"es":"再者 = además, por otra parte. Añade otra razón o circunstancia al inicio de la siguiente cláusula. Es de registro escrito y argumentativo; en lo oral se prefiere 而且 o 還有.","en":"Adds another reason or circumstance; placed at the start of the later clause. Written, common in argumentation; in speech people usually say 而且.","tc":"用來追加另一個理由或情況，位置在後面的分句開頭。書面，常用在議論裡，口語多說「而且」。","sc":"用来追加另一个理由或情况，位置在后面的分句开头。书面，常用在议论里，口语多说「而且」。"},"ex":[{"c":"舉辦奧運可以吸引全球目光，是極好的行銷機會；再者也可以展現國力，是極大的榮耀。","s":"举办奥运可以吸引全球目光，是极好的行销机会；再者也可以展现国力，是极大的荣耀。","es":"Organizar unos Juegos Olímpicos atrae la atención del mundo y es una excelente oportunidad de marketing; además, permite mostrar el poder del país y es un gran honor.","en":"Hosting the Olympics draws global attention and is an excellent marketing opportunity; moreover, it also shows national strength and is a great honor.","p":"jǔ bàn ào yùn kě yǐ xī yǐn quán qiú mù guāng, shì jí hǎo de xíng xiāo jī huì; zài zhě yě kě yǐ zhǎn xiàn guó lì, shì jí dà de róng yào."},{"c":"這個地點交通方便；再者，附近的環境也很安靜。","s":"这个地点交通方便；再者，附近的环境也很安静。","es":"Este lugar tiene buen transporte; además, los alrededores son muy tranquilos.","en":"This location has convenient transport; moreover, the surroundings are quiet too.","p":"zhè ge dì diǎn jiāo tōng fāng biàn; zài zhě, fù jìn de huán jìng yě hěn ān jìng."}]},{"id":"6-8-13","b":6,"l":8,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Un descuido: 一個不小心","en":"One careless moment: 一個不小心","ens":"One careless moment: 一个不小心","tc":"一個不小心","sc":"一个不小心"},"d":{"es":"一個不小心 = por un descuido, si uno se descuida. Indica que un pequeño error lleva a un mal resultado; suele ir al inicio y va seguido de 就 + consecuencia. Informal-neutral.","en":"Says that a slight lapse leads to a (bad) result; typically at the start of a sentence, followed by what might happen, often with 就.","tc":"表示稍微一疏忽就會出現（壞）結果。常放在句首或主句前，後面接可能發生的壞事，常帶「就」。","sc":"表示稍微一疏忽就会出现（坏）结果。常放在句首或主句前，后面接可能发生的坏事，常带「就」。"},"ex":[{"c":"寫中國字，是培養觀察力的好機會，因為一個不小心就可能寫成別的字，造成誤會。","s":"写中国字，是培养观察力的好机会，因为一个不小心就可能写成别的字，造成误会。","es":"Escribir caracteres chinos es una buena oportunidad para cultivar la observación, porque con un pequeño descuido puedes escribir otro carácter y causar un malentendido.","en":"Writing Chinese characters is a great chance to cultivate observation, because one small slip may turn into a different character and cause a misunderstanding.","p":"xiě zhōng guó zì, shì péi yǎng guān chá lì de hǎo jī huì, yīn wèi yí ge bù xiǎo xīn jiù kě néng xiě chéng bié de zì, zào chéng wù huì."},{"c":"開車的時候一個不小心，就可能發生意外。","s":"开车的时候一个不小心，就可能发生意外。","es":"Un descuido al conducir puede provocar un accidente.","en":"One careless moment while driving can cause an accident.","p":"kāi chē de shí hòu yí ge bù xiǎo xīn, jiù kě néng fā shēng yì wài."}]},{"id":"6-8-14","b":6,"l":8,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No se puede dejar de…: 不可不……","en":"Must not fail to…: 不可不……","ens":"Must not fail to…: 不可不……","tc":"不可不……","sc":"不可不……"},"d":{"es":"不可不… = no se puede dejar de…, hay que… sí o sí. Es doble negación que equivale a «es imprescindible»; suena a recomendación enfática o consejo. Va seguida de un verbo y es de registro más escrito. No confundir con 不可以 (prohibición).","en":"A double negative meaning 'must'; stronger or more of a recommendation than 必須. A verb follows; written or advisory.","tc":"雙重否定，意思是「一定要」「必須」，語氣比「必須」更強調或勸告。後面是動詞，書面或勸告時用。","sc":"双重否定，意思是「一定要」「必须」，语气比「必须」更强调或劝告。后面是动词，书面或劝告时用。"},"ex":[{"c":"出國旅遊，當地有特色的小吃，不可不品嘗，要不然會覺得有所遺憾。","s":"出国旅游，当地有特色的小吃，不可不品尝，要不然会觉得有所遗憾。","es":"Al viajar al extranjero, no puedes dejar de probar los bocadillos típicos del lugar; si no, te quedará un sentimiento de pesar.","en":"When traveling abroad, you must try the local specialty snacks; otherwise you will feel something was missing.","p":"chū guó lǚ yóu, dāng dì yǒu tè sè de xiǎo chī, bù kě bù pǐn cháng, yào bù rán huì jué dé yǒu suǒ yí hàn."},{"c":"來到台灣，不可不去夜市逛逛。","s":"来到台湾，不可不去夜市逛逛。","es":"Si vienes a Taiwán, no puedes dejar de ir a un mercado nocturno.","en":"If you come to Taiwan, you shouldn't miss visiting a night market.","p":"lái dào tái wān, bù kě bú qù yè shì guàng guàng."}]},{"id":"6-9-0","b":6,"l":9,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Si lo calculamos…: 算計起來","en":"All told: 算計起來","ens":"All told: 算计起来","tc":"算計起來","sc":"算计起来"},"d":{"es":"算計起來 = haciendo las cuentas, si se calcula. Presenta el resultado de sumar tiempo, cantidad o gasto; suele ir seguido de «ya llevan… / ya son…». Nota: 算計 solo, como verbo, también significa «tramar contra alguien».","en":"The result of totaling up time, quantity or cost, often followed by 已經……了 to say how long or how much in all.","tc":"把時間、數量或花費加總計算後得到的結果，常接「已經……了」，用來說明總共多久、多少。","sc":"把时间、数量或花费加总计算后得到的结果，常接「已经……了」，用来说明总共多久、多少。"},"ex":[{"c":"教授成立｢照亮世界基金會｣，算計起來已二十多年了，而且讓全球四十三個國家的偏遠村落大放光明。","s":"教授成立｢照亮世界基金会｣，算计起来已二十多年了，而且让全球四十三个国家的偏远村落大放光明。","es":"El profesor fundó la «Fundación Ilumina el Mundo»; haciendo las cuentas, ya llevan más de veinte años, y han iluminado aldeas remotas de cuarenta y tres países.","en":"The professor founded the 'Light Up the World Foundation'; counting it up, it has been over twenty years, and it has brought light to remote villages in forty-three countries.","p":"jiào shòu chéng lì｢ zhào liàng shì jiè jī jīn huì｣, suàn jì qǐ lái yǐ èr shí duō nián le, ér qiě ràng quán qiú sì shí sān ge guó jiā de piān yuǎn cūn luò dà fàng guāng míng."},{"c":"算計起來，我來台灣已經快五年了。","s":"算计起来，我来台湾已经快五年了。","es":"Si hago las cuentas, ya llevo casi cinco años en Taiwán.","en":"Counting it up, I have already been in Taiwan for almost five years.","p":"suàn jì qǐ lái, wǒ lái tái wān yǐ jīng kuài wǔ nián le."}]},{"id":"6-9-1","b":6,"l":9,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Sin darse cuenta: （在）不知不覺中","en":"Without realizing: （在）不知不覺中","ens":"Without realizing: （在）不知不觉中","tc":"（在）不知不覺中","sc":"（在）不知不觉中"},"d":{"es":"（在）不知不覺中 = sin darse cuenta, imperceptiblemente. Indica que un cambio ocurre poco a poco sin que se note; suele ir al inicio de la oración o tras el sujeto. Neutro, usable en hablado y escrito.","en":"While not noticing, something has gradually changed or happened. Placed at the start or after the subject, showing an unnoticeable process.","tc":"沒有注意到的時候，事情已經慢慢變化或發生了。放在句首或主語後，表示過程不明顯。","sc":"没有注意到的时候，事情已经慢慢变化或发生了。放在句首或主语后，表示过程不明显。"},"ex":[{"c":"由於各國動物園同意支付高額的租金租借貓熊，在不知不覺中，貓熊沾染了濃重的商業色彩，變成有利可圖的生財工具了。","s":"由于各国动物园同意支付高额的租金租借猫熊，在不知不觉中，猫熊沾染了浓重的商业色彩，变成有利可图的生财工具了。","es":"Como los zoológicos de varios países aceptaron pagar altos alquileres por los pandas, sin darse cuenta estos se impregnaron de un fuerte matiz comercial y pasaron a ser una herramienta rentable.","en":"Because zoos in many countries agreed to pay high rent for pandas, unnoticed, pandas became heavily tinged with commercialism and turned into a profitable money-maker.","p":"yóu yú gè guó dòng wù yuán tóng yì zhī fù gāo é de zū jīn zū jiè māo xióng, zài bù zhī bù jué zhōng, māo xióng zhān rǎn le nóng zhòng de shāng yè sè cǎi, biàn chéng yǒu lì kě tú de shēng cái gōng jù le."},{"c":"在不知不覺中，天已經黑了。","s":"在不知不觉中，天已经黑了。","es":"Sin darnos cuenta, ya se hizo de noche.","en":"Before we knew it, it had grown dark.","p":"zài bù zhī bù jué zhōng, tiān yǐ jīng hēi le."}]},{"id":"6-9-2","b":6,"l":9,"k":"","t":{"es":"Cosas como…: ……之類的N","en":"Things like…: ……之類的N","ens":"Things like…: ……之类的N","tc":"……之類的N","sc":"……之类的N"},"d":{"es":"…之類的 N = N como…, N de ese tipo. Se citan uno o dos ejemplos y 之類的 abarca la categoría; después va el sustantivo (收入, 食物, 工作…). Es más general que 等等 y algo coloquial.","en":"Gives one or two examples, then 之類的 covers the same kind of things, followed by a noun. Means 'things like…'.","tc":"列出一兩個例子，再用「之類的」概括同類事物，後面接名詞。意思是「像……這一類的」。","sc":"列出一两个例子，再用「之类的」概括同类事物，后面接名词。意思是「像……这一类的」。"},"ex":[{"c":"單單靠贊助、 門票之類的收入，投入興建運動場館的資金，難以回本。","s":"单单靠赞助、 门票之类的收入，投入兴建运动场馆的资金，难以回本。","es":"Solo con ingresos como los de patrocinios y entradas, es difícil recuperar el dinero invertido en construir estadios deportivos.","en":"Relying only on revenue like sponsorships and tickets, it is hard to recoup the funds invested in building sports venues.","p":"dān dān kào zàn zhù, mén piào zhī lèi de shōu rù, tóu rù xīng jiàn yùn dòng chǎng guǎn de zī jīn, nán yǐ huí běn."},{"c":"像蔬菜、水果之類的食物，每天都應該多吃一點。","s":"像蔬菜、水果之类的食物，每天都应该多吃一点。","es":"Alimentos como las verduras y las frutas conviene comerlos en mayor cantidad cada día.","en":"Foods such as vegetables and fruits should be eaten more of every day.","p":"xiàng shū cài, shuǐ guǒ zhī lèi de shí wù, měi tiān dōu yīng gāi duō chī yì diǎn."}]},{"id":"6-9-3","b":6,"l":9,"k":"","t":{"es":"Uno por uno: 一一","en":"One by one: 一一","ens":"One by one: 一一","tc":"一一","sc":"一一"},"d":{"es":"一一 = uno por uno, uno a uno, sin omitir ninguno. Va antes del verbo y recalca que se hace de manera individual y completa. Registro escrito o formal. No es el número «11».","en":"Doing something one after another, item by item, without missing any; placed before the verb; written or formal.","tc":"表示一個接一個、逐項地做，不遺漏。放在動詞前，書面或正式。","sc":"表示一个接一个、逐项地做，不遗漏。放在动词前，书面或正式。"},"ex":[{"c":"該賣場重視服務，不論客戶親購或網購的商品，必將一一送到客戶家中，難怪能吸引源源不絕的客人。","s":"该卖场重视服务，不论客户亲购或网购的商品，必将一一送到客户家中，难怪能吸引源源不绝的客人。","es":"El establecimiento valora el servicio: sea que el cliente compre en persona o en línea, cada producto se entrega uno por uno a su domicilio, por eso no es de extrañar que atraiga un flujo constante de clientes.","en":"The store emphasizes service: whether customers buy in person or online, every product will be delivered to their homes one by one, no wonder it attracts a never-ending flow of customers.","p":"gāi mài chǎng zhòng shì fú wù, bú lùn kè hù qīn gòu huò wǎng gòu de shāng pǐn, bì jiāng yī yī sòng dào kè hù jiā zhōng, nán guài néng xī yǐn yuán yuán bù jué de kè rén."},{"c":"老師把每位學生的作業一一檢查過了。","s":"老师把每位学生的作业一一检查过了。","es":"La profesora revisó uno por uno los deberes de cada estudiante.","en":"The teacher checked each student's homework one by one.","p":"lǎo shī bǎ měi wèi xué shēng de zuò yè yī yī jiǎn chá guò le."}]},{"id":"6-10-0","b":6,"l":10,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Hasta cierto punto: 某種程度來說","en":"To some extent: 某種程度來說","ens":"To some extent: 某种程度来说","tc":"某種程度來說","sc":"某种程度来说"},"d":{"es":"某種程度來說 = hasta cierto punto, en cierto sentido. Matiza una afirmación para que no sea absoluta. Va al inicio de la oración o tras el sujeto. Se usa tanto en lo oral como en lo escrito; también «某種程度上».","en":"Means 'in a certain sense or to some extent', making a claim less absolute. Often at the start of a sentence, usable in speech and writing.","tc":"表示「在某個範圍或意義上」，用來讓說法比較保守、不絕對。常放在句子前面，口語與書面都能用。","sc":"表示「在某个范围或意义上」，用来让说法比较保守、不绝对。常放在句子前面，口语与书面都能用。"},"ex":[{"c":"主辦奧運，某種程度來說，可以視為國力的展現，因此即便有舉債的可能，各國仍爭相申請。","s":"主办奥运，某种程度来说，可以视为国力的展现，因此即便有举债的可能，各国仍争相申请。","es":"Organizar los Juegos Olímpicos puede verse, hasta cierto punto, como una demostración del poder del país; por eso, aunque exista la posibilidad de endeudarse, los países siguen compitiendo por postularse.","en":"Hosting the Olympics can, to some extent, be seen as a display of national strength, so even though there is a possibility of going into debt, countries still rush to apply.","p":"zhǔ bàn ào yùn, mǒu zhǒng chéng dù lái shuō, kě yǐ shì wéi guó lì de zhǎn xiàn, yīn cǐ jí biàn yǒu jǔ zhài de kě néng, gè guó réng zhēng xiāng shēn qǐng."},{"c":"某種程度來說，他的成功是靠運氣。","s":"某种程度来说，他的成功是靠运气。","es":"Hasta cierto punto, su éxito se debe a la suerte.","en":"In a certain sense, his success depended on luck.","p":"mǒu zhǒng chéng dù lái shuō, tā de chéng gōng shì kào yùn qì."}]},{"id":"6-10-1","b":6,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Confundir X con Y: 把X和Y混為一談","en":"Lump X and Y together: 把X和Y混為一談","ens":"Lump X and Y together: 把X和Y混为一谈","tc":"把X和Y混為一談","sc":"把X和Y混为一谈"},"d":{"es":"把 X 和 Y 混為一談 = confundir X con Y, meter a X e Y en el mismo saco. Se critica que se traten como lo mismo dos cosas diferentes. Tono negativo; suele ir en estructuras con 不能 o 不要.","en":"Treating two different things as one; often used to criticize mixing them up. Negative, pointing out an error.","tc":"把本來不同的兩件事當成同一件事來談，常用來批評別人搞混了。有負面、指出錯誤的語氣。","sc":"把本来不同的两件事当成同一件事来谈，常用来批评别人搞混了。有负面、指出错误的语气。"},"ex":[{"c":"不少新興經濟體把傾銷和行銷混為一談，難怪遭他國抵制這種不公平的行為。","s":"不少新兴经济体把倾销和行销混为一谈，难怪遭他国抵制这种不公平的行为。","es":"Muchas economías emergentes confunden el dumping con el marketing; no es de extrañar que otros países boicoteen esta práctica desleal.","en":"Many emerging economies lump dumping and marketing together, no wonder other countries boycott this unfair practice.","p":"bù shǎo xīn xīng jīng jì tǐ bǎ qīng xiāo hàn xíng xiāo hùn wéi yì tán, nán guài zāo tā guó dǐ zhì zhè zhǒng bù gōng píng de xíng wéi."},{"c":"不要把個人隱私和公共利益混為一談。","s":"不要把个人隐私和公共利益混为一谈。","es":"No hay que confundir la privacidad individual con el interés público.","en":"Don't confuse personal privacy with the public interest.","p":"bú yào bǎ gè rén yǐn sī hàn gōng gòng lì yì hùn wéi yì tán."}]},{"id":"6-10-2","b":6,"l":10,"k":"","t":{"es":"Sufrir por: 為……所苦","en":"Be plagued by…: 為……所苦","ens":"Be plagued by…: 为……所苦","tc":"為……所苦","sc":"为……所苦"},"d":{"es":"為…所苦 = sufrir de, estar atormentado por…. 為…所 es una pasiva escrita clásica; 所苦 indica el tormento. Se usa con problemas persistentes (病痛, 失眠, 貧窮). Registro formal/escrito.","en":"Troubled or tormented by some difficulty or problem. 為……所 is a written passive pattern, often followed by 苦, 困擾, 擾.","tc":"被某個困難或問題困擾、折磨。「為……所」是被動的書面格式，後面常接「苦、困擾、擾」。","sc":"被某个困难或问题困扰、折磨。「为……所」是被动的书面格式，后面常接「苦、困扰、扰」。"},"ex":[{"c":"語言翻譯機是給為外語能力不足所苦的人使用的，但只能翻譯日常生活用語，意思較複雜的句子就未必能翻譯。","s":"语言翻译机是给为外语能力不足所苦的人使用的，但只能翻译日常生活用语，意思较复杂的句子就未必能翻译。","es":"Los traductores de idiomas están pensados para quienes sufren por su escaso dominio de lenguas extranjeras, pero solo traducen el lenguaje cotidiano; las oraciones de significado más complejo no necesariamente se traducen.","en":"Language translators are for people troubled by insufficient foreign-language ability, but they can only translate everyday language; sentences with complex meaning may not be translatable.","p":"yǔ yán fān yì jī shì gěi wéi wài yǔ néng lì bù zú suǒ kǔ de rén shǐ yòng de, dàn zhǐ néng fān yì rì cháng shēng huó yòng yǔ, yì sī jiào fù zá de jù zi jiù wèi bì néng fān yì."},{"c":"他多年來為失眠所苦。","s":"他多年来为失眠所苦。","es":"Durante años ha sufrido de insomnio.","en":"For years he has suffered from insomnia.","p":"tā duō nián lái wéi shī mián suǒ kǔ."}]},{"id":"6-10-3","b":6,"l":10,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No dañar (su…): 不損（其）……","en":"Not harm its…: 不損（其）……","ens":"Not harm its…: 不损（其）……","tc":"不損（其）……","sc":"不损（其）……"},"d":{"es":"不損（其）… = no perjudica (su…), no merma (su…). 其 remite al objeto ya mencionado; 損 es «dañar». Estilo escrito de aire clásico; puede decirse más llanamente 不會損失它的…. Se combina con 並不 (並不損其營養).","en":"Says it will not harm or reduce the benefit of something; 其 refers to the earlier item and 損 means damage. Classical-sounding written style.","tc":"表示不會損害、減少某個事物的好處。「其」指前面提到的東西，「損」是損害，文言口吻的書面語。","sc":"表示不会损害、减少某个事物的好处。「其」指前面提到的东西，「损」是损害，文言口吻的书面语。"},"ex":[{"c":"蒸、煮食物並不損其營養成分，是最大的優點，但華人重視色、香、味，常用大火快炒方式料理。","s":"蒸、煮食物并不损其营养成分，是最大的优点，但华人重视色、香、味，常用大火快炒方式料理。","es":"Cocer al vapor o hervir los alimentos no daña su valor nutritivo, y esa es su mayor ventaja, pero los chinos valoran el color, el aroma y el sabor y suelen cocinarlos salteándolos a fuego fuerte.","en":"Steaming and boiling food do not harm its nutrients, which is the greatest advantage, but Chinese people value color, aroma and flavor and often stir-fry over high heat.","p":"zhēng, zhǔ shí wù bìng bù sǔn qí yíng yǎng chéng fēn, shì zuì dà de yōu diǎn, dàn huá rén zhòng shì sè, xiāng, wèi, cháng yòng dà huǒ kuài chǎo fāng shì liào lǐ."},{"c":"多喝水不損其健康，反而有益。","s":"多喝水不损其健康，反而有益。","es":"Beber más agua no perjudica la salud; al contrario, es beneficioso.","en":"Drinking more water does not harm one's health; on the contrary, it helps.","p":"duō hē shuǐ bù sǔn qí jiàn kāng, fǎn ér yǒu yì."}]},{"id":"6-10-4","b":6,"l":10,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No estorbar: 不礙","en":"Not hinder: 不礙","ens":"Not hinder: 不碍","tc":"不礙","sc":"不碍"},"d":{"es":"不礙 = no obstaculiza, no impide. Suele ir seguido de 其, 事, 正事, etc. Registro escrito de aire clásico (similar a 不損). Es más coloquial decir 不會妨礙 / 不影響.","en":"Means it will not hinder or affect; often followed by 其, 事, 正事, etc. Classical-sounding written style, like 不損.","tc":"表示不會妨礙、不會影響。後面常接「其／事／正事」等，是文言口吻的書面語，與「不損」類似。","sc":"表示不会妨碍、不会影响。后面常接「其／事／正事」等，是文言口吻的书面语，与「不损」类似。"},"ex":[{"c":"即使嬰兒不會說話，也不礙其溝通，有經驗的父母能從他們的哭聲，了解他們的需求。","s":"即使婴儿不会说话，也不碍其沟通，有经验的父母能从他们的哭声，了解他们的需求。","es":"Aunque el bebé no sepa hablar, eso no le impide comunicarse; los padres con experiencia entienden sus necesidades por su llanto.","en":"Even if infants can't speak, it doesn't hinder their communication; experienced parents can understand their needs from their cries.","p":"jí shǐ yīng ér bú huì shuō huà, yě bú ài qí gōu tōng, yǒu jīng yàn de fù mǔ néng cóng tā men de kū shēng, liǎo jiě tā men de xū qiú."},{"c":"工作再忙也不礙他每天運動。","s":"工作再忙也不碍他每天运动。","es":"Por más ocupado que esté en el trabajo, eso no le impide hacer ejercicio cada día.","en":"However busy work is, it doesn't keep him from exercising every day.","p":"gōng zuò zài máng yě bú ài tā měi tiān yùn dòng."}]},{"id":"6-10-5","b":6,"l":10,"k":"","t":{"es":"El espíritu de X reside en…: X的精神在（於）……","en":"The essence of X lies in…: X的精神在（於）……","ens":"The essence of X lies in…: X的精神在（于）……","tc":"X的精神在（於）……","sc":"X的精神在（于）……"},"d":{"es":"X 的精神在（於）… = el espíritu de X radica en…. Introduce la esencia o principio central de algo (un sistema, una educación, un ideal). 在於 introduce lo esencial. Registro escrito, común en definiciones y explicaciones.","en":"Explains the core idea or principle of something (system, education, ideal); 在於 introduces the key point. Written.","tc":"說明某種事物最核心的想法或原則是什麼。X 是制度、教育、理念等，「在於」引出重點，書面。","sc":"说明某种事物最核心的想法或原则是什么。X 是制度、教育、理念等，「在于」引出重点，书面。"},"ex":[{"c":"技職教育的精神在與產業緊密合作，以了解市場需求，提升個人或國家的競爭力。","s":"技职教育的精神在与产业紧密合作，以了解市场需求，提升个人或国家的竞争力。","es":"El espíritu de la educación técnica y profesional radica en colaborar estrechamente con la industria para entender las necesidades del mercado y aumentar la competitividad personal o del país.","en":"The spirit of technical and vocational education lies in working closely with industry to understand market needs and raise personal or national competitiveness.","p":"jì zhí jiào yù de jīng shén zài yǔ chǎn yè jǐn mì hé zuò, yǐ liǎo jiě shì chǎng xū qiú, tí shēng gè rén huò guó jiā de jìng zhēng lì."},{"c":"民主的精神在於尊重不同的意見。","s":"民主的精神在于尊重不同的意见。","es":"El espíritu de la democracia reside en respetar las opiniones distintas.","en":"The spirit of democracy lies in respecting different opinions.","p":"mín zhǔ de jīng shén zài yú zūn zhòng bù tóng de yì jiàn."}]},{"id":"6-10-6","b":6,"l":10,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Lograr / poder (por fin): 得以","en":"Be able to (thanks to…): 得以","ens":"Be able to (thanks to…): 得以","tc":"得以","sc":"得以"},"d":{"es":"得以 = poder, lograr (gracias a una condición u oportunidad). Va antes del verbo y suele implicar que algo antes imposible ahora es posible. Registro escrito. A diferencia de 可以, no expresa permiso, y el sujeto no suele ser quien decide.","en":"Shows that thanks to a condition or opportunity one is able to do something, often 'finally can'. Placed before the verb; written.","tc":"表示因為有了某個條件或機會，才能夠做到某事，常有「終於可以」的意思。放在動詞前，書面。","sc":"表示因为有了某个条件或机会，才能够做到某事，常有「终于可以」的意思。放在动词前，书面。"},"ex":[{"c":"設立了自然保護區後，貓熊得以安全成長，順利繁殖，在保育方面取得明顯進展。","s":"设立了自然保护区后，猫熊得以安全成长，顺利繁殖，在保育方面取得明显进展。","es":"Tras establecerse reservas naturales, los pandas pueden crecer con seguridad y reproducirse sin problemas, lo que muestra un progreso claro en la conservación.","en":"After nature reserves were established, pandas have been able to grow up safely and reproduce successfully, showing clear progress in conservation.","p":"shè lì le zì rán bǎo hù qū hòu, māo xióng dé yǐ ān quán chéng zhǎng, shùn lì fán zhí, zài bǎo yù fāng miàn qǔ dé míng xiǎn jìn zhǎn."},{"c":"經過治療，他得以重新回到工作崗位。","s":"经过治疗，他得以重新回到工作岗位。","es":"Gracias al tratamiento, pudo volver a su puesto de trabajo.","en":"After treatment, he was able to return to work.","p":"jīng guò zhì liáo, tā dé yǐ chóng xīn huí dào gōng zuò gāng wèi."}]},{"id":"6-10-7","b":6,"l":10,"k":"","t":{"es":"Con algún V (leve): 有所V","en":"To some extent V: 有所V","ens":"To some extent V: 有所V","tc":"有所V","sc":"有所V"},"d":{"es":"有所 V = V en cierta medida, algo de V. Va con verbos bisílabos (改善, 期待, 幫助, 了解). Indica un grado moderado y es de registro escrito y objetivo. No se usa con verbos monosilábicos ni con complementos de grado.","en":"Means 'to some degree', not deep; a two-syllable verb follows, as in 有所改善 or 有所期待. Written, objective and measured.","tc":"表示「有一些……」，程度不深，後面接雙音節動詞，如「有所改善」「有所期待」。書面，語氣比較客觀、保守。","sc":"表示「有一些……」，程度不深，后面接双音节动词，如「有所改善」「有所期待」。书面，语气比较客观、保守。"},"ex":[{"c":"年輕時就得訓練獨立精神，不能對別人的協助有所期待，免得養成依賴心。","s":"年轻时就得训练独立精神，不能对别人的协助有所期待，免得养成依赖心。","es":"Hay que entrenar el espíritu de independencia desde joven y no esperar nada de la ayuda ajena, para no volverse dependiente.","en":"One has to train a spirit of independence when young, and cannot expect anything from others' help, lest one develop a habit of dependence.","p":"nián qīng shí jiù děi xùn liàn dú lì jīng shén, bù néng duì bié rén de xié zhù yǒu suǒ qí dài, miǎn dé yǎng chéng yī lài xīn."},{"c":"經過這次改革，教育品質有所提升。","s":"经过这次改革，教育品质有所提升。","es":"Tras esta reforma, la calidad de la educación mejoró en cierta medida.","en":"After this reform, the quality of education has improved somewhat.","p":"jīng guò zhè cì gǎi gé, jiào yù pǐn zhí yǒu suǒ tí shēng."}]},{"id":"6-10-8","b":6,"l":10,"k":"","t":{"es":"Distinguir X de Y: 區分（出）X和Y","en":"Distinguish X from Y: 區分（出）X和Y","ens":"Distinguish X from Y: 区分（出）X和Y","tc":"區分（出）X和Y","sc":"区分（出）X和Y"},"d":{"es":"區分（出）X 和 Y = distinguir X de Y. Se usa para reconocer la diferencia entre dos cosas; frecuente con complemento potencial: 區分不出 (no poder distinguir) / 區分得出. No es lo mismo que 分開, que significa «separar».","en":"Telling two things apart and seeing their difference; often with 不出 or 得出, e.g., 區分不出X和Y.","tc":"把兩樣東西分辨出來，看出它們的不同。常和「不出」「得出」搭配：「區分不出X和Y」。","sc":"把两样东西分辨出来，看出它们的不同。常和「不出」「得出」搭配：「区分不出X和Y」。"},"ex":[{"c":"不少神經大條的男性，永遠區分不出字面上的意義和字面背後的意義，使女友氣得不想再說話。","s":"不少神经大条的男性，永远区分不出字面上的意义和字面背后的意义，使女友气得不想再说话。","es":"Muchos hombres despistados nunca logran distinguir el significado literal del significado que hay detrás de las palabras, y eso enfurece a sus novias hasta el punto de no querer volver a hablar.","en":"Many oblivious men can never tell the literal meaning from the meaning behind the words, making their girlfriends so angry that they don't want to talk anymore.","p":"bù shǎo shén jīng dà tiáo de nán xìng, yǒng yuǎn qū fēn bù chū zì miàn shàng de yì yì hàn zì miàn bèi hòu de yì yì, shǐ nǚ yǒu qì de bù xiǎng zài shuō huà."},{"c":"她分得出雙胞胎兄弟，我卻總是區分不出誰是誰。","s":"她分得出双胞胎兄弟，我却总是区分不出谁是谁。","es":"Ella sabe quién es quién de los gemelos, pero yo nunca logro distinguirlos.","en":"She can tell the twin brothers apart, but I can never distinguish who is who.","p":"tā fēn dé chū shuāng bāo tāi xiōng dì, wǒ què zǒng shì qū fēn bù chū shéi shì shéi."}]},{"id":"6-10-9","b":6,"l":10,"k":"","t":{"es":"Una de las formas de…: X是Y的方式之一","en":"One of the ways of…: X是Y的方式之一","ens":"One of the ways of…: X是Y的方式之一","tc":"X是Y的方式之一","sc":"X是Y的方式之一"},"d":{"es":"X 是 Y 的方式之一 = X es una de las maneras de Y. 之一 indica que hay otras opciones; es neutro y propio de la argumentación. Se puede sustituir 方式 por 方法, 途徑 o 手段.","en":"Says X is one of several ways of achieving Y; 之一 shows it's not the only one. Common in written argument.","tc":"說明 X 是達成 Y 的眾多方法中的一個。「之一」表示不是唯一，書面、議論時常用。","sc":"说明 X 是达成 Y 的众多方法中的一个。「之一」表示不是唯一，书面、议论时常用。"},"ex":[{"c":"政府若想拼經濟，主辦大型國際賽事是促進旅遊業發展的方式之一，必能有驚人的成效。","s":"政府若想拼经济，主办大型国际赛事是促进旅游业发展的方式之一，必能有惊人的成效。","es":"Si el gobierno quiere impulsar la economía, organizar grandes eventos deportivos internacionales es una de las formas de promover el turismo y seguramente dará resultados asombrosos.","en":"If the government wants to boost the economy, hosting major international sporting events is one way of promoting tourism and is sure to deliver striking results.","p":"zhèng fǔ ruò xiǎng pīn jīng jì, zhǔ bàn dà xíng guó jì sài shì shì cù jìn lǚ yóu yè fā zhǎn de fāng shì zhī yī, bì néng yǒu jīng rén de chéng xiào."},{"c":"多讀報紙是增加詞彙量的方式之一。","s":"多读报纸是增加词汇量的方式之一。","es":"Leer más periódicos es una de las maneras de ampliar el vocabulario.","en":"Reading more newspapers is one way to expand your vocabulary.","p":"duō dú bào zhǐ shì zēng jiā cí huì liàng de fāng shì zhī yī."}]},{"id":"6-10-10","b":6,"l":10,"k":"","t":{"es":"Todo (lo que sea): 凡是","en":"Every / all…: 凡是","ens":"Every / all…: 凡是","tc":"凡是","sc":"凡是"},"d":{"es":"凡是 = todo lo que, todos los que. Se aplica a cualquier elemento de una categoría y la segunda parte lleva 都 / 皆 / 無不. Es normal que la cláusula con 凡是 sea una regla general. Registro escrito; también hablado con 只要是… .","en":"Means everyone or everything within a range applies; often echoed by 都, 皆, 無不. For general rules or facts; written.","tc":"表示在某一範圍內的所有人或事物都適用，後面常用「都、皆、無不」呼應。用於一般規則或事實，書面。","sc":"表示在某一范围内的所有人或事物都适用，后面常用「都、皆、无不」呼应。用于一般规则或事实，书面。"},"ex":[{"c":"凡是前人的經驗，皆可使後人少走許多曲折路，避免身陷危險境地。","s":"凡是前人的经验，皆可使后人少走许多曲折路，避免身陷危险境地。","es":"Toda experiencia de los antiguos permite a las generaciones posteriores evitar muchos rodeos y no caer en situaciones peligrosas.","en":"All experience of the predecessors can spare later generations from many detours and keep them out of dangerous situations.","p":"fán shì qián rén de jīng yàn, jiē kě shǐ hòu rén shǎo zǒu xǔ duō qǔ zhé lù, bì miǎn shēn xiàn wéi xiǎn jìng dì."},{"c":"凡是參加這次活動的人，都可以得到一份小禮物。","s":"凡是参加这次活动的人，都可以得到一份小礼物。","es":"Todos los que participen en esta actividad recibirán un pequeño regalo.","en":"Everyone who takes part in this event will receive a small gift.","p":"fán shì cān jiā zhè cì huó dòng de rén, dōu kě yǐ dé dào yí fèn xiǎo lǐ wù."}]},{"id":"6-10-11","b":6,"l":10,"k":"","t":{"es":"Resolver el misterio de…: 解開……之謎","en":"Solve the mystery of…: 解開……之謎","ens":"Solve the mystery of…: 解开……之谜","tc":"解開……之謎","sc":"解开……之谜"},"d":{"es":"解開…之謎 = resolver el misterio de…, desentrañar el enigma de…. Lo que se quiere saber va antes de 之謎. Habitual en noticias y divulgación científica. El verbo 解開 también se usa con 結, 疑惑.","en":"Finally clearing up a question that has long had no answer. What people want to know goes before 之謎; common in news or science reports.","tc":"把一直沒有答案的問題弄明白。「謎」前面放大家想知道的事，常見於新聞或科學報導。","sc":"把一直没有答案的问题弄明白。「谜」前面放大家想知道的事，常见于新闻或科学报导。"},"ex":[{"c":"許多人相信，宗教能為人類解開生死之謎。","s":"许多人相信，宗教能为人类解开生死之谜。","es":"Mucha gente cree que la religión puede resolver para la humanidad el misterio de la vida y la muerte.","en":"Many people believe that religion can unravel the mystery of life and death for humankind.","p":"xǔ duō rén xiāng xìn, zōng jiào néng wéi rén lèi jiě kāi shēng sǐ zhī mí."},{"c":"科學家終於解開了恐龍滅絕之謎。","s":"科学家终于解开了恐龙灭绝之谜。","es":"Los científicos por fin resolvieron el misterio de la extinción de los dinosaurios.","en":"Scientists finally solved the mystery of the dinosaurs' extinction.","p":"kē xué jiā zhōng yú jiě kāi le kǒng lóng miè jué zhī mí."}]},{"id":"6-10-12","b":6,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Separar X de Y: 把X和Y分開","en":"Separate X and Y: 把X和Y分開","ens":"Separate X and Y: 把X和Y分开","tc":"把X和Y分開","sc":"把X和Y分开"},"d":{"es":"把 X 和 Y 分開 = separar X de Y, tratar X e Y por separado. Estructura con 把. En el ejemplo, el autor critica esa separación y luego explica con 其實 que ambos se complementan. No lo confundas con 區分 (distinguir mentalmente).","en":"Treats two related things as separate and doesn't discuss them together. Uses 把; 其實 often introduces the writer's different view.","tc":"把原本有關聯的兩件事分成兩邊看待，不放在一起談。結構用「把」，後面常有「其實」引出作者的不同看法。","sc":"把原本有关联的两件事分成两边看待，不放在一起谈。结构用「把」，后面常有「其实」引出作者的不同看法。"},"ex":[{"c":"有人把讀萬卷書和行萬里路分開，其實前者代表記憶前人經驗，後者意味著觀察與詮釋，兩者相輔相成。","s":"有人把读万卷书和行万里路分开，其实前者代表记忆前人经验，后者意味着观察与诠释，两者相辅相成。","es":"Hay quienes separan «leer diez mil libros» de «viajar diez mil li»; en realidad, lo primero representa memorizar la experiencia de los antiguos y lo segundo significa observar e interpretar, y ambos se complementan.","en":"Some people separate reading ten thousand books from traveling ten thousand miles, but in fact the former means taking in earlier people's experience, and the latter means observing and interpreting; the two complement each other.","p":"yǒu rén bǎ dú wàn juàn shū hàn xíng wàn lǐ lù fēn kāi, qí shí qián zhě dài biǎo jì yì qián rén jīng yàn, hòu zhě yì wèi zhe guān chá yǔ quán shì, liǎng zhě xiāng fǔ xiāng chéng."},{"c":"工作和生活不應該完全分開。","s":"工作和生活不应该完全分开。","es":"El trabajo y la vida no deberían separarse por completo.","en":"Work and life should not be completely separated.","p":"gōng zuò hàn shēng huó bù yīng gāi wán quán fēn kāi."}]},{"id":"6-10-13","b":6,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Interiorizar X como Y: 把X內化為Y","en":"Internalize X as Y: 把X內化為Y","ens":"Internalize X as Y: 把X内化为Y","tc":"把X內化為Y","sc":"把X内化为Y"},"d":{"es":"把 X 內化為 Y = interiorizar X convirtiéndolo en Y. Estructura 把 + 內化為: X es algo externo (experiencia, conocimiento) que se asimila hasta ser propio (Y). Registro académico y escrito.","en":"Absorbing what comes from outside and making it part of oneself. X is external experience or knowledge, Y is one's own ability or habit; written.","tc":"把外面得到的東西，經過理解吸收，變成自己的一部分。X 是外來的經驗或知識，Y 是自己的能力或習慣，書面。","sc":"把外面得到的东西，经过理解吸收，变成自己的一部分。X 是外来的经验或知识，Y 是自己的能力或习惯，书面。"},"ex":[{"c":"學習的一個目的，即是把別人的經驗內化為自己的知識，增加本身的能力，成就一番事業。","s":"学习的一个目的，即是把别人的经验内化为自己的知识，增加本身的能力，成就一番事业。","es":"Uno de los propósitos del aprendizaje es interiorizar la experiencia de otros como conocimiento propio, aumentar la propia capacidad y lograr una carrera.","en":"One purpose of learning is to internalize others' experience as one's own knowledge, increase one's ability, and achieve success in a career.","p":"xué xí de yí ge mù dì, jí shì bǎ bié rén de jīng yàn nèi huà wéi zì jǐ de zhī shì, zēng jiā běn shēn de néng lì, chéng jiù yì fān shì yè."},{"c":"好的老師會幫助學生把課本上的知識內化為自己的想法。","s":"好的老师会帮助学生把课本上的知识内化为自己的想法。","es":"Un buen profesor ayuda a los estudiantes a hacer propios los conocimientos del libro de texto.","en":"Good teachers help students internalize what's in the textbook into their own thinking.","p":"hǎo de lǎo shī huì bāng zhù xué shēng bǎ kè běn shàng de zhī shì nèi huà wéi zì jǐ de xiǎng fǎ."}]}]};
